INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86712, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使两个或几个事物相连。", "primary_collocate": null, "pronunciation": "lián jié", "ipa": "ljɛn˧˥ tɕjɛ˧˥", "syllable_count": 2, "sentences": [{"text": "这座大桥连结了河两边的城市。", "target_word": "连结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车把南方和北方连结起来。", "target_word": "连结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络把世界各地的人连结在一起。", "target_word": "连结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条铁路连结着三个大城市。", "target_word": "连结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的故事能把过去和现在连结起来。", "target_word": "连结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐把不同国家的人连结在一起。", "target_word": "连结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机让我们和家人连结得更紧。", "target_word": "连结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个活动连结了学校、家庭和社会。", "target_word": "连结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁连结了城市的东边和西边。", "target_word": "连结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几条小路连结成了一张网。", "target_word": "连结", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "连结了", "label": "体标"}, {"form": "连结着", "label": "体标"}, {"form": "连结过", "label": "体标"}, {"form": "連結", "label": "繁体"}], "register": "书面", "sense_fingerprint": "使地点、人或事物之间产生联系、相通", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19b140c7-e308-4628-aaa0-d46ef4cd89fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86712, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "连结", "is_correct": true, "explanation": "正确：连结表示使两地相通，符合“这座大桥连结了河两边的城市”的句意。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：唱的对象是歌曲，不能用“唱城市”来表示连接两地。"}, {"text": "流", "is_correct": false, "explanation": "配价：流是不及物动词，不能带宾语“城市”。"}, {"text": "热爱", "is_correct": false, "explanation": "语义：热爱表示喜爱某人或某事，与桥梁连接两地的意思不符。"}], "explanations": {"连结": "正确：连结表示使两地相通，符合“这座大桥连结了河两边的城市”的句意。", "唱": "搭配：唱的对象是歌曲，不能用“唱城市”来表示连接两地。", "流": "配价：流是不及物动词，不能带宾语“城市”。", "热爱": "语义：热爱表示喜爱某人或某事，与桥梁连接两地的意思不符。"}, "sentence_index": 0, "correct_answer": "连结"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天连结三杯咖啡，一边喝一边工作。", "explanation": "这里应该用〈喝〉。喝指把饮料咽下，连结指使事物相通或产生联系，不能用于饮料。"}, {"text": "他每天早上都连结头发，然后出门上班。", "explanation": "这里应该用〈洗〉。洗头发指用水清除污垢，连结不用于清洗头发。"}, {"text": "他在考场上连结了一道难题，很快做完了。", "explanation": "这里应该用〈解〉。解指解答题目，连结指使事物相通或产生联系，不用于解题。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63a6e138-c20d-4a52-81ce-9599688f9dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86712, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "连结", "is_correct": true, "explanation": "正确：连结表示使人与人之间保持联系，符合“手机让我们和家人连结得更紧”的句意。"}, {"text": "疏远", "is_correct": false, "explanation": "语义：疏远与“更紧”意思相反，与句意不符。"}, {"text": "相信", "is_correct": false, "explanation": "搭配：相信要带对象或内容，不能说“和家人相信得更紧”。"}, {"text": "扔", "is_correct": false, "explanation": "语义：扔是抛掷，无法表示人与人之间关系的紧密程度。"}], "explanations": {"连结": "正确：连结表示使人与人之间保持联系，符合“手机让我们和家人连结得更紧”的句意。", "疏远": "语义：疏远与“更紧”意思相反，与句意不符。", "相信": "搭配：相信要带对象或内容，不能说“和家人相信得更紧”。", "扔": "语义：扔是抛掷，无法表示人与人之间关系的紧密程度。"}, "sentence_index": 6, "correct_answer": "连结"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他这几天连结加班，身体很累。", "explanation": "这里应该用〈连续〉。连续指接连不断地做某事，连结指使事物相连，不用于表示时间上的接续。"}, {"text": "火车连结了大量的货物。", "explanation": "这里应该用〈运输〉。运输指把货物从一地运到另一地，连结指使地点相通，不用于搬运货物。"}, {"text": "我每天都把那本书连结一会儿，然后去睡觉。", "explanation": "这里应该用〈读〉。读指看书上的文字，连结不用于书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63a6e138-c20d-4a52-81ce-9599688f9dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86712, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条航线把两个港口连结起了来。", "corrected_sentence": "这条航线把两个港口连结起来了。", "error_description": "错误：趋向补语“起来”被拆开，写成“起了来”。“起来”应整体放在动词后，“了”放在句末，正确形式为“连结起来了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63a6e138-c20d-4a52-81ce-9599688f9dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86712, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两块板子连结很牢。", "corrected_sentence": "这两块板子连结得很牢。", "error_description": "错误：“连结”后漏掉助词“得”。程度补语要用“动词+得+形容词”，应说“连结得很牢”，不能直接说“连结很牢”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63a6e138-c20d-4a52-81ce-9599688f9dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
