INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86713, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "美元是美国用的钱。", "primary_collocate": null, "pronunciation": "měi yuán", "ipa": "mei˨˩ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "去美国旅游要带美元。", "target_word": "美元", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我在美国买咖啡，付了五美元。", "target_word": "美元", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家美国商店只收美元，不收人民币。", "target_word": "美元", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哥哥从美国回来，给我带了二十美元。", "target_word": "美元", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷住在美国，每个月用美元付房租。", "target_word": "美元", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在美国坐地铁，一次要两美元多。", "target_word": "美元", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多人去国外旅游前会先换一些美元。", "target_word": "美元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出发去美国之前，我把人民币换成了美元。", "target_word": "美元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，美国人买东西都用美元。", "target_word": "美元", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书在美国卖十五美元。", "target_word": "美元", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "美元汇率", "label": "复合"}, {"form": "美元账户", "label": "复合"}], "register": "中性", "sense_fingerprint": "美元|美国日常使用的钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0727280a-acea-49ed-8e15-f9af5e9803df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86713, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "美元", "is_correct": true, "explanation": "美元是美国的钱，去美国旅游应该带美元，符合句意。"}, {"text": "日元", "is_correct": false, "explanation": "语义：日元是日本的货币，去美国旅游用不到。"}, {"text": "欧元", "is_correct": false, "explanation": "语义：欧元是欧洲的货币，美国不用欧元，所以不该带欧元去美国。"}, {"text": "景点", "is_correct": false, "explanation": "搭配：“带”只能用于东西或钱，不能说“带景点”。"}], "explanations": {"美元": "美元是美国的钱，去美国旅游应该带美元，符合句意。", "日元": "语义：日元是日本的货币，去美国旅游用不到。", "欧元": "语义：欧元是欧洲的货币，美国不用欧元，所以不该带欧元去美国。", "景点": "搭配：“带”只能用于东西或钱，不能说“带景点”。"}, "sentence_index": 0, "correct_answer": "美元"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "哥哥从美元回来，给我带了二十美元。", "explanation": "这里应该用〈美国〉。美元是钱的名称，表示从哪里回来要用“美国”。"}, {"text": "这是一个美元的地方，风景很好。", "explanation": "这里应该用〈美丽〉。“美元”是货币名，不能修饰地方，形容风景优美要用“美丽”。"}, {"text": "这张桌子有三美元长。", "explanation": "这里应该用〈米〉。“美元”是货币单位，不能计量长度，表示长度要用“米”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7826ac8e-eb2c-4f1d-9120-80ce4bc6347b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86713, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "美元", "is_correct": true, "explanation": "美元是可以兑换的外币，出国前换一些美元很常见，符合句意。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能兑换，“换一些天气”说不通。"}, {"text": "行李", "is_correct": false, "explanation": "搭配：行李要“带”或“装”，不能说“换行李”。"}, {"text": "西红柿", "is_correct": false, "explanation": "语义：西红柿是蔬菜，不是可以兑换的东西，句子说不通。"}], "explanations": {"美元": "美元是可以兑换的外币，出国前换一些美元很常见，符合句意。", "天气": "语义：天气不能兑换，“换一些天气”说不通。", "行李": "搭配：行李要“带”或“装”，不能说“换行李”。", "西红柿": "语义：西红柿是蔬菜，不是可以兑换的东西，句子说不通。"}, "sentence_index": 6, "correct_answer": "美元"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位美元人很热情。", "explanation": "这里应该用〈美国人〉。美元是货币，不能用来指人。"}, {"text": "他会说美元，所以在国外很方便。", "explanation": "这里应该用〈英语〉。美元是货币，不是语言，“会说”后面不能接它。"}, {"text": "他大学的专业是美元。", "explanation": "这里应该用〈美术〉。“美元”是货币，不能作专业名称，应说“美术专业”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7826ac8e-eb2c-4f1d-9120-80ce4bc6347b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86713, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在机场换了一百个美元。", "corrected_sentence": "他在机场换了一百美元。", "error_description": "量词错误：“美元”本身是货币单位，数量词后不加个体量词“个”，应说“一百美元”，不能说“一百个美元”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7826ac8e-eb2c-4f1d-9120-80ce4bc6347b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86713, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把五百个美元换成了人民币。", "corrected_sentence": "我把五百美元换成了人民币。", "error_description": "量词错误：“美元”是货币单位，数量词后不加个体量词“个”，应说“五百美元”，不能说“五百个美元”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7826ac8e-eb2c-4f1d-9120-80ce4bc6347b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
