INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86716, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee70e2e-4902-4e6c-8abc-23b1965f5913') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86716, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "某个范围、群体或时间段以内。", "primary_collocate": null, "pronunciation": "lǐ miàn", "ipa": "li˨˩ mjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "我们班里面，小王跑得最快。", "target_word": "里面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这三本书里面，我最爱看这本。", "target_word": "里面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一年里面，他只回家两次。", "target_word": "里面", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "五个人里面有三个会游泳。", "target_word": "里面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些水果里面，苹果最便宜。", "target_word": "里面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在朋友里面年纪最大。", "target_word": "里面", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "两个月里面，他瘦了十斤。", "target_word": "里面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "全班同学里面，没有人比他高。", "target_word": "里面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些歌里面，我听过的只有一首。", "target_word": "里面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十个学生里面，他是最小的。", "target_word": "里面", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "某个范围、群体或时间段之内", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a432da1f-feea-49d0-a707-faedc977933d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86716, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "里面", "is_correct": true, "explanation": "正确答案。里面表示某个范围之内。"}, {"text": "立面", "is_correct": false, "explanation": "lì（第四声）与 lǐ（第三声）声调不同，意思是建筑物的立面，与范围无关。"}, {"text": "米面", "is_correct": false, "explanation": "mǐ 与 lǐ 声母不同（m 与 l），意思是大米和面粉。"}, {"text": "体面", "is_correct": false, "explanation": "tǐ 与 lǐ 声母不同（t 与 l），意思是有面子、有光彩。"}, {"text": "洗面", "is_correct": false, "explanation": "xǐ 与 lǐ 声母不同（x 与 l），意思是洗脸。"}], "explanations": {"里面": "正确答案。里面表示某个范围之内。", "立面": "lì（第四声）与 lǐ（第三声）声调不同，意思是建筑物的立面，与范围无关。", "米面": "mǐ 与 lǐ 声母不同（m 与 l），意思是大米和面粉。", "体面": "tǐ 与 lǐ 声母不同（t 与 l），意思是有面子、有光彩。", "洗面": "xǐ 与 lǐ 声母不同（x 与 l），意思是洗脸。"}, "sentence_index": null, "correct_answer": "里面"}, "level_3": {"options": [{"text": "里面", "is_correct": true, "explanation": "正确。里面表示“我们班”这个范围之内。"}, {"text": "空中", "is_correct": false, "explanation": "语义：空中指天空之中，与“我们班”所指的范围无关。"}, {"text": "身边", "is_correct": false, "explanation": "搭配：身边多指人的周围，不能用来指一个班级的范围。"}, {"text": "桌上", "is_correct": false, "explanation": "搭配：桌上指桌面，不能用来指一个班级的范围。"}], "explanations": {"里面": "正确。里面表示“我们班”这个范围之内。", "空中": "语义：空中指天空之中，与“我们班”所指的范围无关。", "身边": "搭配：身边多指人的周围，不能用来指一个班级的范围。", "桌上": "搭配：桌上指桌面，不能用来指一个班级的范围。"}, "sentence_index": 0, "correct_answer": "里面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这些书里面，我还买了一支笔。", "explanation": "这里应该用〈之外〉。里面表示在这些书之内，而句中买的是笔，不是书，应表示除这些书之外。"}, {"text": "马路里面有一家银行。", "explanation": "这里应该用〈对面〉。银行在马路的另一边，马路本身不能说是银行的所在范围。"}, {"text": "两个学生里面站着一位老师。", "explanation": "这里应该用〈中间〉。两人之间的位置不是两人的范围之内，“里面”表示范围，不表示两者之间的空间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee70e2e-4902-4e6c-8abc-23b1965f5913') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86716, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "里面", "is_correct": true, "explanation": "正确。里面表示两个月之内这段时间的范围。"}, {"text": "外面", "is_correct": false, "explanation": "语义：外面指某个范围之外，与“两个月里瘦了十斤”的意思相反。"}, {"text": "旁边", "is_correct": false, "explanation": "搭配：旁边指空间上的位置，不能用来指一段时间。"}, {"text": "上面", "is_correct": false, "explanation": "搭配：上面指物体的上方或表面，不能用来指一段时间。"}], "explanations": {"里面": "正确。里面表示两个月之内这段时间的范围。", "外面": "语义：外面指某个范围之外，与“两个月里瘦了十斤”的意思相反。", "旁边": "搭配：旁边指空间上的位置，不能用来指一段时间。", "上面": "搭配：上面指物体的上方或表面，不能用来指一段时间。"}, "sentence_index": 6, "correct_answer": "里面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "河里面有一座小桥。", "explanation": "这里应该用〈上面〉。小桥架在河的上方，不在河水里面；这里的“里面”是物体内部的用法，不表示某个范围之内。"}, {"text": "床里面站着一个小孩。", "explanation": "这里应该用〈旁边〉。小孩站在床边，不在床的内部；“里面”指物体的内部，床里面没有可以站人的空间，应说“床旁边”。"}, {"text": "墙里面挂着一幅画。", "explanation": "这里应该用〈上面〉。画挂在墙的表面，墙不是可以放东西的容器。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee70e2e-4902-4e6c-8abc-23b1965f5913') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86716, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这几家店外面，那家的菜最好吃。", "corrected_sentence": "这几家店里面，那家的菜最好吃。", "error_description": "错误：“这几家店外面”；正确：“这几家店里面”。“那家”就在这几家店的范围之内，表示范围之内要用“里面”，不能用“外面”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee70e2e-4902-4e6c-8abc-23b1965f5913') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86716, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们班里里面有三十个人。", "corrected_sentence": "我们班里面有三十个人。", "error_description": "“里面”是一个整体，“里”和“面”之间不能再加一个“里”，正确说法是“我们班里面有三十个人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee70e2e-4902-4e6c-8abc-23b1965f5913') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
