INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86717, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "周年是过了整整一年，或者几年。", "primary_collocate": null, "pronunciation": "zhōu nián", "ipa": "tʂoʊ̯˥ njɛn˧˥", "syllable_count": 2, "sentences": [{"text": "这台机器运行满一周年了。", "target_word": "周年", "complexity_tier": "T3", "furigana": "zhōu nián", "sentence_source": "generated"}, {"text": "这家店开业已经两周年了。", "target_word": "周年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他离开家乡快三周年了。", "target_word": "周年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗来我家整整一周年。", "target_word": "周年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师去国外工作已满五周年。", "target_word": "周年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们认识十周年了，还是好朋友。", "target_word": "周年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥通车刚过一周年。", "target_word": "周年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们搬到这里不到两周年。", "target_word": "周年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷去世已经三周年了，奶奶还是很想他。", "target_word": "周年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我学中文满一周年了，会说很多话。", "target_word": "周年", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "周年纪念", "label": "复合"}, {"form": "周年庆", "label": "复合"}], "register": "中性", "sense_fingerprint": "时间长度意义的周年：从某件事开始起整整满一年或几年", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb942baf-2f2e-4d1b-8c28-1bbea51ff9ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86717, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "周年", "is_correct": true, "explanation": "正确：“运行满一周年”指机器运行满整整一年，符合“满”的用法。"}, {"text": "集", "is_correct": false, "explanation": "语义：“集”指影视剧的集数，不能用来计算机器的运行时间。"}, {"text": "届", "is_correct": false, "explanation": "搭配：“届”指届次，不能与“运行”搭配来计时。"}, {"text": "课", "is_correct": false, "explanation": "语义：“课”指课时，与机器运行的时长不符。"}], "explanations": {"周年": "正确：“运行满一周年”指机器运行满整整一年，符合“满”的用法。", "集": "语义：“集”指影视剧的集数，不能用来计算机器的运行时间。", "届": "搭配：“届”指届次，不能与“运行”搭配来计时。", "课": "语义：“课”指课时，与机器运行的时长不符。"}, "sentence_index": 0, "correct_answer": "周年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们买了三周年苹果。", "explanation": "这里应该用〈斤〉。周年是时间单位，不能用来计量苹果，买苹果要说“斤”。"}, {"text": "这条河有三周年宽。", "explanation": "这里应该用〈米〉。周年是时间单位，不能用来计量宽度。"}, {"text": "他今年二十周年了。", "explanation": "这里应该用〈岁〉。周年指满整年的时间，人的年龄要说岁。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7107b31-8fc7-4fd6-a9d1-020d059188d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86717, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "周年", "is_correct": true, "explanation": "正确：“通车刚过一周年”指桥通车满一年不久，符合语境。"}, {"text": "幕", "is_correct": false, "explanation": "语义：“幕”指戏剧的一场，与桥的通车时间不符。"}, {"text": "章", "is_correct": false, "explanation": "语义：“章”指书籍的章节，不能用于桥的通车时长。"}, {"text": "局", "is_correct": false, "explanation": "搭配：“局”用于棋局或比赛，不与“通车”搭配。"}], "explanations": {"周年": "正确：“通车刚过一周年”指桥通车满一年不久，符合语境。", "幕": "语义：“幕”指戏剧的一场，与桥的通车时间不符。", "章": "语义：“章”指书籍的章节，不能用于桥的通车时长。", "局": "搭配：“局”用于棋局或比赛，不与“通车”搭配。"}, "sentence_index": 6, "correct_answer": "周年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们学校的周年有两千个。", "explanation": "这里应该用〈老师〉。周年是时间单位或纪念日，不能用来指学校里的人。"}, {"text": "我每周年练习中文，已经练了很多。", "explanation": "这里应该用〈每天〉。周年指整整一年或几年，不能表示每天的重复。"}, {"text": "他的周年很高，篮球打得好。", "explanation": "这里应该用〈个子〉。周年是时间单位，不能用来描述人的高矮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7107b31-8fc7-4fd6-a9d1-020d059188d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86717, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们结婚满一个周年了。", "corrected_sentence": "我们结婚满一周年了。", "error_description": "错误形式：“我们结婚满一个周年了”。正确形式：“我们结婚满一周年了”。原因：表示时长时，数词直接接“周年”，中间不加量词“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7107b31-8fc7-4fd6-a9d1-020d059188d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86717, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家餐厅开业满一次周年了。", "corrected_sentence": "这家餐厅开业满一周年了。", "error_description": "量词错误：“周年”前不能加“次”，“次”指次数，不能用来计算时间长度。应说“满一周年”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7107b31-8fc7-4fd6-a9d1-020d059188d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
