INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86718, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "每年到了的那一天的纪念，多用于结婚、成立等事件。", "primary_collocate": null, "pronunciation": "zhōu nián", "ipa": "tʂoʊ̯˥ njɛn˧˥", "syllable_count": 2, "sentences": [{"text": "今天是我们结婚五周年。", "target_word": "周年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司成立十周年，大家一起吃饭。", "target_word": "周年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸给妈妈买了花，庆祝结婚二十周年。", "target_word": "周年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校明天举行建校一百周年的活动。", "target_word": "周年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司今年迎来了成立十周年。", "target_word": "周年", "complexity_tier": "T3", "furigana": "zhōu nián", "sentence_source": "generated"}, {"text": "这家饭店开业三周年，所有菜都打折。", "target_word": "周年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年是国家成立七十五周年。", "target_word": "周年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父母去海边旅行，庆祝他们的结婚三十周年。", "target_word": "周年", "complexity_tier": "T3", "furigana": "zhōu nián", "sentence_source": "generated"}, {"text": "商场为了迎接开业五周年，搞了一个大型促销。", "target_word": "周年", "complexity_tier": "T3", "furigana": "zhōu nián", "sentence_source": "generated"}, {"text": "他忘了结婚十周年这一天，太太很生气。", "target_word": "周年", "complexity_tier": "T3", "furigana": "zhōu nián", "sentence_source": "generated"}], "morphological_forms": [{"form": "周年纪念", "label": "复合"}, {"form": "周年庆", "label": "复合"}], "register": "中性", "sense_fingerprint": "纪念日意义的周年：结婚、成立等事件每年到来的纪念日", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb942baf-2f2e-4d1b-8c28-1bbea51ff9ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86718, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "周年", "is_correct": true, "explanation": "正确：“结婚五周年”指结婚满五年的纪念日，与“今天是……”相符。"}, {"text": "月", "is_correct": false, "explanation": "语义：“五月”是月份名，不表示结婚满几个纪念周期。"}, {"text": "岁", "is_correct": false, "explanation": "搭配：“岁”用于年龄，不能说“结婚五岁”。"}, {"text": "季", "is_correct": false, "explanation": "语义：“季”指季节，与结婚纪念无关。"}], "explanations": {"周年": "正确：“结婚五周年”指结婚满五年的纪念日，与“今天是……”相符。", "月": "语义：“五月”是月份名，不表示结婚满几个纪念周期。", "岁": "搭配：“岁”用于年龄，不能说“结婚五岁”。", "季": "语义：“季”指季节，与结婚纪念无关。"}, "sentence_index": 0, "correct_answer": "周年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块布有两周年长。", "explanation": "这里应该用〈米〉。周年表示纪念日或整年的时间，不能用来计量长度。"}, {"text": "春节是中国最重要的周年。", "explanation": "这里应该用〈节日〉。春节是节日，不是某一事件的纪念日，不能说周年。"}, {"text": "他今年三十周年了。", "explanation": "这里应该用〈岁〉。人的年龄要说岁，周年不用于计算年龄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7107b31-8fc7-4fd6-a9d1-020d059188d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86718, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "周年", "is_correct": true, "explanation": "正确：“成立七十五周年”指国家成立满七十五年的纪念，与“今年是”相符。"}, {"text": "天", "is_correct": false, "explanation": "语义：“天”指日子，与“今年”矛盾，不能用来说国家成立的年数。"}, {"text": "世纪", "is_correct": false, "explanation": "语义：“世纪”指一百年，“七十五世纪”与“今年”的语境不符。"}, {"text": "代", "is_correct": false, "explanation": "搭配：“代”用于世代，不能用于计算国家成立的纪念。"}], "explanations": {"周年": "正确：“成立七十五周年”指国家成立满七十五年的纪念，与“今年是”相符。", "天": "语义：“天”指日子，与“今年”矛盾，不能用来说国家成立的年数。", "世纪": "语义：“世纪”指一百年，“七十五世纪”与“今年”的语境不符。", "代": "搭配：“代”用于世代，不能用于计算国家成立的纪念。"}, "sentence_index": 6, "correct_answer": "周年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们班的周年有三十个。", "explanation": "这里应该用〈同学〉。周年是纪念日或时间单位，不能用来指班里的人。"}, {"text": "这次周年我考得很好。", "explanation": "这里应该用〈考试〉。周年指纪念日，不能指考试这类事件。"}, {"text": "他的周年是一米八。", "explanation": "这里应该用〈身高〉。周年用于纪念日，不用于描述身高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7107b31-8fc7-4fd6-a9d1-020d059188d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86718, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们结婚五张周年了。", "corrected_sentence": "我们结婚五周年了。", "error_description": "量词错误：数词与“周年”之间不能加量词“张”，应说“结婚五周年”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7107b31-8fc7-4fd6-a9d1-020d059188d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86718, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这所学校建校一个周年了。", "corrected_sentence": "这所学校建校一周年了。", "error_description": "错误形式：“建校一个周年”。正确形式：“建校一周年”。原因：表示纪念年数时，数词后直接接“周年”，不用“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7107b31-8fc7-4fd6-a9d1-020d059188d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
