INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86720, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "球类运动项目，两队用脚踢球，把球踢进对方的球门。", "primary_collocate": null, "pronunciation": "zú qiú", "ipa": "tsu˧˥ tɕʰiu˧˥", "syllable_count": 2, "sentences": [{"text": "我很喜欢足球，每个周末都看比赛。", "target_word": "足球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就爱踢足球。", "target_word": "足球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "足球比赛有两个队，每队十一个人。", "target_word": "足球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多中国人喜欢足球，晚上常常看比赛。", "target_word": "足球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥在学校天天踢足球。", "target_word": "足球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "足球是世界上很受欢迎的运动。", "target_word": "足球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "足球和篮球，你更喜欢哪一个？", "target_word": "足球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸喜欢看足球，妈妈喜欢看电影。", "target_word": "足球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天下午我们去公园踢足球。", "target_word": "足球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他踢足球踢得很好，很多人都认识他。", "target_word": "足球", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "足球队", "label": "复合"}, {"form": "足球赛", "label": "复合"}, {"form": "足球场", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词，指两队比赛、用脚踢球进门的球类运动项目，如“踢足球”“看足球”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c202a5e-a9ce-434e-8067-66e8bfcf13bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86720, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "足球", "is_correct": true, "explanation": "正确答案。“喜欢足球，每个周末都看比赛”，足球是可以看比赛的运动。"}, {"text": "地震", "is_correct": false, "explanation": "语义：“喜欢地震”不成立，句意不通。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：“喜欢垃圾”不成立，句意不通。"}, {"text": "病毒", "is_correct": false, "explanation": "语义：“喜欢病毒”不成立，句意不通。"}], "explanations": {"足球": "正确答案。“喜欢足球，每个周末都看比赛”，足球是可以看比赛的运动。", "地震": "语义：“喜欢地震”不成立，句意不通。", "垃圾": "语义：“喜欢垃圾”不成立，句意不通。", "病毒": "语义：“喜欢病毒”不成立，句意不通。"}, "sentence_index": 0, "correct_answer": "足球"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我看了一张足球。", "explanation": "这里应该用〈场〉。足球比赛的量词是“场”，“张”用于平面的东西。"}, {"text": "妹妹挥拍打足球。", "explanation": "这里应该用〈网球〉。挥拍是网球的动作，足球不用球拍。"}, {"text": "他晚上在家里下足球。", "explanation": "这里应该用〈象棋〉。“下”用于棋类，足球不能下。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07347810-90e0-4782-b133-85a9486f945f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86720, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "足球", "is_correct": true, "explanation": "正确答案。“足球和篮球”是两种并列的体育运动，可以比较喜欢哪一个。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是体育运动，无法与篮球并列比较喜欢哪一个。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：感冒是疾病，不能作为选择的对象，句子不通。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：“垃圾”不能与“篮球”并列作为可以比较喜欢的对象，句子不通。"}], "explanations": {"足球": "正确答案。“足球和篮球”是两种并列的体育运动，可以比较喜欢哪一个。", "天空": "语义：天空不是体育运动，无法与篮球并列比较喜欢哪一个。", "感冒": "语义：感冒是疾病，不能作为选择的对象，句子不通。", "垃圾": "语义：“垃圾”不能与“篮球”并列作为可以比较喜欢的对象，句子不通。"}, "sentence_index": 6, "correct_answer": "足球"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是个足球。", "explanation": "这里应该用〈运动员〉。足球是运动项目，不能直接表示人的身份。"}, {"text": "我喜欢一条足球运动。", "explanation": "这里应该用〈项〉。足球运动的量词是“项”，“条”多用于细长的东西。"}, {"text": "他每天下午在游泳池里游足球。", "explanation": "这里应该用〈泳〉。“游”用于游泳，足球是用脚踢的运动，不能“游”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07347810-90e0-4782-b133-85a9486f945f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86720, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹妹喝了足球。", "corrected_sentence": "妹妹踢了足球。", "error_description": "搭配错误：“喝”不能用于足球，足球是运动项目，应说“踢了足球”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07347810-90e0-4782-b133-85a9486f945f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86720, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我昨天看了一把足球。", "corrected_sentence": "我昨天看了一场足球。", "error_description": "错误在量词。足球作为体育比赛时，量词用“场”；“把”用于有柄的东西，不能用来数足球，应说“看了一场足球”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07347810-90e0-4782-b133-85a9486f945f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86721, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "去年", "is_correct": true, "explanation": "“去年”指今年之前的一年，与“来年”方向相反，是反义关系。"}, {"text": "冬天", "is_correct": false, "explanation": "与“来年”没有反义关系，冬天是季节。"}, {"text": "傍晚", "is_correct": false, "explanation": "与“来年”没有反义关系，傍晚指一天的某个时段。"}, {"text": "钢笔", "is_correct": false, "explanation": "与“来年”没有任何关系，钢笔是文具。"}], "correct_answer": "去年", "explanations": {"去年": "“去年”指今年之前的一年，与“来年”方向相反，是反义关系。", "冬天": "与“来年”没有反义关系，冬天是季节。", "傍晚": "与“来年”没有反义关系，傍晚指一天的某个时段。", "钢笔": "与“来年”没有任何关系，钢笔是文具。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cf7ce71-ddfc-406e-88fa-d631d3cd9ba7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86721, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "去年", "is_correct": true, "explanation": "“去年”指今年之前的一年，与“来年”方向相反，是反义关系。"}, {"text": "秋天", "is_correct": false, "explanation": "与“来年”没有反义关系，秋天是季节。"}, {"text": "清晨", "is_correct": false, "explanation": "与“来年”没有反义关系，清晨指一天的开始。"}, {"text": "桌子", "is_correct": false, "explanation": "与“来年”没有任何关系，桌子是家具。"}], "correct_answer": "去年", "explanations": {"去年": "“去年”指今年之前的一年，与“来年”方向相反，是反义关系。", "秋天": "与“来年”没有反义关系，秋天是季节。", "清晨": "与“来年”没有反义关系，清晨指一天的开始。", "桌子": "与“来年”没有任何关系，桌子是家具。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cf7ce71-ddfc-406e-88fa-d631d3cd9ba7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86721, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "来年是今年过完以后的那一年。", "primary_collocate": null, "pronunciation": "lái nián", "ipa": "lai˧˥ njɛn˧˥", "syllable_count": 2, "sentences": [{"text": "今年过完了，来年就到了。", "target_word": "来年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "来年我就十八岁了。", "target_word": "来年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这棵树来年会开更多花。", "target_word": "来年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年先存钱，来年再买车。", "target_word": "来年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家来年要搬到新房子。", "target_word": "来年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "来年的今天，我们再见面吧。", "target_word": "来年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年我读二年级，来年读三年级。", "target_word": "来年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说来年会有新同学。", "target_word": "来年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟来年要上小学了。", "target_word": "来年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他攒了钱，来年想去旅行。", "target_word": "来年", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "时间词：今年过去之后紧接着的那一年", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T1: 3 words above tier T1 (max 2): 我读 (Zipf 3.53), 二年级 (Zipf 3.21), 三年级 (Zipf 3.41)']::text[], '7673fbc5-6e78-4bef-848b-ae27656be33f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86721, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "来年", "is_correct": true, "explanation": "“来年”紧接在“今年过完了”之后，句意通顺。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不会“到了”，与句意不符。"}, {"text": "上午", "is_correct": false, "explanation": "搭配：“上午”与“今年过完了”时间冲突，不能接“就到了”。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是时间，无法“到了”。"}], "explanations": {"来年": "“来年”紧接在“今年过完了”之后，句意通顺。", "窗户": "语义：窗户不会“到了”，与句意不符。", "上午": "搭配：“上午”与“今年过完了”时间冲突，不能接“就到了”。", "石头": "语义：石头不是时间，无法“到了”。"}, "sentence_index": 0, "correct_answer": "来年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈每天早上来年做饭。", "explanation": "这里不能用〈来年〉。〈来年〉表示一整年的时间范围，不能用来表示反复出现的习惯。"}, {"text": "他上午十点来年去上学。", "explanation": "这里不能用〈来年〉。“来年”指一年，不能用来指一个时刻。"}, {"text": "我一下子就来年吃完了饭。", "explanation": "这里不能用〈来年〉。“来年”指一年，不能用来表示瞬间完成的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cf7ce71-ddfc-406e-88fa-d631d3cd9ba7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86721, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "来年", "is_correct": true, "explanation": "“来年”表示下一年，与“今年我读二年级”前后衔接，句意通顺。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：空格处需要表示时间的词，“小猫”不是时间，句意不通。"}, {"text": "早上", "is_correct": false, "explanation": "语义：“早上”指一天中的时段，不能和“今年”对应表示下一个学年，句意不通。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙不会读书，句意不通。"}], "explanations": {"来年": "“来年”表示下一年，与“今年我读二年级”前后衔接，句意通顺。", "小猫": "语义：空格处需要表示时间的词，“小猫”不是时间，句意不通。", "早上": "语义：“早上”指一天中的时段，不能和“今年”对应表示下一个学年，句意不通。", "钥匙": "语义：钥匙不会读书，句意不通。"}, "sentence_index": 6, "correct_answer": "来年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们每周来年打扫一次教室。", "explanation": "这里不能用〈来年〉。〈来年〉表示一整年的时间范围，不能用来表示反复出现的周期。"}, {"text": "妹妹半小时来年写完了作业。", "explanation": "这里不能用〈来年〉。〈来年〉表示一整年的时间范围，不能用来表示几十分钟这样很短的时间。"}, {"text": "他每个小时来年喝一杯水。", "explanation": "这里不能用〈来年〉。〈来年〉表示一整年的时间范围，不能用来表示反复出现的周期。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cf7ce71-ddfc-406e-88fa-d631d3cd9ba7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86721, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "来年我们一起去了登山吧。", "corrected_sentence": "来年我们一起去登山吧。", "error_description": "“了”用错：“来年”指将来，句子是提议未来一起去登山，不能用表示完成的“了”。错误形式“来年我们一起去了登山吧。”，正确形式“来年我们一起去登山吧。”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cf7ce71-ddfc-406e-88fa-d631d3cd9ba7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86721, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "来年地学费我已经准备好了。", "corrected_sentence": "来年的学费我已经准备好了。", "error_description": "助词用错：“来年”修饰名词“学费”时要用“的”，不用“地”。“地”用于修饰动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cf7ce71-ddfc-406e-88fa-d631d3cd9ba7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
