INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86722, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指明年；也指以后的一年。", "primary_collocate": null, "pronunciation": "lái nián", "ipa": "lai˧˥ njɛn˧˥", "syllable_count": 2, "sentences": [{"text": "来年春天，我们打算去北京。", "target_word": "来年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说来年要换一份工作。", "target_word": "来年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年雨水多，来年一定丰收。", "target_word": "来年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司来年会招更多的人。", "target_word": "来年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的花很漂亮，我想来年春天带家人去看。", "target_word": "来年", "complexity_tier": "T3", "furigana": "zhè lǐ de huā hěn piào liang wǒ xiǎng lái nián chūn tiān dài jiā rén qù kàn", "sentence_source": "generated"}, {"text": "农民盼着来年有个好收成。", "target_word": "来年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "来年的计划，我已经写好了。", "target_word": "来年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "祝你来年身体健康，工作顺利。", "target_word": "来年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们来年夏天就要结婚了。", "target_word": "来年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "来年这个时候，我已经毕业了。", "target_word": "来年", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "时间词：明年，或将来的某一年", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7673fbc5-6e78-4bef-848b-ae27656be33f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86722, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "来年", "is_correct": true, "explanation": "“来年”指明年，与后文“打算去北京”表示的将来相符。"}, {"text": "清晨", "is_correct": false, "explanation": "搭配：“清晨”不能修饰“春天”，这样说法不通。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑不是时间词，不能作“春天”的时间修饰语，句意不通。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙不是时间，句意不通。"}], "explanations": {"来年": "“来年”指明年，与后文“打算去北京”表示的将来相符。", "清晨": "搭配：“清晨”不能修饰“春天”，这样说法不通。", "电脑": "语义：电脑不是时间词，不能作“春天”的时间修饰语，句意不通。", "钥匙": "语义：钥匙不是时间，句意不通。"}, "sentence_index": 0, "correct_answer": "来年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天晚上来年写作业。", "explanation": "这里不能用〈来年〉。〈来年〉表示一整年的时间范围，不能用来表示反复出现的习惯。"}, {"text": "我们上午十点来年开会。", "explanation": "这里不能用〈来年〉。“来年”指一整年，不能用来指一个时刻。"}, {"text": "他一下子就来年学会了游泳。", "explanation": "这里不能用〈来年〉。“来年”指一年，不能用来表示瞬间完成的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cf7ce71-ddfc-406e-88fa-d631d3cd9ba7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86722, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "来年", "is_correct": true, "explanation": "“来年”修饰“计划”，表示明年或将来的计划，句意通顺。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会制订计划，句意不通。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不能作“计划”的定语，句意不通。"}, {"text": "笑声", "is_correct": false, "explanation": "搭配：“笑声”不能与“计划”搭配，“写好”也不合适。"}], "explanations": {"来年": "“来年”修饰“计划”，表示明年或将来的计划，句意通顺。", "石头": "语义：石头不会制订计划，句意不通。", "窗户": "语义：窗户不能作“计划”的定语，句意不通。", "笑声": "搭配：“笑声”不能与“计划”搭配，“写好”也不合适。"}, "sentence_index": 6, "correct_answer": "来年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈每个星期来年洗一次衣服。", "explanation": "这里不能用〈来年〉。〈来年〉表示一整年的时间范围，不能用来表示反复出现的周期。"}, {"text": "我下午三点来年去图书馆。", "explanation": "这里不能用〈来年〉。“来年”指一年，不能用来指一个时刻。"}, {"text": "他每个小时来年喝一杯水。", "explanation": "这里不能用〈来年〉。〈来年〉表示一整年的时间范围，不能用来表示反复出现的周期。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cf7ce71-ddfc-406e-88fa-d631d3cd9ba7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86722, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们来年夏天去了海边。", "corrected_sentence": "我们来年夏天去海边。", "error_description": "“了”用错：“来年”指将来，“去海边”是未来的计划，不能用表示完成的“了”。错误形式“我们来年夏天去了海边。”，正确形式“我们来年夏天去海边。”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cf7ce71-ddfc-406e-88fa-d631d3cd9ba7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86722, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "来年地目标我已经定好了。", "corrected_sentence": "来年的目标我已经定好了。", "error_description": "助词用错：“来年”修饰名词“目标”时要用“的”，不用“地”。“地”用于修饰动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cf7ce71-ddfc-406e-88fa-d631d3cd9ba7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
