INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86723, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "首都是一个国家里最重要的城市，国家管事的人在那里。", "primary_collocate": null, "pronunciation": "shǒu dū", "ipa": "ʂoʊ˨˩˦ tu˥", "syllable_count": 2, "sentences": [{"text": "你知道哪个城市是韩国的首都吗？", "target_word": "首都", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "首都里有总统住的地方。", "target_word": "首都", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想去英国的首都看看。", "target_word": "首都", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "澳大利亚的首都不是悉尼。", "target_word": "首都", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多重要的人都在首都工作。", "target_word": "首都", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "首都的路上车很多。", "target_word": "首都", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我的朋友住在首都。", "target_word": "首都", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "中国的首都是哪个城市？", "target_word": "首都", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在首都工作了三年。", "target_word": "首都", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个国家的首都有很多老房子。", "target_word": "首都", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个首都", "label": "量词"}, {"form": "首都机场", "label": "复合"}], "register": "中性", "sense_fingerprint": "一国最重要的城市，管理国家的人在那里", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cfcb1-6d77-42d7-8839-f55207ff99d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86723, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "首都", "is_correct": true, "explanation": "正确：指一国最重要、管理国家的人所在的城市，与“哪个城市是韩国的……”搭配。"}, {"text": "面积", "is_correct": false, "explanation": "搭配：“哪个城市是……的面积”不成立，“面积”是量度，不能指城市本身。"}, {"text": "总统", "is_correct": false, "explanation": "语义：总统是人，不是城市，句子说“哪个城市是韩国的总统”不通。"}, {"text": "人口", "is_correct": false, "explanation": "语义：人口是数量，不能用来说明哪个城市是韩国的身份。"}], "explanations": {"首都": "正确：指一国最重要、管理国家的人所在的城市，与“哪个城市是韩国的……”搭配。", "面积": "搭配：“哪个城市是……的面积”不成立，“面积”是量度，不能指城市本身。", "总统": "语义：总统是人，不是城市，句子说“哪个城市是韩国的总统”不通。", "人口": "语义：人口是数量，不能用来说明哪个城市是韩国的身份。"}, "sentence_index": 0, "correct_answer": "首都"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "广西的首都是南宁。", "explanation": "这里应该用“首府”。首都指国家的政府所在地；广西是自治区，它的政府所在地叫首府。"}, {"text": "湖南的首都是长沙。", "explanation": "这里应该用“省会”。首都指国家的政府所在地；湖南是省，它的政府所在地叫省会。"}, {"text": "这所学校的首都很大。", "explanation": "这里应该用“校园”。首都指国家的政府所在地，学校的占地要用校园。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df95e100-f8a6-4de5-a7f9-cc8b779e0c80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86723, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "首都", "is_correct": true, "explanation": "正确：指国家的政府所在地，朋友住在那里，句意通顺。"}, {"text": "数学", "is_correct": false, "explanation": "配价：“住在”后要接处所，数学不是处所，句子不成立。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：人可以住在海边，但不能住在海洋里，句意不通。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙是小物件，不是可以居住的地方，句意不通。"}], "explanations": {"首都": "正确：指国家的政府所在地，朋友住在那里，句意通顺。", "数学": "配价：“住在”后要接处所，数学不是处所，句子不成立。", "海洋": "语义：人可以住在海边，但不能住在海洋里，句意不通。", "钥匙": "语义：钥匙是小物件，不是可以居住的地方，句意不通。"}, "sentence_index": 6, "correct_answer": "首都"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家银行的首都在北京。", "explanation": "这里应该用“总部”。首都指国家的政府所在地，银行的总办事机构要用总部。"}, {"text": "这家商场的首都很热闹。", "explanation": "这里应该用“中心区”。首都指国家的政府所在地，商场里热闹的区域要说中心区。"}, {"text": "这座工厂的首都很大。", "explanation": "这里应该用“厂区”。首都指国家的政府所在地，工厂的占地要说厂区。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df95e100-f8a6-4de5-a7f9-cc8b779e0c80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86723, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条首都有很多博物馆。", "corrected_sentence": "这个首都有很多博物馆。", "error_description": "量词错误：“条”用于细长的东西，不能修饰首都；应用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df95e100-f8a6-4de5-a7f9-cc8b779e0c80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86723, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想首都找一份工作。", "corrected_sentence": "我想在首都找一份工作。", "error_description": "介词遗漏：“在首都”表示地点，要用介词“在”引出，不能直接说“首都找一份工作”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df95e100-f8a6-4de5-a7f9-cc8b779e0c80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
