INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86725, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "分钟是用来数时间的，六十分钟是一小时。", "primary_collocate": null, "pronunciation": "fēn zhōng", "ipa": "fən˥ ʈʂʊŋ˥", "syllable_count": 2, "sentences": [{"text": "一小时有六十分钟。", "target_word": "分钟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我走路去学校要十五分钟。", "target_word": "分钟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影还有五分钟就开始了。", "target_word": "分钟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请等我两分钟，好吗？", "target_word": "分钟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天跑步三十分钟。", "target_word": "分钟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个菜要煮二十分钟才能熟。", "target_word": "分钟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说休息十分钟再上课。", "target_word": "分钟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公共汽车每五分钟来一辆。", "target_word": "分钟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我迟到了十分钟，老师没生气。", "target_word": "分钟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他睡了五分钟就醒了。", "target_word": "分钟", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "分鐘", "label": "繁体"}], "register": "通用", "sense_fingerprint": "用来数时间的单位，几分钟、一小时有六十分钟", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93ba1550-0d24-40f4-930c-c7587d5653db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86725, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分钟", "is_correct": true, "explanation": "正确。分钟是时间单位，一小时有六十分钟。"}, {"text": "星期", "is_correct": false, "explanation": "语义：“一小时”之内不可能有六十星期，与前文的时长矛盾。"}, {"text": "天", "is_correct": false, "explanation": "语义：“一小时”之内不可能有六十天，与前文的时长矛盾。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“时间”是不可数的概括名词，不能与“六十”直接组合计数。"}], "explanations": {"分钟": "正确。分钟是时间单位，一小时有六十分钟。", "星期": "语义：“一小时”之内不可能有六十星期，与前文的时长矛盾。", "天": "语义：“一小时”之内不可能有六十天，与前文的时长矛盾。", "时间": "搭配：“时间”是不可数的概括名词，不能与“六十”直接组合计数。"}, "sentence_index": 0, "correct_answer": "分钟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他记住了开会的分钟。", "explanation": "这里应该用〈时刻〉。分钟表示时间的长短，指开会的那个确切时间点要用时刻。"}, {"text": "这个角是三十度零五分钟。", "explanation": "这里应该用〈分〉。这是角度单位，分钟只用于计量时间，不能用来计量角度。"}, {"text": "我们花了一段分钟讨论这个问题。", "explanation": "这里应该用〈时间〉。分钟是固定的时长，不能用“一段”来修饰；说不确定的一段时间要用“时间”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51e94512-9e25-4c76-b7c1-a48af2308abf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86725, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分钟", "is_correct": true, "explanation": "正确。“休息十分钟”是常见搭配，分钟计量休息的时长。"}, {"text": "人", "is_correct": false, "explanation": "语义：“休息”后接的应是时长，“十人”与“休息”的对象不相符，句子不通。"}, {"text": "问题", "is_correct": false, "explanation": "语义：“问题”不是可以休息的时长，“休息十问题”与句意矛盾。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“空气”是不可数名词，不能直接与数词“十”组合。"}], "explanations": {"分钟": "正确。“休息十分钟”是常见搭配，分钟计量休息的时长。", "人": "语义：“休息”后接的应是时长，“十人”与“休息”的对象不相符，句子不通。", "问题": "语义：“问题”不是可以休息的时长，“休息十问题”与句意矛盾。", "空气": "搭配：“空气”是不可数名词，不能直接与数词“十”组合。"}, "sentence_index": 6, "correct_answer": "分钟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块布长五分钟，正好做一件衣服。", "explanation": "这里应该用〈米〉。分钟只计量时间，不能用来说布的长度。"}, {"text": "分钟转了一圈，就过了一个小时。", "explanation": "这里应该用〈分针〉。分钟是时间单位，钟面上转动的指针要用分针。"}, {"text": "现在是五分钟，他还没醒。", "explanation": "这里应该用〈五点〉。分钟是时长单位，不能用来说钟点；问时刻要说“几点”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51e94512-9e25-4c76-b7c1-a48af2308abf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86725, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他等了十只分钟。", "corrected_sentence": "他等了十分钟。", "error_description": "错误：表示时长的“分钟”前不能加量词“只”，应直接说“十分钟”；“十只分钟”量词用错，应说“他等了十分钟”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51e94512-9e25-4c76-b7c1-a48af2308abf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86725, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我坐车三分钟的就到了。", "corrected_sentence": "我坐车三分钟就到了。", "error_description": "错误：“三分钟”后不能加“的”再接“就到了”，“的”多余；应说“我坐车三分钟就到了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51e94512-9e25-4c76-b7c1-a48af2308abf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
