INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86728, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "皮肤黑色的人种；一般指非洲裔的人。", "primary_collocate": null, "pronunciation": "hēi rén", "ipa": "xeɪ˥ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "这位黑人歌手唱得非常好听。", "target_word": "黑人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的同学里有一位黑人朋友。", "target_word": "黑人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是一个来自非洲的黑人。", "target_word": "黑人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个黑人男孩正在公园里踢球。", "target_word": "黑人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家有白人，也有黑人。", "target_word": "黑人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "马丁·路德·金是一位著名的黑人领袖。", "target_word": "黑人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里的黑人医生帮助了很多病人。", "target_word": "黑人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她嫁给了一个美国黑人。", "target_word": "黑人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "篮球队里有三个黑人，两个白人。", "target_word": "黑人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位黑人作家写了很多关于家乡的书。", "target_word": "黑人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}], "register": "中性", "sense_fingerprint": "人种：非洲裔的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19b140c7-e308-4628-aaa0-d46ef4cd89fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86728, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "黑人", "is_correct": true, "explanation": "正确。“黑人”指非洲裔的人，可以与量词“位”和“歌手”搭配，符合句子。"}, {"text": "猫咪", "is_correct": false, "explanation": "语义：“猫咪”是动物，不能指称“这位”所说的人，也不能做“歌手”。"}, {"text": "课桌", "is_correct": false, "explanation": "搭配：“课桌”不能用量词“位”来数，也不能做“歌手”的修饰语。"}, {"text": "花园", "is_correct": false, "explanation": "语义：“花园”是场所，不是人，与“这位……歌手”的所指矛盾。"}], "explanations": {"黑人": "正确。“黑人”指非洲裔的人，可以与量词“位”和“歌手”搭配，符合句子。", "猫咪": "语义：“猫咪”是动物，不能指称“这位”所说的人，也不能做“歌手”。", "课桌": "搭配：“课桌”不能用量词“位”来数，也不能做“歌手”的修饰语。", "花园": "语义：“花园”是场所，不是人，与“这位……歌手”的所指矛盾。"}, "sentence_index": 0, "correct_answer": "黑人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位年轻人是一名很厉害的黑人，能侵入别人的电脑。", "explanation": "这里应该用〈黑客〉。“黑客”指擅长侵入计算机系统的人，“黑人”指人种，不能用来说这种人。"}, {"text": "比赛中途冒出了一匹黑人，最后拿了冠军。", "explanation": "这里应该用〈黑马〉。“黑马”指比赛中出人意料获胜的选手，“黑人”指人种，这里不能用。"}, {"text": "他是这起案件的幕后黑人。", "explanation": "这里应该用〈黑手〉。“幕后黑手”指暗中策划坏事的人，“黑人”指人种，不能表示这个意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63a6e138-c20d-4a52-81ce-9599688f9dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86728, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "黑人", "is_correct": true, "explanation": "正确。“黑人”指非洲裔的人，可以修饰“医生”，符合“电影里的”这一人物语境。"}, {"text": "花盆", "is_correct": false, "explanation": "语义：“花盆”是容器，不能指人，与“电影里的……医生”的所指矛盾。"}, {"text": "玻璃", "is_correct": false, "explanation": "搭配：“玻璃”不能修饰“医生”这类表示职业的人，这个位置要用能表示人的词。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：“黑板”是教室里的物品，不能与“医生”组成人物称谓。"}], "explanations": {"黑人": "正确。“黑人”指非洲裔的人，可以修饰“医生”，符合“电影里的”这一人物语境。", "花盆": "语义：“花盆”是容器，不能指人，与“电影里的……医生”的所指矛盾。", "玻璃": "搭配：“玻璃”不能修饰“医生”这类表示职业的人，这个位置要用能表示人的词。", "黑板": "语义：“黑板”是教室里的物品，不能与“医生”组成人物称谓。"}, "sentence_index": 6, "correct_answer": "黑人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家饭馆是个黑人，专门宰客。", "explanation": "这里应该用〈黑店〉。“黑店”指暗中坑害顾客的店，“黑人”指人，不能用来说饭馆。"}, {"text": "教室里的黑人很干净，老师每天都擦。", "explanation": "这里应该用〈黑板〉。“黑板”是教室里写字的板，“黑人”指人，不能指这个东西。"}, {"text": "天文学家观测到了一个新的黑人。", "explanation": "这里应该用〈黑洞〉。“黑洞”是天文学中的天体，“黑人”指人，不能指天体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63a6e138-c20d-4a52-81ce-9599688f9dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86728, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们班有一只黑人同学，他很聪明。", "corrected_sentence": "我们班有一位黑人同学，他很聪明。", "error_description": "错误形式是“一只黑人同学”，正确形式是“一位黑人同学”。“只”用于动物或成对的东西，指人要用量词“位”或“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63a6e138-c20d-4a52-81ce-9599688f9dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86728, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那位年轻的很黑人医生很有名。", "corrected_sentence": "那位年轻的黑人医生很有名。", "error_description": "错误形式是“很黑人”，“很”不能修饰名词“黑人”，应去掉。正确形式是“年轻的黑人医生”，“黑人”直接修饰“医生”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63a6e138-c20d-4a52-81ce-9599688f9dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
