INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86729, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "十分是非常、特别的意思。", "primary_collocate": null, "pronunciation": "shí fēn", "ipa": "ʂɻ̩˧˥ fən˥", "syllable_count": 2, "sentences": [{"text": "这本书十分有意思。", "target_word": "十分", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他今天一直在工作，十分累。", "target_word": "十分", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师对我们十分热情。", "target_word": "十分", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈做的饭十分香。", "target_word": "十分", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个城市的夏天十分热。", "target_word": "十分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小王对这份工作十分满意。", "target_word": "十分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事对我十分重要，请你一定帮忙。", "target_word": "十分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他刚来中国，学习却十分认真。", "target_word": "十分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条街晚上十分热闹，有很多小吃摊。", "target_word": "十分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山上的空气十分新鲜，很多人早上来这里散步。", "target_word": "十分", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "程度副词：非常、特别，放在形容词前加强程度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3100c7d4-8539-4c18-af4c-52368be70353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86729, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "十分", "is_correct": true, "explanation": "正确：十分（shí fēn），意思是非常、特别。"}, {"text": "失分", "is_correct": false, "explanation": "shī（第一声）与 shí（第二声）声调不同，意思是失去分数。"}, {"text": "十份", "is_correct": false, "explanation": "fèn（第四声）与 fēn（第一声）声调不同，意思是十份。"}, {"text": "石粉", "is_correct": false, "explanation": "fěn（第三声）与 fēn（第一声）声调不同，意思是石头磨成的粉。"}, {"text": "十封", "is_correct": false, "explanation": "fēng 与 fēn 韵母不同（ng 与 n），意思是十封（信）。"}], "explanations": {"十分": "正确：十分（shí fēn），意思是非常、特别。", "失分": "shī（第一声）与 shí（第二声）声调不同，意思是失去分数。", "十份": "fèn（第四声）与 fēn（第一声）声调不同，意思是十份。", "石粉": "fěn（第三声）与 fēn（第一声）声调不同，意思是石头磨成的粉。", "十封": "fēng 与 fēn 韵母不同（ng 与 n），意思是十封（信）。"}, "sentence_index": null, "correct_answer": "十分"}, "level_3": {"options": [{"text": "十分", "is_correct": true, "explanation": "正确：“十分”加强“有意思”的程度，表示非常有意思。"}, {"text": "只", "is_correct": false, "explanation": "语义：“只”表示限定，“这本书只有意思”指只有趣味、别无用处，与“十分”的程度义不符。"}, {"text": "曾", "is_correct": false, "explanation": "语义：“曾”指过去，与对当前的评价不符，句子意思不通。"}, {"text": "已", "is_correct": false, "explanation": "语义：“已”表示已经完成，不能用来说明“有意思”的程度，句子意思不通。"}], "explanations": {"十分": "正确：“十分”加强“有意思”的程度，表示非常有意思。", "只": "语义：“只”表示限定，“这本书只有意思”指只有趣味、别无用处，与“十分”的程度义不符。", "曾": "语义：“曾”指过去，与对当前的评价不符，句子意思不通。", "已": "语义：“已”表示已经完成，不能用来说明“有意思”的程度，句子意思不通。"}, "sentence_index": 0, "correct_answer": "十分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们十分早点回家吧。", "explanation": "这里应该用〈尽量〉。“十分”表示程度很高，不表示尽力去做，要说“尽量早点”。"}, {"text": "我想换十分快一点的车。", "explanation": "这里应该用〈更〉。“十分”不能与“一点”连用表示比较，要说“更快一点”。"}, {"text": "这件衣服十分有点大，我想换小一点的。", "explanation": "这里应该用〈稍微〉。“十分”表示程度很高，不能与“有点”连用，说略大要用“稍微”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa6461e6-920a-4182-a42e-c248a1792d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86729, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "十分", "is_correct": true, "explanation": "正确：“十分”修饰“重要”，表示程度很高。"}, {"text": "不", "is_correct": false, "explanation": "语义：“不重要”与后句“请你一定帮忙”矛盾。"}, {"text": "未", "is_correct": false, "explanation": "语法：“未”表示没有发生，不能这样修饰“重要”，句子不通。"}, {"text": "却", "is_correct": false, "explanation": "搭配：“却”表示转折，需要前文有对比语境，这里句子不通。"}], "explanations": {"十分": "正确：“十分”修饰“重要”，表示程度很高。", "不": "语义：“不重要”与后句“请你一定帮忙”矛盾。", "未": "语法：“未”表示没有发生，不能这样修饰“重要”，句子不通。", "却": "搭配：“却”表示转折，需要前文有对比语境，这里句子不通。"}, "sentence_index": 6, "correct_answer": "十分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这碗汤十分好喝了！", "explanation": "这里应该用〈太〉。“十分”不能与“了”搭配表示感叹，要说“太好喝了”。"}, {"text": "你十分把门关上吧。", "explanation": "这里应该用〈赶紧〉。“十分”表示程度，不能表示催促，要说“赶紧把门关上”。"}, {"text": "我们要十分准备这次考试。", "explanation": "这里应该用〈充分〉。“十分”作程度副词，修饰形容词或心理动词，不修饰动作“准备”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa6461e6-920a-4182-a42e-c248a1792d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86729, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这部电影十分比那部好看，大家都爱看。", "corrected_sentence": "这部电影比那部好看，大家都爱看。", "error_description": "搭配错误：「十分」是程度副词，不能用在「比」字句中；比较句中应去掉「十分」。正确句是「这部电影比那部好看，大家都爱看」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa6461e6-920a-4182-a42e-c248a1792d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86729, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件事对他很十分重要，希望你能来。", "corrected_sentence": "这件事对他十分重要，希望你能来。", "error_description": "叠用错误：“很”和“十分”都是程度副词，不能叠用，应只用“十分”。正确句是「这件事对他十分重要，希望你能来」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa6461e6-920a-4182-a42e-c248a1792d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
