INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86730, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示程度很高；很，非常。", "primary_collocate": null, "pronunciation": "shí fēn", "ipa": "ʂɻ̩˧˥ fən˥", "syllable_count": 2, "sentences": [{"text": "今天天气十分好。", "target_word": "十分", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个菜十分好吃。", "target_word": "十分", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她的汉语说得十分流利。", "target_word": "十分", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我十分喜欢这个新同学。", "target_word": "十分", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "听到这个好消息，大家都十分高兴。", "target_word": "十分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "图书馆里十分安静，没有人说话。", "target_word": "十分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他工作十分努力，老板常常夸他。", "target_word": "十分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "昨天的比赛十分精彩，我们看得很开心。", "target_word": "十分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学好一门外语，每天练习十分重要。", "target_word": "十分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家饭馆的服务十分周到，客人都很满意。", "target_word": "十分", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "程度副词：表示程度很高，修饰形容词或心理动词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3100c7d4-8539-4c18-af4c-52368be70353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86730, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "十分", "is_correct": true, "explanation": "正确：十分（shí fēn），意思是程度很高，很，非常。"}, {"text": "失分", "is_correct": false, "explanation": "shī（第一声）与 shí（第二声）声调不同，意思是失去分数。"}, {"text": "十份", "is_correct": false, "explanation": "fèn（第四声）与 fēn（第一声）声调不同，意思是十份。"}, {"text": "石粉", "is_correct": false, "explanation": "fěn（第三声）与 fēn（第一声）声调不同，意思是石头磨成的粉。"}, {"text": "十封", "is_correct": false, "explanation": "fēng 与 fēn 韵母不同（ng 与 n），意思是十封（信）。"}], "explanations": {"十分": "正确：十分（shí fēn），意思是程度很高，很，非常。", "失分": "shī（第一声）与 shí（第二声）声调不同，意思是失去分数。", "十份": "fèn（第四声）与 fēn（第一声）声调不同，意思是十份。", "石粉": "fěn（第三声）与 fēn（第一声）声调不同，意思是石头磨成的粉。", "十封": "fēng 与 fēn 韵母不同（ng 与 n），意思是十封（信）。"}, "sentence_index": null, "correct_answer": "十分"}, "level_3": {"options": [{"text": "十分", "is_correct": true, "explanation": "正确：“十分”作程度副词，修饰“好”，表示天气非常好。"}, {"text": "曾", "is_correct": false, "explanation": "语义：“曾”指过去，与“今天”矛盾，“今天天气曾好”意思不通。"}, {"text": "已", "is_correct": false, "explanation": "语义：“已”表示已经完成，不能说明“好”的程度，句子意思不通。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”与天气无关，“今天天气唱好”搭配不当。"}], "explanations": {"十分": "正确：“十分”作程度副词，修饰“好”，表示天气非常好。", "曾": "语义：“曾”指过去，与“今天”矛盾，“今天天气曾好”意思不通。", "已": "语义：“已”表示已经完成，不能说明“好”的程度，句子意思不通。", "唱": "搭配：“唱”与天气无关，“今天天气唱好”搭配不当。"}, "sentence_index": 0, "correct_answer": "十分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们十分利用了这次机会。", "explanation": "这里应该用〈充分〉。“十分”是程度副词，不修饰“利用”这样的动作，要说“充分利用”。"}, {"text": "我们十分早点出发吧。", "explanation": "这里应该用〈尽量〉。“十分”表示程度很高，不表示尽力去做，要说“尽量早点”。"}, {"text": "请你十分等一下，我马上就来。", "explanation": "这里应该用〈稍微〉。“十分”表示程度很高，不能用来表示略微等待，要说“稍微等一下”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa6461e6-920a-4182-a42e-c248a1792d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86730, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "十分", "is_correct": true, "explanation": "正确：“十分”修饰“努力”，表示程度很高。"}, {"text": "不", "is_correct": false, "explanation": "语义：“他工作不努力”与后半句“老板常常夸他”矛盾。"}, {"text": "没", "is_correct": false, "explanation": "语义：“他工作没努力”与“老板常常夸他”矛盾。"}, {"text": "未", "is_correct": false, "explanation": "语法：“未”表示没有发生，不能这样修饰“努力”，且与“老板常常夸他”矛盾。"}], "explanations": {"十分": "正确：“十分”修饰“努力”，表示程度很高。", "不": "语义：“他工作不努力”与后半句“老板常常夸他”矛盾。", "没": "语义：“他工作没努力”与“老板常常夸他”矛盾。", "未": "语法：“未”表示没有发生，不能这样修饰“努力”，且与“老板常常夸他”矛盾。"}, "sentence_index": 6, "correct_answer": "十分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我想要十分快一点的车。", "explanation": "这里应该用〈更〉。“十分”不能与“一点”连用表示比较，要说“更快一点”。"}, {"text": "这个菜十分好吃了！", "explanation": "这里应该用〈太〉。“十分”不能与“了”搭配表示感叹，要说“太好吃了”。"}, {"text": "我们十分出发吧。", "explanation": "这里应该用〈赶紧〉。“十分”表示程度，不能表示催促，要说“赶紧出发”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa6461e6-920a-4182-a42e-c248a1792d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86730, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把房间打扫十分干净。", "corrected_sentence": "他把房间打扫得十分干净。", "error_description": "补语错误：程度补语前要加「得」，应说“打扫得十分干净”；“打扫十分干净”漏掉了“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa6461e6-920a-4182-a42e-c248a1792d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86730, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个菜的味道很十分好，大家都吃了很多。", "corrected_sentence": "这个菜的味道十分好，大家都吃了很多。", "error_description": "“很”和“十分”都是程度副词，不能叠用，应只用“十分”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa6461e6-920a-4182-a42e-c248a1792d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
