INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86734, 1, 'prompt1_core', '{"pos": "叹词", "semantic_class": "function", "definition": "叹词或语气词，表示领会、明白，或应答。", "primary_collocate": null, "pronunciation": "ò", "ipa": "ɔ˥˩", "syllable_count": 1, "sentences": [{"text": "老师讲了一遍，我说：“哦，我明白了。”", "target_word": "哦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“这是你的书。”“哦，谢谢你。”", "target_word": "哦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“哦，原来是这样！”我终于懂了。", "target_word": "哦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“请把门关上。”“哦，好的。”", "target_word": "哦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听她解释完，我才“哦”了一声。", "target_word": "哦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“哦，我想起来了，你是小李。”", "target_word": "哦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“今天不用带电脑。”“哦，知道了。”", "target_word": "哦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哦，原来他是你哥哥，难怪长得这么像。", "target_word": "哦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“你的手机在桌子上。”“哦，我看到了。”", "target_word": "哦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哦，我懂了，这个字是这样写的。", "target_word": "哦", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "表示明白、领会或应答的叹词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19b140c7-e308-4628-aaa0-d46ef4cd89fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86734, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "哦", "is_correct": true, "explanation": "正确：哦在此表示领会，符合“我明白了”的句意。"}, {"text": "嘘", "is_correct": false, "explanation": "语义：嘘是让人安静的声音，与“我明白了”不符。"}, {"text": "呸", "is_correct": false, "explanation": "语义：呸表示唾弃、鄙视，不能表示领会。"}, {"text": "呜", "is_correct": false, "explanation": "语义：呜是哭声或呜咽，不能表示领会。"}], "explanations": {"哦": "正确：哦在此表示领会，符合“我明白了”的句意。", "嘘": "语义：嘘是让人安静的声音，与“我明白了”不符。", "呸": "语义：呸表示唾弃、鄙视，不能表示领会。", "呜": "语义：呜是哭声或呜咽，不能表示领会。"}, "sentence_index": 0, "correct_answer": "哦"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子摔了一跤，“哦”地哭了起来。", "explanation": "这里应该用〈哇〉。哇是哭声，哦只表示领会或应答，不表示哭。"}, {"text": "我在远处叫他，“哦”了一声，他没听见。", "explanation": "这里的“哦”用作招呼，与表示领会的用法不同，不能用来叫人。"}, {"text": "我的手被热水烫到，“哦”地缩了回去。", "explanation": "这里的“哦”表示疼痛，与表示领会的用法不同，不能用来表示疼痛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63a6e138-c20d-4a52-81ce-9599688f9dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86734, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "哦", "is_correct": true, "explanation": "正确：哦在此表示领会，符合“知道了”的语境。"}, {"text": "哈", "is_correct": false, "explanation": "语义：哈表示笑声，与领会对方的话不符。"}, {"text": "嗬", "is_correct": false, "explanation": "语义：嗬表示惊讶或赞叹，不是简单的领会应答。"}, {"text": "咳", "is_correct": false, "explanation": "语义：咳是咳嗽声，与领会对方的话无关。"}], "explanations": {"哦": "正确：哦在此表示领会，符合“知道了”的语境。", "哈": "语义：哈表示笑声，与领会对方的话不符。", "嗬": "语义：嗬表示惊讶或赞叹，不是简单的领会应答。", "咳": "语义：咳是咳嗽声，与领会对方的话无关。"}, "sentence_index": 6, "correct_answer": "哦"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨下得很大，他“哦”地跑进了屋子。", "explanation": "这里应该用〈嗖〉。嗖是快速移动的声音，哦不表示动作，不能用来形容跑。"}, {"text": "汽车开过来，司机“哦”了一声，我赶紧让开。", "explanation": "这里应该用〈嘀嘀〉。嘀嘀是模拟汽车喇叭的声音，哦表示领会或应答，不用来模拟鸣笛。"}, {"text": "考试没考好，他“哦”地叹了口气。", "explanation": "这里的“哦”表示叹息，与表示领会的用法不同，不能用于表示失望。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63a6e138-c20d-4a52-81ce-9599688f9dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86734, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "“你的书在桌上。”“哦，我找到哦了。”", "corrected_sentence": "“你的书在桌上。”“哦，我找到了。”", "error_description": "错误：“哦”插在“找到”与“了”之间，打断了结果补语与“了”。“哦”应放在句首，作为独立的应答词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63a6e138-c20d-4a52-81ce-9599688f9dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86734, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "“这个字怎么写？”“我哦懂了。”", "corrected_sentence": "“这个字怎么写？”“哦，我懂了。”", "error_description": "错误：“哦”插在“我”与“懂了”之间，拆开了词组。应放在句首，作为独立的应答词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63a6e138-c20d-4a52-81ce-9599688f9dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
