INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86735, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "之下是在某个东西的下面。", "primary_collocate": null, "pronunciation": "zhī xià", "ipa": "ʈʂɻ̩˥ ɕja˥˩", "syllable_count": 2, "sentences": [{"text": "桥之下有很多小鱼。", "target_word": "之下", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "山顶之下是一片树林。", "target_word": "之下", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "云层之下是一座安静的小城。", "target_word": "之下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座楼之下有一个停车场。", "target_word": "之下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河水之下藏着很多石头。", "target_word": "之下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子之下有一只小猫。", "target_word": "之下", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大海之下住着很多奇怪的鱼。", "target_word": "之下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地面之下有一条很长的水管。", "target_word": "之下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那棵树之下有一把旧椅子。", "target_word": "之下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雪之下是绿色的草。", "target_word": "之下", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "之下：名词性方位词，放在名词后，指该物体下面的位置，如“桥之下”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '851174ca-2114-4551-bf43-9f2fc3ac5b77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86735, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "之下", "is_correct": true, "explanation": "本词，指某物的下面。"}, {"text": "直下", "is_correct": false, "explanation": "zhí（第二声）与 zhī（第一声）声调不同，意思是一直往下。"}, {"text": "吃下", "is_correct": false, "explanation": "chī 与 zhī 声母不同，意思是把食物吃进去。"}, {"text": "治下", "is_correct": false, "explanation": "zhì（第四声）与 zhī 声调不同，意思是统治之下。"}], "explanations": {"之下": "本词，指某物的下面。", "直下": "zhí（第二声）与 zhī（第一声）声调不同，意思是一直往下。", "吃下": "chī 与 zhī 声母不同，意思是把食物吃进去。", "治下": "zhì（第四声）与 zhī 声调不同，意思是统治之下。"}, "sentence_index": null, "correct_answer": "之下"}, "level_3": {"options": [{"text": "上", "is_correct": false, "explanation": "语义：桥上不是小鱼生活的地方，与“有很多小鱼”的语境不合。"}, {"text": "里", "is_correct": false, "explanation": "搭配：桥不是容器，不能说“桥里”来表示位置。"}, {"text": "之下", "is_correct": true, "explanation": "本词，表示桥的下方，小鱼可以在水里。"}, {"text": "顶", "is_correct": false, "explanation": "语义：桥顶不是小鱼生活的地方，与“有很多小鱼”的语境不合。"}], "explanations": {"上": "语义：桥上不是小鱼生活的地方，与“有很多小鱼”的语境不合。", "里": "搭配：桥不是容器，不能说“桥里”来表示位置。", "之下": "本词，表示桥的下方，小鱼可以在水里。", "顶": "语义：桥顶不是小鱼生活的地方，与“有很多小鱼”的语境不合。"}, "sentence_index": 0, "correct_answer": "之下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "下课之下，我们去操场。", "explanation": "这里应该用〈之后〉。“之下”表示空间的下方，不能表示时间的先后；下课之后才去操场，要说“下课之后”。"}, {"text": "这个月之下我会回来。", "explanation": "这里应该用〈之内〉。“之下”表示空间的下方或条件，不能表示一段时间的范围；一个月之内回来要用〈之内〉。"}, {"text": "全班之下只有我一个人会游泳。", "explanation": "这里应该用〈之中〉。“之下”表示空间的下方，不能指在一群人里面；在全班之中只有我会游泳，要说“之中”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '711ec6d4-218e-455b-9b09-3ea66234cce2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86735, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "之下", "is_correct": true, "explanation": "本词，指某物的下面。"}, {"text": "直辖", "is_correct": false, "explanation": "zhíxiá 与 zhīxià 声调不同（第二声对第一声、第二声对第四声），意思是直接管辖。"}, {"text": "知晓", "is_correct": false, "explanation": "xiǎo 与 xià 韵母和声调都不同，知晓的意思是知道。"}, {"text": "支线", "is_correct": false, "explanation": "xiàn 比 xià 多一个韵尾 n，支线的意思是从主线分出来的线路。"}], "explanations": {"之下": "本词，指某物的下面。", "直辖": "zhíxiá 与 zhīxià 声调不同（第二声对第一声、第二声对第四声），意思是直接管辖。", "知晓": "xiǎo 与 xià 韵母和声调都不同，知晓的意思是知道。", "支线": "xiàn 比 xià 多一个韵尾 n，支线的意思是从主线分出来的线路。"}, "sentence_index": null, "correct_answer": "之下"}, "level_3": {"options": [{"text": "之上", "is_correct": false, "explanation": "语义：鱼不住在海面以上，“之上”与“住着奇怪的鱼”的语境不合。"}, {"text": "之前", "is_correct": false, "explanation": "语义：“大海之前”指海的前面，不能说鱼住在那里。"}, {"text": "之下", "is_correct": true, "explanation": "本词，表示大海的下方，鱼住在海里。"}, {"text": "之外", "is_correct": false, "explanation": "搭配：“大海之外”指海洋以外，不能用来说鱼生活在大海里。"}], "explanations": {"之上": "语义：鱼不住在海面以上，“之上”与“住着奇怪的鱼”的语境不合。", "之前": "语义：“大海之前”指海的前面，不能说鱼住在那里。", "之下": "本词，表示大海的下方，鱼住在海里。", "之外": "搭配：“大海之外”指海洋以外，不能用来说鱼生活在大海里。"}, "sentence_index": 6, "correct_answer": "之下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "海面之下飞着一只海鸥。", "explanation": "这里应该用〈之上〉。海鸥在海面之上飞，“之下”指水面以下，不能说海鸥在水下飞。"}, {"text": "两点之下我会到。", "explanation": "这里应该用〈之前〉。“之下”表示空间的下方，不能表示时间的先后；两点之前到要用〈之前〉。"}, {"text": "会议之下，我们吃了午饭。", "explanation": "这里应该用〈之前〉。“之下”表示空间的下方，不能表示时间的先后；吃午饭应在会议之前，要说“会议之前”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '711ec6d4-218e-455b-9b09-3ea66234cce2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86735, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "岩石之之下藏着一只小螃蟹。", "corrected_sentence": "岩石之下藏着一只小螃蟹。", "error_description": "错误：“之”被多写了一次，成了“之之下”。正确形式是“之下”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '711ec6d4-218e-455b-9b09-3ea66234cce2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
