INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86736, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "在……下面。", "primary_collocate": null, "pronunciation": "zhī xià", "ipa": "ʈʂɻ̩˥ ɕja˥˩", "syllable_count": 2, "sentences": [{"text": "在石板之下，压着一张旧地图。", "target_word": "之下", "complexity_tier": "T3", "furigana": "zài shíbǎn zhīxià, yāzhe yì zhāng jiù dìtú.", "sentence_source": "generated"}, {"text": "在桥洞之下，躲着几只小鸟。", "target_word": "之下", "complexity_tier": "T3", "furigana": "zài qiáodòng zhīxià, duǒzhe jǐ zhī xiǎo niǎo.", "sentence_source": "generated"}, {"text": "在灯光之下，她的脸很红。", "target_word": "之下", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "在屋檐之下，挂着一串玉米。", "target_word": "之下", "complexity_tier": "T3", "furigana": "zài wūyán zhīxià, guàzhe yí chuàn yùmǐ.", "sentence_source": "generated"}, {"text": "在阳光之下，雪很快就化了。", "target_word": "之下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在地板之下，有一个小房间。", "target_word": "之下", "complexity_tier": "T3", "furigana": "zài dìbǎn zhīxià, yǒu yí gè xiǎo fángjiān.", "sentence_source": "generated"}, {"text": "在水库之下，沉睡着一个小村庄。", "target_word": "之下", "complexity_tier": "T3", "furigana": "zài shuǐkù zhīxià, chénshuìzhe yí gè xiǎo cūnzhuāng.", "sentence_source": "generated"}, {"text": "在路灯之下，有几个孩子在玩耍。", "target_word": "之下", "complexity_tier": "T3", "furigana": "zài lùdēng zhīxià, yǒu jǐ gè háizi zài wánshuǎ.", "sentence_source": "generated"}, {"text": "在大树之下，几个老人正在下棋。", "target_word": "之下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在泥土之下，埋着一颗种子。", "target_word": "之下", "complexity_tier": "T3", "furigana": "zài nítǔ zhīxià, máizhe yì kē zhǒngzi.", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "之下：与“在”搭配成“在……之下”，表示处在某种帮助、影响、条件或事物的下面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '851174ca-2114-4551-bf43-9f2fc3ac5b77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86736, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "之下", "is_correct": true, "explanation": "本词，表示在某物的下面或某种条件之下。"}, {"text": "吃下", "is_correct": false, "explanation": "chī 与 zhī 声母不同（送气），意思是把食物吃进去。"}, {"text": "直下", "is_correct": false, "explanation": "zhí（第二声）与 zhī（第一声）声调不同，意思是一直往下。"}, {"text": "治下", "is_correct": false, "explanation": "zhì（第四声）与 zhī 声调不同，意思是统治之下。"}], "explanations": {"之下": "本词，表示在某物的下面或某种条件之下。", "吃下": "chī 与 zhī 声母不同（送气），意思是把食物吃进去。", "直下": "zhí（第二声）与 zhī（第一声）声调不同，意思是一直往下。", "治下": "zhì（第四声）与 zhī 声调不同，意思是统治之下。"}, "sentence_index": null, "correct_answer": "之下"}, "level_3": {"options": [{"text": "之中", "is_correct": false, "explanation": "语义：“石板之中”指石板内部，地图不会被压在石板里面，与句意不符。"}, {"text": "之内", "is_correct": false, "explanation": "语义：“石板之内”指石板的范围之内，与“地图压在石板下”的位置不符。"}, {"text": "之下", "is_correct": true, "explanation": "本词，表示在石板的下面，与“压着地图”的语境相符。"}, {"text": "之外", "is_correct": false, "explanation": "语义：“石板之外”指石板的外面，与“压着一张地图”的方位不符。"}], "explanations": {"之中": "语义：“石板之中”指石板内部，地图不会被压在石板里面，与句意不符。", "之内": "语义：“石板之内”指石板的范围之内，与“地图压在石板下”的位置不符。", "之下": "本词，表示在石板的下面，与“压着地图”的语境相符。", "之外": "语义：“石板之外”指石板的外面，与“压着一张地图”的方位不符。"}, "sentence_index": 0, "correct_answer": "之下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "在人群之下，他最显眼。", "explanation": "这里应该用〈之中〉。人群是一个整体，“之下”表示下方，不能指在人群里。"}, {"text": "在三天之下，我们会完成这个项目。", "explanation": "这里应该用〈之内〉。“在……之下”指空间的下方，不能表示时间范围；三天之内完成要用〈之内〉。"}, {"text": "在头发之下，戴着一顶帽子。", "explanation": "这里应该用〈之上〉。帽子戴在头发的上面，“之下”表示下方，方位相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '711ec6d4-218e-455b-9b09-3ea66234cce2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86736, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "之下", "is_correct": true, "explanation": "本词，表示在某物的下面或某种条件之下。"}, {"text": "支线", "is_correct": false, "explanation": "xiàn 比 xià 多一个韵尾 n，支线的意思是从主线分出来的线路。"}, {"text": "直辖", "is_correct": false, "explanation": "zhíxiá 与 zhīxià 声调不同（第二声对第一声、第二声对第四声），意思是直接管辖。"}, {"text": "知晓", "is_correct": false, "explanation": "xiǎo 与 xià 韵母和声调都不同，知晓的意思是知道。"}], "explanations": {"之下": "本词，表示在某物的下面或某种条件之下。", "支线": "xiàn 比 xià 多一个韵尾 n，支线的意思是从主线分出来的线路。", "直辖": "zhíxiá 与 zhīxià 声调不同（第二声对第一声、第二声对第四声），意思是直接管辖。", "知晓": "xiǎo 与 xià 韵母和声调都不同，知晓的意思是知道。"}, "sentence_index": null, "correct_answer": "之下"}, "level_3": {"options": [{"text": "之间", "is_correct": false, "explanation": "搭配：“水库之间”指两座水库中间，不能表示村庄沉在水库下面。"}, {"text": "之后", "is_correct": false, "explanation": "语义：“水库之后”指水库的后面，与村庄沉在水库下方的情况不符。"}, {"text": "之下", "is_correct": true, "explanation": "本词，表示村庄沉在水库的下方，与句意相符。"}, {"text": "之前", "is_correct": false, "explanation": "语义：“水库之前”指水库的前面，与村庄沉在水库下方的情况不符。"}], "explanations": {"之间": "搭配：“水库之间”指两座水库中间，不能表示村庄沉在水库下面。", "之后": "语义：“水库之后”指水库的后面，与村庄沉在水库下方的情况不符。", "之下": "本词，表示村庄沉在水库的下方，与句意相符。", "之前": "语义：“水库之前”指水库的前面，与村庄沉在水库下方的情况不符。"}, "sentence_index": 6, "correct_answer": "之下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "在一小时之下，我会回来。", "explanation": "这里应该用〈之内〉。“在……之下”指空间的下方，不能表示时间范围；一小时之内回来要用〈之内〉。"}, {"text": "在晚饭之下，我写完了作业。", "explanation": "这里应该用〈之前〉。“在……之下”指空间或条件，不能表示时间的先后；晚饭之前写完作业要用〈之前〉。"}, {"text": "在爬山之下，我们吃了午饭。", "explanation": "这里应该用〈之后〉。“在……之下”不能表示时间的先后；爬完山之后才吃午饭，要用〈之后〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '711ec6d4-218e-455b-9b09-3ea66234cce2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86736, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "在桌子的之下，躲着一只猫。", "corrected_sentence": "在桌子之下，躲着一只猫。", "error_description": "错误：“桌子”与“之下”之间多加了“的”，成了“桌子的之下”。空间方位要说“桌子之下”，中间不加“的”；“……的之下”只用于“在……的领导之下”这类抽象说法。正确形式是“桌子之下”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '711ec6d4-218e-455b-9b09-3ea66234cce2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86736, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "在石头之下下，埋着一颗种子。", "corrected_sentence": "在石头之下，埋着一颗种子。", "error_description": "错误：“之下”后面多写了一个“下”，成了“之下下”。正确形式是“之下”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '711ec6d4-218e-455b-9b09-3ea66234cce2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86737, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "出去", "is_correct": true, "explanation": "反义：“出去”与“回来”相对，指离开原来的地方。"}, {"text": "洗澡", "is_correct": false, "explanation": "无反义关系：“洗澡”指清洁身体，与“回来”没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "无反义关系：“散步”指慢走活动，与“回来”没有反义关系。"}, {"text": "看书", "is_correct": false, "explanation": "无反义关系：“看书”指阅读，与“回来”没有反义关系。"}], "correct_answer": "出去", "explanations": {"出去": "反义：“出去”与“回来”相对，指离开原来的地方。", "洗澡": "无反义关系：“洗澡”指清洁身体，与“回来”没有反义关系。", "散步": "无反义关系：“散步”指慢走活动，与“回来”没有反义关系。", "看书": "无反义关系：“看书”指阅读，与“回来”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b98cb1a-b764-4cf7-8b0f-bea141ae3341') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86737, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "离开", "is_correct": true, "explanation": "反义：“离开”与“回来”相对，指从某地走开。"}, {"text": "唱歌", "is_correct": false, "explanation": "无反义关系：“唱歌”指发出乐声，与“回来”没有反义关系。"}, {"text": "跳舞", "is_correct": false, "explanation": "无反义关系：“跳舞”指舞蹈动作，与“回来”没有反义关系。"}, {"text": "画画", "is_correct": false, "explanation": "无反义关系：“画画”指绘画，与“回来”没有反义关系。"}], "correct_answer": "离开", "explanations": {"离开": "反义：“离开”与“回来”相对，指从某地走开。", "唱歌": "无反义关系：“唱歌”指发出乐声，与“回来”没有反义关系。", "跳舞": "无反义关系：“跳舞”指舞蹈动作，与“回来”没有反义关系。", "画画": "无反义关系：“画画”指绘画，与“回来”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b98cb1a-b764-4cf7-8b0f-bea141ae3341') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86737, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "回来是从别的地方走到原来的地方。", "primary_collocate": null, "pronunciation": "huí lái", "ipa": "xuei˧˥ lai˧˥", "syllable_count": 2, "sentences": [{"text": "她下班回来，先洗手。", "target_word": "回来", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师出去开会，下午回来。", "target_word": "回来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟踢完球，满头大汗地回来了。", "target_word": "回来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我忘了带钥匙，要回来拿。", "target_word": "回来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷每天早上出去散步，八点回来。", "target_word": "回来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们去旅行了，下个星期回来。", "target_word": "回来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我把伞忘在家里了，所以回来拿。", "target_word": "回来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你一个人在外面，早点回来吧。", "target_word": "回来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他出差回来后，大家一起吃了饭。", "target_word": "回来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "姐姐在国外住着，很少回来。", "target_word": "回来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "回来了", "label": "体标"}, {"form": "回来过", "label": "体标"}, {"form": "回不来", "label": "可能补语"}], "register": "中性", "sense_fingerprint": "从外面走回原来的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7ebaaf2-ff86-4acd-81d5-d33d40a45ed1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86737, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "回来", "is_correct": true, "explanation": "与语境相符：她下班后回到家，然后先洗手。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“下班睡觉”与“先洗手”的动作顺序和语境都不协调。"}, {"text": "修理", "is_correct": false, "explanation": "配价：“修理”是及物动词，后面需要宾语，不能单独作谓语。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：“结婚”不是下班后的日常动作，与语境冲突。"}], "explanations": {"回来": "与语境相符：她下班后回到家，然后先洗手。", "睡觉": "语义：“下班睡觉”与“先洗手”的动作顺序和语境都不协调。", "修理": "配价：“修理”是及物动词，后面需要宾语，不能单独作谓语。", "结婚": "语义：“结婚”不是下班后的日常动作，与语境冲突。"}, "sentence_index": 0, "correct_answer": "回来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这孩子还没出过门，就回来了。", "explanation": "回来要先离开原来的地方再返回；孩子没出过门，没有离开，不能说回来了。"}, {"text": "妹妹从没离开过宿舍，今天才回来。", "explanation": "回来要先离开再返回；妹妹从没离开过宿舍，说她回来自相矛盾。"}, {"text": "我还没离开教室，就已经回来了。", "explanation": "回来要先离开再返回；还没离开教室就不可能回来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b98cb1a-b764-4cf7-8b0f-bea141ae3341') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86737, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "回来", "is_correct": true, "explanation": "与语境相符：伞忘在家里，所以回到家里去拿。"}, {"text": "打扫", "is_correct": false, "explanation": "配价：“打扫”是及物动词，这里缺少宾语，“所以打扫拿”不成立。"}, {"text": "发烧", "is_correct": false, "explanation": "语义：发烧与“忘在家里的伞”的取回动作无关，语境冲突。"}, {"text": "毕业", "is_correct": false, "explanation": "语义：毕业与“取伞”的动作无关，语境冲突。"}], "explanations": {"回来": "与语境相符：伞忘在家里，所以回到家里去拿。", "打扫": "配价：“打扫”是及物动词，这里缺少宾语，“所以打扫拿”不成立。", "发烧": "语义：发烧与“忘在家里的伞”的取回动作无关，语境冲突。", "毕业": "语义：毕业与“取伞”的动作无关，语境冲突。"}, "sentence_index": 6, "correct_answer": "回来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "奶奶一辈子住在乡下，从没去过城里，昨天刚回来。", "explanation": "回来要先离开再返回；奶奶从没去过城里，说她回来自相矛盾。"}, {"text": "老师一直在办公室，从没出去过，刚才回来。", "explanation": "回来要先离开再返回；老师从没出去过，就不存在回来。"}, {"text": "他一直待在家里，一步也没走出去，晚上才回来。", "explanation": "回来要先离开再返回；他没走出去过，说他回来自相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b98cb1a-b764-4cf7-8b0f-bea141ae3341') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86737, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他下午三点就回来了过。", "corrected_sentence": "他下午三点就回来了。", "error_description": "错误形式：回来了过；正确形式：回来了。“过”不能放在“了”之后；且“下午三点就”说的是已完成的具体事件，只用“了”即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b98cb1a-b764-4cf7-8b0f-bea141ae3341') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86737, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他去年出国，今年终于的回来了。", "corrected_sentence": "他去年出国，今年终于回来了。", "error_description": "错误形式：终于的回来；正确形式：终于回来。“终于”是副词，直接修饰动词，中间不加结构助词“的”，应删去“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b98cb1a-b764-4cf7-8b0f-bea141ae3341') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
