INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86740, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "中华人民共和国的法定货币。", "primary_collocate": null, "pronunciation": "rén mín bì", "ipa": "ʐən˧˥ min˧˥ pi˥˩", "syllable_count": 3, "sentences": [{"text": "人民币是中国的法定货币。", "target_word": "人民币", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人民币的汇率每天都有变化。", "target_word": "人民币", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国人民银行发行人民币。", "target_word": "人民币", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人民币的单位是元、角和分。", "target_word": "人民币", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家规定，在中国要用人民币付款。", "target_word": "人民币", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在中国的商店里，价格都用人民币标出来。", "target_word": "人民币", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多国家的人也愿意持有人民币。", "target_word": "人民币", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人民币汇率上升，外国商品变便宜了。", "target_word": "人民币", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司用人民币给员工发工资。", "target_word": "人民币", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在人民币也可以在网上支付。", "target_word": "人民币", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "人民幣", "label": "繁体"}], "register": "中性", "sense_fingerprint": "中国的法定货币，涉及汇率、发行和支付", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e8d98bf-ca56-4497-b80d-a8800a5dfbfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86740, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人民币", "is_correct": true, "explanation": "正确：“是……的法定货币”的主语应是货币的名称，人民币是中国的法定货币。"}, {"text": "美元", "is_correct": false, "explanation": "语义：美元不是中国的法定货币，与“中国的”不符。"}, {"text": "银行", "is_correct": false, "explanation": "语义：银行是机构，不是货币，不能成为法定货币。"}, {"text": "汇率", "is_correct": false, "explanation": "搭配：“汇率”指两种货币的比价，不是货币名称，不能说“是……的法定货币”。"}], "explanations": {"人民币": "正确：“是……的法定货币”的主语应是货币的名称，人民币是中国的法定货币。", "美元": "语义：美元不是中国的法定货币，与“中国的”不符。", "银行": "语义：银行是机构，不是货币，不能成为法定货币。", "汇率": "搭配：“汇率”指两种货币的比价，不是货币名称，不能说“是……的法定货币”。"}, "sentence_index": 0, "correct_answer": "人民币"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用人民币写了一本小说。", "explanation": "语义：人民币是货币，不是书写工具，不能用来“写”。这里应该用〈钢笔〉之类的工具。"}, {"text": "各国都有自己的人民币。", "explanation": "这里应该用〈货币〉。人民币专指中国的货币，泛指各国的货币应说“货币”。"}, {"text": "我买了一条人民币。", "explanation": "这里“条”用错了。“条”用于河流、道路等长条形事物，不能用于货币。纸币应说“一张人民币”，这里应把“条”换成“张”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e286751-3bfa-4706-aff2-38058e45a08d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86740, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人民币", "is_correct": true, "explanation": "正确：“持有”的对象可以是货币，很多国家的人愿意持有人民币。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能被持有，也不能作为资产。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不能被持有，也不是可以持有的资产。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“持有”搭配的是货币、股票等资产，“脚步”不能被持有。"}], "explanations": {"人民币": "正确：“持有”的对象可以是货币，很多国家的人愿意持有人民币。", "天气": "语义：天气不能被持有，也不能作为资产。", "空气": "语义：空气不能被持有，也不是可以持有的资产。", "脚步": "搭配：“持有”搭配的是货币、股票等资产，“脚步”不能被持有。"}, "sentence_index": 6, "correct_answer": "人民币"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天早上给人民币刷牙。", "explanation": "语义：“刷牙”的对象应是人的牙齿，人民币是货币，不能被刷牙。"}, {"text": "这位同学每天给人民币辅导作业。", "explanation": "语义：“辅导”的对象应是需要学习的人，人民币不能接受辅导。"}, {"text": "我每天都去人民币上班。", "explanation": "语义：人民币是货币，不是工作场所，不能说“去人民币上班”。这里应该用〈银行〉之类的工作单位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e286751-3bfa-4706-aff2-38058e45a08d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86740, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "人民币的汇率每天都有了变化。", "corrected_sentence": "人民币的汇率每天都有变化。", "error_description": "体标错误：“每天都”表示经常发生的情况，不能和完成体“了”搭配。应去掉“了”，说“每天都有变化”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e286751-3bfa-4706-aff2-38058e45a08d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86740, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "许多国家的央行也愿意持有了人民币。", "corrected_sentence": "许多国家的央行也愿意持有人民币。", "error_description": "体标错误：“愿意”表示意愿、尚未发生，不能与完成体“了”搭配；应说“愿意持有人民币”，不能说“愿意持有了人民币”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e286751-3bfa-4706-aff2-38058e45a08d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
