INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86741, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "报是印着新闻、每天可以看的大张纸。", "primary_collocate": null, "pronunciation": "bào", "ipa": "pau˥˩", "syllable_count": 1, "sentences": [{"text": "爷爷每天早上都看报。", "target_word": "报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上有一份报。", "target_word": "报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在报上看到了这个消息。", "target_word": "报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家订了一份报。", "target_word": "报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸喝着茶看报。", "target_word": "报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是今天的报吗？", "target_word": "报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把报放在桌子上。", "target_word": "报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天去门口拿报。", "target_word": "报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报上说明天会下雨。", "target_word": "报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶戴着眼镜读报。", "target_word": "报", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}, {"form": "報", "label": "繁体"}], "register": "中性", "sense_fingerprint": "报纸（单音节用法），每天印着新闻的大张纸", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25be5f49-5a16-4b1c-a339-0cf287f7ff26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86741, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "报", "is_correct": true, "explanation": "正确答案：报（bào，第四声），指印着新闻、每天可以阅读的大张纸。"}, {"text": "包", "is_correct": false, "explanation": "bāo（第一声）与 bào（第四声）声调不同，意思是包裹、包。"}, {"text": "保", "is_correct": false, "explanation": "bǎo（第三声）与 bào（第四声）声调不同，意思是保护。"}, {"text": "泡", "is_correct": false, "explanation": "pào 与 bào 声母不同（p 与 b），意思是泡在水里。"}, {"text": "薄", "is_correct": false, "explanation": "báo（第二声）与 bào（第四声）声调不同，意思是薄。"}], "explanations": {"报": "正确答案：报（bào，第四声），指印着新闻、每天可以阅读的大张纸。", "包": "bāo（第一声）与 bào（第四声）声调不同，意思是包裹、包。", "保": "bǎo（第三声）与 bào（第四声）声调不同，意思是保护。", "泡": "pào 与 bào 声母不同（p 与 b），意思是泡在水里。", "薄": "báo（第二声）与 bào（第四声）声调不同，意思是薄。"}, "sentence_index": null, "correct_answer": "报"}, "level_3": {"options": [{"text": "报", "is_correct": true, "explanation": "正确答案：报，“看报”即阅读报纸，符合“每天早上都看”的语境。"}, {"text": "夜景", "is_correct": false, "explanation": "语义：夜景指夜间的景色，与“每天早上”矛盾。"}, {"text": "晚会", "is_correct": false, "explanation": "语义：晚会一般在晚上举行，与“每天早上”矛盾。"}, {"text": "歌", "is_correct": false, "explanation": "搭配：“看”不能以“歌”为宾语，应说“听歌”。"}], "explanations": {"报": "正确答案：报，“看报”即阅读报纸，符合“每天早上都看”的语境。", "夜景": "语义：夜景指夜间的景色，与“每天早上”矛盾。", "晚会": "语义：晚会一般在晚上举行，与“每天早上”矛盾。", "歌": "搭配：“看”不能以“歌”为宾语，应说“听歌”。"}, "sentence_index": 0, "correct_answer": "报"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师让我写一份报。", "explanation": "这里应该用〈报告〉。报是印好发行的报纸，不能“写”；要“写”的是报告。"}, {"text": "这份文件里有很多报。", "explanation": "这里应该用〈信息〉。“报”指报纸，不能指文件里的内容；内容信息才说“很多”。"}, {"text": "这份报是我最喜欢的小说，我已经看了三遍。", "explanation": "这里应该用〈书〉。报是每天发行的报纸，不能等同于小说；装订成册的小说要说“书”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f59eef98-5920-4c5f-afac-18238bea63cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86741, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "报", "is_correct": true, "explanation": "正确答案：报（bào，第四声），指印着新闻、每天可以阅读的大张纸。"}, {"text": "饱", "is_correct": false, "explanation": "bǎo（第三声）与 bào（第四声）声调不同，意思是吃饱。"}, {"text": "帽", "is_correct": false, "explanation": "mào 与 bào 声母不同（m 与 b），意思是帽子。"}, {"text": "到", "is_correct": false, "explanation": "dào 与 bào 声母不同（d 与 b），意思是到达。"}], "explanations": {"报": "正确答案：报（bào，第四声），指印着新闻、每天可以阅读的大张纸。", "饱": "bǎo（第三声）与 bào（第四声）声调不同，意思是吃饱。", "帽": "mào 与 bào 声母不同（m 与 b），意思是帽子。", "到": "dào 与 bào 声母不同（d 与 b），意思是到达。"}, "sentence_index": null, "correct_answer": "报"}, "level_3": {"options": [{"text": "报", "is_correct": true, "explanation": "正确答案：报，“把报放在桌子上”中的对象是报纸，是可以放置的具体印刷品。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是可以放在桌子上的具体物体，与“放在桌子上”冲突。"}, {"text": "感情", "is_correct": false, "explanation": "语义：感情是抽象的心理状态，不能放在桌子上。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“放”不与“味道”搭配，味道不能被放在桌子上。"}], "explanations": {"报": "正确答案：报，“把报放在桌子上”中的对象是报纸，是可以放置的具体印刷品。", "天气": "语义：天气不是可以放在桌子上的具体物体，与“放在桌子上”冲突。", "感情": "语义：感情是抽象的心理状态，不能放在桌子上。", "味道": "搭配：“放”不与“味道”搭配，味道不能被放在桌子上。"}, "sentence_index": 6, "correct_answer": "报"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份报的镜头拍得很好，我看了很多次。", "explanation": "这里应该用〈电影〉。报是印着新闻的报纸，没有镜头；“镜头拍得好、看很多次”说的是电影。"}, {"text": "这本书的报很丰富。", "explanation": "这里应该用〈内容〉。“报”指报纸，不能指书的内容。"}, {"text": "这台机器的报很详细。", "explanation": "这里应该用〈说明书〉。“报”指报纸，不能用来说明机器。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f59eef98-5920-4c5f-afac-18238bea63cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86741, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我妈妈每天都买一只报。", "corrected_sentence": "我妈妈每天都买一份报。", "error_description": "量词错误：报纸应用量词“份”，“只”用于动物等，不能用于报纸。“一只报”应改为“一份报”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f59eef98-5920-4c5f-afac-18238bea63cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
