INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86742, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "报纸；刊登新闻和评论的出版物。", "primary_collocate": null, "pronunciation": "bào", "ipa": "pau˥˩", "syllable_count": 1, "sentences": [{"text": "我不太常看报，只看手机。", "target_word": "报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份报很有名。", "target_word": "报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在报上写过文章。", "target_word": "报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人坐在门口读报。", "target_word": "报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天的报还在沙发上。", "target_word": "报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里有人在看报。", "target_word": "报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每个月花五十元订报。", "target_word": "报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条新闻是从报上看到的。", "target_word": "报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把旧报放在箱子里。", "target_word": "报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报上没有写这件事。", "target_word": "报", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}, {"form": "報", "label": "繁体"}], "register": "中性", "sense_fingerprint": "报纸，刊登新闻和评论的出版物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25be5f49-5a16-4b1c-a339-0cf287f7ff26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86742, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "报", "is_correct": true, "explanation": "正确答案：报（bào，第四声），指刊登新闻和评论的出版物。"}, {"text": "宝", "is_correct": false, "explanation": "bǎo（第三声）与 bào（第四声）声调不同，意思是宝贝。"}, {"text": "泡", "is_correct": false, "explanation": "pào 与 bào 声母不同（p 与 b），意思是泡在水里。"}, {"text": "到", "is_correct": false, "explanation": "dào 与 bào 声母不同（d 与 b），意思是到达。"}, {"text": "帽", "is_correct": false, "explanation": "mào 与 bào 声母不同（m 与 b），意思是帽子。"}], "explanations": {"报": "正确答案：报（bào，第四声），指刊登新闻和评论的出版物。", "宝": "bǎo（第三声）与 bào（第四声）声调不同，意思是宝贝。", "泡": "pào 与 bào 声母不同（p 与 b），意思是泡在水里。", "到": "dào 与 bào 声母不同（d 与 b），意思是到达。", "帽": "mào 与 bào 声母不同（m 与 b），意思是帽子。"}, "sentence_index": null, "correct_answer": "报"}, "level_3": {"options": [{"text": "报", "is_correct": true, "explanation": "正确答案：报，“看报”即阅读报纸，符合“不太常看”的语境。"}, {"text": "歌", "is_correct": false, "explanation": "搭配：“看”不能以“歌”为宾语，应说“听歌”。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“看”不能以“味道”为宾语，应说“闻味道”。"}, {"text": "噪音", "is_correct": false, "explanation": "语义：噪音是听的对象，与“看”所涉及的内容不符。"}], "explanations": {"报": "正确答案：报，“看报”即阅读报纸，符合“不太常看”的语境。", "歌": "搭配：“看”不能以“歌”为宾语，应说“听歌”。", "味道": "搭配：“看”不能以“味道”为宾语，应说“闻味道”。", "噪音": "语义：噪音是听的对象，与“看”所涉及的内容不符。"}, "sentence_index": 0, "correct_answer": "报"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他经常在杂志上写报。", "explanation": "这里应该用〈文章〉。“报”指报纸，不能用“写”；在杂志上“写”的是文章。"}, {"text": "这份报的比例尺很清楚，我们可以按照它找路。", "explanation": "这里应该用〈地图〉。报是印着新闻的报纸，没有比例尺；找路要用地图。"}, {"text": "我家订了一把报。", "explanation": "量词错误：报纸应用“份”，“把”用于有柄或成把的东西，不能用于报纸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f59eef98-5920-4c5f-afac-18238bea63cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86742, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "报", "is_correct": true, "explanation": "正确答案：报（bào，第四声），指刊登新闻和评论的出版物。"}, {"text": "包", "is_correct": false, "explanation": "bāo（第一声）与 bào（第四声）声调不同，意思是包裹、包。"}, {"text": "薄", "is_correct": false, "explanation": "báo（第二声）与 bào（第四声）声调不同，意思是薄。"}, {"text": "冒", "is_correct": false, "explanation": "mào 与 bào 声母不同（m 与 b），意思是冒出。"}, {"text": "饱", "is_correct": false, "explanation": "bǎo（第三声）与 bào（第四声）声调不同，意思是吃饱。"}], "explanations": {"报": "正确答案：报（bào，第四声），指刊登新闻和评论的出版物。", "包": "bāo（第一声）与 bào（第四声）声调不同，意思是包裹、包。", "薄": "báo（第二声）与 bào（第四声）声调不同，意思是薄。", "冒": "mào 与 bào 声母不同（m 与 b），意思是冒出。", "饱": "bǎo（第三声）与 bào（第四声）声调不同，意思是吃饱。"}, "sentence_index": null, "correct_answer": "报"}, "level_3": {"options": [{"text": "报", "is_correct": true, "explanation": "正确答案：报，“订报”即订阅报纸，符合“每个月花五十元”的语境。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是可以订购的东西，与“花五十元订”冲突。"}, {"text": "阳光", "is_correct": false, "explanation": "语义：阳光不能订购，与“花五十元订”冲突。"}, {"text": "信", "is_correct": false, "explanation": "搭配：“订”不与“信”搭配，信件应说“写”或“寄”。"}], "explanations": {"报": "正确答案：报，“订报”即订阅报纸，符合“每个月花五十元”的语境。", "空气": "语义：空气不是可以订购的东西，与“花五十元订”冲突。", "阳光": "语义：阳光不能订购，与“花五十元订”冲突。", "信": "搭配：“订”不与“信”搭配，信件应说“写”或“寄”。"}, "sentence_index": 6, "correct_answer": "报"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份报每一页都印着日期，可以挂在墙上。", "explanation": "这里应该用〈日历〉。报是印着新闻的报纸，每页印日期、挂在墙上的要说日历。"}, {"text": "这本书里有很多报。", "explanation": "这里应该用〈信息〉。“报”指报纸，不能指书里的内容。"}, {"text": "我家订了一只报。", "explanation": "量词错误：报纸应用“份”，“只”用于动物等，不能用于报纸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f59eef98-5920-4c5f-afac-18238bea63cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86742, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我是在报看到这条新闻的。", "corrected_sentence": "我是在报上看到这条新闻的。", "error_description": "方位词漏掉：应说“在报上看到”，不能说“在报看到”，缺少方位词“上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f59eef98-5920-4c5f-afac-18238bea63cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86742, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位老师每天都读一块报。", "corrected_sentence": "这位老师每天都读一份报。", "error_description": "量词错误：报纸应用量词“份”，“块”用于块状物，不能用于报纸。“一块报”应改为“一份报”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f59eef98-5920-4c5f-afac-18238bea63cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
