INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86743, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "俱乐部是有同样爱好的人聚在一起玩的地方。", "primary_collocate": null, "pronunciation": "jù lè bù", "ipa": "tɕy˥˩ lɤ˥˩ pu˥˩", "syllable_count": 3, "sentences": [{"text": "我每个周末都去俱乐部下棋。", "target_word": "俱乐部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家俱乐部有很多爱唱歌的人。", "target_word": "俱乐部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在俱乐部里认识了好朋友。", "target_word": "俱乐部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "俱乐部离我家很近，走路五分钟。", "target_word": "俱乐部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在俱乐部里一起打乒乓球。", "target_word": "俱乐部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸退休以后，每天都去俱乐部打太极拳。", "target_word": "俱乐部", "complexity_tier": "T3", "furigana": "bà ba tuì xiū yǐ hòu， měi tiān dōu qù jù lè bù dǎ tài jí quán", "sentence_source": "generated"}, {"text": "这个俱乐部的人都爱看书。", "target_word": "俱乐部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下课后，同学们都去俱乐部打球了。", "target_word": "俱乐部", "complexity_tier": "T3", "furigana": "xià kè hòu， tóng xué men dōu qù jù lè bù dǎ qiú le", "sentence_source": "generated"}, {"text": "俱乐部里有桌子，也有一些书。", "target_word": "俱乐部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，这个俱乐部几点开门？", "target_word": "俱乐部", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}, {"form": "读书俱乐部", "label": "复合"}, {"form": "俱樂部", "label": "繁体"}], "register": "中性", "sense_fingerprint": "爱好相同的人聚在一起玩的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88131405-7030-4d15-aa9d-0a48d00bcf95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86743, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "医院", "is_correct": false, "explanation": "语义：医院是看病的地方，不是下棋的场所，与“去……下棋”的语境矛盾。"}, {"text": "俱乐部", "is_correct": true, "explanation": "俱乐部指志趣相同的人聚在一起玩的地方，去那里下棋符合词义。"}, {"text": "银行", "is_correct": false, "explanation": "语义：银行是办理存取款的地方，与下棋无关。"}, {"text": "殿堂", "is_correct": false, "explanation": "语域：“殿堂”是书面、庄重的说法，与日常周末下棋的口语语境不搭。"}], "explanations": {"医院": "语义：医院是看病的地方，不是下棋的场所，与“去……下棋”的语境矛盾。", "俱乐部": "俱乐部指志趣相同的人聚在一起玩的地方，去那里下棋符合词义。", "银行": "语义：银行是办理存取款的地方，与下棋无关。", "殿堂": "语域：“殿堂”是书面、庄重的说法，与日常周末下棋的口语语境不搭。"}, "sentence_index": 0, "correct_answer": "俱乐部"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的爷爷每天在俱乐部看病。", "explanation": "这里“俱乐部”被当作看病的地方，但它是爱好者聚会玩耍的场所，看病应该用〈医院〉。"}, {"text": "他把俱乐部装进了书包。", "explanation": "这里“俱乐部”被当作可以装进书包的物品，但它是团体或场所，装东西应该用〈盒子〉。"}, {"text": "我昨天去俱乐部洗车了。", "explanation": "这里“俱乐部”被当作洗车的地方，但它是团体或场所，洗车应该用〈洗车店〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af95e219-044f-4d55-9840-f6ea9329cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86743, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是挡雨的东西，不能说“这个雨伞的人”，句意不通。"}, {"text": "俱乐部", "is_correct": true, "explanation": "俱乐部指志趣相同的人聚会的地方或团体，“这个俱乐部的人都爱看书”说的正是这类聚会的成员。"}, {"text": "苹果", "is_correct": false, "explanation": "语义：苹果是水果，没有“成员”，“这个苹果的人都爱看书”句意不通。"}, {"text": "铅笔", "is_correct": false, "explanation": "语义：铅笔是写字的工具，没有“成员”，与句意矛盾。"}], "explanations": {"雨伞": "语义：雨伞是挡雨的东西，不能说“这个雨伞的人”，句意不通。", "俱乐部": "俱乐部指志趣相同的人聚会的地方或团体，“这个俱乐部的人都爱看书”说的正是这类聚会的成员。", "苹果": "语义：苹果是水果，没有“成员”，“这个苹果的人都爱看书”句意不通。", "铅笔": "语义：铅笔是写字的工具，没有“成员”，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "俱乐部"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每个周末去俱乐部买菜。", "explanation": "这里“俱乐部”被当作买菜的地方，但它是爱好者聚会玩耍的场所，买菜应该用〈超市〉。"}, {"text": "我明天要去俱乐部办护照。", "explanation": "这里“俱乐部”被当作办证件的机构，但它是团体或场所，办护照应该用〈出入境管理局〉。"}, {"text": "我用俱乐部给手机充电。", "explanation": "这里“俱乐部”被当作给手机充电的工具，但它是团体或场所，充电应该用〈充电器〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af95e219-044f-4d55-9840-f6ea9329cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86743, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他加入了一只俱乐部，认识了很多朋友。", "corrected_sentence": "他加入了一家俱乐部，认识了很多朋友。", "error_description": "量词错误：“俱乐部”作团体或场所时用量词“家”，不能用“只”。“只”多用于动物，应把“一只俱乐部”改为“一家俱乐部”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af95e219-044f-4d55-9840-f6ea9329cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86743, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只俱乐部每个星期六都有活动。", "corrected_sentence": "这个俱乐部每个星期六都有活动。", "error_description": "量词错误：“俱乐部”用量词“个”或“家”，不能用“只”。“只”多用于动物，应把“这只俱乐部”改为“这个俱乐部”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af95e219-044f-4d55-9840-f6ea9329cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
