INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86744, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "志趣相同的人为社交、娱乐等活动组成的团体或场所。", "primary_collocate": null, "pronunciation": "jù lè bù", "ipa": "tɕy˥˩ lɤ˥˩ pu˥˩", "syllable_count": 3, "sentences": [{"text": "她参加了学校的俱乐部，每个星期都很开心。", "target_word": "俱乐部", "complexity_tier": "T3", "furigana": "tā cān jiā le xué xiào de jù lè bù， měi gè xīng qī dōu hěn kāi xīn", "sentence_source": "generated"}, {"text": "俱乐部每个月都有一次活动。", "target_word": "俱乐部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想加入一个俱乐部，认识更多朋友。", "target_word": "俱乐部", "complexity_tier": "T3", "furigana": "wǒ xiǎng jiā rù yí gè jù lè bù， rèn shi gèng duō péng you", "sentence_source": "generated"}, {"text": "这个俱乐部有二十多个会员。", "target_word": "俱乐部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "俱乐部的会员每年交两百块钱。", "target_word": "俱乐部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是这个俱乐部的老会员。", "target_word": "俱乐部", "complexity_tier": "T3", "furigana": "tā shì zhè ge jù lè bù de lǎo huì yuán", "sentence_source": "generated"}, {"text": "俱乐部组织大家去海边玩了一天。", "target_word": "俱乐部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的俱乐部欢迎新朋友参加。", "target_word": "俱乐部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在一个俱乐部里当过组长。", "target_word": "俱乐部", "complexity_tier": "T3", "furigana": "tā zài yí gè jù lè bù lǐ dāng guo zǔ zhǎng", "sentence_source": "generated"}, {"text": "俱乐部的成员常常一起旅行。", "target_word": "俱乐部", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}, {"form": "足球俱乐部", "label": "复合"}, {"form": "俱樂部", "label": "繁体"}], "register": "中性", "sense_fingerprint": "志趣相同的人为社交、娱乐等组成的团体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88131405-7030-4d15-aa9d-0a48d00bcf95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86744, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "食堂", "is_correct": false, "explanation": "语义：食堂是吃饭的地方，不是可以参加的团体，与“参加”搭配不当。"}, {"text": "俱乐部", "is_correct": true, "explanation": "俱乐部指志趣相同的人为娱乐活动组成的团体，参加它符合词义。"}, {"text": "仓库", "is_correct": false, "explanation": "语义：仓库用来存放货物，不能参加，也和“每个星期都很开心”的语境无关。"}, {"text": "宫殿", "is_correct": false, "explanation": "语域：“宫殿”是书面、庄重的说法，与日常学校活动的语境不搭。"}], "explanations": {"食堂": "语义：食堂是吃饭的地方，不是可以参加的团体，与“参加”搭配不当。", "俱乐部": "俱乐部指志趣相同的人为娱乐活动组成的团体，参加它符合词义。", "仓库": "语义：仓库用来存放货物，不能参加，也和“每个星期都很开心”的语境无关。", "宫殿": "语域：“宫殿”是书面、庄重的说法，与日常学校活动的语境不搭。"}, "sentence_index": 0, "correct_answer": "俱乐部"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我开着俱乐部去上班。", "explanation": "这里“俱乐部”被当作交通工具，但它是团体或场所，开的应该是〈汽车〉。"}, {"text": "我家阳台上种着俱乐部。", "explanation": "这里“俱乐部”被当作植物，但它是团体或场所，阳台上种的应该是〈花〉。"}, {"text": "我昨天读完了俱乐部。", "explanation": "这里“俱乐部”被当作可以读的东西，但它是团体或场所，读的应该是〈书〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af95e219-044f-4d55-9840-f6ea9329cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86744, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "盒子", "is_correct": false, "explanation": "语义：盒子是装东西的容器，不能组织大家去海边玩。"}, {"text": "俱乐部", "is_correct": true, "explanation": "俱乐部是有组织能力的团体，能组织成员出游，符合句意。"}, {"text": "厕所", "is_correct": false, "explanation": "语义：厕所是方便的地方，无法组织活动，与“去海边玩”的语境矛盾。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟只能报时，不能组织大家去海边玩，与句意矛盾。"}], "explanations": {"盒子": "语义：盒子是装东西的容器，不能组织大家去海边玩。", "俱乐部": "俱乐部是有组织能力的团体，能组织成员出游，符合句意。", "厕所": "语义：厕所是方便的地方，无法组织活动，与“去海边玩”的语境矛盾。", "闹钟": "语义：闹钟只能报时，不能组织大家去海边玩，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "俱乐部"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家俱乐部生产手机。", "explanation": "这里“俱乐部”被当作生产产品的企业，但它是团体或场所，生产产品应该用〈公司〉。"}, {"text": "俱乐部判了他三年徒刑。", "explanation": "这里“俱乐部”被当作司法机关，但它是团体或场所，不能判刑，判刑应该用〈法院〉。"}, {"text": "这家俱乐部每天接收很多病人。", "explanation": "这里“俱乐部”被当作接收病人的医疗机构，但它是团体或场所，接收病人应该用〈医院〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af95e219-044f-4d55-9840-f6ea9329cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86744, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她在学校参加了一只俱乐部，每个星期都很开心。", "corrected_sentence": "她在学校参加了一家俱乐部，每个星期都很开心。", "error_description": "量词错误：“俱乐部”作团体时量词用“家”，不能用“只”。“只”多用于动物，应把“一只俱乐部”改为“一家俱乐部”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af95e219-044f-4d55-9840-f6ea9329cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86744, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们这位俱乐部欢迎新会员加入。", "corrected_sentence": "我们这家俱乐部欢迎新会员加入。", "error_description": "量词错误：“俱乐部”应使用量词“家”。“位”只用于人，不能修饰俱乐部，应把“这位俱乐部”改为“这家俱乐部”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af95e219-044f-4d55-9840-f6ea9329cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
