INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86745, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51e94512-9e25-4c76-b7c1-a48af2308abf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86745, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "年来是说从过去到现在的这些年。", "primary_collocate": null, "pronunciation": "nián lái", "ipa": "njɛn˧˥ laɪ˧˥", "syllable_count": 2, "sentences": [{"text": "三年来，我一直住在这个城市，到现在也没有搬走。", "target_word": "年来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十年来，这里的变化很大。", "target_word": "年来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "五年来，他每天早上都跑步。", "target_word": "年来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两年来，我们家没有搬过家。", "target_word": "年来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多年来，她一直在帮助老人。", "target_word": "年来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "八年来，我没有回过老家。", "target_word": "年来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "四年来，他学了很多汉字。", "target_word": "年来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "六年来，这家饭馆的菜一直很好吃。", "target_word": "年来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几年来，我的汉语越来越好。", "target_word": "年来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "二十年来，妈妈每天都早起做饭。", "target_word": "年来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "年來", "label": "繁体"}], "register": "书面", "sense_fingerprint": "数字加年来，从过去到现在的这些年，三年来、十年来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93ba1550-0d24-40f4-930c-c7587d5653db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86745, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "年来", "is_correct": true, "explanation": "“年来”指从过去到现在的这些年，与“三年”和“一直住”的持续意义相合。"}, {"text": "年后", "is_correct": false, "explanation": "语义：“年后”指某个时间之后，与“一直住在这个城市”所说的持续到现在不符。"}, {"text": "年底", "is_correct": false, "explanation": "搭配：“三年底”不能表示三年这一段时间，“年底”只指某一年的年末。"}, {"text": "年初", "is_correct": false, "explanation": "语义：“年初”指某一年开头的时间点，不能与表示持续的“一直”搭配。"}], "explanations": {"年来": "“年来”指从过去到现在的这些年，与“三年”和“一直住”的持续意义相合。", "年后": "语义：“年后”指某个时间之后，与“一直住在这个城市”所说的持续到现在不符。", "年底": "搭配：“三年底”不能表示三年这一段时间，“年底”只指某一年的年末。", "年初": "语义：“年初”指某一年开头的时间点，不能与表示持续的“一直”搭配。"}, "sentence_index": 0, "correct_answer": "年来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次假期年来，我一直在家休息。", "explanation": "这里不能用〈年来〉。年来只跟“几年、三年”这样的年数，“这次假期”不到一年；应说“这次假期，我一直在家休息”。"}, {"text": "我这个星期年来一直很忙。", "explanation": "这里不能用〈年来〉。年来只跟年数，不能跟“这个星期”；应说“我这个星期一直很忙”。"}, {"text": "这一天年来，我的心情一直很好。", "explanation": "这里不能用〈年来〉。年来指若干年以来，“这一天”太短；应说“这一天，我的心情一直很好”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51e94512-9e25-4c76-b7c1-a48af2308abf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86745, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "年来", "is_correct": true, "explanation": "“年来”指过去到现在的这段时间，与“四年”和“学了很多汉字”的累积结果相合。"}, {"text": "年终", "is_correct": false, "explanation": "语义：“年终”指一年的末尾，是时间点，与“四年”的时间跨度不符。"}, {"text": "年末", "is_correct": false, "explanation": "语义：“年末”指年底这一时点，与“四年”里持续学习的过程不符。"}, {"text": "年尾", "is_correct": false, "explanation": "搭配：“四年尾”不能表示一段时间，“年尾”只指一年的末段。"}], "explanations": {"年来": "“年来”指过去到现在的这段时间，与“四年”和“学了很多汉字”的累积结果相合。", "年终": "语义：“年终”指一年的末尾，是时间点，与“四年”的时间跨度不符。", "年末": "语义：“年末”指年底这一时点，与“四年”里持续学习的过程不符。", "年尾": "搭配：“四年尾”不能表示一段时间，“年尾”只指一年的末段。"}, "sentence_index": 6, "correct_answer": "年来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我计划三年来去北京旅行。", "explanation": "这里应该用〈三年后〉。年来指过去到现在的若干年，不能指将来；说将来的时间应用“三年后”。"}, {"text": "我们家这个学期年来没有搬过家。", "explanation": "这里应该用〈以来〉。年来只跟年数，“这个学期”不到一年；应说“这个学期以来，我们家没有搬过家”。"}, {"text": "我这两天年来很累。", "explanation": "这里不能用〈年来〉。年来指若干年以来，“这两天”很短；应说“我这两天很累”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51e94512-9e25-4c76-b7c1-a48af2308abf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86745, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这五个年来，他一直在学习中文。", "corrected_sentence": "这五年来，他一直在学习中文。", "error_description": "错误：“五”和“年来”之间多加了量词“个”。正确说法是“这五年来”，数词直接与“年”组成时间跨度。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51e94512-9e25-4c76-b7c1-a48af2308abf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86745, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "十年来的，我们城市的变化很大。", "corrected_sentence": "十年来，我们城市的变化很大。", "error_description": "错误：“十年来”后多加了助词“的”，后面没有被修饰的名词，应去掉“的”。正确说法是“十年来，我们城市的变化很大”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51e94512-9e25-4c76-b7c1-a48af2308abf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86747, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af95e219-044f-4d55-9840-f6ea9329cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86747, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af95e219-044f-4d55-9840-f6ea9329cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86747, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "内中是在里面。", "primary_collocate": null, "pronunciation": "nèi zhōng", "ipa": "nei˥˩ ʈʂʊŋ˥", "syllable_count": 2, "sentences": [{"text": "盒盖掀开，内中放着一封信。", "target_word": "内中", "complexity_tier": "T3", "furigana": "hé gài xiān kāi， nèi zhōng fàng zhe yì fēng xìn", "sentence_source": "generated"}, {"text": "屋外下着大雪，内中却很暖和。", "target_word": "内中", "complexity_tier": "T3", "furigana": "wū wài xià zhe dà xuě， nèi zhōng què hěn nuǎn huo", "sentence_source": "generated"}, {"text": "这座楼外面很旧，内中却很新。", "target_word": "内中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "箱子打开，内中装满了旧书。", "target_word": "内中", "complexity_tier": "T3", "furigana": "xiāng zi dǎ kāi， nèi zhōng zhuāng mǎn le jiù shū", "sentence_source": "generated"}, {"text": "钱包打开，内中还夹着一张照片。", "target_word": "内中", "complexity_tier": "T3", "furigana": "qián bāo dǎ kāi， nèi zhōng hái jiā zhe yì zhāng zhào piàn", "sentence_source": "generated"}, {"text": "洞外阳光明亮，内中却传来水声。", "target_word": "内中", "complexity_tier": "T3", "furigana": "dòng wài yáng guāng míng liàng， nèi zhōng què chuán lái shuǐ shēng", "sentence_source": "generated"}, {"text": "瓶子晃了晃，内中还剩半瓶水。", "target_word": "内中", "complexity_tier": "T3", "furigana": "píng zi huàng le huàng， nèi zhōng hái shèng bàn píng shuǐ", "sentence_source": "generated"}, {"text": "房子外面有灯，内中没有人，门却开着。", "target_word": "内中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面吵吵闹闹，内中却很安静。", "target_word": "内中", "complexity_tier": "T3", "furigana": "wài miàn chāo chao nào nao， nèi zhōng què hěn ān jìng", "sentence_source": "generated"}, {"text": "包拉开，内中还有一把伞。", "target_word": "内中", "complexity_tier": "T3", "furigana": "bāo lā kāi， nèi zhōng hái yǒu yì bǎ sǎn", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "内中：事物的里面，指空间的内部", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88131405-7030-4d15-aa9d-0a48d00bcf95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86747, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "厨房", "is_correct": false, "explanation": "语义：厨房是做饭的房间，盒子掀开后不会放在厨房里，句意不通。"}, {"text": "内中", "is_correct": true, "explanation": "内中指物体的里面。“盒盖掀开，内中放着一封信”说的是盒子里面放着信，符合词义。"}, {"text": "操场", "is_correct": false, "explanation": "语义：操场是运动场地，不能用来放信，与“盒盖掀开”的语境矛盾。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不能用来放信，与“盒盖掀开”的语境矛盾。"}], "explanations": {"厨房": "语义：厨房是做饭的房间，盒子掀开后不会放在厨房里，句意不通。", "内中": "内中指物体的里面。“盒盖掀开，内中放着一封信”说的是盒子里面放着信，符合词义。", "操场": "语义：操场是运动场地，不能用来放信，与“盒盖掀开”的语境矛盾。", "天空": "语义：天空不能用来放信，与“盒盖掀开”的语境矛盾。"}, "sentence_index": 0, "correct_answer": "内中"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他站在门内中的台阶上。", "explanation": "这里“内中”被当作门前的位置，但台阶在门外，不在里面，应该用〈门前〉。"}, {"text": "他吃饭内中接了一个电话。", "explanation": "这里“内中”被当作时间范围，但它只表示空间的里面，吃饭的时间应该用〈期间〉。"}, {"text": "桌面内中有一本书。", "explanation": "这里“内中”被当作物体的表面，但桌面没有里面，书在桌面的上方，应该用〈上面〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af95e219-044f-4d55-9840-f6ea9329cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86747, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地板", "is_correct": false, "explanation": "语义：地板不能盛水，“瓶子晃了晃”后说“地板还剩半瓶水”，句意不通。"}, {"text": "内中", "is_correct": true, "explanation": "内中指物体的里面。“瓶子晃了晃，内中还剩半瓶水”说的是瓶子里面还有水，符合词义。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：窗户不是盛水的空间，与“瓶子晃了晃”的语境搭配不当。"}, {"text": "天花板", "is_correct": false, "explanation": "语义：天花板是房顶，不能盛水，与句意矛盾。"}], "explanations": {"地板": "语义：地板不能盛水，“瓶子晃了晃”后说“地板还剩半瓶水”，句意不通。", "内中": "内中指物体的里面。“瓶子晃了晃，内中还剩半瓶水”说的是瓶子里面还有水，符合词义。", "窗户": "搭配：窗户不是盛水的空间，与“瓶子晃了晃”的语境搭配不当。", "天花板": "语义：天花板是房顶，不能盛水，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "内中"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两把椅子内中放着一盆花。", "explanation": "这里应该用〈中间〉。内中指物体的里面，两把椅子之间的位置要用中间。"}, {"text": "他跑步内中出了一身汗。", "explanation": "这里“内中”被当作活动过程中的时间，但它只表示空间的里面，跑步期间应该用〈期间〉。"}, {"text": "墙内中挂着一幅画。", "explanation": "这里“内中”被当作墙面上的位置，但画是挂在墙面上，而不是墙的里面，应该用〈墙上〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af95e219-044f-4d55-9840-f6ea9329cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86747, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "抽屉拉开，内中了还有几封信。", "corrected_sentence": "抽屉拉开，内中还有几封信。", "error_description": "用法错误：「内中」是方位词，后面不能加「了」；应说「内中还有几封信」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af95e219-044f-4d55-9840-f6ea9329cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86747, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "杯子晃了晃，内中了还剩一点水。", "corrected_sentence": "杯子晃了晃，内中还剩一点水。", "error_description": "用法错误：「内中」是方位词，后面不能加「了」；应说「内中还剩一点水」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af95e219-044f-4d55-9840-f6ea9329cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86748, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af95e219-044f-4d55-9840-f6ea9329cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86748, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af95e219-044f-4d55-9840-f6ea9329cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86748, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "里头；其中。", "primary_collocate": null, "pronunciation": "nèi zhōng", "ipa": "nei˥˩ ʈʂʊŋ˥", "syllable_count": 2, "sentences": [{"text": "事情的经过很复杂，内中原因很多。", "target_word": "内中", "complexity_tier": "T3", "furigana": "shì qing de jīng guò hěn fù zá， nèi zhōng yuán yīn hěn duō", "sentence_source": "generated"}, {"text": "内中的情况，我不太清楚。", "target_word": "内中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们三个人，内中有一个是我同学。", "target_word": "内中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我买了五本书，内中两本是送人的。", "target_word": "内中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司有三个部门，内中的问题不少。", "target_word": "内中", "complexity_tier": "T3", "furigana": "zhè jiā gōng sī yǒu sān gè bù mén， nèi zhōng de wèn tí bù shǎo", "sentence_source": "generated"}, {"text": "这件事看起来简单，内中却不简单。", "target_word": "内中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外人不知道内中的缘由。", "target_word": "内中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校有两百个学生，内中一半是外地人。", "target_word": "内中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "内中的道理，你慢慢想吧。", "target_word": "内中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事内中有人暗中帮忙，他才成功了。", "target_word": "内中", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "内中：其中，指事情的内情或总数之中的一部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88131405-7030-4d15-aa9d-0a48d00bcf95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86748, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "椅子", "is_correct": false, "explanation": "语义：椅子不能作为事情的原因，“事情的经过很复杂，椅子原因很多”句意不通。"}, {"text": "内中", "is_correct": true, "explanation": "内中表示其中，指事情内部的情况。“内中原因很多”说的是事情的内情，符合词义。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是房间，不能成为事情的原因，与句意矛盾。"}, {"text": "宫殿", "is_correct": false, "explanation": "语域：“宫殿”是书面、庄重的说法，与叙述事情经过的语境不搭，且指建筑，无法指原因。"}], "explanations": {"椅子": "语义：椅子不能作为事情的原因，“事情的经过很复杂，椅子原因很多”句意不通。", "内中": "内中表示其中，指事情内部的情况。“内中原因很多”说的是事情的内情，符合词义。", "厨房": "语义：厨房是房间，不能成为事情的原因，与句意矛盾。", "宫殿": "语域：“宫殿”是书面、庄重的说法，与叙述事情经过的语境不搭，且指建筑，无法指原因。"}, "sentence_index": 0, "correct_answer": "内中"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两座山内中有一条河。", "explanation": "这里“内中”被当作两山之间的空隙，但它只表示范围里面或其中的一部分，两座山之间应该用〈之间〉。"}, {"text": "吃完饭内中，我去散步。", "explanation": "这里“内中”被当作时间的先后，但它表示里头或其中，不表示先后，吃完饭之后应该用〈之后〉。"}, {"text": "三天内中完成了任务。", "explanation": "这里“内中”被当作时间范围，但它不表示时间段，三天之内应该用〈之内〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af95e219-044f-4d55-9840-f6ea9329cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86748, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不是事情的缘由，“外人不知道冰箱的缘由”句意不通。"}, {"text": "内中", "is_correct": true, "explanation": "内中表示内情，“外人不知道内中的缘由”说的是事情内部的缘由，符合词义。"}, {"text": "公交车", "is_correct": false, "explanation": "语义：公交车不是事情的缘由，“外人不知道公交车的缘由”句意不通。"}, {"text": "书桌", "is_correct": false, "explanation": "语义：书桌不是事情的缘由，“外人不知道书桌的缘由”句意不通。"}], "explanations": {"冰箱": "语义：冰箱不是事情的缘由，“外人不知道冰箱的缘由”句意不通。", "内中": "内中表示内情，“外人不知道内中的缘由”说的是事情内部的缘由，符合词义。", "公交车": "语义：公交车不是事情的缘由，“外人不知道公交车的缘由”句意不通。", "书桌": "语义：书桌不是事情的缘由，“外人不知道书桌的缘由”句意不通。"}, "sentence_index": 6, "correct_answer": "内中"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我内中去过北京。", "explanation": "这里“内中”被当作表示经历的时间副词，但它表示其中或内情，表示以前做过应该用〈曾经〉。"}, {"text": "这本书很内中。", "explanation": "这里“内中”被当作形容词，但它表示其中或内情，不能受“很”修饰，夸书好看应该用〈有意思〉。"}, {"text": "他上课内中迟到。", "explanation": "这里“内中”被当作表示频率的副词，但它表示其中或内情，表示常常发生应该用〈经常〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af95e219-044f-4d55-9840-f6ea9329cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86748, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "事情的经过很复杂，内中了的原因不少。", "corrected_sentence": "事情的经过很复杂，内中的原因不少。", "error_description": "用法错误：「内中」是方位词，不能带「了」；应说「内中的原因不少」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af95e219-044f-4d55-9840-f6ea9329cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86748, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "班上有四十个学生，的内中一半是女生。", "corrected_sentence": "班上有四十个学生，内中一半是女生。", "error_description": "位置错误：「的」不能放在「内中」前面；应说「内中一半是女生」，「内中」直接放在数量短语「一半」之前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af95e219-044f-4d55-9840-f6ea9329cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
