INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86750, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指时代、岁月；日子。", "primary_collocate": null, "pronunciation": "nián yuè", "ipa": "njɛn˧˥ ɥɛ˥˩", "syllable_count": 2, "sentences": [{"text": "这年月，找一份好工作不容易。", "target_word": "年月", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好年月不会一直有，要懂得珍惜。", "target_word": "年月", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这年月，谁都离不开手机。", "target_word": "年月", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他在这座城市度过了漫长的年月。", "target_word": "年月", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在平静的年月里，人们过着简单的生活。", "target_word": "年月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年月久了，墙上的画也旧了。", "target_word": "年月", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "太平年月，人们都想过好日子。", "target_word": "年月", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不管什么年月，诚实都是最重要的。", "target_word": "年月", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这是一个人人都忙的年月。", "target_word": "年月", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在那个年月，读书的人还不多。", "target_word": "年月", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "年月：时代、岁月、日子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef6fb817-c5a5-47d1-a0ed-24e25267f898') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86750, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "钥匙", "is_correct": false, "explanation": "语义：“钥匙”是物件，不能指时代，与“这……，找工作不容易”的时代义不符。"}, {"text": "房间", "is_correct": false, "explanation": "语义：“房间”与时代无关，“这房间，找工作不容易”说不通。"}, {"text": "年月", "is_correct": true, "explanation": "“年月”指时代，“这年月”即当前的时代，符合语境。"}, {"text": "书包", "is_correct": false, "explanation": "语义：“书包”是物件，不能指时代，句子说不通。"}], "explanations": {"钥匙": "语义：“钥匙”是物件，不能指时代，与“这……，找工作不容易”的时代义不符。", "房间": "语义：“房间”与时代无关，“这房间，找工作不容易”说不通。", "年月": "“年月”指时代，“这年月”即当前的时代，符合语境。", "书包": "语义：“书包”是物件，不能指时代，句子说不通。"}, "sentence_index": 0, "correct_answer": "年月"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他参观了这座城市的年月。", "explanation": "这里应该用〈历史〉。“参观”的对象是博物馆、遗迹等具体场所，不能参观“年月”；“年月”指时代或日子。"}, {"text": "他的年月比我大三岁。", "explanation": "这里应该用〈年龄〉。“年月”指时代或日子，不指人的岁数。"}, {"text": "他在这座城市拍下了漫长的年月。", "explanation": "这里应该用〈度过〉。“拍”用于照片、影像，不能“拍”年月。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a681fc-fe7f-4c14-8977-15c7203e90a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86750, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "战乱", "is_correct": false, "explanation": "语义：“战乱”与“太平”意思相反。"}, {"text": "年月", "is_correct": true, "explanation": "“年月”指时代，“太平年月”指和平的时代，符合语境。"}, {"text": "年纪", "is_correct": false, "explanation": "搭配：“太平”修饰社会或时代，不修饰“年纪”。"}, {"text": "灾年", "is_correct": false, "explanation": "语义：“灾年”指灾荒之年，与“太平”相矛盾。"}], "explanations": {"战乱": "语义：“战乱”与“太平”意思相反。", "年月": "“年月”指时代，“太平年月”指和平的时代，符合语境。", "年纪": "搭配：“太平”修饰社会或时代，不修饰“年纪”。", "灾年": "语义：“灾年”指灾荒之年，与“太平”相矛盾。"}, "sentence_index": 6, "correct_answer": "年月"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他辞去了漫长的年月。", "explanation": "这里应该用〈工作〉。“辞去”的对象是工作、职务，不能辞去“年月”；“年月”指时代或日子。"}, {"text": "我们班里年纪最大的学生，年月也最大。", "explanation": "这里应该用〈岁数〉。“年月”指时代或日子，不能用来说人的岁数。"}, {"text": "他把这个年月的工资都花光了。", "explanation": "这里应该用〈月〉。“年月”指时代或日子，不表示某一个具体的月份；某个月的工资应说“这个月”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a681fc-fe7f-4c14-8977-15c7203e90a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86750, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我度过了一根漫长的年月。", "corrected_sentence": "我度过了一段漫长的年月。", "error_description": "量词用错：“年月”应用“段”，“根”用于条状的东西，不能修饰“年月”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a681fc-fe7f-4c14-8977-15c7203e90a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86750, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个的年月，年轻人还很少出门。", "corrected_sentence": "那个年月，年轻人还很少出门。", "error_description": "指示词“那个”与名词“年月”之间不能加“的”，应说“那个年月”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a681fc-fe7f-4c14-8977-15c7203e90a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
