INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86751, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "几乎是差一点就这样了，可是没有。", "primary_collocate": null, "pronunciation": "jī hū", "ipa": "tɕi˥ xu˥", "syllable_count": 2, "sentences": [{"text": "我几乎要迟到了。", "target_word": "几乎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他几乎摔倒了，幸好扶住了桌子。", "target_word": "几乎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我几乎忘了今天是她的生日。", "target_word": "几乎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车开得太快，几乎撞到了人。", "target_word": "几乎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到这个消息，我几乎哭了。", "target_word": "几乎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我几乎错过了最后一班地铁。", "target_word": "几乎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他几乎把手机掉进水里。", "target_word": "几乎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刚才我几乎说错了她的名字。", "target_word": "几乎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只杯子几乎掉到地上，我赶紧接住了。", "target_word": "几乎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我几乎买了那件贵衣服，后来还是放下了。", "target_word": "几乎", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "幾乎", "label": "繁体"}], "register": "中性", "sense_fingerprint": "几乎：差一点发生某事，但实际没有发生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93ba1550-0d24-40f4-930c-c7587d5653db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86751, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "几乎", "is_correct": true, "explanation": "“几乎”表示差一点发生却没有发生，与“要迟到了”的紧迫情况相合。"}, {"text": "从来", "is_correct": false, "explanation": "语义：“从来”表示从未发生过，与“要迟到了”的眼前情况相矛盾。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示动作正在进行，不能与表示将要发生的“要迟到了”组合。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不常发生，与“要迟到了”的紧迫情况不合。"}], "explanations": {"几乎": "“几乎”表示差一点发生却没有发生，与“要迟到了”的紧迫情况相合。", "从来": "语义：“从来”表示从未发生过，与“要迟到了”的眼前情况相矛盾。", "正在": "体貌：“正在”表示动作正在进行，不能与表示将要发生的“要迟到了”组合。", "偶尔": "语义：“偶尔”表示不常发生，与“要迟到了”的紧迫情况不合。"}, "sentence_index": 0, "correct_answer": "几乎"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我几乎摔倒了，结果我真的摔倒在地上。", "explanation": "这里不能用〈几乎〉。几乎表示差一点发生却没有发生，后面说真的摔倒了，应直接说“我摔倒了”。"}, {"text": "他几乎撞到了桌子，桌子已经被撞倒了。", "explanation": "这里不能用〈几乎〉。几乎表示差一点发生却没有发生，桌子已经被撞倒，应直接说“他撞到了桌子”。"}, {"text": "我几乎丢了钱包，现在钱包真的找不到了。", "explanation": "这里不能用〈几乎〉。几乎表示差一点发生却没有发生，钱包真的丢了，应直接说“我丢了钱包”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51e94512-9e25-4c76-b7c1-a48af2308abf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86751, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "几乎", "is_correct": true, "explanation": "“几乎”表示差一点把手机掉进水里却没有掉，与句子描述的险情相合。"}, {"text": "终于", "is_correct": false, "explanation": "语义：“终于”表示经过努力后达到某种结果，与“掉进水里”的意外情况不合。"}, {"text": "不必", "is_correct": false, "explanation": "语义：“不必”表示没有必要，与“掉进水里”这一具体事件的叙述不合。"}, {"text": "从来", "is_correct": false, "explanation": "语义：“从来”表示一贯如此或从未发生，与一次具体的意外事件不合。"}], "explanations": {"几乎": "“几乎”表示差一点把手机掉进水里却没有掉，与句子描述的险情相合。", "终于": "语义：“终于”表示经过努力后达到某种结果，与“掉进水里”的意外情况不合。", "不必": "语义：“不必”表示没有必要，与“掉进水里”这一具体事件的叙述不合。", "从来": "语义：“从来”表示一贯如此或从未发生，与一次具体的意外事件不合。"}, "sentence_index": 6, "correct_answer": "几乎"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我几乎买了那件衣服，最后真的买了。", "explanation": "这里不能用〈几乎〉。几乎表示差一点发生却没有发生，最后真的买了，应直接说“我买了那件衣服”。"}, {"text": "他几乎迟到了，结果迟到了二十分钟。", "explanation": "这里不能用〈几乎〉。几乎表示差一点发生却没有发生，后面说真的迟到了，应直接说“他迟到了”。"}, {"text": "我几乎忘了带伞，所以全身都淋湿了。", "explanation": "这里不能用〈几乎〉。几乎表示差一点发生却没有发生，淋湿说明真的忘了，应直接说“我忘了带伞”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51e94512-9e25-4c76-b7c1-a48af2308abf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86751, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈几乎很把饭烧糊了。", "corrected_sentence": "妈妈几乎把饭烧糊了。", "error_description": "错误：副词“几乎”与“把”字句之间多加了程度副词“很”，“几乎”后不能接“很”。正确说法是“妈妈几乎把饭烧糊了。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51e94512-9e25-4c76-b7c1-a48af2308abf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86751, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他几乎的把书包忘在地铁上了。", "corrected_sentence": "他几乎把书包忘在地铁上了。", "error_description": "错误：副词“几乎”后多加了“的”，“几乎”与后面的“把”字结构之间不能插入“的”。正确说法是“他几乎把书包忘在地铁上了。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51e94512-9e25-4c76-b7c1-a48af2308abf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
