INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86753, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "公路是汽车跑的大马路。", "primary_collocate": null, "pronunciation": "gōng lù", "ipa": "kʊŋ˥ lu˥˩", "syllable_count": 2, "sentences": [{"text": "这条公路又宽又平。", "target_word": "公路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车在公路上跑得很快。", "target_word": "公路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公路两边都是高高的树。", "target_word": "公路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把车停在公路旁边。", "target_word": "公路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公路上有很多大卡车。", "target_word": "公路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们不能在公路上玩。", "target_word": "公路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，公路变得很滑。", "target_word": "公路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们沿着公路一直往前走。", "target_word": "公路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条公路晚上很安静。", "target_word": "公路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公路上的车越来越多。", "target_word": "公路", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "高速公路", "label": "复合"}, {"form": "公路网", "label": "复合"}], "register": "中性", "sense_fingerprint": "汽车行驶的宽大路面，强调路本身", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb942baf-2f2e-4d1b-8c28-1bbea51ff9ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86753, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "公路", "is_correct": true, "explanation": "公路：供汽车等车辆行驶的宽阔道路，即正确答案。"}, {"text": "公务", "is_correct": false, "explanation": "l 与 w 声母不同（lù 与 wù），公务指公家的事务。"}, {"text": "功率", "is_correct": false, "explanation": "lù 与 lǜ 韵母不同（u 与 ü），功率指做功的快慢。"}, {"text": "公寓", "is_correct": false, "explanation": "l 与零声母不同（lù 与 yù），公寓指居住的楼房单元。"}, {"text": "公墓", "is_correct": false, "explanation": "l 与 m 声母不同，公墓指供埋葬用的墓地。"}], "explanations": {"公路": "公路：供汽车等车辆行驶的宽阔道路，即正确答案。", "公务": "l 与 w 声母不同（lù 与 wù），公务指公家的事务。", "功率": "lù 与 lǜ 韵母不同（u 与 ü），功率指做功的快慢。", "公寓": "l 与零声母不同（lù 与 yù），公寓指居住的楼房单元。", "公墓": "l 与 m 声母不同，公墓指供埋葬用的墓地。"}, "sentence_index": null, "correct_answer": "公路"}, "level_3": {"options": [{"text": "公路", "is_correct": true, "explanation": "公路：指宽阔平整、供汽车行驶的路面，符合“又宽又平”。"}, {"text": "楼梯", "is_correct": false, "explanation": "语义：楼梯有台阶，不平，不能说“又宽又平”。"}, {"text": "绳子", "is_correct": false, "explanation": "语义：绳子细长，不能说“又宽”。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“条”不用来量桌子，应说“张”。"}], "explanations": {"公路": "公路：指宽阔平整、供汽车行驶的路面，符合“又宽又平”。", "楼梯": "语义：楼梯有台阶，不平，不能说“又宽又平”。", "绳子": "语义：绳子细长，不能说“又宽”。", "桌子": "搭配：“条”不用来量桌子，应说“张”。"}, "sentence_index": 0, "correct_answer": "公路"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "火车在公路上开得很快。", "explanation": "这里应该用〈铁路〉。火车只能在铁路上行驶，公路供汽车等车辆通行，不能说火车在公路上开。"}, {"text": "飞机在公路上滑行。", "explanation": "这里应该用〈跑道〉。飞机起飞、滑行要在跑道上进行，公路是供汽车行驶的路面。"}, {"text": "这只公路很宽。", "explanation": "这里应该用〈条〉。公路的量词是“条”，“只”多用于动物，不能量公路。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7107b31-8fc7-4fd6-a9d1-020d059188d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86753, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "公路", "is_correct": true, "explanation": "公路：供汽车等车辆行驶的宽阔道路，即正确答案。"}, {"text": "通路", "is_correct": false, "explanation": "g 与 t 声母不同，通路指通行的途径，不是供汽车跑的大路。"}, {"text": "功利", "is_correct": false, "explanation": "lù 与 lì 韵母不同（u 与 i），功利指追求实际利益。"}, {"text": "公诉", "is_correct": false, "explanation": "l 与 s 声母不同，公诉指检察机关向法院提起诉讼。"}, {"text": "中路", "is_correct": false, "explanation": "g 与 zh 声母不同，中路指中间的路线，不是公路。"}], "explanations": {"公路": "公路：供汽车等车辆行驶的宽阔道路，即正确答案。", "通路": "g 与 t 声母不同，通路指通行的途径，不是供汽车跑的大路。", "功利": "lù 与 lì 韵母不同（u 与 i），功利指追求实际利益。", "公诉": "l 与 s 声母不同，公诉指检察机关向法院提起诉讼。", "中路": "g 与 zh 声母不同，中路指中间的路线，不是公路。"}, "sentence_index": null, "correct_answer": "公路"}, "level_3": {"options": [{"text": "公路", "is_correct": true, "explanation": "公路：下雨后路面变滑，符合句意。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不会“变得很滑”，“滑”只用来描述路面等表面。"}, {"text": "朋友", "is_correct": false, "explanation": "语义：句中“滑”指路面湿滑，下雨使路面变滑，“朋友”不能因下雨而“变得很滑”。"}, {"text": "蛋糕", "is_correct": false, "explanation": "搭配：“变得很滑”多用于路面、地面，不说食物变滑。"}], "explanations": {"公路": "公路：下雨后路面变滑，符合句意。", "天空": "语义：天空不会“变得很滑”，“滑”只用来描述路面等表面。", "朋友": "语义：句中“滑”指路面湿滑，下雨使路面变滑，“朋友”不能因下雨而“变得很滑”。", "蛋糕": "搭配：“变得很滑”多用于路面、地面，不说食物变滑。"}, "sentence_index": 6, "correct_answer": "公路"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们每天坐公路去上班。", "explanation": "这里应该用〈走〉。公路是路，不是交通工具，不能说“坐公路”。"}, {"text": "我在公路上煮了一锅饭。", "explanation": "这里应该用〈厨房〉。做饭要在厨房里进行，公路是供汽车行驶的路，不是做饭的地方。"}, {"text": "这条公路开得很快。", "explanation": "这里的主语应该是〈汽车〉。公路不会开车，它是供车辆行驶的路，不能做“开”的主语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7107b31-8fc7-4fd6-a9d1-020d059188d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXC