INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86755, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "文章是用字写成的一篇东西。", "primary_collocate": null, "pronunciation": "wén zhāng", "ipa": "wən˧˥ ʈʂɑŋ˥", "syllable_count": 2, "sentences": [{"text": "这篇文章很长。", "target_word": "文章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天写了一篇文章。", "target_word": "文章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们读这篇文章。", "target_word": "文章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的文章写得很好。", "target_word": "文章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章有三百个字。", "target_word": "文章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在网上看到一篇有意思的文章。", "target_word": "文章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每周写一篇文章。", "target_word": "文章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把这篇文章读一遍。", "target_word": "文章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章的名字是什么？", "target_word": "文章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟的文章里有很多错字。", "target_word": "文章", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "篇", "label": "量词"}], "register": "中性", "sense_fingerprint": "用字写成的一篇东西，可以读、可以写", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25be5f49-5a16-4b1c-a339-0cf287f7ff26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86755, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "文章", "is_correct": true, "explanation": "正确答案：文章，“这篇文章”指一篇文字作品，符合“很长”的语境。"}, {"text": "河", "is_correct": false, "explanation": "搭配：量词“篇”只用于文字作品，河流应说“条”。"}, {"text": "桥", "is_correct": false, "explanation": "搭配：桥应用量词“座”，“篇”不能用于桥。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字不是独立成篇的作品，与量词“篇”的语义不符。"}], "explanations": {"文章": "正确答案：文章，“这篇文章”指一篇文字作品，符合“很长”的语境。", "河": "搭配：量词“篇”只用于文字作品，河流应说“条”。", "桥": "搭配：桥应用量词“座”，“篇”不能用于桥。", "名字": "语义：名字不是独立成篇的作品，与量词“篇”的语义不符。"}, "sentence_index": 0, "correct_answer": "文章"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这篇文章的颜色很漂亮，我很喜欢。", "explanation": "这里应该用〈画〉。文章是用字写成的作品，没有颜色；谈颜色、色彩的是画。"}, {"text": "他写了一只文章。", "explanation": "量词错误：文章应用“篇”，“只”用于动物等，不能用于文章。"}, {"text": "这篇文章很高，放在书架的最上层。", "explanation": "这里应该用〈书〉。文章是用字写成的作品，本身没有高矮；说高矮、放在书架上的一般是书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f59eef98-5920-4c5f-afac-18238bea63cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86755, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "文章", "is_correct": true, "explanation": "正确答案：文章，“写一篇文章”符合“每周”的语境。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“写”不能与“体温”搭配，体温也不是文字作品。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“写”不能以“声音”为宾语。"}, {"text": "梦", "is_correct": false, "explanation": "语义：梦不是用来“写”的独立文字作品，与“一篇”不符。"}], "explanations": {"文章": "正确答案：文章，“写一篇文章”符合“每周”的语境。", "体温": "搭配：“写”不能与“体温”搭配，体温也不是文字作品。", "声音": "搭配：“写”不能以“声音”为宾语。", "梦": "语义：梦不是用来“写”的独立文字作品，与“一篇”不符。"}, "sentence_index": 6, "correct_answer": "文章"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这篇文章有四条腿，跑得很快。", "explanation": "这里应该用〈动物〉。文章是用字写成的作品，没有腿，不会跑；有腿会跑的要说动物。"}, {"text": "我读了一本文章。", "explanation": "量词错误：文章应用“篇”，“本”用于书籍，不能用于文章。"}, {"text": "妈妈用文章包饺子。", "explanation": "这里应该用〈面皮〉。文章是用字写成的作品，不能用来包东西；包饺子要用面皮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f59eef98-5920-4c5f-afac-18238bea63cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86755, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她前天写了一个文章。", "corrected_sentence": "她前天写了一篇文章。", "error_description": "量词错误：“文章”应用量词“篇”，“个”不能用于文章，“一个文章”应改为“一篇文章”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f59eef98-5920-4c5f-afac-18238bea63cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86755, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他昨天写了一幅文章。", "corrected_sentence": "他昨天写了一篇文章。", "error_description": "量词错误：“文章”应用量词“篇”，“幅”用于画作等，不能用于文章，“一幅文章”应改为“一篇文章”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f59eef98-5920-4c5f-afac-18238bea63cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
