INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86756, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "独立成篇的文字作品。", "primary_collocate": null, "pronunciation": "wén zhāng", "ipa": "wən˧˥ ʈʂɑŋ˥", "syllable_count": 2, "sentences": [{"text": "报上有一篇关于北京的文章。", "target_word": "文章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写的文章常常在杂志上发表。", "target_word": "文章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章讲的是健康问题。", "target_word": "文章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最喜欢她的文章。", "target_word": "文章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章分成了三个部分。", "target_word": "文章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他读过很多好文章。", "target_word": "文章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说这篇文章写得很清楚。", "target_word": "文章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "文章的开头很吸引人。", "target_word": "文章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想给学校的杂志写一篇文章。", "target_word": "文章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些文章都是学生写的。", "target_word": "文章", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "篇", "label": "量词"}], "register": "中性", "sense_fingerprint": "独立成篇的文字作品，可发表、有主题", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25be5f49-5a16-4b1c-a339-0cf287f7ff26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86756, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "文章", "is_correct": true, "explanation": "正确答案：文章，“报上有一篇关于北京的文章”指报纸上刊登的文字作品。"}, {"text": "地图", "is_correct": false, "explanation": "搭配：量词“篇”不用于地图，地图应说“张”。"}, {"text": "广播", "is_correct": false, "explanation": "语义：广播是声音节目，不能刊登在报上。"}, {"text": "视频", "is_correct": false, "explanation": "语义：视频不能刊登在报纸上，与“报上”冲突。"}], "explanations": {"文章": "正确答案：文章，“报上有一篇关于北京的文章”指报纸上刊登的文字作品。", "地图": "搭配：量词“篇”不用于地图，地图应说“张”。", "广播": "语义：广播是声音节目，不能刊登在报上。", "视频": "语义：视频不能刊登在报纸上，与“报上”冲突。"}, "sentence_index": 0, "correct_answer": "文章"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这篇文章有四条腿，每天会自己在院子里跑。", "explanation": "这里应该用〈动物〉。文章是用字写成的作品，没有腿，不会跑；会自己跑的要说动物。"}, {"text": "我最喜欢她的一只文章。", "explanation": "量词错误：文章应用“篇”，“只”不能用于文章。"}, {"text": "她的文章会叫，每天早上都叫我起床。", "explanation": "这里应该用〈闹钟〉。文章是用字写成的作品，不会叫；每天早上叫人起床的要说闹钟。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f59eef98-5920-4c5f-afac-18238bea63cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86756, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "文章", "is_correct": true, "explanation": "正确答案：文章，“写得很清楚”可以用来描述文字作品，符合语境。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“写得很清楚”只用于文字，不能用于声音。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是可以被“写”的对象，与“写得很清楚”冲突。"}, {"text": "脸", "is_correct": false, "explanation": "语义：脸不能被“写”，与“写得很清楚”冲突。"}], "explanations": {"文章": "正确答案：文章，“写得很清楚”可以用来描述文字作品，符合语境。", "声音": "搭配：“写得很清楚”只用于文字，不能用于声音。", "天空": "语义：天空不是可以被“写”的对象，与“写得很清楚”冲突。", "脸": "语义：脸不能被“写”，与“写得很清楚”冲突。"}, "sentence_index": 6, "correct_answer": "文章"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这篇文章每一页都印着日期，可以挂在墙上。", "explanation": "这里应该用〈日历〉。文章是用字写成的作品，每页印日期、挂在墙上的要说日历。"}, {"text": "她买了一双文章。", "explanation": "量词错误：文章应用“篇”，“双”用于成对的东西，不能用于文章。"}, {"text": "这篇文章很冷，放在冰箱里保存。", "explanation": "这里应该用〈食物〉。文章是用字写成的作品，没有温度；要冷藏、放进冰箱的是食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f59eef98-5920-4c5f-afac-18238bea63cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86756, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块文章很有意思。", "corrected_sentence": "这篇文章很有意思。", "error_description": "量词错误：“文章”应用量词“篇”，“块”用于块状物，不能用于文章，“这块文章”应改为“这篇文章”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f59eef98-5920-4c5f-afac-18238bea63cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86756, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他昨天写了一封文章。", "corrected_sentence": "他昨天写了一篇文章。", "error_description": "量词错误：“文章”应用量词“篇”，“封”用于信件等，不能用于文章，“一封文章”应改为“一篇文章”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f59eef98-5920-4c5f-afac-18238bea63cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
