INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86757, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "生命是活着的东西才有的，没有它就不能动也不能长。", "primary_collocate": null, "pronunciation": "shēng mìng", "ipa": "ʂɤŋ˥ miŋ˥˩", "syllable_count": 2, "sentences": [{"text": "小草也有生命。", "target_word": "生命", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "种子里面有生命，春天就会长出来。", "target_word": "生命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月亮上没有生命。", "target_word": "生命", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "石头没有生命，不会动也不会长。", "target_word": "生命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家想找到别的星球上的生命。", "target_word": "生命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水是生命的来源。", "target_word": "生命", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小鸟的生命从一个蛋开始。", "target_word": "生命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这棵树看起来没有生命了，其实春天会发芽。", "target_word": "生命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地球上的生命需要水和空气。", "target_word": "生命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们很爱护身边的小生命。", "target_word": "生命", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "生命力", "label": "复合"}, {"form": "生命线", "label": "复合"}], "register": "中性", "sense_fingerprint": "生命：活的东西才有，能动能长", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93ba1550-0d24-40f4-930c-c7587d5653db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86757, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生命", "is_correct": true, "explanation": "正确：“小草也有生命”指小草具有生长的活动能力，句子通顺。"}, {"text": "钱", "is_correct": false, "explanation": "语义：小草不会拥有钱，与“小草”的语境不符。"}, {"text": "嘴", "is_correct": false, "explanation": "体貌：小草没有嘴巴，“小草也有嘴”不合常识。"}, {"text": "手", "is_correct": false, "explanation": "体貌：小草没有手，“小草也有手”不合常识。"}], "explanations": {"生命": "正确：“小草也有生命”指小草具有生长的活动能力，句子通顺。", "钱": "语义：小草不会拥有钱，与“小草”的语境不符。", "嘴": "体貌：小草没有嘴巴，“小草也有嘴”不合常识。", "手": "体貌：小草没有手，“小草也有手”不合常识。"}, "sentence_index": 0, "correct_answer": "生命"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这束花的生命只要十块钱。", "explanation": "这里应该用〈价钱〉。“价钱”指商品的售价，“生命”指活的状态，不能用来说花的价钱。"}, {"text": "这株小草的生命一天比一天高。", "explanation": "这里应该用〈个子〉。说草长得多高要用“个子”或“高度”，“生命”不能用“一天比一天高”来描述。"}, {"text": "这棵树的生命已经五十岁了。", "explanation": "这里应该用〈年龄〉。说树木多少岁要用“年龄”，“生命”不能与“五十岁”搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51e94512-9e25-4c76-b7c1-a48af2308abf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86757, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生命", "is_correct": true, "explanation": "正确：“小鸟的生命从一个蛋开始”指小鸟生命的起点，句子通顺。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“作业”不能指生命的开端，“小鸟的作业从一个蛋开始”不通。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子不会从一个蛋开始，与“小鸟”的语境不相配。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：“从……开始”不能搭配“名字”，“名字从一个蛋开始”不通。"}], "explanations": {"生命": "正确：“小鸟的生命从一个蛋开始”指小鸟生命的起点，句子通顺。", "作业": "搭配：“作业”不能指生命的开端，“小鸟的作业从一个蛋开始”不通。", "房子": "语义：房子不会从一个蛋开始，与“小鸟”的语境不相配。", "名字": "搭配：“从……开始”不能搭配“名字”，“名字从一个蛋开始”不通。"}, "sentence_index": 6, "correct_answer": "生命"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这节课的生命有四十分钟。", "explanation": "这里应该用〈时长〉。“时长”指一段时间的长短，一节课的长度要说“时长”，“生命”不能指这段时间。"}, {"text": "这个月孩子的生命增加了三公斤。", "explanation": "这里应该用〈体重〉。“体重”指身体的重量，孩子的重量要说“体重”，“生命”不能用“增加了三公斤”来描述。"}, {"text": "今天是孩子们的生命，大家都来祝贺。", "explanation": "这里应该用〈生日〉。“生日”指出生的那一天，“生命”不能用来指这一天。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51e94512-9e25-4c76-b7c1-a48af2308abf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86757, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块石头里没有一朵生命。", "corrected_sentence": "这块石头里没有一条生命。", "error_description": "量词错误：“生命”应使用量词“条”，应说“没有一条生命”，不能说“没有一朵生命”。“朵”只用于花、云等。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51e94512-9e25-4c76-b7c1-a48af2308abf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86757, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们在花园里发现了一座小生命。", "corrected_sentence": "孩子们在花园里发现了一个小生命。", "error_description": "“小生命”前的量词错误：应用“个”，“座”多用于山、房屋等大型固定物，不能修饰“小生命”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51e94512-9e25-4c76-b7c1-a48af2308abf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86758, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "死亡", "is_correct": true, "explanation": "反义：“生命”指活着的状态，“死亡”指生命的终结，二者构成反义关系。"}, {"text": "音乐", "is_correct": false, "explanation": "无关：“音乐”与“生命”的任何义项都没有反义关系。"}, {"text": "天空", "is_correct": false, "explanation": "无关：“天空”与“生命”的任何义项都没有反义关系。"}, {"text": "河流", "is_correct": false, "explanation": "无关：“河流”与“生命”的任何义项都没有反义关系。"}], "correct_answer": "死亡", "explanations": {"死亡": "反义：“生命”指活着的状态，“死亡”指生命的终结，二者构成反义关系。", "音乐": "无关：“音乐”与“生命”的任何义项都没有反义关系。", "天空": "无关：“天空”与“生命”的任何义项都没有反义关系。", "河流": "无关：“河流”与“生命”的任何义项都没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51e94512-9e25-4c76-b7c1-a48af2308abf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86758, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "死亡", "is_correct": true, "explanation": "反义：“生命”指活着的状态，“死亡”指生命的终结，二者构成反义关系。"}, {"text": "考试", "is_correct": false, "explanation": "无关：“考试”与“生命”的任何义项都没有反义关系。"}, {"text": "花园", "is_correct": false, "explanation": "无关：“花园”与“生命”的任何义项都没有反义关系。"}, {"text": "收音机", "is_correct": false, "explanation": "无关：“收音机”与“生命”的任何义项都没有反义关系。"}], "correct_answer": "死亡", "explanations": {"死亡": "反义：“生命”指活着的状态，“死亡”指生命的终结，二者构成反义关系。", "考试": "无关：“考试”与“生命”的任何义项都没有反义关系。", "花园": "无关：“花园”与“生命”的任何义项都没有反义关系。", "收音机": "无关：“收音机”与“生命”的任何义项都没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51e94512-9e25-4c76-b7c1-a48af2308abf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86758, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "生物体具有的生长、繁殖、新陈代谢等活动能力；人的性命。", "primary_collocate": null, "pronunciation": "shēng mìng", "ipa": "ʂɤŋ˥ miŋ˥˩", "syllable_count": 2, "sentences": [{"text": "医生保住了他的生命。", "target_word": "生命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为了救孩子，失去了生命。", "target_word": "生命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人的生命都很宝贵。", "target_word": "生命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场大火夺走了三个人的生命。", "target_word": "生命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机的生命没有危险。", "target_word": "生命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生物的生命活动需要能量。", "target_word": "生命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人的生命走到了尽头。", "target_word": "生命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要拿生命开玩笑。", "target_word": "生命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把一生都献给了科学，直到生命的最后一天。", "target_word": "生命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "安全带能保护我们的生命。", "target_word": "生命", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "生命力", "label": "复合"}, {"form": "生命线", "label": "复合"}], "register": "中性", "sense_fingerprint": "生命：人的性命，生物的生命活动能力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93ba1550-0d24-40f4-930c-c7587d5653db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86758, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生命", "is_correct": true, "explanation": "正确：“保住”的对象是人的性命，“保住了他的生命”通顺。"}, {"text": "房子", "is_correct": false, "explanation": "语义：医生保住的是病人的性命，不会去保住一座房子。"}, {"text": "考试", "is_correct": false, "explanation": "搭配：“保住”不能与“考试”搭配，“保住了他的考试”不成话。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”与“医生”“保住”不相配，医生不会保住一张桌子。"}], "explanations": {"生命": "正确：“保住”的对象是人的性命，“保住了他的生命”通顺。", "房子": "语义：医生保住的是病人的性命，不会去保住一座房子。", "考试": "搭配：“保住”不能与“考试”搭配，“保住了他的考试”不成话。", "桌子": "语义：“桌子”与“医生”“保住”不相配，医生不会保住一张桌子。"}, "sentence_index": 0, "correct_answer": "生命"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场足球比赛的生命是九十分钟。", "explanation": "这里应该用〈时长〉。“时长”指经历的时间长短，比赛的长短要说“时长”；“生命”指生物的生存或生命活动，不指比赛的时间。"}, {"text": "这台机器的生命只有三年。", "explanation": "这里应该用〈寿命〉。“寿命”指事物能使用的年限，机器没有生命，“生命只有三年”不符合习惯。"}, {"text": "他每月的生命是五千元。", "explanation": "这里应该用〈工资〉。“工资”指按月发给的报酬，“生命”不指收入，不能说“每月的生命是五千元”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51e94512-9e25-4c76-b7c1-a48af2308abf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86758, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生命", "is_correct": true, "explanation": "正确：“走到尽头”可以用于人的生命，“老人的生命走到了尽头”通顺。"}, {"text": "学号", "is_correct": false, "explanation": "语义：“学号”是学生的编号，不会“走到尽头”，“老人的学号走到了尽头”不通。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：“走到尽头”不能搭配“名字”，“名字走到了尽头”不通。"}, {"text": "地址", "is_correct": false, "explanation": "语义：“地址”是住所的位置，不会“走到尽头”，“老人的地址走到了尽头”不通。"}], "explanations": {"生命": "正确：“走到尽头”可以用于人的生命，“老人的生命走到了尽头”通顺。", "学号": "语义：“学号”是学生的编号，不会“走到尽头”，“老人的学号走到了尽头”不通。", "名字": "搭配：“走到尽头”不能搭配“名字”，“名字走到了尽头”不通。", "地址": "语义：“地址”是住所的位置，不会“走到尽头”，“老人的地址走到了尽头”不通。"}, "sentence_index": 6, "correct_answer": "生命"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的生命已经三十岁了。", "explanation": "这里应该用〈年龄〉。说人的岁数要用“年龄”，“生命”不能与“三十岁”搭配。"}, {"text": "今天是我的生命，大家都来祝贺。", "explanation": "这里应该用〈生日〉。“生日”指出生的那一天，“生命”不能用来指这一天。"}, {"text": "这家店的生命很好。", "explanation": "这里应该用〈生意〉。“生意”指买卖的状况，“生命”不用于形容店铺的经营。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51e94512-9e25-4c76-b7c1-a48af2308abf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86758, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "医生救了两座生命。", "corrected_sentence": "医生救了两条生命。", "error_description": "“生命”前的量词错误：应说“两条生命”，不能说“两座生命”。“座”多用于山、房屋等大型固定物，不能修饰“生命”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51e94512-9e25-4c76-b7c1-a48af2308abf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86758, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次事故夺走了三座生命。", "corrected_sentence": "这次事故夺走了三条生命。", "error_description": "量词错误：“生命”应使用量词“条”，应说“夺走了三条生命”，不能说“夺走了三座生命”。“座”多用于山、房屋等大型固定物。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51e94512-9e25-4c76-b7c1-a48af2308abf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86759, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "女", "is_correct": true, "explanation": "反义：“男”与“女”相对，指性别。"}, {"text": "大", "is_correct": false, "explanation": "无关：“大”与“男”没有反义关系。"}, {"text": "高", "is_correct": false, "explanation": "无关：“高”与“男”没有反义关系。"}, {"text": "快", "is_correct": false, "explanation": "无关：“快”与“男”没有反义关系。"}], "correct_answer": "女", "explanations": {"女": "反义：“男”与“女”相对，指性别。", "大": "无关：“大”与“男”没有反义关系。", "高": "无关：“高”与“男”没有反义关系。", "快": "无关：“快”与“男”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51e94512-9e25-4c76-b7c1-a48af2308abf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86759, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "女", "is_correct": true, "explanation": "反义：“男”与“女”相对，指性别。"}, {"text": "早", "is_correct": false, "explanation": "无关：“早”与“男”没有反义关系。"}, {"text": "远", "is_correct": false, "explanation": "无关：“远”与“男”没有反义关系。"}, {"text": "轻", "is_correct": false, "explanation": "无关：“轻”与“男”没有反义关系。"}], "correct_answer": "女", "explanations": {"女": "反义：“男”与“女”相对，指性别。", "早": "无关：“早”与“男”没有反义关系。", "远": "无关：“远”与“男”没有反义关系。", "轻": "无关：“轻”与“男”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51e94512-9e25-4c76-b7c1-a48af2308abf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86759, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "性别中与“女”相对的一方，指男性。", "primary_collocate": null, "pronunciation": "nán", "ipa": "nan˧˥", "syllable_count": 1, "sentences": [{"text": "表格上的性别请写男或女。", "target_word": "男", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班有二十个男的，十五个女的。", "target_word": "男", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是男的，她是女的。", "target_word": "男", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "门上写着“男”，我走错了吗？", "target_word": "男", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个表格上要选男还是女。", "target_word": "男", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们有两个孩子，一男一女。", "target_word": "男", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新来的老师是男的还是女的？", "target_word": "男", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在还看不出孩子是男是女。", "target_word": "男", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "身份证上写着他的性别：男。", "target_word": "男", "complexity_tier": "T3", "furigana": "shēn fèn zhèng shàng xiě zhe tā de xìng bié：nán。", "sentence_source": "generated"}, {"text": "排队的时候，男的站左边，女的站右边。", "target_word": "男", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "男人", "label": "复合"}, {"form": "男孩", "label": "复合"}], "register": "中性", "sense_fingerprint": "男：和女相对，指男性这一边", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93ba1550-0d24-40f4-930c-c7587d5653db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86759, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "男", "is_correct": true, "explanation": "正确：“男”读 nán，意思是男性，与“女”相对。"}, {"text": "蓝", "is_correct": false, "explanation": "声母不同：lán 与 nán 声母不同（l 与 n），意思是蓝色。"}, {"text": "篮", "is_correct": false, "explanation": "声母不同：lán 与 nán 只差声母（l 与 n），意思是篮子。"}, {"text": "年", "is_correct": false, "explanation": "韵母不同：nián 与 nán 只差介音 i，意思是年份。"}, {"text": "拿", "is_correct": false, "explanation": "韵母不同：ná 与 nán 韵母不同（a 与 an），意思是拿。"}], "explanations": {"男": "正确：“男”读 nán，意思是男性，与“女”相对。", "蓝": "声母不同：lán 与 nán 声母不同（l 与 n），意思是蓝色。", "篮": "声母不同：lán 与 nán 只差声母（l 与 n），意思是篮子。", "年": "韵母不同：nián 与 nán 只差介音 i，意思是年份。", "拿": "韵母不同：ná 与 nán 韵母不同（a 与 an），意思是拿。"}, "sentence_index": null, "correct_answer": "男"}, "level_3": {"options": [{"text": "男", "is_correct": true, "explanation": "正确：“男”与“女”并列作性别标注，“请写男或女”通顺。"}, {"text": "中", "is_correct": false, "explanation": "搭配：“中或女”不能成对举，“中”不能作性别选项。"}, {"text": "名", "is_correct": false, "explanation": "语义：“名”指名字，不是性别选项，与“或女”不相配。"}, {"text": "年", "is_correct": false, "explanation": "语义：“年”指年份，不能作性别选项。"}], "explanations": {"男": "正确：“男”与“女”并列作性别标注，“请写男或女”通顺。", "中": "搭配：“中或女”不能成对举，“中”不能作性别选项。", "名": "语义：“名”指名字，不是性别选项，与“或女”不相配。", "年": "语义：“年”指年份，不能作性别选项。"}, "sentence_index": 0, "correct_answer": "男"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只男猫每天都在院子里晒太阳。", "explanation": "这里应该用〈公〉。“男”只用于人，动物的雄性说“公”或“雄”，不说“男猫”。"}, {"text": "这只男狮子很威武。", "explanation": "这里应该用〈雄〉。狮子的雄性说“雄狮”，“男”不用于动物。"}, {"text": "这盏男灯很亮。", "explanation": "这个用法不对：“男”只指人的性别，灯没有性别，不能说“男灯”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51e94512-9e25-4c76-b7c1-a48af2308abf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86759, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "男", "is_correct": true, "explanation": "正确：“男”读 nán，意思是男性，与“女”相对。"}, {"text": "拦", "is_correct": false, "explanation": "声母不同：lán 与 nán 声母不同（l 与 n），意思是拦住。"}, {"text": "拿", "is_correct": false, "explanation": "韵母不同：ná 与 nán 只差韵尾 n，意思是拿。"}, {"text": "年", "is_correct": false, "explanation": "韵母不同：nián 与 nán 只差介音 i，意思是年份。"}, {"text": "兰", "is_correct": false, "explanation": "声母不同：lán 与 nán 只差声母（l 与 n），意思是兰花。"}], "explanations": {"男": "正确：“男”读 nán，意思是男性，与“女”相对。", "拦": "声母不同：lán 与 nán 声母不同（l 与 n），意思是拦住。", "拿": "韵母不同：ná 与 nán 只差韵尾 n，意思是拿。", "年": "韵母不同：nián 与 nán 只差介音 i，意思是年份。", "兰": "声母不同：lán 与 nán 只差声母（l 与 n），意思是兰花。"}, "sentence_index": null, "correct_answer": "男"}, "level_3": {"options": [{"text": "男", "is_correct": true, "explanation": "正确：“男的……还是女的”成对，问的是老师的性别。"}, {"text": "高", "is_correct": false, "explanation": "语义：“高的”与“女的”不能成对，题干问的是性别。"}, {"text": "快", "is_correct": false, "explanation": "搭配：“快”不能与“女的”对举，“快的还是女的”不通。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：“胖”描述体形，不指性别，与“女的”不相配。"}], "explanations": {"男": "正确：“男的……还是女的”成对，问的是老师的性别。", "高": "语义：“高的”与“女的”不能成对，题干问的是性别。", "快": "搭配：“快”不能与“女的”对举，“快的还是女的”不通。", "胖": "体貌：“胖”描述体形，不指性别，与“女的”不相配。"}, "sentence_index": 6, "correct_answer": "男"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条男鱼很新鲜。", "explanation": "这里应该用〈雄〉。“男”不用于动物，鱼的雄性说“雄鱼”。"}, {"text": "这个男插头插不进去。", "explanation": "这里应该用〈公〉。“男”不用于物品，成对接插件中凸出的一头说“公插头”。"}, {"text": "这棵男树很高。", "explanation": "这个用法不对：“男”只指人的性别，植物的雌雄要说“雄株”或“雌株”，不能说“男树”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51e94512-9e25-4c76-b7c1-a48af2308abf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86759, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们班来了两只男的。", "corrected_sentence": "我们班来了两个男的。", "error_description": "“男的”指人，量词应用“个”，不能用“只”。“只”多用于动物或成对的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51e94512-9e25-4c76-b7c1-a48af2308abf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86759, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新来的老师是的男。", "corrected_sentence": "新来的老师是男的。", "error_description": "“的”的位置错误：应放在“男”之后，说“男的”，不能说“的男”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51e94512-9e25-4c76-b7c1-a48af2308abf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
