INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86761, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "若是说“如果”，意思是假如这样。", "primary_collocate": null, "pronunciation": "ruò", "ipa": "ʐwo˥˩", "syllable_count": 1, "sentences": [{"text": "你若不想去，可以留在家里。", "target_word": "若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我若有钱，就买一间大房子。", "target_word": "若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他若来了，请让他等我一下。", "target_word": "若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家若有问题，可以随时问我。", "target_word": "若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你若累了，就先回家休息吧。", "target_word": "若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天若黑了，我们就别走山路了。", "target_word": "若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子若生病了，要马上去医院。", "target_word": "若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们若努力，就一定能成功。", "target_word": "若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你若喜欢这本书，我就送给你。", "target_word": "若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他若知道这件事，一定会很高兴。", "target_word": "若", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "假若", "label": "复合"}, {"form": "倘若", "label": "复合"}, {"form": "若是", "label": "复合"}], "register": "书面语", "sense_fingerprint": "放在主语之后引出假设，意思是如果、假如", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2568f57c-7316-43f4-ae41-0373852d042f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86761, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "若", "is_correct": true, "explanation": "若：ruò（第四声），连词，意思是如果、假如。"}, {"text": "落", "is_correct": false, "explanation": "luò（第四声）与 ruò 声母不同（l 与 r），意思是落下。"}, {"text": "诺", "is_correct": false, "explanation": "nuò（第四声）与 ruò 声母不同（n 与 r），声调相同，意思是答应。"}, {"text": "锐", "is_correct": false, "explanation": "ruì（第四声）与 ruò 韵母不同（ui 与 uo），意思是锐利。"}], "explanations": {"若": "若：ruò（第四声），连词，意思是如果、假如。", "落": "luò（第四声）与 ruò 声母不同（l 与 r），意思是落下。", "诺": "nuò（第四声）与 ruò 声母不同（n 与 r），声调相同，意思是答应。", "锐": "ruì（第四声）与 ruò 韵母不同（ui 与 uo），意思是锐利。"}, "sentence_index": null, "correct_answer": "若"}, "level_3": {"options": [{"text": "若", "is_correct": true, "explanation": "若：书面语连词，放在主语之后引出假设，意思是如果，可以填入。"}, {"text": "然后", "is_correct": false, "explanation": "语义：「然后」表示先后动作，不表示假设，「你然后不想去」不成立。"}, {"text": "而且", "is_correct": false, "explanation": "语义：「而且」表示递进或并列，不引出假设条件，「你而且不想去」不成立。"}, {"text": "所以", "is_correct": false, "explanation": "搭配：「所以」要接在原因之后，「你所以不想去」不能说，也不能引出条件。"}], "explanations": {"若": "若：书面语连词，放在主语之后引出假设，意思是如果，可以填入。", "然后": "语义：「然后」表示先后动作，不表示假设，「你然后不想去」不成立。", "而且": "语义：「而且」表示递进或并列，不引出假设条件，「你而且不想去」不成立。", "所以": "搭配：「所以」要接在原因之后，「你所以不想去」不能说，也不能引出条件。"}, "sentence_index": 0, "correct_answer": "若"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次比赛我们若取得了好成绩，多亏了大家的努力。", "explanation": "这里应该用〈因为〉。若表示假设，不能用来说明已经取得的成绩是由什么原因造成的。"}, {"text": "雨下得很大，若比赛就取消了。", "explanation": "这里应该用〈所以〉。若表示假设，不能用来引出已经发生的结果。"}, {"text": "我先洗了澡，若去看了书，最后睡觉了。", "explanation": "这里应该用〈然后〉。若表示假设，不能用来表示动作的先后顺序。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35726a13-f82e-4a20-8211-11cdd2ec28a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86761, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "若", "is_correct": true, "explanation": "若：ruò（第四声），连词，意思是如果、假如。"}, {"text": "入", "is_correct": false, "explanation": "rù（第四声）与 ruò 韵母不同（u 与 uo），声调相同，意思是进入。"}, {"text": "热", "is_correct": false, "explanation": "rè（第四声）与 ruò 韵母不同（e 与 uo），声调相同，意思是温度高。"}, {"text": "肉", "is_correct": false, "explanation": "ròu（第四声）与 ruò 韵母不同（ou 与 uo），声调相同，意思是动物的肌肉。"}], "explanations": {"若": "若：ruò（第四声），连词，意思是如果、假如。", "入": "rù（第四声）与 ruò 韵母不同（u 与 uo），声调相同，意思是进入。", "热": "rè（第四声）与 ruò 韵母不同（e 与 uo），声调相同，意思是温度高。", "肉": "ròu（第四声）与 ruò 韵母不同（ou 与 uo），声调相同，意思是动物的肌肉。"}, "sentence_index": null, "correct_answer": "若"}, "level_3": {"options": [{"text": "若", "is_correct": true, "explanation": "若：书面语连词，引出假设，与后面的「要马上」相配合，可以填入。"}, {"text": "但是", "is_correct": false, "explanation": "语义：「但是」表示转折，句中没有前后对立，「孩子但是生病了」不通。"}, {"text": "不过", "is_correct": false, "explanation": "搭配：「不过」前面需要有前文的对比或让步，句中单独用于「孩子生病了」不成立。"}, {"text": "并且", "is_correct": false, "explanation": "语义：「并且」表示并列或递进，不引出假设条件，「孩子并且生病了」不成立。"}], "explanations": {"若": "若：书面语连词，引出假设，与后面的「要马上」相配合，可以填入。", "但是": "语义：「但是」表示转折，句中没有前后对立，「孩子但是生病了」不通。", "不过": "搭配：「不过」前面需要有前文的对比或让步，句中单独用于「孩子生病了」不成立。", "并且": "语义：「并且」表示并列或递进，不引出假设条件，「孩子并且生病了」不成立。"}, "sentence_index": 6, "correct_answer": "若"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我先去了银行，若去了超市。", "explanation": "这里应该用〈然后〉。若表示假设，不能用来表示动作的先后顺序。"}, {"text": "他看起来很年轻，若已经五十岁了。", "explanation": "这里应该用〈其实〉。若表示假设，不能用来说明实际情况。"}, {"text": "他很努力，若成绩却不好。", "explanation": "这里应该用〈但是〉。若表示假设，不能引出与前文相反的转折。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35726a13-f82e-4a20-8211-11cdd2ec28a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version,