INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86761, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你若渴了，就若先喝点水吧。", "corrected_sentence": "你若渴了，就先喝点水吧。", "error_description": "错误：「若」被多加在主句「就先喝点水」中，写成「就若先喝点水」。正确写法是「你若渴了，就先喝点水吧」，「若」只放在条件分句的主语之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35726a13-f82e-4a20-8211-11cdd2ec28a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86761, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我是若有空，就去看你。", "corrected_sentence": "我若有空，就去看你。", "error_description": "错误：「是」被放在了「若」前面，写成「是若有空」。「若」前不能加「是」，正确写法是「我若有空，就去看你」，「若」应放在主语之后、条件分句之前，表示假设。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35726a13-f82e-4a20-8211-11cdd2ec28a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
