INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86762, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，如果，假如。", "primary_collocate": null, "pronunciation": "ruò", "ipa": "ʐwo˥˩", "syllable_count": 1, "sentences": [{"text": "若明天下雨，我们就不去公园了。", "target_word": "若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "若你有空，请给我打个电话。", "target_word": "若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "若天气好，我们便去爬山。", "target_word": "若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "若人人都帮忙，这件事很快就能做完。", "target_word": "若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "若今晚不睡觉，明天就会很累。", "target_word": "若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "若遇到困难，请马上告诉老师。", "target_word": "若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "若路上堵车，我们就坐地铁去。", "target_word": "若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "若他同意，我们就可以开始了。", "target_word": "若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "若时间不够，这个计划就先放一放。", "target_word": "若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "若车票卖完了，我们就明天再走。", "target_word": "若", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "假若", "label": "复合"}, {"form": "倘若", "label": "复合"}, {"form": "若是", "label": "复合"}], "register": "书面语", "sense_fingerprint": "放在分句开头引出假设条件，后面常接就、便、则", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2568f57c-7316-43f4-ae41-0373852d042f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
