INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86762, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你若有空，若就来帮忙吧。", "corrected_sentence": "你若有空，就来帮忙吧。", "error_description": "错误：「若」在条件分句「你若有空」之后又多写了一个，主句「就来帮忙」前写成「若就来帮忙」。正确写法是「你若有空，就来帮忙吧」，主句前不需要再加「若」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35726a13-f82e-4a20-8211-11cdd2ec28a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86762, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "若路上下雨，我们若坐车去。", "corrected_sentence": "若路上下雨，我们就坐车去。", "error_description": "错误：主句里的「就」被写成了「若」，成了「我们若坐车去」。「若」只用在条件分句开头引出假设，主句应该用「就」承接结果。正确写法是「若路上下雨，我们就坐车去」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35726a13-f82e-4a20-8211-11cdd2ec28a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
