INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86763, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cf7ce71-ddfc-406e-88fa-d631d3cd9ba7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86763, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "都会是很大很热闹的城。", "primary_collocate": null, "pronunciation": "dū huì", "ipa": "tu˥ xweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "北京是一座很大的都会。", "target_word": "都会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个都会白天晚上都很热闹。", "target_word": "都会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我第一次来到这样的都会，觉得很新鲜。", "target_word": "都会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "都会里有很多商店、饭馆和高楼。", "target_word": "都会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我姐姐在南方的一座都会工作。", "target_word": "都会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座都会的街上每天都有很多人。", "target_word": "都会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想去繁华的都会看看。", "target_word": "都会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那座都会的夜景非常漂亮。", "target_word": "都会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "和乡下比，都会的生活节奏快多了。", "target_word": "都会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们坐了一晚上火车，终于到了这座都会。", "target_word": "都会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "大都会", "label": "复合"}, {"form": "都會", "label": "繁体"}], "register": "中性", "sense_fingerprint": "很大很热闹的城（名词，dū huì）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7673fbc5-6e78-4bef-848b-ae27656be33f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86763, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "都会", "is_correct": true, "explanation": "正确。“都会”指很大很热闹的城，与“北京是一座很大的……”相符。"}, {"text": "村子", "is_correct": false, "explanation": "语义：村子规模小，与“很大”的修饰矛盾。"}, {"text": "山", "is_correct": false, "explanation": "语义：北京是城市，不能说成山，与前文“北京”相悖。"}, {"text": "书", "is_correct": false, "explanation": "搭配：量词“座”不能用于“书”，“很大的书”与“座”也不搭配。"}], "explanations": {"都会": "正确。“都会”指很大很热闹的城，与“北京是一座很大的……”相符。", "村子": "语义：村子规模小，与“很大”的修饰矛盾。", "山": "语义：北京是城市，不能说成山，与前文“北京”相悖。", "书": "搭配：量词“座”不能用于“书”，“很大的书”与“座”也不搭配。"}, "sentence_index": 0, "correct_answer": "都会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个都会里只有几户人家。", "explanation": "这里应该用〈村庄〉。“都会”指很大很热闹的城，几户人家的地方不能称为都会。"}, {"text": "北京是一棵很大的都会。", "explanation": "这里应该用〈座〉。“都会”是城市，量词要用“座”，“棵”用于植物。"}, {"text": "我每天骑自行车下地，住在一个都会里。", "explanation": "这里应该用〈农村〉。“都会”是很大很热闹的城，下地干活的农村不能称为都会。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cf7ce71-ddfc-406e-88fa-d631d3cd9ba7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86763, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "都会", "is_correct": true, "explanation": "正确。“都会”指很大很热闹的城，与“繁华的”相符。"}, {"text": "田野", "is_correct": false, "explanation": "语义：田野属于乡野，与“繁华”的特点相悖。"}, {"text": "草地", "is_correct": false, "explanation": "语义：草地没有“繁华”的特点，与前面的修饰冲突。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“繁华”不能修饰桌子，二者搭配不当。"}], "explanations": {"都会": "正确。“都会”指很大很热闹的城，与“繁华的”相符。", "田野": "语义：田野属于乡野，与“繁华”的特点相悖。", "草地": "语义：草地没有“繁华”的特点，与前面的修饰冲突。", "桌子": "搭配：“繁华”不能修饰桌子，二者搭配不当。"}, "sentence_index": 6, "correct_answer": "都会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们爬了一天山，终于到了那个偏远的都会。", "explanation": "这里应该用〈山村〉。“都会”是很大很热闹的城，不能用来形容偏远的山村。"}, {"text": "我们坐了一晚上火车，终于到了这本都会。", "explanation": "这里应该用〈座〉。“都会”是城市，量词要用“座”，“本”用于书册。"}, {"text": "我奶奶住在都会，每天都在田里干活。", "explanation": "这里应该用〈乡下〉。“都会”指大城市，不能用来说在田里干活的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cf7ce71-ddfc-406e-88fa-d631d3cd9ba7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86763, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只都会的街道很宽。", "corrected_sentence": "那座都会的街道很宽。", "error_description": "“都会”指城市，量词应用“座”，“只”用于动物。错误形式“那只都会”，正确形式“那座都会”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cf7ce71-ddfc-406e-88fa-d631d3cd9ba7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86763, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那些都会们的夜景都很美。", "corrected_sentence": "那些都会的夜景都很美。", "error_description": "“都会”是指地方的名词，不能加复数词尾“们”（“们”只用于指人的名词）。错误形式“都会们”，正确形式“都会”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cf7ce71-ddfc-406e-88fa-d631d3cd9ba7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86764, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cf7ce71-ddfc-406e-88fa-d631d3cd9ba7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86764, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cf7ce71-ddfc-406e-88fa-d631d3cd9ba7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86764, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人口集中、工商业发达的大城市。", "primary_collocate": null, "pronunciation": "dū huì", "ipa": "tu˥ xweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "上海是中国最大的都会之一。", "target_word": "都会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座都会的人口超过一千万。", "target_word": "都会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小生活在繁华的都会里。", "target_word": "都会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "都会里的工作机会很多，房价也很高。", "target_word": "都会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多年轻人离开小镇，到都会去找工作。", "target_word": "都会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座都会里有很多银行和大公司。", "target_word": "都会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住在都会的人，每天都坐地铁上班。", "target_word": "都会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜晚的都会灯火通明，十分热闹。", "target_word": "都会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢小城的安静，不喜欢忙碌的都会。", "target_word": "都会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座都会的工商业非常发达。", "target_word": "都会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "大都会", "label": "复合"}, {"form": "都會", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人口集中、工商业发达的大城市（名词，dū huì）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7673fbc5-6e78-4bef-848b-ae27656be33f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86764, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "都会", "is_correct": true, "explanation": "正确。“都会”指人口集中、工商业发达的大城市，符合上海的情况。"}, {"text": "村庄", "is_correct": false, "explanation": "语义：村庄规模小，与“中国最大的……之一”矛盾。"}, {"text": "山脉", "is_correct": false, "explanation": "语义：山脉是连绵的山岭地形，上海是城市，不能说成“最大的山脉之一”。"}, {"text": "学校", "is_correct": false, "explanation": "语义：学校是教育机构，不是地域，与“上海”不能构成“最大的……之一”的关系。"}], "explanations": {"都会": "正确。“都会”指人口集中、工商业发达的大城市，符合上海的情况。", "村庄": "语义：村庄规模小，与“中国最大的……之一”矛盾。", "山脉": "语义：山脉是连绵的山岭地形，上海是城市，不能说成“最大的山脉之一”。", "学校": "语义：学校是教育机构，不是地域，与“上海”不能构成“最大的……之一”的关系。"}, "sentence_index": 0, "correct_answer": "都会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家住在一个都会里，门前全是稻田。", "explanation": "这里应该用〈村庄〉。“都会”指人口集中、工商业发达的大城市，门前全是稻田的地方不能称为都会。"}, {"text": "我爷爷一辈子住在都会，每天在山上砍柴。", "explanation": "这里应该用〈山村〉。“都会”指人口集中、工商业发达的大城市，在山上砍柴的地方不能称为都会。"}, {"text": "北京是一条很大的都会。", "explanation": "这里应该用〈座〉。“都会”是城市，量词要用“座”，“条”用于长条形的事物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cf7ce71-ddfc-406e-88fa-d631d3cd9ba7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86764, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "都会", "is_correct": true, "explanation": "正确。“都会”有地铁等交通，符合“每天坐地铁上班”。"}, {"text": "乡下", "is_correct": false, "explanation": "语义：乡下通常没有地铁，与“坐地铁上班”矛盾。"}, {"text": "小镇", "is_correct": false, "explanation": "语义：小镇一般没有地铁，与“坐地铁上班”不符。"}, {"text": "草原", "is_correct": false, "explanation": "搭配：“住在草原的人”与“每天坐地铁上班”搭配不当，草原一般不通地铁。"}], "explanations": {"都会": "正确。“都会”有地铁等交通，符合“每天坐地铁上班”。", "乡下": "语义：乡下通常没有地铁，与“坐地铁上班”矛盾。", "小镇": "语义：小镇一般没有地铁，与“坐地铁上班”不符。", "草原": "搭配：“住在草原的人”与“每天坐地铁上班”搭配不当，草原一般不通地铁。"}, "sentence_index": 6, "correct_answer": "都会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们的都会只有一条街。", "explanation": "这里应该用〈小镇〉。“都会”指很大的城市，只有一条街的地方不能称为都会。"}, {"text": "这张都会的工商业很发达。", "explanation": "这里应该用〈座〉。“都会”是城市，量词要用“座”，“张”用于平面的事物。"}, {"text": "这个都会人口很少，只有几十户。", "explanation": "这里应该用〈村子〉。“都会”指人口集中的大城市，人口很少的地方不能用“都会”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cf7ce71-ddfc-406e-88fa-d631d3cd9ba7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86764, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只都会的交通很方便。", "corrected_sentence": "这座都会的交通很方便。", "error_description": "“都会”指城市，量词应用“座”，“只”用于动物。错误形式“这只都会”，正确形式“这座都会”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cf7ce71-ddfc-406e-88fa-d631d3cd9ba7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86764, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些都会们的人口都很多。", "corrected_sentence": "这些都会的人口都很多。", "error_description": "“都会”是指地方的名词，不能加复数词尾“们”（“们”只用于指人的名词）。错误形式“都会们”，正确形式“都会”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cf7ce71-ddfc-406e-88fa-d631d3cd9ba7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86765, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "死亡", "is_correct": true, "explanation": "正确。死亡与“出生”相对，指生命结束。"}, {"text": "唱歌", "is_correct": false, "explanation": "唱歌是一种动作，与“出生”没有反义关系。"}, {"text": "写字", "is_correct": false, "explanation": "写字是一种动作，与“出生”没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "散步是一种活动，与“出生”没有反义关系。"}], "correct_answer": "死亡", "explanations": {"死亡": "正确。死亡与“出生”相对，指生命结束。", "唱歌": "唱歌是一种动作，与“出生”没有反义关系。", "写字": "写字是一种动作，与“出生”没有反义关系。", "散步": "散步是一种活动，与“出生”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee70e2e-4902-4e6c-8abc-23b1965f5913') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86765, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "死亡", "is_correct": true, "explanation": "正确。死亡与“出生”相对，指生命结束。"}, {"text": "睡觉", "is_correct": false, "explanation": "睡觉是一种休息的动作，与“出生”没有反义关系。"}, {"text": "跑步", "is_correct": false, "explanation": "跑步是一种运动，与“出生”没有反义关系。"}, {"text": "工作", "is_correct": false, "explanation": "工作指做事、劳动，与“出生”没有反义关系。"}], "correct_answer": "死亡", "explanations": {"死亡": "正确。死亡与“出生”相对，指生命结束。", "睡觉": "睡觉是一种休息的动作，与“出生”没有反义关系。", "跑步": "跑步是一种运动，与“出生”没有反义关系。", "工作": "工作指做事、劳动，与“出生”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee70e2e-4902-4e6c-8abc-23b1965f5913') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86765, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "出生是小宝宝从妈妈的肚子里来到世界上。", "primary_collocate": null, "pronunciation": "chū shēng", "ipa": "ʈʂʰu˥ ʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "我的小侄子昨天出生了。", "target_word": "出生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是在北京出生的。", "target_word": "出生", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "宝宝出生的时候哭得很大声。", "target_word": "出生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小狗出生三天了，眼睛还没睁开。", "target_word": "出生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "姐姐出生那年，家里很穷。", "target_word": "出生", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "听说你家宝宝出生了，恭喜你！", "target_word": "出生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷出生在一个小村子里。", "target_word": "出生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子出生后，妈妈每天都很累。", "target_word": "出生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他出生的那天，天上下着大雪。", "target_word": "出生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的女儿在春天出生。", "target_word": "出生", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "出生了", "label": "体标"}, {"form": "出生过", "label": "体标"}], "register": "通用", "sense_fingerprint": "宝宝来到世界上，指人生的开始", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a432da1f-feea-49d0-a707-faedc977933d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86765, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "出生", "is_correct": true, "explanation": "正确答案。出生指小宝宝从妈妈的肚子里来到世界上。"}, {"text": "出身", "is_correct": false, "explanation": "shēn 与 shēng 韵尾不同（n 与 ng），意思是家庭出身、背景。"}, {"text": "出神", "is_correct": false, "explanation": "shén（第二声）与 shēng（第一声）韵尾和声调都不同，意思是发呆、入神。"}, {"text": "书生", "is_correct": false, "explanation": "shū 与 chū 声母不同（sh 与 ch），意思是读书人。"}, {"text": "出征", "is_correct": false, "explanation": "zhēng 与 shēng 声母不同（zh 与 sh），意思是出去打仗。"}], "explanations": {"出生": "正确答案。出生指小宝宝从妈妈的肚子里来到世界上。", "出身": "shēn 与 shēng 韵尾不同（n 与 ng），意思是家庭出身、背景。", "出神": "shén（第二声）与 shēng（第一声）韵尾和声调都不同，意思是发呆、入神。", "书生": "shū 与 chū 声母不同（sh 与 ch），意思是读书人。", "出征": "zhēng 与 shēng 声母不同（zh 与 sh），意思是出去打仗。"}, "sentence_index": null, "correct_answer": "出生"}, "level_3": {"options": [{"text": "出生", "is_correct": true, "explanation": "正确。出生与“昨天……了”搭配，说明小侄子刚来到世界上。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：结婚指成年人组建家庭，不能用于刚出生的小侄子。"}, {"text": "毕业", "is_correct": false, "explanation": "搭配：毕业需要完成学业，“小侄子”不能说毕业。"}, {"text": "长大", "is_correct": false, "explanation": "语义：长大指身体和年龄逐渐增长，与“昨天”刚出生的情况矛盾。"}], "explanations": {"出生": "正确。出生与“昨天……了”搭配，说明小侄子刚来到世界上。", "结婚": "语义：结婚指成年人组建家庭，不能用于刚出生的小侄子。", "毕业": "搭配：毕业需要完成学业，“小侄子”不能说毕业。", "长大": "语义：长大指身体和年龄逐渐增长，与“昨天”刚出生的情况矛盾。"}, "sentence_index": 0, "correct_answer": "出生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个国家出生于1949年。", "explanation": "这里应该用〈诞生〉。国家、组织的开始说“诞生”，“出生”只用于人或动物。"}, {"text": "这个想法出生于去年。", "explanation": "这里应该用〈产生〉。想法、问题的出现说“产生”，“出生”不用于想法。"}, {"text": "太阳出生在东边的天空。", "explanation": "这里应该用〈升起〉。太阳从地平线上升起，不说“出生”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee70e2e-4902-4e6c-8abc-23b1965f5913') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86765, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出生", "is_correct": true, "explanation": "正确。出生说明爷爷是在这个小村子里来到世界上的。"}, {"text": "出国", "is_correct": false, "explanation": "语义：出国指到国外去，不能说在一个小村子里出国。"}, {"text": "出院", "is_correct": false, "explanation": "语义：出院指从医院离开，与“小村子”的地点不搭。"}, {"text": "退学", "is_correct": false, "explanation": "搭配：退学针对学生，不能用于爷爷。"}], "explanations": {"出生": "正确。出生说明爷爷是在这个小村子里来到世界上的。", "出国": "语义：出国指到国外去，不能说在一个小村子里出国。", "出院": "语义：出院指从医院离开，与“小村子”的地点不搭。", "退学": "搭配：退学针对学生，不能用于爷爷。"}, "sentence_index": 6, "correct_answer": "出生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座城市出生于三百年前。", "explanation": "这里应该用〈建立〉。城市的开始说“建立”，“出生”只用于人或动物。"}, {"text": "这起事故出生在昨天晚上。", "explanation": "这里应该用〈发生〉。事故的出现说“发生”，“出生”不用于事故。"}, {"text": "樱花在春天出生。", "explanation": "这里应该用〈开花〉。植物开花说“开花”，不说“出生”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee70e2e-4902-4e6c-8abc-23b1965f5913') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86765, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的弟弟在上海没出生了。", "corrected_sentence": "我的弟弟在上海出生了。", "error_description": "“没”表示否定，不能与“了”同时用在“出生”后；否定说法应为“没出生”，肯定陈述应说“在上海出生了”，“没出生了”两者都不是。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee70e2e-4902-4e6c-8abc-23b1965f5913') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86765, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的朋友在冬天出生着。", "corrected_sentence": "我的朋友在冬天出生了。", "error_description": "“出生”是一次性的动作，不能用“着”表示持续；应说“出生了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee70e2e-4902-4e6c-8abc-23b1965f5913') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
