INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86766, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee70e2e-4902-4e6c-8abc-23b1965f5913') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86766, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "胎儿从母体中分娩出来。", "primary_collocate": null, "pronunciation": "chū shēng", "ipa": "ʈʂʰu˥ ʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "这个婴儿在医院顺利出生。", "target_word": "出生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生说，孩子下周就会出生。", "target_word": "出生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "婴儿出生时，体重三公斤。", "target_word": "出生", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子出生后，护士马上检查了身体。", "target_word": "出生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经过两小时，婴儿终于出生了。", "target_word": "出生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这对双胞胎在同一天出生。", "target_word": "出生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "早产的婴儿出生后要住进保温箱。", "target_word": "出生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院去年有两千个婴儿出生。", "target_word": "出生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "胎儿长到足月，才能平安出生。", "target_word": "出生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是在医院出生的，不是在家里。", "target_word": "出生", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "出生了", "label": "体标"}, {"form": "出生过", "label": "体标"}], "register": "书面", "sense_fingerprint": "胎儿从母体分娩，医学和正式场合的说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a432da1f-feea-49d0-a707-faedc977933d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86766, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "出生", "is_correct": true, "explanation": "正确答案。出生指胎儿从母体中分娩出来。"}, {"text": "出身", "is_correct": false, "explanation": "shēn 与 shēng 韵尾不同（n 与 ng），意思是家庭出身、背景。"}, {"text": "出神", "is_correct": false, "explanation": "shén（第二声）与 shēng（第一声）韵尾和声调都不同，意思是发呆、入神。"}, {"text": "书生", "is_correct": false, "explanation": "shū 与 chū 声母不同（sh 与 ch），意思是读书人。"}, {"text": "出征", "is_correct": false, "explanation": "zhēng 与 shēng 声母不同（zh 与 sh），意思是出去打仗。"}], "explanations": {"出生": "正确答案。出生指胎儿从母体中分娩出来。", "出身": "shēn 与 shēng 韵尾不同（n 与 ng），意思是家庭出身、背景。", "出神": "shén（第二声）与 shēng（第一声）韵尾和声调都不同，意思是发呆、入神。", "书生": "shū 与 chū 声母不同（sh 与 ch），意思是读书人。", "出征": "zhēng 与 shēng 声母不同（zh 与 sh），意思是出去打仗。"}, "sentence_index": null, "correct_answer": "出生"}, "level_3": {"options": [{"text": "出生", "is_correct": true, "explanation": "正确。出生指胎儿从母体分娩出来，与“顺利”搭配自然。"}, {"text": "去世", "is_correct": false, "explanation": "语义：去世指人死亡，与“顺利”的分娩情况矛盾。"}, {"text": "毕业", "is_correct": false, "explanation": "搭配：毕业用于学生完成学业，不能用于婴儿。"}, {"text": "长大", "is_correct": false, "explanation": "语义：长大指逐渐成长，与刚在医院分娩的情况不符。"}], "explanations": {"出生": "正确。出生指胎儿从母体分娩出来，与“顺利”搭配自然。", "去世": "语义：去世指人死亡，与“顺利”的分娩情况矛盾。", "毕业": "搭配：毕业用于学生完成学业，不能用于婴儿。", "长大": "语义：长大指逐渐成长，与刚在医院分娩的情况不符。"}, "sentence_index": 0, "correct_answer": "出生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这所大学出生于1902年。", "explanation": "这里应该用〈创办〉。学校的开办说“创办”，“出生”只用于人或动物。"}, {"text": "种子在春天出生，很快就长出了叶子。", "explanation": "这里应该用〈发芽〉。种子长出新芽说“发芽”，不说“出生”。"}, {"text": "新的政党出生于1921年。", "explanation": "这里应该用〈诞生〉。政党、国家的开始说“诞生”，“出生”只用于人或动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee70e2e-4902-4e6c-8abc-23b1965f5913') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86766, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出生", "is_correct": true, "explanation": "正确。出生后要住进保温箱，说明婴儿在这之前已经来到世界上。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：结婚指成年人组建家庭，与早产的婴儿不符。"}, {"text": "退休", "is_correct": false, "explanation": "搭配：退休针对有工作单位的人，不能用于婴儿。"}, {"text": "上学", "is_correct": false, "explanation": "语义：上学指儿童进入学校读书，与刚出生的婴儿不符。"}], "explanations": {"出生": "正确。出生后要住进保温箱，说明婴儿在这之前已经来到世界上。", "结婚": "语义：结婚指成年人组建家庭，与早产的婴儿不符。", "退休": "搭配：退休针对有工作单位的人，不能用于婴儿。", "上学": "语义：上学指儿童进入学校读书，与刚出生的婴儿不符。"}, "sentence_index": 6, "correct_answer": "出生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个组织出生于1980年。", "explanation": "这里应该用〈建立〉。组织的成立说“建立”，“出生”只用于人或动物。"}, {"text": "这场火灾出生在昨天晚上。", "explanation": "这里应该用〈发生〉。火灾的出现说“发生”，“出生”不用于火灾。"}, {"text": "这家公司出生于2005年。", "explanation": "这里应该用〈创立〉。公司的成立说“创立”，“出生”只用于人或动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee70e2e-4902-4e6c-8abc-23b1965f5913') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86766, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个孩子在凌晨没出生了。", "corrected_sentence": "这个孩子在凌晨出生了。", "error_description": "“没”表示否定，不能与“了”同时用在“出生”后；否定说法应为“没出生”，肯定陈述应说“在凌晨出生了”，“没出生了”两者都不是。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee70e2e-4902-4e6c-8abc-23b1965f5913') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86766, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家医院每年有很多婴儿出生着。", "corrected_sentence": "这家医院每年有很多婴儿出生。", "error_description": "“出生”是一次性的动作，不能加“着”表示持续；正确说法是“出生”，不加“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee70e2e-4902-4e6c-8abc-23b1965f5913') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86767, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cf7ce71-ddfc-406e-88fa-d631d3cd9ba7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
