INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86767, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "又及是写完信以后，又想起来再加的话。", "primary_collocate": null, "pronunciation": "yòu jí", "ipa": "joʊ˥˩ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "信的最后，他另起一行写了又及。", "target_word": "又及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "信写完了，他又加了一段又及。", "target_word": "又及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶的信末尾有一行又及，说她想我了。", "target_word": "又及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这封信的又及比正文还长。", "target_word": "又及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我忘了说一件事，只好在信后面写个又及。", "target_word": "又及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看完正文，我又仔细读了读又及。", "target_word": "又及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈的又及里写着：别忘了带伞。", "target_word": "又及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在又及里说，下个月会回家。", "target_word": "又及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "信的最后，她用小字写了又及。", "target_word": "又及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王的信没有又及，只有一页正文。", "target_word": "又及", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "写完信后又想起来补加的话（名词，yòu jí）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7673fbc5-6e78-4bef-848b-ae27656be33f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86767, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "又及", "is_correct": true, "explanation": "又及 yòu jí 指写完信以后又想起来再加的话，即信末的附言。"}, {"text": "有机", "is_correct": false, "explanation": "有机 yǒujī 两个音节的声调都与 yòu jí 不同，意思是“有机的”。"}, {"text": "游击", "is_correct": false, "explanation": "游击 yóujī 两个音节的声调都与 yòu jí 不同，意思是“游击”，指游动作战。"}, {"text": "游记", "is_correct": false, "explanation": "游记 yóujì 两个音节的声调都与 yòu jí 不同，意思是“游览的文字记录”。"}], "explanations": {"又及": "又及 yòu jí 指写完信以后又想起来再加的话，即信末的附言。", "有机": "有机 yǒujī 两个音节的声调都与 yòu jí 不同，意思是“有机的”。", "游击": "游击 yóujī 两个音节的声调都与 yòu jí 不同，意思是“游击”，指游动作战。", "游记": "游记 yóujì 两个音节的声调都与 yòu jí 不同，意思是“游览的文字记录”。"}, "sentence_index": null, "correct_answer": "又及"}, "level_3": {"options": [{"text": "又及", "is_correct": true, "explanation": "又及：书信末尾追加的话，放在“写了”之后正合适。"}, {"text": "信封", "is_correct": false, "explanation": "语义：信封是装信的纸袋，不是写在信末的文字，“另起一行写了信封”说不通。"}, {"text": "邮票", "is_correct": false, "explanation": "语义：邮票贴在信封上，不写在信的最后，“写了邮票”不合常理。"}, {"text": "笑声", "is_correct": false, "explanation": "搭配：“写”的对象是文字，不能说“写了笑声”。"}], "explanations": {"又及": "又及：书信末尾追加的话，放在“写了”之后正合适。", "信封": "语义：信封是装信的纸袋，不是写在信末的文字，“另起一行写了信封”说不通。", "邮票": "语义：邮票贴在信封上，不写在信的最后，“写了邮票”不合常理。", "笑声": "搭配：“写”的对象是文字，不能说“写了笑声”。"}, "sentence_index": 0, "correct_answer": "又及"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这封信的又及是我的名字。", "explanation": "这里应该用〈落款〉。落款是信末的署名和日期，又及是信后补充的话，不能用来写名字。"}, {"text": "我在信的最后写了一首又及。", "explanation": "这里应该用〈段〉。又及是一段附加的文字，量词“首”只用于诗词、歌曲。"}, {"text": "这张表格的又及一栏很小。", "explanation": "这里应该用〈备注〉。又及只用于书信末尾；表格里的附加说明要用备注。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cf7ce71-ddfc-406e-88fa-d631d3cd9ba7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86767, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "又及", "is_correct": true, "explanation": "又及：书信末尾追加的话，这里是妈妈在信末的叮嘱。"}, {"text": "菜谱", "is_correct": false, "explanation": "语义：菜谱记的是做菜的步骤，不会在里面叮嘱别忘了带伞。"}, {"text": "公文", "is_correct": false, "explanation": "语域：公文是正式的行政文体，与家人口语式的叮嘱不合。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“里面写着”的载体是文字，“天气”不能写在里面。"}], "explanations": {"又及": "又及：书信末尾追加的话，这里是妈妈在信末的叮嘱。", "菜谱": "语义：菜谱记的是做菜的步骤，不会在里面叮嘱别忘了带伞。", "公文": "语域：公文是正式的行政文体，与家人口语式的叮嘱不合。", "天气": "搭配：“里面写着”的载体是文字，“天气”不能写在里面。"}, "sentence_index": 6, "correct_answer": "又及"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在信里写了一把又及。", "explanation": "这里应该用〈段〉。“把”用于有柄的器具，又及是一段文字。"}, {"text": "信封上盖着又及。", "explanation": "这里应该用〈邮戳〉。邮戳是寄信时盖在信封上的印记；又及是信末追加的文字，不能盖在信封上。"}, {"text": "他在句末加了一个又及。", "explanation": "这里应该用〈感叹号〉。又及是书信末尾追加的话，不是标点符号。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cf7ce71-ddfc-406e-88fa-d631d3cd9ba7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86767, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "写完正文后，妈妈又加了一首又及。", "corrected_sentence": "写完正文后，妈妈又加了一段又及。", "error_description": "错误：“首”只用于诗词、歌曲，“又及”是书信末尾的附言，应用“段”。正确：“又加了一段又及”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cf7ce71-ddfc-406e-88fa-d631d3cd9ba7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86767, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈在信末写了一只又及。", "corrected_sentence": "妈妈在信末写了一段又及。", "error_description": "错误：量词“只”用于动物，不能修饰又及。正确：“一段又及”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cf7ce71-ddfc-406e-88fa-d631d3cd9ba7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
