INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86768, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "书信结尾后追加的话，即附言。", "primary_collocate": null, "pronunciation": "yòu jí", "ipa": "joʊ˥˩ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "信的最后有一句又及，提醒我早点回信。", "target_word": "又及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在又及里问我身体好不好。", "target_word": "又及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这封信的又及只有一行字。", "target_word": "又及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把地址写在又及里。", "target_word": "又及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写信时，他常常在最后加一个又及。", "target_word": "又及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "又及里说，包裹已经寄出了。", "target_word": "又及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸的又及很短，只写了注意安全四个字。", "target_word": "又及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我先读了正文，然后才看到又及。", "target_word": "又及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老朋友的信里常有有趣的又及。", "target_word": "又及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "读到又及，我才知道他下周要来。", "target_word": "又及", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "书信结尾后追加的附言（名词，yòu jí）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7673fbc5-6e78-4bef-848b-ae27656be33f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86768, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "又及", "is_correct": true, "explanation": "又及 yòu jí 指书信结尾后追加的话，即附言。"}, {"text": "有机", "is_correct": false, "explanation": "有机 yǒujī 两个音节的声调都与 yòu jí 不同，意思是“有机的”。"}, {"text": "邮寄", "is_correct": false, "explanation": "邮寄 yóujì 两个音节的声调都与 yòu jí 不同，意思是“通过邮局寄送”。"}, {"text": "游击", "is_correct": false, "explanation": "游击 yóujī 两个音节的声调都与 yòu jí 不同，意思是“游击”，指游动作战。"}], "explanations": {"又及": "又及 yòu jí 指书信结尾后追加的话，即附言。", "有机": "有机 yǒujī 两个音节的声调都与 yòu jí 不同，意思是“有机的”。", "邮寄": "邮寄 yóujì 两个音节的声调都与 yòu jí 不同，意思是“通过邮局寄送”。", "游击": "游击 yóujī 两个音节的声调都与 yòu jí 不同，意思是“游击”，指游动作战。"}, "sentence_index": null, "correct_answer": "又及"}, "level_3": {"options": [{"text": "又及", "is_correct": true, "explanation": "又及：书信结尾追加的附言，正好可以写“提醒我早点回信”。"}, {"text": "笑话", "is_correct": false, "explanation": "语义：笑话是用来逗人笑的，不会在信末提醒人回信。"}, {"text": "颂词", "is_correct": false, "explanation": "语域：颂词是庄重的赞美文字，与信末的口语提醒不合。"}, {"text": "谎言", "is_correct": false, "explanation": "语义：谎言是假话，与“提醒我早点回信”的内容不合。"}], "explanations": {"又及": "又及：书信结尾追加的附言，正好可以写“提醒我早点回信”。", "笑话": "语义：笑话是用来逗人笑的，不会在信末提醒人回信。", "颂词": "语域：颂词是庄重的赞美文字，与信末的口语提醒不合。", "谎言": "语义：谎言是假话，与“提醒我早点回信”的内容不合。"}, "sentence_index": 0, "correct_answer": "又及"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她用胶水把又及粘好。", "explanation": "这里应该用〈信封〉。又及是信末追加的文字，不能用胶水粘；被粘好的是信封。"}, {"text": "信的右上角写着又及。", "explanation": "这里应该用〈日期〉。又及是书信结尾追加的话，不写在信的右上角。"}, {"text": "我在信里写了一幅又及。", "explanation": "这里应该用〈段〉。“幅”用于画作、照片，不用于又及。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cf7ce71-ddfc-406e-88fa-d631d3cd9ba7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86768, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "又及", "is_correct": true, "explanation": "又及：信末的附言，这里是爸爸写的一句叮嘱。"}, {"text": "菜单", "is_correct": false, "explanation": "语义：菜单列的是菜名，不会只写“注意安全”四个字。"}, {"text": "账本", "is_correct": false, "explanation": "语义：账本记的是收支，不会写“注意安全”这样的叮嘱。"}, {"text": "乐谱", "is_correct": false, "explanation": "语义：乐谱记的是音符和曲谱，不会只写“注意安全”四个字。"}], "explanations": {"又及": "又及：信末的附言，这里是爸爸写的一句叮嘱。", "菜单": "语义：菜单列的是菜名，不会只写“注意安全”四个字。", "账本": "语义：账本记的是收支，不会写“注意安全”这样的叮嘱。", "乐谱": "语义：乐谱记的是音符和曲谱，不会只写“注意安全”四个字。"}, "sentence_index": 6, "correct_answer": "又及"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书的又及排在最前面。", "explanation": "这里应该用〈目录〉。又及只用于书信结尾，不会排在书的最前面。"}, {"text": "书的又及印在每页下方。", "explanation": "这里应该用〈页码〉。又及只用于书信结尾，不会印在每一页上。"}, {"text": "信里夹着一颗又及。", "explanation": "这里应该用〈段〉。“颗”用于粒状的小东西，又及是一段文字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cf7ce71-ddfc-406e-88fa-d631d3cd9ba7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86768, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "奶奶在信末写了一头又及。", "corrected_sentence": "奶奶在信末写了一段又及。", "error_description": "错误：量词“头”用于牛、猪等动物，不能修饰又及。正确：“一段又及”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cf7ce71-ddfc-406e-88fa-d631d3cd9ba7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
