INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86769, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "大公司是很多人一起工作的、很大的公司。", "primary_collocate": null, "pronunciation": "dà gōng sī", "ipa": "ta˥˩ kʊŋ˥ sɨ˥", "syllable_count": 3, "sentences": [{"text": "这家大公司有很多员工。", "target_word": "大公司", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在一家大公司工作。", "target_word": "大公司", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大公司的办公楼又高又新。", "target_word": "大公司", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想去大公司找工作。", "target_word": "大公司", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个大公司每天都有很多人上班。", "target_word": "大公司", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大公司的老板很忙，每天开很多会。", "target_word": "大公司", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她毕业后进了一家大公司。", "target_word": "大公司", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大公司里的同事来自不同的国家。", "target_word": "大公司", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爸爸在大公司做了十年。", "target_word": "大公司", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中午，大公司楼下的饭馆总是坐满了人。", "target_word": "大公司", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一家大公司", "label": "量词"}, {"form": "一个大公司", "label": "量词"}], "register": "中性", "sense_fingerprint": "很多人一起工作的很大的公司", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff939fe6-9da8-4641-8328-502a2b4a468a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86769, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大公司", "is_correct": true, "explanation": "正确：“大公司”指员工很多的大公司，与“有很多员工”相符。"}, {"text": "大学生", "is_correct": false, "explanation": "语义：学生没有员工，“有很多员工”说的是机构，不能说学生有员工。"}, {"text": "大山", "is_correct": false, "explanation": "搭配：机构用量词“家”，山用“座”，“这家大山”不成立。"}, {"text": "大森林", "is_correct": false, "explanation": "语义：森林里没有员工，“有很多员工”不能用于森林。"}], "explanations": {"大公司": "正确：“大公司”指员工很多的大公司，与“有很多员工”相符。", "大学生": "语义：学生没有员工，“有很多员工”说的是机构，不能说学生有员工。", "大山": "搭配：机构用量词“家”，山用“座”，“这家大山”不成立。", "大森林": "语义：森林里没有员工，“有很多员工”不能用于森林。"}, "sentence_index": 0, "correct_answer": "大公司"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我想去一座大公司找工作。", "explanation": "这里应该用〈家〉。大公司是机构，量词用“家”；“座”多用于山、桥、楼房等。"}, {"text": "大公司流过很多城市。", "explanation": "这里应该用〈大河〉。“大河”是水道，能流过很多城市；“大公司”指机构，不会流动，不能这样用。"}, {"text": "我姐姐是一家大公司。", "explanation": "这里应该用〈老板〉。“大公司”是机构，不能直接指人；说人与公司的关系要用〈老板〉或〈员工〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbe18f3c-0bfb-4f8d-8f30-faa5ce06c6e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86769, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大公司", "is_correct": true, "explanation": "正确：“进了一家大公司”指进入规模大的公司工作，与“毕业后”相符。"}, {"text": "大海", "is_correct": false, "explanation": "搭配：量词“家”不用于海，“进了”也不能接海。"}, {"text": "大草原", "is_correct": false, "explanation": "语义：草原不是可以“毕业后进”的单位，句意说不通。"}, {"text": "大宫殿", "is_correct": false, "explanation": "搭配：宫殿用量词“座”，不用“家”；而且一般不说“毕业后进了宫殿”。"}], "explanations": {"大公司": "正确：“进了一家大公司”指进入规模大的公司工作，与“毕业后”相符。", "大海": "搭配：量词“家”不用于海，“进了”也不能接海。", "大草原": "语义：草原不是可以“毕业后进”的单位，句意说不通。", "大宫殿": "搭配：宫殿用量词“座”，不用“家”；而且一般不说“毕业后进了宫殿”。"}, "sentence_index": 6, "correct_answer": "大公司"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家大公司只有两个员工，我们每天都能见面。", "explanation": "这里应该用〈小公司〉。“大公司”指规模大、人员多，只有两个员工时应说〈小公司〉。"}, {"text": "大公司的学生每个学期都要参加期末考试。", "explanation": "这里应该用〈大学〉。学生、期末考试是学校的事，“大公司”指企业。"}, {"text": "这家大公司里有很多大象。", "explanation": "这里应该用〈大动物园〉。动物园里才有大象；“大公司”指企业，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbe18f3c-0bfb-4f8d-8f30-faa5ce06c6e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86769, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只大公司的老板很有名。", "corrected_sentence": "这家大公司的老板很有名。", "error_description": "量词错误：“大公司”是机构，量词应用“家”，不能用“只”（“只”用于动物、单个物品等）。应说“这家大公司的老板很有名”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbe18f3c-0bfb-4f8d-8f30-faa5ce06c6e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86769, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我姐姐在一只大公司上班。", "corrected_sentence": "我姐姐在一家大公司上班。", "error_description": "量词错误：“大公司”是机构，量词应用“家”，不能用“只”（“只”用于动物、单个物品等）。应说“在一家大公司上班”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbe18f3c-0bfb-4f8d-8f30-faa5ce06c6e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
