INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86771, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbe18f3c-0bfb-4f8d-8f30-faa5ce06c6e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86771, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "完善是很完整，没有缺的地方。", "primary_collocate": null, "pronunciation": "wán shàn", "ipa": "wan˧˥ ʂan˥˩", "syllable_count": 2, "sentences": [{"text": "这家医院的设备很完善。", "target_word": "完善", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的服务非常完善。", "target_word": "完善", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个计划还不够完善。", "target_word": "完善", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的制度已经很完善了。", "target_word": "完善", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的交通系统很完善。", "target_word": "完善", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的想法不太完善，还要再想想。", "target_word": "完善", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒店里的设施很完善，住着很舒服。", "target_word": "完善", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的内容很完善，什么都有。", "target_word": "完善", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新楼的安全设备十分完善。", "target_word": "完善", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的规定不完善，大家都有意见。", "target_word": "完善", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不完善", "label": "否定式"}], "register": "中性", "sense_fingerprint": "制度、设备等很完整，没有缺的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff939fe6-9da8-4641-8328-502a2b4a468a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86771, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "完善", "is_correct": true, "explanation": "正确：“完善”指设备完整、没有缺的地方，符合句意。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：“高兴”说人的心情，设备没有情绪。"}, {"text": "苦", "is_correct": false, "explanation": "搭配：“苦”是味觉词，不能用来形容设备。"}, {"text": "害羞", "is_correct": false, "explanation": "语义：“害羞”是人的表现，设备不会害羞。"}], "explanations": {"完善": "正确：“完善”指设备完整、没有缺的地方，符合句意。", "高兴": "语义：“高兴”说人的心情，设备没有情绪。", "苦": "搭配：“苦”是味觉词，不能用来形容设备。", "害羞": "语义：“害羞”是人的表现，设备不会害羞。"}, "sentence_index": 0, "correct_answer": "完善"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这幅画的色彩很完善，看上去很舒服。", "explanation": "这里应该用〈完美〉。“完善”多用于制度、设备、计划，形容色彩等美好的事物要用〈完美〉。"}, {"text": "我的成绩很完善，每次考试都名列前茅。", "explanation": "这里应该用〈优秀〉。“完善”不用于说学习成绩，成绩好要用〈优秀〉。"}, {"text": "他的身体很完善，每天都锻炼。", "explanation": "这里应该用〈健全〉。“完善”指制度、设备等完整，身体的完好要用〈健全〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbe18f3c-0bfb-4f8d-8f30-faa5ce06c6e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86771, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "完善", "is_correct": true, "explanation": "正确：“完善”指设施齐全，与“住着很舒服”一致。"}, {"text": "破旧", "is_correct": false, "explanation": "语义：“破旧”说设施陈旧，与“住着很舒服”矛盾。"}, {"text": "尖锐", "is_correct": false, "explanation": "搭配：“尖锐”形容物体的尖头或言辞，不用于说设施齐全。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：“热闹”说人多、有声响的场面，不能形容设施。"}], "explanations": {"完善": "正确：“完善”指设施齐全，与“住着很舒服”一致。", "破旧": "语义：“破旧”说设施陈旧，与“住着很舒服”矛盾。", "尖锐": "搭配：“尖锐”形容物体的尖头或言辞，不用于说设施齐全。", "热闹": "语义：“热闹”说人多、有声响的场面，不能形容设施。"}, "sentence_index": 6, "correct_answer": "完善"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他今天心情很完善，一直在笑。", "explanation": "这里应该用〈愉快〉。“完善”说制度、设备的完整，心情好要用〈愉快〉。"}, {"text": "这个小饭馆的厨房很完善，连一个炉子都没有。", "explanation": "这里应该用〈简陋〉。“完善”指设备完整、没有缺的地方，连炉子都没有说明设备很少，应说〈简陋〉。"}, {"text": "服务员的态度很完善，大家都很满意。", "explanation": "这里应该用〈热情〉。“完善”说制度、设备，态度好要用〈热情〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbe18f3c-0bfb-4f8d-8f30-faa5ce06c6e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86771, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这所学校的图书室完善。", "corrected_sentence": "这所学校的图书室很完善。", "error_description": "副词遗漏：形容词“完善”作谓语时，前面要加程度副词“很”。应说“这所学校的图书室很完善”，不能说“这所学校的图书室完善”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbe18f3c-0bfb-4f8d-8f30-faa5ce06c6e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86771, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一个很完善计划，大家都很满意。", "corrected_sentence": "这是一个很完善的计划，大家都很满意。", "error_description": "结构助词错误：多音节形容词“完善”作定语修饰名词时，后面要加“的”，应说“很完善的计划”，不能省略“的”说“很完善计划”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbe18f3c-0bfb-4f8d-8f30-faa5ce06c6e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
