INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86772, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使计划、制度等变得完备。", "primary_collocate": null, "pronunciation": "wán shàn", "ipa": "wan˧˥ ʂan˥˩", "syllable_count": 2, "sentences": [{"text": "我们要不断完善这个计划。", "target_word": "完善", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师请我们继续完善自己的论文。", "target_word": "完善", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司正在完善新的规定。", "target_word": "完善", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把方案又完善了一遍。", "target_word": "完善", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师想办法完善这个软件。", "target_word": "完善", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校完善了图书馆的设备。", "target_word": "完善", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个制度还需要继续完善。", "target_word": "完善", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你完善一下这份表格。", "target_word": "完善", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理要求大家完善工作报告。", "target_word": "完善", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府完善了城市的交通。", "target_word": "完善", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "完善了", "label": "体标"}, {"form": "完善过", "label": "体标"}], "register": "中性", "sense_fingerprint": "使计划、制度等变得完备", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff939fe6-9da8-4641-8328-502a2b4a468a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86772, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "完善", "is_correct": true, "explanation": "正确：“完善”是使计划更完备，与“不断”和“这个计划”搭配，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语是食物，不能接“计划”。"}, {"text": "哭", "is_correct": false, "explanation": "语义：“哭”是人的动作，不能用于处理计划。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的宾语是饮品，不能接“计划”。"}], "explanations": {"完善": "正确：“完善”是使计划更完备，与“不断”和“这个计划”搭配，符合句意。", "吃": "搭配：“吃”的宾语是食物，不能接“计划”。", "哭": "语义：“哭”是人的动作，不能用于处理计划。", "喝": "搭配：“喝”的宾语是饮品，不能接“计划”。"}, "sentence_index": 0, "correct_answer": "完善"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他终于完善了任务。", "explanation": "这里应该用〈完成〉。“完善”指使事物更完备，任务做完要用〈完成〉。"}, {"text": "政府正在完善空气质量。", "explanation": "这里应该用〈改善〉。“完善”指制度、计划等变得完备，空气变好要用〈改善〉。"}, {"text": "工人用水泥完善了墙上的裂缝。", "explanation": "这里应该用〈修补〉。“完善”不用于修复破损，裂缝要用〈修补〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbe18f3c-0bfb-4f8d-8f30-faa5ce06c6e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86772, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "完善", "is_correct": true, "explanation": "正确：“完善”指使制度更完备，与“还需要继续”相符。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能接“制度”，制度不是歌曲。"}, {"text": "养", "is_correct": false, "explanation": "搭配：“养”的宾语多是动植物或习惯，不能接“制度”。"}, {"text": "睡", "is_correct": false, "explanation": "语义：“睡”是人的动作，制度不能睡觉，句意说不通。"}], "explanations": {"完善": "正确：“完善”指使制度更完备，与“还需要继续”相符。", "唱": "搭配：“唱”不能接“制度”，制度不是歌曲。", "养": "搭配：“养”的宾语多是动植物或习惯，不能接“制度”。", "睡": "语义：“睡”是人的动作，制度不能睡觉，句意说不通。"}, "sentence_index": 6, "correct_answer": "完善"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生完善了病人的伤口。", "explanation": "这里应该用〈治疗〉。“完善”指使事物更完备，伤口要用〈治疗〉。"}, {"text": "妈妈完善了这顿晚饭。", "explanation": "这里应该用〈做〉。“完善”多用于计划、制度，做饭要用〈做〉。"}, {"text": "他把生日礼物完善得很漂亮。", "explanation": "这里应该用〈包装〉。“完善”不用于说礼物的外观，包装礼物要用〈包装〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbe18f3c-0bfb-4f8d-8f30-faa5ce06c6e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86772, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个计划完善很好。", "corrected_sentence": "这个计划完善得很好。", "error_description": "补语错误：“完善”后带程度补语时要用“得”连接，应说“完善得很好”，不能说“完善很好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbe18f3c-0bfb-4f8d-8f30-faa5ce06c6e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86772, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "政府正在完善了城市的交通。", "corrected_sentence": "政府正在完善城市的交通。", "error_description": "体标错误：“正在”表示动作正在进行，不能与表示完成的“了”同时使用。应说“政府正在完善城市的交通”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbe18f3c-0bfb-4f8d-8f30-faa5ce06c6e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
