INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86774, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e286751-3bfa-4706-aff2-38058e45a08d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86774, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "子女的父母或其他监护人。", "primary_collocate": null, "pronunciation": "jiā zhǎng", "ipa": "tɕja˥ ʈʂaŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "爷爷是孩子的家长，每天送他上学。", "target_word": "家长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子没有父母，奶奶是他的家长。", "target_word": "家长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校请每位家长在表上写名字。", "target_word": "家长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家长要在文件上签字。", "target_word": "家长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会时，老师请家长留下来。", "target_word": "家长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的家长住在外地，不能来学校。", "target_word": "家长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个家长都应该关心孩子的学习。", "target_word": "家长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子生病了，老师马上给家长打电话。", "target_word": "家长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请让家长看看你的成绩单。", "target_word": "家长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校通知家长，下周不上课。", "target_word": "家长", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家長", "label": "繁体"}, {"form": "家长会", "label": "复合"}], "register": "中性", "sense_fingerprint": "孩子的父母或其他监护人，负责孩子的事务", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e8d98bf-ca56-4497-b80d-a8800a5dfbfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86774, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "家长", "is_correct": true, "explanation": "正确：“爷爷”作为孩子的监护人，承担送孩子上学的责任，与“家长”的定义相符。"}, {"text": "学生", "is_correct": false, "explanation": "语义：“学生”指在校学习的人，爷爷不是孩子的学生。"}, {"text": "同学", "is_correct": false, "explanation": "语义：“同学”指同龄同校的人，爷爷与孩子的年龄不相符。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“是孩子的”后应接指人的名词，“作业”不能指人，也不能送孩子上学。"}], "explanations": {"家长": "正确：“爷爷”作为孩子的监护人，承担送孩子上学的责任，与“家长”的定义相符。", "学生": "语义：“学生”指在校学习的人，爷爷不是孩子的学生。", "同学": "语义：“同学”指同龄同校的人，爷爷与孩子的年龄不相符。", "作业": "搭配：“是孩子的”后应接指人的名词，“作业”不能指人，也不能送孩子上学。"}, "sentence_index": 0, "correct_answer": "家长"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师是学生的家长。", "explanation": "语义：老师不是学生的父母或监护人，不能称为学生的家长。这里应该说“学生的老师”。"}, {"text": "学校门口站着一只家长。", "explanation": "这里应该用〈位〉。“只”多用于动物或成对器官，人用“位”或“个”，不用“只”。"}, {"text": "我们医院的家长每天给病人看病。", "explanation": "语义：“家长”指子女的父母或监护人，不是给病人看病的医生。这里应该用〈医生〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e286751-3bfa-4706-aff2-38058e45a08d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86774, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "家长", "is_correct": true, "explanation": "正确：“关心孩子的学习”的主体应是孩子的父母或监护人，与“每个家长”相符。"}, {"text": "家具", "is_correct": false, "explanation": "语义：家具是物件，不能关心孩子的学习。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是物件，不能关心孩子的学习。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“关心”需要指人的主语，“房子”不能作“关心”的主语。"}], "explanations": {"家长": "正确：“关心孩子的学习”的主体应是孩子的父母或监护人，与“每个家长”相符。", "家具": "语义：家具是物件，不能关心孩子的学习。", "窗户": "语义：窗户是物件，不能关心孩子的学习。", "房子": "搭配：“关心”需要指人的主语，“房子”不能作“关心”的主语。"}, "sentence_index": 6, "correct_answer": "家长"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个家长今年才三岁，还不会走路。", "explanation": "语义：“家长”指子女的父母或监护人，不是三岁还不会走路的孩子。这里应该用〈孩子〉。"}, {"text": "这位家长是一张桌子。", "explanation": "语义：家长指孩子的父母或监护人，是人，不能是桌子这样的东西。"}, {"text": "这个家长每天要玩积木，不会写字。", "explanation": "语义：“家长”指子女的父母或监护人，不是玩积木、不会写字的小孩。这里应该用〈孩子〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e286751-3bfa-4706-aff2-38058e45a08d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86774, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校请两位家长们在表上写名字。", "corrected_sentence": "学校请两位家长在表上写名字。", "error_description": "“们”不能与数量词连用，应说“两位家长”，不能说“两位家长们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e286751-3bfa-4706-aff2-38058e45a08d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86774, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校请每家长来参加会议。", "corrected_sentence": "学校请每位家长来参加会议。", "error_description": "量词缺失：“每”后要用量词“位”，应说“每位家长”；“每家长”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e286751-3bfa-4706-aff2-38058e45a08d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86776, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbe18f3c-0bfb-4f8d-8f30-faa5ce06c6e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86776, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbe18f3c-0bfb-4f8d-8f30-faa5ce06c6e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86776, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "对本国或本单位内部。", "primary_collocate": null, "pronunciation": "duì nèi", "ipa": "tweɪ˥˩ neɪ˥˩", "syllable_count": 2, "sentences": [{"text": "这家公司对内管理很严。", "target_word": "对内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对内，我们要做好工作；对外，我们要多交朋友。", "target_word": "对内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家对内要发展经济，对外要多交朋友。", "target_word": "对内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司对内要培养新人。", "target_word": "对内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校对内加强管理，对外开放交流。", "target_word": "对内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理说，这份计划对内可以公开，对外要保密。", "target_word": "对内", "complexity_tier": "T3", "furigana": "jīng lǐ shuō， zhè fèn jì huà duì nèi kě yǐ gōng kāi， duì wài yào bǎo mì。", "sentence_source": "generated"}, {"text": "我们的网站对内对外都很方便。", "target_word": "对内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司对内统一了考勤制度，大家都能遵守。", "target_word": "对内", "complexity_tier": "T3", "furigana": "gōng sī duì nèi tǒng yī le kǎo qín zhì dù， dà jiā dōu néng zūn shǒu。", "sentence_source": "generated"}, {"text": "对内，公司要让员工满意。", "target_word": "对内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个部门对内做服务，不对外卖东西。", "target_word": "对内", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "针对本国或本单位内部（与对外相对）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff939fe6-9da8-4641-8328-502a2b4a468a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86776, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "对内", "is_correct": true, "explanation": "正确：“对内”指对本单位内部，这里说的是公司内部管理很严。"}, {"text": "乱", "is_correct": false, "explanation": "语义：“乱”表示没有章法，与“管理很严”自相矛盾。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不常发生，与“管理很严”这种持续状态矛盾。"}, {"text": "随便", "is_correct": false, "explanation": "语义：“随便”表示随意、不严格，与“管理很严”相反。"}], "explanations": {"对内": "正确：“对内”指对本单位内部，这里说的是公司内部管理很严。", "乱": "语义：“乱”表示没有章法，与“管理很严”自相矛盾。", "偶尔": "语义：“偶尔”表示不常发生，与“管理很严”这种持续状态矛盾。", "随便": "语义：“随便”表示随意、不严格，与“管理很严”相反。"}, "sentence_index": 0, "correct_answer": "对内"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司对内宣传新产品，希望海外游客了解。", "explanation": "这里应该用〈对外〉。对外指面向外部，这句的宣传对象是海外游客；对内只指本单位内部。"}, {"text": "这家公司对内开放网站，外国客户都能访问。", "explanation": "这里应该用〈对外〉。对外指面向外部，这句说外国客户都能访问，是面向外部的做法；对内只指本单位内部。"}, {"text": "这家公司对内签订了一份合同，对方是一家海外企业。", "explanation": "这里应该用〈对外〉。对内只指本单位内部，合同的对方是海外企业，应说“对外签订”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbe18f3c-0bfb-4f8d-8f30-faa5ce06c6e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86776, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "对内", "is_correct": true, "explanation": "正确：“对内”与“对外”并列，指网站对本单位内部和外部都方便。"}, {"text": "只", "is_correct": false, "explanation": "语义：“只”表示限定，与后面“对内对外都”的并列结构矛盾。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”表示马上，与“都很方便”这种长期状态不协调。"}, {"text": "单独", "is_correct": false, "explanation": "搭配：“单独”指单个进行，不能与“对内对外都”的并列结构搭配。"}], "explanations": {"对内": "正确：“对内”与“对外”并列，指网站对本单位内部和外部都方便。", "只": "语义：“只”表示限定，与后面“对内对外都”的并列结构矛盾。", "立刻": "语义：“立刻”表示马上，与“都很方便”这种长期状态不协调。", "单独": "搭配：“单独”指单个进行，不能与“对内对外都”的并列结构搭配。"}, "sentence_index": 6, "correct_answer": "对内"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司对内公开了财务报告，连路人都能在网上查到。", "explanation": "这里应该用〈向外界〉。对内只指本单位内部，这句说路人也能查到，是向外界公开。"}, {"text": "这所大学对内招收留学生，外国学生也能报名。", "explanation": "这里应该用〈对外〉。对外指面向外部，这句说外国学生也能报名，是面向外部招生；对内只指本单位内部。"}, {"text": "学校对内开放了图书馆，校外的人也可以借书。", "explanation": "这里应该用〈向外部〉。对内只指本单位内部，这句说校外的人也能借书，是向外部开放。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbe18f3c-0bfb-4f8d-8f30-faa5ce06c6e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86776, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家医院对内了要做好服务。", "corrected_sentence": "这家医院对内要做好服务。", "error_description": "错误形式：“这家医院对内了要做好服务”，副词“对内”后不能直接加“了”；正确形式：“这家医院对内要做好服务”，“对内”是副词，放在主语之后、动词之前作状语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbe18f3c-0bfb-4f8d-8f30-faa5ce06c6e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86776, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校对内了开放图书馆，只给老师用。", "corrected_sentence": "学校对内开放图书馆，只给老师用。", "error_description": "错误形式：“学校对内了开放图书馆”，副词“对内”后不能直接加“了”；正确形式：“学校对内开放图书馆”，“对内”作状语，指对本单位内部开放。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbe18f3c-0bfb-4f8d-8f30-faa5ce06c6e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
