INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86777, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "加是把东西放在一起，变得更多。", "primary_collocate": null, "pronunciation": "jiā", "ipa": "tɕja˥", "syllable_count": 1, "sentences": [{"text": "煮汤的时候，要加一点盐。", "target_word": "加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这杯咖啡太苦，请再加一勺糖。", "target_word": "加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "锅里的水不够，你再加一些吧。", "target_word": "加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在茶里加了两块冰。", "target_word": "加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面太干了，再加点水吧。", "target_word": "加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在粥里加过红枣。", "target_word": "加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你把牛奶加到咖啡里吧。", "target_word": "加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的面里要加辣，不要加葱。", "target_word": "加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "炒菜时先放油，再加肉。", "target_word": "加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这碗面不加醋，我不爱吃酸。", "target_word": "加", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "加了", "label": "体标（完成）"}, {"form": "加过", "label": "体标（经历）"}, {"form": "加上", "label": "复合"}], "register": "中性", "sense_fingerprint": "往已有的东西里再放进一些，如盐、糖、水", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2568f57c-7316-43f4-ae41-0373852d042f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86777, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "加", "is_correct": true, "explanation": "加：jiā（第一声），意思是往已有的东西里再放进去，是正确答案。"}, {"text": "价", "is_correct": false, "explanation": "jià（第四声）与 jiā（第一声）声调不同，意思是价格。"}, {"text": "假", "is_correct": false, "explanation": "jiǎ（第三声）与 jiā（第一声）声调不同，意思是假的。"}, {"text": "架", "is_correct": false, "explanation": "jià（第四声）与 jiā（第一声）声调不同，意思是架子。"}, {"text": "甲", "is_correct": false, "explanation": "jiǎ（第三声）与 jiā（第一声）声调不同，意思是天干之一，也指指甲。"}], "explanations": {"加": "加：jiā（第一声），意思是往已有的东西里再放进去，是正确答案。", "价": "jià（第四声）与 jiā（第一声）声调不同，意思是价格。", "假": "jiǎ（第三声）与 jiā（第一声）声调不同，意思是假的。", "架": "jià（第四声）与 jiā（第一声）声调不同，意思是架子。", "甲": "jiǎ（第三声）与 jiā（第一声）声调不同，意思是天干之一，也指指甲。"}, "sentence_index": null, "correct_answer": "加"}, "level_3": {"options": [{"text": "加", "is_correct": true, "explanation": "加：往汤里再放入一点盐，符合句子语境，是正确答案。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象须是可以冲洗的东西，不说洗盐，句子不通。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发出歌声，与煮汤时放盐的情境毫不相干。"}, {"text": "踢", "is_correct": false, "explanation": "搭配：“踢”的对象须是可以用脚踢的东西，不能与盐搭配。"}], "explanations": {"加": "加：往汤里再放入一点盐，符合句子语境，是正确答案。", "洗": "搭配：“洗”的对象须是可以冲洗的东西，不说洗盐，句子不通。", "唱": "语义：“唱”指发出歌声，与煮汤时放盐的情境毫不相干。", "踢": "搭配：“踢”的对象须是可以用脚踢的东西，不能与盐搭配。"}, "sentence_index": 0, "correct_answer": "加"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把书加在桌子上了。", "explanation": "这里应该用〈放〉。加表示往已有的东西里再放入同类的东西，不能用来说把书安放在桌子上。"}, {"text": "他把画加在墙上。", "explanation": "这里应该用〈挂〉。加不能用于把物品挂在墙上，此处不是往已有的东西里再加。"}, {"text": "他加了篮球队。", "explanation": "这里应该用〈加入〉。加表示把东西放进已有的东西里，不能用来说加入一个团体，应说加入篮球队。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35726a13-f82e-4a20-8211-11cdd2ec28a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86777, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "加", "is_correct": true, "explanation": "加：jiā（第一声），意思是往已有的东西里再放进去，是正确答案。"}, {"text": "掐", "is_correct": false, "explanation": "qiā 与 jiā 声母不同（q 与 j），意思是用手指捏或按。"}, {"text": "嫁", "is_correct": false, "explanation": "jià（第四声）与 jiā（第一声）声调不同，意思是出嫁。"}, {"text": "驾", "is_correct": false, "explanation": "jià（第四声）与 jiā（第一声）声调不同，意思是驾驶。"}], "explanations": {"加": "加：jiā（第一声），意思是往已有的东西里再放进去，是正确答案。", "掐": "qiā 与 jiā 声母不同（q 与 j），意思是用手指捏或按。", "嫁": "jià（第四声）与 jiā（第一声）声调不同，意思是出嫁。", "驾": "jià（第四声）与 jiā（第一声）声调不同，意思是驾驶。"}, "sentence_index": null, "correct_answer": "加"}, "level_3": {"options": [{"text": "加", "is_correct": true, "explanation": "加：把牛奶加到咖啡里，符合句子语境，是正确答案。"}, {"text": "切", "is_correct": false, "explanation": "搭配：“切”的对象须是有形状的固体，不能切牛奶，句子不通。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指把食物咽下，不能说吃到咖啡里。"}, {"text": "烤", "is_correct": false, "explanation": "搭配：“烤”指用火加热固体食物，不能说烤牛奶到咖啡里。"}], "explanations": {"加": "加：把牛奶加到咖啡里，符合句子语境，是正确答案。", "切": "搭配：“切”的对象须是有形状的固体，不能切牛奶，句子不通。", "吃": "语义：“吃”指把食物咽下，不能说吃到咖啡里。", "烤": "搭配：“烤”指用火加热固体食物，不能说烤牛奶到咖啡里。"}, "sentence_index": 6, "correct_answer": "加"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在河边加了一条鱼。", "explanation": "这里应该用〈钓〉。加表示往已有的东西里再放入，不能用来说钓鱼。"}, {"text": "我每天加了一个小时的琴。", "explanation": "这里应该用〈练〉。加不能用于练习乐器，此处应说练了一个小时的琴。"}, {"text": "他把花加在窗台上。", "explanation": "这里应该用〈摆〉。加表示往已有的东西里放入，不能用来说把花摆在窗台上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35726a13-f82e-4a20-8211-11cdd2ec28a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86777, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "汤太淡了，我加了一点了盐。", "corrected_sentence": "汤太淡了，我加了一点盐。", "error_description": "错误在于“了”的位置。“加了一点盐”中“了”紧跟动词“加”，表示完成；“一点”后的“盐”前不能再加“了”，应去掉多余的“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35726a13-f82e-4a20-8211-11cdd2ec28a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86777, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你把醋进加汤里吧。", "corrected_sentence": "你把醋加进汤里吧。", "error_description": "错误在于补语“进”的位置。“进”是“加”的结果补语，应放在“加”之后，说“加进汤里”，不能说“进加汤里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35726a13-f82e-4a20-8211-11cdd2ec28a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86778, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "减", "is_correct": true, "explanation": "减：与加相反，指从数目中去掉一部分，是加法的反义词，是正确答案。"}, {"text": "乘", "is_correct": false, "explanation": "乘：是另一种运算，即乘法，并不是加的反义词。"}, {"text": "除", "is_correct": false, "explanation": "除：是另一种运算，即除法，并不是加的反义词。"}, {"text": "等", "is_correct": false, "explanation": "等：表示相同或等于，与加没有反义关系。"}], "correct_answer": "减", "explanations": {"减": "减：与加相反，指从数目中去掉一部分，是加法的反义词，是正确答案。", "乘": "乘：是另一种运算，即乘法，并不是加的反义词。", "除": "除：是另一种运算，即除法，并不是加的反义词。", "等": "等：表示相同或等于，与加没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35726a13-f82e-4a20-8211-11cdd2ec28a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
