INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86778, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把数目或东西合在一起；使数量增多。", "primary_collocate": null, "pronunciation": "jiā", "ipa": "tɕja˥", "syllable_count": 1, "sentences": [{"text": "二加三等于五。", "target_word": "加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三加四是多少？", "target_word": "加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一加一等于二。", "target_word": "加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问我：五加六等于几？", "target_word": "加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把这三个数加在一起是九。", "target_word": "加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十加二十是三十。", "target_word": "加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明算错了，八加七不是十四。", "target_word": "加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把五和七加在一起，得数是十二。", "target_word": "加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先加后减，答案是对的。", "target_word": "加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "四加六再加二，一共十二。", "target_word": "加", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "加了", "label": "体标（完成）"}, {"form": "加法", "label": "复合"}, {"form": "加上", "label": "复合"}], "register": "中性", "sense_fingerprint": "数学运算中把几个数合起来求和", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2568f57c-7316-43f4-ae41-0373852d042f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86778, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "加", "is_correct": true, "explanation": "加：jiā（第一声），意思是把数合在一起，是正确答案。"}, {"text": "价", "is_correct": false, "explanation": "jià（第四声）与 jiā（第一声）声调不同，意思是价格。"}, {"text": "假", "is_correct": false, "explanation": "jiǎ（第三声）与 jiā（第一声）声调不同，意思是假的。"}, {"text": "甲", "is_correct": false, "explanation": "jiǎ（第三声）与 jiā（第一声）声调不同，意思是天干之一，也指指甲。"}], "explanations": {"加": "加：jiā（第一声），意思是把数合在一起，是正确答案。", "价": "jià（第四声）与 jiā（第一声）声调不同，意思是价格。", "假": "jiǎ（第三声）与 jiā（第一声）声调不同，意思是假的。", "甲": "jiǎ（第三声）与 jiā（第一声）声调不同，意思是天干之一，也指指甲。"}, "sentence_index": null, "correct_answer": "加"}, "level_3": {"options": [{"text": "加", "is_correct": true, "explanation": "加：二加三等于五，表示把两个数合起来，是正确答案。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”指书写文字，“二写三等于五”不成算式，句子不通。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发出歌声，与数字运算无关，句子不通。"}, {"text": "踢", "is_correct": false, "explanation": "搭配：“踢”的对象须是可以用脚踢的东西，不能用于数字。"}], "explanations": {"加": "加：二加三等于五，表示把两个数合起来，是正确答案。", "写": "语义：“写”指书写文字，“二写三等于五”不成算式，句子不通。", "唱": "语义：“唱”指发出歌声，与数字运算无关，句子不通。", "踢": "搭配：“踢”的对象须是可以用脚踢的东西，不能用于数字。"}, "sentence_index": 0, "correct_answer": "加"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把书加在桌子上了。", "explanation": "这里应该用〈放〉。此处的加表示把数目或东西合在一起，不能用来说把书安放在桌子上。"}, {"text": "他加了篮球队。", "explanation": "这里应该用〈加入〉。此处的加表示把数目或东西合在一起，不能用来说加入一个团体，应说加入篮球队。"}, {"text": "我每天加了一个小时的琴。", "explanation": "这里应该用〈练〉。此处的加表示把数目或东西合在一起，不能用来说练琴，应说练了一个小时的琴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35726a13-f82e-4a20-8211-11cdd2ec28a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86778, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "加", "is_correct": true, "explanation": "加：jiā（第一声），意思是把数合在一起，是正确答案。"}, {"text": "掐", "is_correct": false, "explanation": "qiā 与 jiā 声母不同（q 与 j），意思是用手指捏或按。"}, {"text": "嫁", "is_correct": false, "explanation": "jià（第四声）与 jiā（第一声）声调不同，意思是出嫁。"}, {"text": "驾", "is_correct": false, "explanation": "jià（第四声）与 jiā（第一声）声调不同，意思是驾驶。"}], "explanations": {"加": "加：jiā（第一声），意思是把数合在一起，是正确答案。", "掐": "qiā 与 jiā 声母不同（q 与 j），意思是用手指捏或按。", "嫁": "jià（第四声）与 jiā（第一声）声调不同，意思是出嫁。", "驾": "jià（第四声）与 jiā（第一声）声调不同，意思是驾驶。"}, "sentence_index": null, "correct_answer": "加"}, "level_3": {"options": [{"text": "加", "is_correct": true, "explanation": "加：八加七不是十四，表示把两个数合起来，是正确答案。"}, {"text": "切", "is_correct": false, "explanation": "搭配：“切”的对象须是有形状的实体，不能切数字，句子不通。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指把食物咽下，与算式无关，句子不通。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象须是可以冲洗的东西，不能用于数字。"}], "explanations": {"加": "加：八加七不是十四，表示把两个数合起来，是正确答案。", "切": "搭配：“切”的对象须是有形状的实体，不能切数字，句子不通。", "吃": "语义：“吃”指把食物咽下，与算式无关，句子不通。", "洗": "搭配：“洗”的对象须是可以冲洗的东西，不能用于数字。"}, "sentence_index": 6, "correct_answer": "加"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把画加在墙上。", "explanation": "这里应该用〈挂〉。加不能用于把物品挂在墙上，此处不是数学上把数合起来。"}, {"text": "我在河边加了一条鱼。", "explanation": "这里应该用〈钓〉。此处的加表示把数合在一起，不能用来说钓鱼。"}, {"text": "我们加了一盘棋。", "explanation": "这里应该用〈下〉。加不能用于棋类，此处应说下了一盘棋。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35726a13-f82e-4a20-8211-11cdd2ec28a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86778, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "七加了八等于十五。", "corrected_sentence": "七加八等于十五。", "error_description": "错误在于“加”后多了“了”。算式“七加八”中不能在“加”后加“了”，应说“七加八等于十五”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35726a13-f82e-4a20-8211-11cdd2ec28a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86778, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把五和九加起等于十四。", "corrected_sentence": "我们把五和九加起来等于十四。", "error_description": "错误在于补语的遗漏。表示合计的“加起来”需要补语“来”，只说“加起”不完整，应说“加起来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35726a13-f82e-4a20-8211-11cdd2ec28a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86779, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "意料之中", "is_correct": true, "explanation": "正确。“意料之中”与“意外”意思相反，指早在预料之中。"}, {"text": "清晰", "is_correct": false, "explanation": "与“意外”没有反义关系，指清楚明白，与“意外”的任何义项都无关。"}, {"text": "热烈", "is_correct": false, "explanation": "与“意外”没有反义关系，指情绪高涨、气氛热闹。"}, {"text": "明亮", "is_correct": false, "explanation": "与“意外”没有反义关系，指光线充足、颜色鲜亮。"}], "correct_answer": "意料之中", "explanations": {"意料之中": "正确。“意料之中”与“意外”意思相反，指早在预料之中。", "清晰": "与“意外”没有反义关系，指清楚明白，与“意外”的任何义项都无关。", "热烈": "与“意外”没有反义关系，指情绪高涨、气氛热闹。", "明亮": "与“意外”没有反义关系，指光线充足、颜色鲜亮。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af95e219-044f-4d55-9840-f6ea9329cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
