INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86781, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "唯一是只有一个，没有别的。", "primary_collocate": null, "pronunciation": "wéi yī", "ipa": "wei˧˥ i˥", "syllable_count": 2, "sentences": [{"text": "这是我唯一的手机。", "target_word": "唯一", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她是我唯一的朋友。", "target_word": "唯一", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "学好汉语的唯一办法是多说。", "target_word": "唯一", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这是他唯一一次迟到。", "target_word": "唯一", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈是家里唯一会做饭的人。", "target_word": "唯一", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店是小镇上唯一的商店。", "target_word": "唯一", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我唯一担心的是你的身体。", "target_word": "唯一", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把唯一的一张票给了我。", "target_word": "唯一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "星期天是我唯一能休息的一天。", "target_word": "唯一", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条路是去山顶唯一的路。", "target_word": "唯一", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "唯一的", "label": "定语形式"}], "register": "中性", "sense_fingerprint": "数量上只有一个，没有其他选择", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7ebaaf2-ff86-4acd-81d5-d33d40a45ed1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86781, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "唯一", "is_correct": true, "explanation": "唯一（wéi yī）是目标词，意思是只有一个，没有别的。"}, {"text": "卫衣", "is_correct": false, "explanation": "wèi（第四声）与 wéi（第二声）声调不同，卫衣指一种带帽子的上衣，意思不同。"}, {"text": "位移", "is_correct": false, "explanation": "wèi（第四声）与 wéi（第二声）、yí（第二声）与 yī（第一声）声调都不同，位移指位置的变化。"}, {"text": "尾翼", "is_correct": false, "explanation": "wěi（第三声）与 wéi（第二声）、yì（第四声）与 yī（第一声）声调都不同，尾翼指飞机尾部的翼片。"}], "explanations": {"唯一": "唯一（wéi yī）是目标词，意思是只有一个，没有别的。", "卫衣": "wèi（第四声）与 wéi（第二声）声调不同，卫衣指一种带帽子的上衣，意思不同。", "位移": "wèi（第四声）与 wéi（第二声）、yí（第二声）与 yī（第一声）声调都不同，位移指位置的变化。", "尾翼": "wěi（第三声）与 wéi（第二声）、yì（第四声）与 yī（第一声）声调都不同，尾翼指飞机尾部的翼片。"}, "sentence_index": null, "correct_answer": "唯一"}, "level_3": {"options": [{"text": "公共", "is_correct": false, "explanation": "语义：“公共”指属于大家的东西，与“我的”表示的专属关系相矛盾。"}, {"text": "唯一", "is_correct": true, "explanation": "“唯一”表示只有一个，填入后意思是“我只有这一部手机”，符合语境。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人或建筑的外形，不能用来形容手机。"}, {"text": "集体", "is_correct": false, "explanation": "搭配：“集体”修饰大家共有的事物，不能与“我的”搭配。"}], "explanations": {"公共": "语义：“公共”指属于大家的东西，与“我的”表示的专属关系相矛盾。", "唯一": "“唯一”表示只有一个，填入后意思是“我只有这一部手机”，符合语境。", "高大": "体貌：“高大”形容人或建筑的外形，不能用来形容手机。", "集体": "搭配：“集体”修饰大家共有的事物，不能与“我的”搭配。"}, "sentence_index": 0, "correct_answer": "唯一"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这所学校有很多唯一的学生。", "explanation": "唯一表示只有一个，不能和“很多”一起用，句子自相矛盾。"}, {"text": "这几个孩子都是唯一的学生。", "explanation": "唯一表示只有一个，“这几个孩子都是唯一的”自相矛盾。"}, {"text": "这三张照片都是唯一的底片。", "explanation": "唯一表示只有一个，与“这三张”的多数矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b98cb1a-b764-4cf7-8b0f-bea141ae3341') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86781, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "共同", "is_correct": false, "explanation": "搭配：“共同”要求多个主体一起做某事，而句子的主语是“我”一个人，不能搭配。"}, {"text": "唯一", "is_correct": true, "explanation": "“唯一”表示只有这一件事让我担心，与后面“担心的是你的身体”相合，符合语境。"}, {"text": "分别", "is_correct": false, "explanation": "搭配：“分别”强调各自去做，需要多个主体，与单独的“我”不搭配。"}, {"text": "特此", "is_correct": false, "explanation": "语域：“特此”是公文或通知中的书面用语，不适用于口语中的表达。"}], "explanations": {"共同": "搭配：“共同”要求多个主体一起做某事，而句子的主语是“我”一个人，不能搭配。", "唯一": "“唯一”表示只有这一件事让我担心，与后面“担心的是你的身体”相合，符合语境。", "分别": "搭配：“分别”强调各自去做，需要多个主体，与单独的“我”不搭配。", "特此": "语域：“特此”是公文或通知中的书面用语，不适用于口语中的表达。"}, "sentence_index": 6, "correct_answer": "唯一"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "好几位同学是唯一的班长。", "explanation": "唯一表示只有一个，“好几位”同学不能都是唯一的班长。"}, {"text": "班里的同学都是唯一的男生。", "explanation": "唯一表示只有一个，多人“都是唯一的”自相矛盾。"}, {"text": "我们班唯一的同学都到了。", "explanation": "唯一表示只有一个，与表示多数的“都”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b98cb1a-b764-4cf7-8b0f-bea141ae3341') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86781, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是他很唯一的梦想。", "corrected_sentence": "这是他唯一的梦想。", "error_description": "“唯一”表示只有一个，是区别词，前面不能加程度副词“很”；正确说法是“这是他唯一的梦想”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b98cb1a-b764-4cf7-8b0f-bea141ae3341') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86781, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是学校里唯一个图书馆。", "corrected_sentence": "这是学校里唯一的图书馆。", "error_description": "错误形式：唯一个图书馆；正确形式：唯一的图书馆（或唯一一个图书馆）。“唯一”后面接量词时必须有数词“一”，或者直接用“的”修饰名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b98cb1a-b764-4cf7-8b0f-bea141ae3341') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
