INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86783, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "感情是你心里对人或事的喜欢、爱或难过。", "primary_collocate": null, "pronunciation": "gǎn qíng", "ipa": "kan˨˩˦ tɕʰiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他们两个人的感情很好。", "target_word": "感情", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我对这个城市有很深的感情。", "target_word": "感情", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷对老房子有感情，不想搬家。", "target_word": "感情", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们认识十年了，感情越来越深。", "target_word": "感情", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她和同学的感情像家人一样。", "target_word": "感情", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这只狗跟我有感情，我不会卖它。", "target_word": "感情", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们俩的感情出了问题。", "target_word": "感情", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老朋友之间的感情最珍贵。", "target_word": "感情", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我和姐姐从小感情就很好。", "target_word": "感情", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "因为工作，他们的感情慢慢变淡了。", "target_word": "感情", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一段感情", "label": "量词"}, {"form": "一份感情", "label": "量词"}, {"form": "感情用事", "label": "复合"}], "register": "中性", "sense_fingerprint": "感情：人与人、人与地方或事物之间的情分和依恋，如“感情很好”“对……有感情”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '851174ca-2114-4551-bf43-9f2fc3ac5b77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86783, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "感情", "is_correct": true, "explanation": "“感情”指人与人之间的情分，句中说两个人的情分很好，正确。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格说高低、贵贱，不能说两个人的价格很好。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高指身体的高矮，与两个人之间的关系无关，不能说“很好”。"}, {"text": "面积", "is_correct": false, "explanation": "搭配：面积多用于土地、房间等场所，不搭配“两个人”。"}], "explanations": {"感情": "“感情”指人与人之间的情分，句中说两个人的情分很好，正确。", "价格": "语义：价格说高低、贵贱，不能说两个人的价格很好。", "身高": "体貌：身高指身体的高矮，与两个人之间的关系无关，不能说“很好”。", "面积": "搭配：面积多用于土地、房间等场所，不搭配“两个人”。"}, "sentence_index": 0, "correct_answer": "感情"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他做事很快，感情很强，大家都很佩服。", "explanation": "这里应该用〈能力〉。“感情”指情分或情绪，不能用来说做事的本领，说本领要用〈能力〉。"}, {"text": "这幅画的感情很鲜艳，大家都很喜欢。", "explanation": "这里应该用〈颜色〉。“感情”指人对人或事物的情分，不能用来形容颜色鲜艳，应说〈颜色〉。"}, {"text": "今天这间教室的感情很宽敞，大家都很满意。", "explanation": "这里应该用〈空间〉。“感情”不能用来形容空间大小，说房间宽敞要用〈空间〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '711ec6d4-218e-455b-9b09-3ea66234cce2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86783, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "感情", "is_correct": true, "explanation": "“感情”指两人之间的情分，句中说感情出了问题，正确。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“出了问题”不搭配年龄，年龄只说大小，不说出问题。"}, {"text": "性别", "is_correct": false, "explanation": "语义：性别是人的固定属性，不会“出了问题”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不属于人，不能说“他们俩的天气出了问题”。"}], "explanations": {"感情": "“感情”指两人之间的情分，句中说感情出了问题，正确。", "年龄": "搭配：“出了问题”不搭配年龄，年龄只说大小，不说出问题。", "性别": "语义：性别是人的固定属性，不会“出了问题”。", "天气": "语义：天气是自然现象，不属于人，不能说“他们俩的天气出了问题”。"}, "sentence_index": 6, "correct_answer": "感情"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服的感情很贵，我们别买了。", "explanation": "这里应该用〈价格〉。“感情”指情分，不能用来说价钱高低，应说〈价格〉。"}, {"text": "这个包的感情很轻，一只手就能提起来。", "explanation": "这里应该用〈重量〉。“感情”不能用来说轻重，说物体的轻重要用〈重量〉。"}, {"text": "这个孩子的感情很胖，妈妈很担心。", "explanation": "这里应该用〈身材〉。“感情”不能用来形容胖瘦，说人的胖瘦要用〈身材〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '711ec6d4-218e-455b-9b09-3ea66234cce2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86783, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我这座小镇有很深的感情。", "corrected_sentence": "我对这座小镇有很深的感情。", "error_description": "错误：“对……有感情”结构中漏掉了介词“对”。正确：“我对这座小镇有很深的感情。”原因：表示对某人或某地的情分时，要用“对……有感情”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '711ec6d4-218e-455b-9b09-3ea66234cce2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86783, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们俩之间有一颗深厚的感情。", "corrected_sentence": "他们俩之间有一份深厚的感情。", "error_description": "量词错误：“感情”应用“份”，“颗”用于小而圆的东西，不用于感情。正确：“一份深厚的感情”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '711ec6d4-218e-455b-9b09-3ea66234cce2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86784, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "理智", "is_correct": true, "explanation": "“理智”与“感情”所指的内心情绪反应相对，指凭道理作出的判断。"}, {"text": "桌子", "is_correct": false, "explanation": "“桌子”指家具，与“感情”的任何义项都没有反义关系。"}, {"text": "河流", "is_correct": false, "explanation": "“河流”指水道，与“感情”的任何义项都没有反义关系。"}, {"text": "书本", "is_correct": false, "explanation": "“书本”指印刷的书册，与“感情”的任何义项都没有反义关系。"}], "correct_answer": "理智", "explanations": {"理智": "“理智”与“感情”所指的内心情绪反应相对，指凭道理作出的判断。", "桌子": "“桌子”指家具，与“感情”的任何义项都没有反义关系。", "河流": "“河流”指水道，与“感情”的任何义项都没有反义关系。", "书本": "“书本”指印刷的书册，与“感情”的任何义项都没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '711ec6d4-218e-455b-9b09-3ea66234cce2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86784, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "理智", "is_correct": true, "explanation": "“理智”与“感情”所指的情绪反应相对，指凭理性作出的判断。"}, {"text": "石头", "is_correct": false, "explanation": "“石头”指岩石的小块，与“感情”的任何义项都没有反义关系。"}, {"text": "窗户", "is_correct": false, "explanation": "“窗户”指房屋上通光透气的开口，与“感情”的任何义项都没有反义关系。"}, {"text": "树叶", "is_correct": false, "explanation": "“树叶”指植物的叶子，与“感情”的任何义项都没有反义关系。"}], "correct_answer": "理智", "explanations": {"理智": "“理智”与“感情”所指的情绪反应相对，指凭理性作出的判断。", "石头": "“石头”指岩石的小块，与“感情”的任何义项都没有反义关系。", "窗户": "“窗户”指房屋上通光透气的开口，与“感情”的任何义项都没有反义关系。", "树叶": "“树叶”指植物的叶子，与“感情”的任何义项都没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '711ec6d4-218e-455b-9b09-3ea66234cce2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86784, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "对人或事物产生的喜爱、关切等心理反应。", "primary_collocate": null, "pronunciation": "gǎn qíng", "ipa": "kan˨˩˦ tɕʰiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "她唱歌的时候带着很深的感情。", "target_word": "感情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不会表达自己的感情。", "target_word": "感情", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这首歌里有很多感情。", "target_word": "感情", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小孩子的感情很容易看出来。", "target_word": "感情", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他控制不住自己的感情，哭了。", "target_word": "感情", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她写信时把感情都写进去了。", "target_word": "感情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个演员的感情很丰富。", "target_word": "感情", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他说话的时候，一点感情也没有。", "target_word": "感情", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看了那部电影，我的感情很复杂。", "target_word": "感情", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师读课文时很有感情。", "target_word": "感情", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "一份感情", "label": "量词"}, {"form": "感情用事", "label": "复合"}], "register": "中性", "sense_fingerprint": "感情：内心产生并表现出来的情绪反应，如“表达感情”“带着感情”“感情丰富”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '851174ca-2114-4551-bf43-9f2fc3ac5b77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86784, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "感情", "is_correct": true, "explanation": "“感情”指唱歌时表现出的情绪，句中“带着很深的感情”正确。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄是人的岁数，不能说唱歌时“带着很深的年龄”。"}, {"text": "力气", "is_correct": false, "explanation": "搭配：“深”不修饰力气，不能说“很深的力气”。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高指身材的高矮，不能用来说唱歌时“带着很深的身高”。"}], "explanations": {"感情": "“感情”指唱歌时表现出的情绪，句中“带着很深的感情”正确。", "年龄": "语义：年龄是人的岁数，不能说唱歌时“带着很深的年龄”。", "力气": "搭配：“深”不修饰力气，不能说“很深的力气”。", "身高": "体貌：身高指身材的高矮，不能用来说唱歌时“带着很深的身高”。"}, "sentence_index": 0, "correct_answer": "感情"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我今年的感情增加了三公斤。", "explanation": "这里应该用〈体重〉。“感情”指情绪或情分，不能用公斤计量，说身体的重量要用〈体重〉。"}, {"text": "这件衣服的感情很鲜艳，很适合夏天穿。", "explanation": "这里应该用〈颜色〉。“感情”指情绪或情分，不能用来形容颜色鲜艳，应说〈颜色〉。"}, {"text": "他的感情很胖，衣服都穿不下了。", "explanation": "这里应该用〈身材〉。“感情”不能用来形容胖瘦，说人的胖瘦要用〈身材〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '711ec6d4-218e-455b-9b09-3ea66234cce2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86784, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "感情", "is_correct": true, "explanation": "“感情”指演员表演时表现出的情绪，说“很丰富”正确。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“丰富”不搭配体重，不能说“体重很丰富”。"}, {"text": "脚步", "is_correct": false, "explanation": "语义：脚步指走路的动作，不能用“很丰富”来形容。"}, {"text": "鞋子", "is_correct": false, "explanation": "语义：鞋子是物品，不能用“很丰富”来形容。"}], "explanations": {"感情": "“感情”指演员表演时表现出的情绪，说“很丰富”正确。", "体重": "搭配：“丰富”不搭配体重，不能说“体重很丰富”。", "脚步": "语义：脚步指走路的动作，不能用“很丰富”来形容。", "鞋子": "语义：鞋子是物品，不能用“很丰富”来形容。"}, "sentence_index": 6, "correct_answer": "感情"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他读课文时感情很快，大家都能听清。", "explanation": "这里应该用〈速度〉。“感情”是情绪，不说快慢；读得快慢要用〈速度〉。"}, {"text": "他这次考试的感情是九十分，老师很高兴。", "explanation": "这里应该用〈成绩〉。“感情”指情绪，不能用分数来计算，考试得多少分要用〈成绩〉。"}, {"text": "他读课文的感情很响亮，同学们都能听见。", "explanation": "这里应该用〈声音〉。“感情”不能用来形容响亮，应说〈声音〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '711ec6d4-218e-455b-9b09-3ea66234cce2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86784, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她读信的时候感情的很丰富。", "corrected_sentence": "她读信的时候感情很丰富。", "error_description": "错误：“感情”后多出了“的”，“的很”不成立。正确：“感情很丰富”，形容词作谓语时不加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '711ec6d4-218e-455b-9b09-3ea66234cce2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86784, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老奶奶讲故事时感情的丰富。", "corrected_sentence": "老奶奶讲故事时感情很丰富。", "error_description": "错误：形容词“丰富”作谓语前应用“很”，误用“的”后，“感情的丰富”只是名词短语，句子没有谓语。正确：写作“老奶奶讲故事时感情很丰富。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '711ec6d4-218e-455b-9b09-3ea66234cce2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
