INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86785, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cf7ce71-ddfc-406e-88fa-d631d3cd9ba7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86785, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "最多是不会再多了，到头了。", "primary_collocate": null, "pronunciation": "zuì duō", "ipa": "tsweɪ˥˩ two˥", "syllable_count": 2, "sentences": [{"text": "这个电梯最多坐八个人。", "target_word": "最多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我今天最多只能吃两个包子。", "target_word": "最多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一个月最多花一千块钱。", "target_word": "最多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家小店最多有十张桌子。", "target_word": "最多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路不远，走过去最多十分钟。", "target_word": "最多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书不难，最多一天就能看完。", "target_word": "最多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我最多睡到九点。", "target_word": "最多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室很小，最多有二十个学生。", "target_word": "最多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去那儿坐车最多半个小时。", "target_word": "最多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我手里的钱最多够买两本书。", "target_word": "最多", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "数量到头、不会再多（副词，zuì duō）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7673fbc5-6e78-4bef-848b-ae27656be33f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86785, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "最多", "is_correct": true, "explanation": "最多：表示数量上限，八人正是这部电梯的上限。"}, {"text": "已经", "is_correct": false, "explanation": "语义：“已经”表示动作已完成，而句子说的是电梯能坐多少人的上限，不是已经发生的事。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示有时候，与电梯固定的容量不合。"}, {"text": "业已", "is_correct": false, "explanation": "语域：“业已”是书面用语，在说电梯容量的口语语境里不合语域。"}], "explanations": {"最多": "最多：表示数量上限，八人正是这部电梯的上限。", "已经": "语义：“已经”表示动作已完成，而句子说的是电梯能坐多少人的上限，不是已经发生的事。", "偶尔": "语义：“偶尔”表示有时候，与电梯固定的容量不合。", "业已": "语域：“业已”是书面用语，在说电梯容量的口语语境里不合语域。"}, "sentence_index": 0, "correct_answer": "最多"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服最多漂亮。", "explanation": "这里应该用〈最〉。“最多”表示数量上限，不能修饰形容词表示程度最高；应说“这件衣服最漂亮”。"}, {"text": "这些学生最多是北方人。", "explanation": "这里应该用〈大多〉。“最多”表示数量不超过某个上限，不能表示“大部分”；说大部分是北方人要用“大多”。"}, {"text": "这场争论最多结束了。", "explanation": "这里应该用〈最终〉。“最多”表示数量上限，不表示结局或先后；说事情最后结束要用“最终”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cf7ce71-ddfc-406e-88fa-d631d3cd9ba7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86785, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "最多", "is_correct": true, "explanation": "最多：表示睡觉到九点为止，不会更晚。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”说的是马上发生，“睡到九点”是持续到某个时间，两者意思冲突。"}, {"text": "赶紧", "is_correct": false, "explanation": "语义：“赶紧”表示催促快做，周末睡觉没有这种急迫的语境。"}, {"text": "根本", "is_correct": false, "explanation": "搭配：“根本”多用于否定句，不能直接修饰“睡到九点”。"}], "explanations": {"最多": "最多：表示睡觉到九点为止，不会更晚。", "立刻": "语义：“立刻”说的是马上发生，“睡到九点”是持续到某个时间，两者意思冲突。", "赶紧": "语义：“赶紧”表示催促快做，周末睡觉没有这种急迫的语境。", "根本": "搭配：“根本”多用于否定句，不能直接修饰“睡到九点”。"}, "sentence_index": 6, "correct_answer": "最多"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我最多非常喜欢吃苹果。", "explanation": "这里应该用〈最喜欢〉。“最多”表示数量上限，不表示喜爱的程度。"}, {"text": "他最多非常怕黑。", "explanation": "这里应该用〈最怕〉。“最多”只表示数量不超过，不用于表达害怕的程度。"}, {"text": "我最多非常想吃火锅。", "explanation": "这里应该用〈最想〉。“最多”不表示愿望的强烈程度，只表示数量上限。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cf7ce71-ddfc-406e-88fa-d631d3cd9ba7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86785, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这辆车很最多坐五个人。", "corrected_sentence": "这辆车最多坐五个人。", "error_description": "错误：“很”放在了“最多”前面。正确：“这辆车最多坐五个人”。“最多”是副词，前面不能再加“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cf7ce71-ddfc-406e-88fa-d631d3cd9ba7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86785, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们最多了睡到九点。", "corrected_sentence": "我们最多睡到九点。", "error_description": "错误：“了”放在了“最多”后面。正确：“我们最多睡到九点”。“最多”是副词，后面直接接动词，不能加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cf7ce71-ddfc-406e-88fa-d631d3cd9ba7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
