INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86786, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，至多；数量上不超过。", "primary_collocate": null, "pronunciation": "zuì duō", "ipa": "tsweɪ˥˩ two˥", "syllable_count": 2, "sentences": [{"text": "他今年最多三十岁。", "target_word": "最多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参加会议的人最多一百个。", "target_word": "最多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条鱼最多两斤重。", "target_word": "最多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买这件衣服最多花两百块。", "target_word": "最多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明学汉语最多一年，说得真好。", "target_word": "最多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最多再等你十分钟，然后就走。", "target_word": "最多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试，他最多错了两个题。", "target_word": "最多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一杯咖啡最多卖二十块钱。", "target_word": "最多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间最多住三个人，再多就挤了。", "target_word": "最多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看上去最多二十岁。", "target_word": "最多", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "至多，数量上不超过（副词，zuì duō）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7673fbc5-6e78-4bef-848b-ae27656be33f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86786, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "最多", "is_correct": true, "explanation": "最多：表示年龄不超过三十岁，正符合句意。"}, {"text": "尽量", "is_correct": false, "explanation": "语义：“尽量”表示尽力做到，年龄不能“尽量”去达到三十岁。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示有时候，年龄不会时而是三十岁、时而不是。"}, {"text": "业已", "is_correct": false, "explanation": "语域：“业已”是书面用语，口语里谈论年龄时不这么用。"}], "explanations": {"最多": "最多：表示年龄不超过三十岁，正符合句意。", "尽量": "语义：“尽量”表示尽力做到，年龄不能“尽量”去达到三十岁。", "偶尔": "语义：“偶尔”表示有时候，年龄不会时而是三十岁、时而不是。", "业已": "语域：“业已”是书面用语，口语里谈论年龄时不这么用。"}, "sentence_index": 0, "correct_answer": "最多"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明天下雨，你最多带伞。", "explanation": "这里应该用〈最好〉。“最多”表示数量上限，不用于提建议。"}, {"text": "这些同学最多是北方人。", "explanation": "这里应该用〈大多〉。“最多”表示数量不超过某个上限，不能表示“大部分”；说大部分是北方人要用“大多”。"}, {"text": "比赛中，他最多冲过终点。", "explanation": "这里应该用〈最先〉。“最多”表示数量上限，不表示先后；“最先冲过终点”才对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cf7ce71-ddfc-406e-88fa-d631d3cd9ba7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86786, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "最多", "is_correct": true, "explanation": "最多：表示错误的题目数量不超过两个，符合句意。"}, {"text": "赶紧", "is_correct": false, "explanation": "语义：“赶紧”表示催促快做，与“错了两个题”这种结果不合。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”说的是马上发生，做题出错不是这样发生的。"}, {"text": "根本", "is_correct": false, "explanation": "搭配：“根本”多用于否定句，不能直接修饰“错了两个题”。"}], "explanations": {"最多": "最多：表示错误的题目数量不超过两个，符合句意。", "赶紧": "语义：“赶紧”表示催促快做，与“错了两个题”这种结果不合。", "立刻": "语义：“立刻”说的是马上发生，做题出错不是这样发生的。", "根本": "搭配：“根本”多用于否定句，不能直接修饰“错了两个题”。"}, "sentence_index": 6, "correct_answer": "最多"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我最多非常讨厌早起。", "explanation": "这里应该用〈最讨厌〉。“最多”表示数量上限，不表示厌恶的程度。"}, {"text": "这道菜最多非常难吃。", "explanation": "这里应该用〈最难吃〉。“最多”表示数量上限，不表示程度最高。"}, {"text": "她的笑容最多温暖。", "explanation": "这里应该用〈最温暖〉。“最多”只表示数量不超过，不能形容笑容的程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cf7ce71-ddfc-406e-88fa-d631d3cd9ba7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86786, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台机器最多的能用五年。", "corrected_sentence": "这台机器最多能用五年。", "error_description": "错误：“最多”后面多加了“的”。正确：“这台机器最多能用五年”。“最多”是副词，后面直接接动词“能”，不能加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cf7ce71-ddfc-406e-88fa-d631d3cd9ba7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86786, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个孩子看上去很最多十岁。", "corrected_sentence": "这个孩子看上去最多十岁。", "error_description": "错误：“很”放在了“最多”前面。正确：“这个孩子看上去最多十岁”。“最多”是副词，前面不能再加“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cf7ce71-ddfc-406e-88fa-d631d3cd9ba7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
