INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86788, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示程度很高；十分。", "primary_collocate": null, "pronunciation": "hěn shì", "ipa": "xən˨˩ ʂʅ˥˩", "syllable_count": 2, "sentences": [{"text": "听到这个好消息，大家都很是高兴。", "target_word": "很是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一个人在国外，妈妈很是担心。", "target_word": "很是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到孩子考得这么好，老师很是满意。", "target_word": "很是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事让我很是生气。", "target_word": "很是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的会议很是重要，请你准时来。", "target_word": "很是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的风景很是美丽，我拍了很多照片。", "target_word": "很是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对这个结果很是失望。", "target_word": "很是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈做的菜很是好吃，我吃了三碗饭。", "target_word": "很是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友突然来看我，我很是惊讶。", "target_word": "很是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人对年轻人的帮助很是感激。", "target_word": "很是", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "程度副词：很是+形容词/心理动词，表示程度很高", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43952535-ce3b-42ad-81d2-56414676474b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86788, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "很是", "is_correct": true, "explanation": "“很是”表示程度很高，修饰心理动词“高兴”，句意通顺。"}, {"text": "不", "is_correct": false, "explanation": "语义：“不”否定了“高兴”，与“听到这个好消息”的情境相矛盾。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：“曾经”表示过去的经历，与“听到”这一当下情境不符。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”多与否定词连用，不说“从来高兴”。"}], "explanations": {"很是": "“很是”表示程度很高，修饰心理动词“高兴”，句意通顺。", "不": "语义：“不”否定了“高兴”，与“听到这个好消息”的情境相矛盾。", "曾经": "语义：“曾经”表示过去的经历，与“听到”这一当下情境不符。", "从来": "搭配：“从来”多与否定词连用，不说“从来高兴”。"}, "sentence_index": 0, "correct_answer": "很是"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张纸很是方形。", "explanation": "这里应该去掉“很是”。“很是”表示程度，只修饰有程度差别的形容词或心理动词；“方形”是形状类别，不能用程度副词修饰。"}, {"text": "这个数字很是偶数。", "explanation": "这里应该去掉“很是”。“偶数”是非程度概念，不能用“很是”表示程度高低。"}, {"text": "我们班很是四十个人。", "explanation": "这里应该去掉“很是”。“很是”表示程度，不能修饰“四十个人”这类数量短语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf5179b-e9a5-4c97-a8f9-af8ae5b88161') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86788, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "很是", "is_correct": true, "explanation": "“很是”表示程度很高，修饰心理状态“失望”，句意通顺。"}, {"text": "根本", "is_correct": false, "explanation": "搭配：“根本”多与否定词连用，不说“根本失望”。"}, {"text": "再三", "is_correct": false, "explanation": "搭配：“再三”修饰反复进行的动作，不修饰心理状态“失望”。"}, {"text": "赶紧", "is_correct": false, "explanation": "搭配：“赶紧”表示急着去做某事，不能修饰“失望”这种心理状态。"}], "explanations": {"很是": "“很是”表示程度很高，修饰心理状态“失望”，句意通顺。", "根本": "搭配：“根本”多与否定词连用，不说“根本失望”。", "再三": "搭配：“再三”修饰反复进行的动作，不修饰心理状态“失望”。", "赶紧": "搭配：“赶紧”表示急着去做某事，不能修饰“失望”这种心理状态。"}, "sentence_index": 6, "correct_answer": "很是"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条路很是双车道。", "explanation": "这里应该去掉“很是”。“很是”表示程度，不能修饰“双车道”这类类别名称。"}, {"text": "这台电脑很是一台。", "explanation": "这里应该去掉“很是”。“很是”表示程度，不能修饰“一台”这类数量短语。"}, {"text": "这张照片很是黑白的。", "explanation": "这里应该去掉“很是”。“黑白”是类别属性，不能用程度副词“很是”修饰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf5179b-e9a5-4c97-a8f9-af8ae5b88161') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86788, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大家都很是很高兴。", "corrected_sentence": "大家都很是高兴。", "error_description": "重复修饰：“很是”已表示程度，后面不能再加“很”。“大家都很是很高兴”应改为“大家都很是高兴”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf5179b-e9a5-4c97-a8f9-af8ae5b88161') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86788, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈对我的成绩很是很满意。", "corrected_sentence": "妈妈对我的成绩很是满意。", "error_description": "重复修饰：“很是”已表示程度，后面不能再加“很”。“很是很满意”应改为“很是满意”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf5179b-e9a5-4c97-a8f9-af8ae5b88161') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
