INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86789, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "会员是加入了一个团体的人。", "primary_collocate": null, "pronunciation": "huì yuán", "ipa": "xweɪ˥˩ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "我上个月加入了登山社，成了新会员。", "target_word": "会员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个网球俱乐部的会员很多。", "target_word": "会员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会员可以用便宜的价钱买票。", "target_word": "会员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王先生是这家商店的老会员。", "target_word": "会员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想看书的会员请到二楼。", "target_word": "会员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司给每位会员寄了一份礼物。", "target_word": "会员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是音乐协会里最年轻的会员。", "target_word": "会员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请会员们明天早上九点到门口集合。", "target_word": "会员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个会员都有自己的号码。", "target_word": "会员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小区的游泳池只给会员用。", "target_word": "会员", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "会员卡", "label": "复合"}, {"form": "會員", "label": "繁体"}], "register": "中性", "sense_fingerprint": "加入某个团体的人，享有该团体的权利", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43952535-ce3b-42ad-81d2-56414676474b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86789, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "会员", "is_correct": true, "explanation": "“会员”指加入团体的人，“加入了登山社，成了新……”的结果就是成为会员，是正确答案。"}, {"text": "球员", "is_correct": false, "explanation": "语义：“球员”指参加球类比赛的人，与加入登山社的身份不符。"}, {"text": "乘客", "is_correct": false, "explanation": "语义：“乘客”指乘坐交通工具的人，与加入登山社无关。"}, {"text": "学生", "is_correct": false, "explanation": "搭配：“成了新……”指加入社团后的身份，社团成员一般不称“学生”。"}], "explanations": {"会员": "“会员”指加入团体的人，“加入了登山社，成了新……”的结果就是成为会员，是正确答案。", "球员": "语义：“球员”指参加球类比赛的人，与加入登山社的身份不符。", "乘客": "语义：“乘客”指乘坐交通工具的人，与加入登山社无关。", "学生": "搭配：“成了新……”指加入社团后的身份，社团成员一般不称“学生”。"}, "sentence_index": 0, "correct_answer": "会员"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这所学校有两百名会员。", "explanation": "这里应该用〈教师〉。学校的教职人员称教师，不称会员；会员指加入团体的人。"}, {"text": "这辆公交车有四十名会员。", "explanation": "这里应该用〈乘客〉。乘坐公交车的人称乘客，会员不用于此。"}, {"text": "这家医院的病房里住着两百名会员，他们昨天都刚做完手术。", "explanation": "这里应该用〈病人〉。接受治疗的人称病人，会员指加入团体的人，不用于就医者。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf5179b-e9a5-4c97-a8f9-af8ae5b88161') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86789, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "会员", "is_correct": true, "explanation": "“会员”指音乐协会的成员，“她是音乐协会里最年轻的……”中填入会员语义通顺，是正确答案。"}, {"text": "病人", "is_correct": false, "explanation": "语义：“病人”指患病就医的人，与音乐协会的身份不合。"}, {"text": "司机", "is_correct": false, "explanation": "语义：“司机”指驾驶车辆的人，与音乐协会无关。"}, {"text": "客户", "is_correct": false, "explanation": "搭配：协会里说的是成员身份，“客户”多指与买卖有关的人，不用于协会成员。"}], "explanations": {"会员": "“会员”指音乐协会的成员，“她是音乐协会里最年轻的……”中填入会员语义通顺，是正确答案。", "病人": "语义：“病人”指患病就医的人，与音乐协会的身份不合。", "司机": "语义：“司机”指驾驶车辆的人，与音乐协会无关。", "客户": "搭配：协会里说的是成员身份，“客户”多指与买卖有关的人，不用于协会成员。"}, "sentence_index": 6, "correct_answer": "会员"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部电影有五百名会员。", "explanation": "这里应该用〈观众〉。看电影的人称观众，会员指加入团体的人。"}, {"text": "这次足球赛有十六名会员。", "explanation": "这里应该用〈选手〉。参加比赛的人称选手，会员不用于此。"}, {"text": "这个夏令营有六十名会员。", "explanation": "这里应该用〈学员〉。参加夏令营等培训活动的人称学员，不称会员。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf5179b-e9a5-4c97-a8f9-af8ae5b88161') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86789, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家游泳馆有三百只会员。", "corrected_sentence": "这家游泳馆有三百名会员。", "error_description": "量词错误：指人的“会员”应用“名”或“位”，“只”用于动物或小件物品。正确说法是“三百名会员”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf5179b-e9a5-4c97-a8f9-af8ae5b88161') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86789, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我是只老会员，每周都来。", "corrected_sentence": "我是个老会员，每周都来。", "error_description": "量词错误：指人的“会员”应用“个”或“名”，“只”用于动物或小件物品。正确说法是“我是个老会员”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf5179b-e9a5-4c97-a8f9-af8ae5b88161') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
