INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86790, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf5179b-e9a5-4c97-a8f9-af8ae5b88161') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86790, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "参加某个组织或团体的人。", "primary_collocate": null, "pronunciation": "huì yuán", "ipa": "xweɪ˥˩ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "他是我们读书俱乐部的会员。", "target_word": "会员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "成为会员后，你可以免费借书。", "target_word": "会员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家健身房一共有五百名会员。", "target_word": "会员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老会员带新会员参加了活动。", "target_word": "会员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想申请成为摄影协会的会员。", "target_word": "会员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每位会员每年要交一百块钱。", "target_word": "会员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只有会员才能进入这个图书馆。", "target_word": "会员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个协会的会员来自很多国家。", "target_word": "会员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他当了十年会员，从来没有缺席过。", "target_word": "会员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新会员今晚七点要参加见面会。", "target_word": "会员", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "会员卡", "label": "复合"}, {"form": "會員", "label": "繁体"}], "register": "中性", "sense_fingerprint": "组织、团体或俱乐部的成员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43952535-ce3b-42ad-81d2-56414676474b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86790, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "会员", "is_correct": true, "explanation": "“会员”指加入俱乐部等团体的人，填入“读书俱乐部的”后语义通顺，是正确答案。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“他是……的”后接的应是指人的身份，“桌子”是物，不能指读书俱乐部里的一员。"}, {"text": "图书", "is_correct": false, "explanation": "搭配：“是……的”要接身份名词，“图书”不能充当人的身份，句子不成立。"}, {"text": "学费", "is_correct": false, "explanation": "语义：“学费”是要交的钱，不指人，与“他是俱乐部的……”语义不合。"}], "explanations": {"会员": "“会员”指加入俱乐部等团体的人，填入“读书俱乐部的”后语义通顺，是正确答案。", "桌子": "语义：“他是……的”后接的应是指人的身份，“桌子”是物，不能指读书俱乐部里的一员。", "图书": "搭配：“是……的”要接身份名词，“图书”不能充当人的身份，句子不成立。", "学费": "语义：“学费”是要交的钱，不指人，与“他是俱乐部的……”语义不合。"}, "sentence_index": 0, "correct_answer": "会员"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班有三十名会员。", "explanation": "这里应该用〈学生〉。班里的人称学生，不称会员；会员指加入团体、需要入会的人。"}, {"text": "这个培训班有二十名会员。", "explanation": "这里应该用〈学员〉。参加培训班的人称学员，不称会员。"}, {"text": "他是这家公司的会员，每天准时上班。", "explanation": "这里应该用〈员工〉。在公司上班、领工资的人称员工，会员指加入团体的人，不用于此。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf5179b-e9a5-4c97-a8f9-af8ae5b88161') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86790, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "会员", "is_correct": true, "explanation": "“会员”指入会的人，“只有……才能进入”的主语是会员，语义通顺，是正确答案。"}, {"text": "动物", "is_correct": false, "explanation": "语义：图书馆只允许人入内，“只有动物才能进入这个图书馆”与常识相悖。"}, {"text": "空气", "is_correct": false, "explanation": "配价：“进入”的施事须是人或动物等能自主行动的主体，“空气”不符合。"}, {"text": "雨水", "is_correct": false, "explanation": "配价：“进入”的施事须是能自主行动的主体，“雨水”不能作“只有……才能进入”的主语。"}], "explanations": {"会员": "“会员”指入会的人，“只有……才能进入”的主语是会员，语义通顺，是正确答案。", "动物": "语义：图书馆只允许人入内，“只有动物才能进入这个图书馆”与常识相悖。", "空气": "配价：“进入”的施事须是人或动物等能自主行动的主体，“空气”不符合。", "雨水": "配价：“进入”的施事须是能自主行动的主体，“雨水”不能作“只有……才能进入”的主语。"}, "sentence_index": 6, "correct_answer": "会员"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这趟列车有一百名会员。", "explanation": "这里应该用〈乘客〉。列车上的旅客称乘客，会员指加入团体的人。"}, {"text": "这场演出的舞台上站着十几名会员，表演得很精彩。", "explanation": "这里应该用〈演员〉。在舞台上表演的人称演员，会员指加入团体的人，不用于此。"}, {"text": "这次比赛有二十名会员。", "explanation": "这里应该用〈选手〉。参加比赛的人称选手，会员指加入团体的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf5179b-e9a5-4c97-a8f9-af8ae5b88161') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86790, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家书店有两百只会员。", "corrected_sentence": "这家书店有两百名会员。", "error_description": "量词错误：指人的“会员”应用“名”或“位”，“只”用于动物或小件物品。正确说法是“两百名会员”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf5179b-e9a5-4c97-a8f9-af8ae5b88161') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86790, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "赵阿姨是只老会员，每周都来。", "corrected_sentence": "赵阿姨是个老会员，每周都来。", "error_description": "量词错误：指人的“会员”应用“个”或“名”，“只”用于动物或小件物品。正确说法是“赵阿姨是个老会员”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf5179b-e9a5-4c97-a8f9-af8ae5b88161') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86791, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af95e219-044f-4d55-9840-f6ea9329cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86791, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af95e219-044f-4d55-9840-f6ea9329cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86791, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "没什么是说不要紧、不算什么，不必在意。", "primary_collocate": null, "pronunciation": "méi shén me", "ipa": "mei̯˧˥ ʂən˧˥ mə", "syllable_count": 3, "sentences": [{"text": "没什么，你不用担心。", "target_word": "没什么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你说对不起，我说没什么。", "target_word": "没什么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这点小伤没什么，过几天就好了。", "target_word": "没什么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "摔了一下没什么，别哭了。", "target_word": "没什么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "迟到五分钟没什么，下次早点来。", "target_word": "没什么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你问我怎么了？没什么，只是有点累。", "target_word": "没什么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这点困难没什么，我们能解决。", "target_word": "没什么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说没什么，可是脸色很不好。", "target_word": "没什么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别担心，这点事没什么。", "target_word": "没什么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个错误没什么，下次注意就行。", "target_word": "没什么", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "没什么：不要紧，不算什么，不必在意", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88131405-7030-4d15-aa9d-0a48d00bcf95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86791, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "没什么", "is_correct": true, "explanation": "正确。“没什么”表示不要紧，用于安慰对方。"}, {"text": "什么", "is_correct": false, "explanation": "语义：“什么”是疑问代词，不能表示“不要紧”的安慰。"}, {"text": "多少", "is_correct": false, "explanation": "搭配：“多少”是数量疑问，不能单独作句首语表示“不要紧”。"}, {"text": "怎么", "is_correct": false, "explanation": "语义：“怎么”表示询问方式，不表示安慰。"}], "explanations": {"没什么": "正确。“没什么”表示不要紧，用于安慰对方。", "什么": "语义：“什么”是疑问代词，不能表示“不要紧”的安慰。", "多少": "搭配：“多少”是数量疑问，不能单独作句首语表示“不要紧”。", "怎么": "语义：“怎么”表示询问方式，不表示安慰。"}, "sentence_index": 0, "correct_answer": "没什么"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次事故造成了三人死亡，没什么，大家不用太在意。", "explanation": "这里的“没什么”表示〈不要紧〉，与“造成三人死亡”的严重后果矛盾，不能用来轻描淡写。"}, {"text": "这笔钱全都被偷了，没什么，你不用去报警。", "explanation": "这里的“没什么”表示〈不要紧〉，但“全都被偷了”十分严重，二者矛盾。"}, {"text": "我们班没什么同学，所以很热闹。", "explanation": "这里的“没什么”表示“没有多少”，与“很热闹”矛盾，不是“不要紧”的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af95e219-044f-4d55-9840-f6ea9329cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86791, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "没什么", "is_correct": true, "explanation": "正确。“没什么”作谓语，表示困难不大。"}, {"text": "巨大", "is_correct": false, "explanation": "语义：“这点”限定困难很小，“巨大”与之矛盾。"}, {"text": "严重", "is_correct": false, "explanation": "语义：“严重”表示程度高，与“这点”矛盾。"}, {"text": "沉重", "is_correct": false, "explanation": "语义：“这点”限定困难很小，“沉重”与之矛盾。"}], "explanations": {"没什么": "正确。“没什么”作谓语，表示困难不大。", "巨大": "语义：“这点”限定困难很小，“巨大”与之矛盾。", "严重": "语义：“严重”表示程度高，与“这点”矛盾。", "沉重": "语义：“这点”限定困难很小，“沉重”与之矛盾。"}, "sentence_index": 6, "correct_answer": "没什么"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个城市没什么人，街上却非常热闹。", "explanation": "这里的“没什么”表示“没有多少”，与“非常热闹”矛盾，不是“不要紧”的意思。"}, {"text": "孩子的病情越来越重了，你却说没什么，不用去看医生。", "explanation": "这里的“没什么”表示〈不要紧〉，但“病情越来越重”十分严重，二者矛盾。"}, {"text": "书架上没什么书，因为我每天都买很多新书。", "explanation": "这里的“没什么”表示“没有多少”，与“每天都买很多新书”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af95e219-044f-4d55-9840-f6ea9329cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86791, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这点雨不没什么，我们继续走吧。", "corrected_sentence": "这点雨没什么，我们继续走吧。", "error_description": "错误：“没什么”本身已表示否定，前面不能再加“不”，形成双重否定。正确：“这点雨没什么”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af95e219-044f-4d55-9840-f6ea9329cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86791, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次失误很没什么，我们下次注意。", "corrected_sentence": "这次失误没什么，我们下次注意。", "error_description": "错误：“没什么”前面不能加程度副词“很”。正确：“这次失误没什么”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af95e219-044f-4d55-9840-f6ea9329cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
