INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86792, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "表示没有特别的事物，没有多少值得说的东西。", "primary_collocate": null, "pronunciation": "méi shén me", "ipa": "mei̯˧˥ ʂən˧˥ mə", "syllable_count": 3, "sentences": [{"text": "冰箱里没什么吃的了。", "target_word": "没什么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我今天没什么事，可以陪你。", "target_word": "没什么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店里没什么好看的东西。", "target_word": "没什么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没什么朋友，常常一个人。", "target_word": "没什么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我没什么计划。", "target_word": "没什么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上没什么东西，很干净。", "target_word": "没什么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影没什么意思。", "target_word": "没什么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对音乐没什么兴趣。", "target_word": "没什么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说话时没什么表情。", "target_word": "没什么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市没什么特别的地方。", "target_word": "没什么", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "没什么：没有特别的事物，没有多少值得说的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88131405-7030-4d15-aa9d-0a48d00bcf95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86792, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "没什么", "is_correct": true, "explanation": "正确。“没什么”表示没有多少可吃的。"}, {"text": "很多", "is_correct": false, "explanation": "语义：“很多”表示数量大，与“没什么”意思相反。"}, {"text": "全是", "is_correct": false, "explanation": "语法：“全是……了”说法不自然，且“全是”表示满满的，与“没什么”意思相反。"}, {"text": "不太", "is_correct": false, "explanation": "语法：“不太”修饰形容词或动词，不能直接修饰“吃的”。"}], "explanations": {"没什么": "正确。“没什么”表示没有多少可吃的。", "很多": "语义：“很多”表示数量大，与“没什么”意思相反。", "全是": "语法：“全是……了”说法不自然，且“全是”表示满满的，与“没什么”意思相反。", "不太": "语法：“不太”修饰形容词或动词，不能直接修饰“吃的”。"}, "sentence_index": 0, "correct_answer": "没什么"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次跌倒很严重，没什么，马上去医院吧。", "explanation": "这里的“没什么”表示〈不要紧〉，与“很严重”“马上去医院”矛盾。"}, {"text": "他身边总围着很多朋友，所以他没什么朋友。", "explanation": "这里的“没什么”表示〈很少〉，但“身边总围着很多朋友”与之矛盾，因果关系也说不通。"}, {"text": "桌子上没什么东西，却堆满了书。", "explanation": "这里的“没什么”表示〈很少〉，但“堆满了书”说明东西很多，二者矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af95e219-044f-4d55-9840-f6ea9329cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86792, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "没什么", "is_correct": true, "explanation": "正确。“没什么”表示这部电影没有多少意思。"}, {"text": "充满", "is_correct": false, "explanation": "语义：“充满意思”表示很有意思，与“没什么意思”意思相反。"}, {"text": "满是", "is_correct": false, "explanation": "搭配：“满是”后接具体事物，不接“意思”。"}, {"text": "很", "is_correct": false, "explanation": "语法：“很”不能直接修饰名词“意思”，应说“很有意思”。"}], "explanations": {"没什么": "正确。“没什么”表示这部电影没有多少意思。", "充满": "语义：“充满意思”表示很有意思，与“没什么意思”意思相反。", "满是": "搭配：“满是”后接具体事物，不接“意思”。", "很": "语法：“很”不能直接修饰名词“意思”，应说“很有意思”。"}, "sentence_index": 6, "correct_answer": "没什么"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个城市每天都挤满了游客，却没什么人来。", "explanation": "这里的“没什么”表示〈很少〉，但“挤满了游客”说明人很多，二者矛盾。"}, {"text": "他的衣柜里没什么衣服，每天都换不同的新衣服。", "explanation": "这里的“没什么”表示〈很少〉，但“每天都换不同的新衣服”说明衣服很多，二者矛盾。"}, {"text": "这次事故造成了很多人受伤，我们却说没什么，大家都别担心。", "explanation": "这里的“没什么”表示〈不要紧〉，与“造成很多人受伤”的严重后果矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af95e219-044f-4d55-9840-f6ea9329cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86792, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个包里很没什么东西。", "corrected_sentence": "这个包里没什么东西。", "error_description": "错误：程度副词“很”不能修饰“没什么”。正确：“这个包里没什么东西”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af95e219-044f-4d55-9840-f6ea9329cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86792, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我这周没什么的作业。", "corrected_sentence": "我这周没什么作业。", "error_description": "错误：“没什么”修饰“作业”时不能加“的”，应说“没什么作业”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af95e219-044f-4d55-9840-f6ea9329cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
