INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86795, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "当前是现在这个时候。", "primary_collocate": null, "pronunciation": "dāng qián", "ipa": "tɑŋ˥ tɕʰjɛn˧˥", "syllable_count": 2, "sentences": [{"text": "当前正是放暑假的时候，城市里的人比较少。", "target_word": "当前", "complexity_tier": "T3", "furigana": "dāng qián zhèng shì fàng shǔ jià de shí hou, chéng shì lǐ de rén bǐ jiào shǎo.", "sentence_source": "generated"}, {"text": "当前时间是八点。", "target_word": "当前", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "当前正是买房的好时候。", "target_word": "当前", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "当前是下班的高峰期，路上的车特别多。", "target_word": "当前", "complexity_tier": "T3", "furigana": "dāng qián shì xià bān de gāo fēng qī, lù shang de chē tè bié duō.", "sentence_source": "generated"}, {"text": "当前大家都在准备考试。", "target_word": "当前", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "当前是深夜，街上几乎没有人。", "target_word": "当前", "complexity_tier": "T3", "furigana": "dāng qián shì shēn yè, jiē shang jī hū méi yǒu rén.", "sentence_source": "generated"}, {"text": "当前是学习汉语最好的时候。", "target_word": "当前", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "当前是学习的关键时期，你要认真听课。", "target_word": "当前", "complexity_tier": "T3", "furigana": "dāng qián shì xué xí de guān jiàn shí qī, nǐ yào rèn zhēn tīng kè.", "sentence_source": "generated"}, {"text": "当前是中午十二点，食堂里的人特别多。", "target_word": "当前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当前正是春天，公园里有很多人在拍照。", "target_word": "当前", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "當前", "label": "繁体"}], "register": "书面", "sense_fingerprint": "当前：现在这个时候，作时间状语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dfa9012-682f-47cd-812e-5fb770f93c09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86795, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "当前", "is_correct": true, "explanation": "正确：“当前”作时间主语，指现在这个时候。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是时间点，“天气正是放暑假的时候”说不通。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”不能表示时间，句子不通。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“正是……的时候”需要时间名词，“窗户”不能用在这个句式里。"}], "explanations": {"当前": "正确：“当前”作时间主语，指现在这个时候。", "天气": "语义：“天气”不是时间点，“天气正是放暑假的时候”说不通。", "石头": "语义：“石头”不能表示时间，句子不通。", "窗户": "搭配：“正是……的时候”需要时间名词，“窗户”不能用在这个句式里。"}, "sentence_index": 0, "correct_answer": "当前"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "当前是明年的春节，我们一起回老家过年。", "explanation": "这里的“当前”指“现在这个时候”，与“明年”的未来时间矛盾；指未来的时间要用“到时”或“将来”。"}, {"text": "当前是我们刚搬来的时候，大家还不认识。", "explanation": "这里应该用〈当时〉。“当时”指过去的某个时候，与“刚搬来的时候”搭配；“当前”指现在，不能指过去的时刻。"}, {"text": "当前是三年前的事情，大家都不记得了。", "explanation": "这里应该用〈当时〉。“当前”指现在，与“三年前”的过去时间矛盾，“当时”才能指过去的某个时候。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab2ec06d-117f-4282-82e1-1de125000776') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86795, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "当前", "is_correct": true, "explanation": "正确：“当前”作主语，指现在这个时候，与“是……最好的时候”搭配。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”不是时间，“桌子是学习汉语最好的时候”说不通。"}, {"text": "大海", "is_correct": false, "explanation": "语义：“大海”不表示时间，句子不成立。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：“是……的时候”需要时间词作主语，“名字”不能这样用。"}], "explanations": {"当前": "正确：“当前”作主语，指现在这个时候，与“是……最好的时候”搭配。", "桌子": "语义：“桌子”不是时间，“桌子是学习汉语最好的时候”说不通。", "大海": "语义：“大海”不表示时间，句子不成立。", "名字": "搭配：“是……的时候”需要时间词作主语，“名字”不能这样用。"}, "sentence_index": 6, "correct_answer": "当前"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "当前是昨天下午，我们一起去了超市。", "explanation": "这里应该用〈当时〉。“当前”指现在这个时候，与“昨天下午”的过去时间矛盾；指过去的时刻要用“当时”。"}, {"text": "他当前明天就要出国了。", "explanation": "这里的“当前”指现在，与“明天就要出国”的未来时间矛盾；指未来的时间要用“将来”或“到时”。"}, {"text": "当前他还在这里，现在已经走了。", "explanation": "这里应该用〈刚才〉。“刚才”指不久前，与“现在已经走了”形成对比；“当前”指现在，两句都说现在，自相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab2ec06d-117f-4282-82e1-1de125000776') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86795, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "当前了是收获的季节。", "corrected_sentence": "当前是收获的季节。", "error_description": "错误：“当前了是收获的季节”。正确：“当前是收获的季节”。“当前”是时间名词，后面不能直接加动态助词“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab2ec06d-117f-4282-82e1-1de125000776') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86795, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "当前了我们都在学习汉语。", "corrected_sentence": "当前我们都在学习汉语。", "error_description": "错误：“当前了我们都在学习汉语”。正确：“当前我们都在学习汉语”。“当前”是时间名词，后面不能直接加动态助词“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab2ec06d-117f-4282-82e1-1de125000776') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
