INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86796, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "目前；眼前。", "primary_collocate": null, "pronunciation": "dāng qián", "ipa": "tɑŋ˥ tɕʰjɛn˧˥", "syllable_count": 2, "sentences": [{"text": "当前的情况很好。", "target_word": "当前", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "当前最重要的是休息。", "target_word": "当前", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们要先解决当前的问题。", "target_word": "当前", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "当前的天气不适合出去玩。", "target_word": "当前", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司当前最大的困难是没有钱。", "target_word": "当前", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "就当前来说，这个办法最好。", "target_word": "当前", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "当前的工作太多了，我没有时间休息。", "target_word": "当前", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，当前的目标是学好每天的新词。", "target_word": "当前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "根据当前的价格，我们买不起这个房子。", "target_word": "当前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当前的网络很慢，所以视频一直打不开。", "target_word": "当前", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "當前", "label": "繁体"}], "register": "书面", "sense_fingerprint": "当前：目前、眼前，多修饰情况、问题、任务等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dfa9012-682f-47cd-812e-5fb770f93c09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86796, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "当前", "is_correct": true, "explanation": "正确：“当前”修饰“情况”，表示目前的状况。"}, {"text": "名字", "is_correct": false, "explanation": "语义：“名字”不是可以“有情况”的对象，“名字的情况很好”说不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不指可以好坏的状况，句子说不清是什么的情况。"}, {"text": "饼干", "is_correct": false, "explanation": "搭配：“情况”通常指人、事或状态，“饼干的情况”不是常用搭配。"}], "explanations": {"当前": "正确：“当前”修饰“情况”，表示目前的状况。", "名字": "语义：“名字”不是可以“有情况”的对象，“名字的情况很好”说不通。", "颜色": "语义：“颜色”不指可以好坏的状况，句子说不清是什么的情况。", "饼干": "搭配：“情况”通常指人、事或状态，“饼干的情况”不是常用搭配。"}, "sentence_index": 0, "correct_answer": "当前"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "当前他不同意，现在却又同意了。", "explanation": "这里应该用〈当初〉。“当初”指过去的某个时候，与“现在却又同意了”形成对比；“当前”指现在，两个时间词都指现在，自相矛盾。"}, {"text": "当前我们住在上海，那时候很热闹。", "explanation": "这里应该用〈以前〉。“以前”指过去的一段时期，与“那时候”呼应；“当前”指现在，不能用来说过去的时期。"}, {"text": "那次事故当前发生在夜里，大家都吓坏了。", "explanation": "这里应该用〈当时〉。“当时”指过去的某个时候，与“那次事故”搭配；“当前”指现在，不能用来说过去发生的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab2ec06d-117f-4282-82e1-1de125000776') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86796, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "当前", "is_correct": true, "explanation": "正确：“当前”修饰“工作”，表示现在正在做的工作。"}, {"text": "天空", "is_correct": false, "explanation": "语义：“天空”没有“工作”可言，“天空的工作太多了”说不通。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”不能有工作，句子不成立。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“工作”指人或机构的职责，“窗户”不说“工作”，搭配不成立。"}], "explanations": {"当前": "正确：“当前”修饰“工作”，表示现在正在做的工作。", "天空": "语义：“天空”没有“工作”可言，“天空的工作太多了”说不通。", "石头": "语义：“石头”不能有工作，句子不成立。", "窗户": "搭配：“工作”指人或机构的职责，“窗户”不说“工作”，搭配不成立。"}, "sentence_index": 6, "correct_answer": "当前"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "当前这里会建一座公园，以后大家都能来玩。", "explanation": "这里应该用〈将来〉。“将来”指以后的时间，与“会建”的未来搭配；“当前”指现在，不能用来说未来的事。"}, {"text": "我们当前下个月就要搬家了。", "explanation": "这里的“当前”指现在这个时候，与“下个月”的未来时间矛盾；指未来的时间要用“将来”或“到时”。"}, {"text": "十年前，他当前还是一个小学生。", "explanation": "这里应该用〈当时〉。“十年前”是过去的时间，“当时”指过去的某个时候；“当前”指现在，不能用来说十年前的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab2ec06d-117f-4282-82e1-1de125000776') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86796, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "当前地最需要的是耐心。", "corrected_sentence": "当前最需要的是耐心。", "error_description": "错误：“当前地最需要的是耐心”。正确：“当前最需要的是耐心”。“当前”作状语修饰“最需要”时直接放在前面，不能用结构助词“地”引出。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab2ec06d-117f-4282-82e1-1de125000776') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86796, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "当前地价格比去年高。", "corrected_sentence": "当前的价格比去年高。", "error_description": "错误：“当前地价格比去年高”。正确：“当前的价格比去年高”。“当前”作定语修饰“价格”，要用结构助词“的”；“地”用于状语，不能用在定语后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab2ec06d-117f-4282-82e1-1de125000776') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86797, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "推", "is_correct": true, "explanation": "推：用力使物体离开自己或朝远处移动，与“拉”构成反义关系。"}, {"text": "送", "is_correct": false, "explanation": "送：把东西交给别人，与“拉”的方向并不相反，不构成反义。"}, {"text": "扛", "is_correct": false, "explanation": "扛：把物体放在肩上承载，与“拉”不构成反义关系。"}, {"text": "挑", "is_correct": false, "explanation": "挑：用扁担担东西，或从中选择，与“拉”不构成反义关系。"}], "correct_answer": "推", "explanations": {"推": "推：用力使物体离开自己或朝远处移动，与“拉”构成反义关系。", "送": "送：把东西交给别人，与“拉”的方向并不相反，不构成反义。", "扛": "扛：把物体放在肩上承载，与“拉”不构成反义关系。", "挑": "挑：用扁担担东西，或从中选择，与“拉”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbe18f3c-0bfb-4f8d-8f30-faa5ce06c6e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86797, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "推", "is_correct": true, "explanation": "推：用力使物体离开自己或朝远处移动，与“拉”构成反义关系。"}, {"text": "抬", "is_correct": false, "explanation": "抬：用手或肩把东西托起，并非与拉相反的方向动作，不构成反义。"}, {"text": "搬", "is_correct": false, "explanation": "搬：挪动物品的位置，强调搬运，与“拉”不构成反义。"}, {"text": "扶", "is_correct": false, "explanation": "扶：用手支撑或帮助站稳，与“拉”不是反义关系。"}], "correct_answer": "推", "explanations": {"推": "推：用力使物体离开自己或朝远处移动，与“拉”构成反义关系。", "抬": "抬：用手或肩把东西托起，并非与拉相反的方向动作，不构成反义。", "搬": "搬：挪动物品的位置，强调搬运，与“拉”不构成反义。", "扶": "扶：用手支撑或帮助站稳，与“拉”不是反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbe18f3c-0bfb-4f8d-8f30-faa5ce06c6e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86797, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "拉是用手把东西往自己这边拖。", "primary_collocate": null, "pronunciation": "lā", "ipa": "la˥", "syllable_count": 1, "sentences": [{"text": "这扇门要拉，不要推。", "target_word": "拉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拉了拉我的衣服。", "target_word": "拉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我拉过椅子坐下。", "target_word": "拉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈拉着我的手。", "target_word": "拉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别拉我，我自己能走。", "target_word": "拉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拉开抽屉找钥匙。", "target_word": "拉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她拉住了朋友的胳膊。", "target_word": "拉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你把绳子拉过来。", "target_word": "拉", "complexity_tier": "T3", "furigana": "nǐ bǎ shéngzi lā guòlai", "sentence_source": "generated"}, {"text": "他双手拉着绳子，把箱子往回拖。", "target_word": "拉", "complexity_tier": "T3", "furigana": "tā shuāngshǒu lāzhe shéngzi, bǎ xiāngzi wǎng huí tuō", "sentence_source": "generated"}, {"text": "他拉了一下门，没拉开。", "target_word": "拉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "拉了", "label": "体标"}, {"form": "拉着", "label": "体标"}, {"form": "拉过", "label": "体标"}, {"form": "拉拉", "label": "重叠"}], "register": "口语", "sense_fingerprint": "用手抓住人或物，往自己这边带、扯", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T1: 3 words above tier T1 (max 2): 绳子 (Zipf 3.86), 箱子 (Zipf 3.78), 往回 (Zipf 3.29)']::text[], 'ff939fe6-9da8-4641-8328-502a2b4a468a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86797, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "拉", "is_correct": true, "explanation": "拉（lā，第一声）：用手抓住人或物往自己这边带、扯，是本条目的目标词。"}, {"text": "腊", "is_correct": false, "explanation": "腊（là，第四声）与拉（lā，第一声）声调不同，意思是腊肉、腊月，不是拉。"}, {"text": "辣", "is_correct": false, "explanation": "辣（là，第四声）与拉（lā，第一声）声调不同，意思是味道刺激，不是拉。"}, {"text": "蜡", "is_correct": false, "explanation": "蜡（là，第四声）与拉（lā，第一声）声调不同，意思是蜡烛的材料，不是拉。"}], "explanations": {"拉": "拉（lā，第一声）：用手抓住人或物往自己这边带、扯，是本条目的目标词。", "腊": "腊（là，第四声）与拉（lā，第一声）声调不同，意思是腊肉、腊月，不是拉。", "辣": "辣（là，第四声）与拉（lā，第一声）声调不同，意思是味道刺激，不是拉。", "蜡": "蜡（là，第四声）与拉（lā，第一声）声调不同，意思是蜡烛的材料，不是拉。"}, "sentence_index": null, "correct_answer": "拉"}, "level_3": {"options": [{"text": "拉", "is_correct": true, "explanation": "拉：用手把门往自己这边扯，与“推”相对，符合“不要推”的语境。"}, {"text": "切", "is_correct": false, "explanation": "语义：“切”指用刀分割，不能用来开关门，“这扇门要切”句意不通。"}, {"text": "扫", "is_correct": false, "explanation": "搭配：“扫”用于地面、灰尘等，不与“门”搭配，“这扇门要扫”不成立。"}, {"text": "泡", "is_correct": false, "explanation": "语义：“泡”指浸在液体中，与门的开合无关，句意荒谬。"}], "explanations": {"拉": "拉：用手把门往自己这边扯，与“推”相对，符合“不要推”的语境。", "切": "语义：“切”指用刀分割，不能用来开关门，“这扇门要切”句意不通。", "扫": "搭配：“扫”用于地面、灰尘等，不与“门”搭配，“这扇门要扫”不成立。", "泡": "语义：“泡”指浸在液体中，与门的开合无关，句意荒谬。"}, "sentence_index": 0, "correct_answer": "拉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他站在自行车后面，拉着车往前走。", "explanation": "这里应该用〈推〉。他站在车后面，车在他前方，要让车往前走应用手往前推；“拉”表示朝自己这边拖，与“往前走”方向相反。"}, {"text": "他拉着一把伞走进教室。", "explanation": "这里应该用〈拿〉。拿伞是手握着，不是朝自己这边用力拖，“拉”用在这里不自然。"}, {"text": "他把纸团拉进了垃圾桶。", "explanation": "这里应该用〈扔〉。把纸团丢进垃圾桶是抛出去，不是朝自己这边拖，应说“扔进”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbe18f3c-0bfb-4f8d-8f30-faa5ce06c6e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86797, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拉", "is_correct": true, "explanation": "拉住：用手抓握并往回带，符合“朋友的胳膊”的语境。"}, {"text": "忍", "is_correct": false, "explanation": "语义：“忍住”的对象通常是疼痛或情绪，不能用来指抓住胳膊。"}, {"text": "记", "is_correct": false, "explanation": "搭配：“记住”的对象是事情或名字，不能与“胳膊”搭配。"}, {"text": "看", "is_correct": false, "explanation": "搭配：“看住”要求看的对象是人或物，“看住胳膊”不成立。"}], "explanations": {"拉": "拉住：用手抓握并往回带，符合“朋友的胳膊”的语境。", "忍": "语义：“忍住”的对象通常是疼痛或情绪，不能用来指抓住胳膊。", "记": "搭配：“记住”的对象是事情或名字，不能与“胳膊”搭配。", "看": "搭配：“看住”要求看的对象是人或物，“看住胳膊”不成立。"}, "sentence_index": 6, "correct_answer": "拉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他拉着一盆热水走进屋。", "explanation": "这里应该用〈端〉。端盆子是双手托着走，不是朝自己这边用力拖，“拉”用在这里不自然。"}, {"text": "她把照片拉成了碎片。", "explanation": "这里应该用〈撕〉。“拉”表示朝自己方向拖动，不表示把照片弄碎，应说“撕成碎片”。"}, {"text": "他拉着一把扇子走进屋。", "explanation": "这里应该用〈摇〉。手拿扇子要摇动扇风，不是朝自己方向拖拽，“拉”用在这里不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbe18f3c-0bfb-4f8d-8f30-faa5ce06c6e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86797, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他着拉我的手走。", "corrected_sentence": "他拉着我的手走。", "error_description": "“着”位置错误：“拉着”是动词加持续体标“着”，“着”必须紧跟动词“拉”之后，应说“拉着我的手走”，不能说“着拉我的手走”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbe18f3c-0bfb-4f8d-8f30-faa5ce06c6e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86797, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把抽屉拉来出了。", "corrected_sentence": "他把抽屉拉出来了。", "error_description": "补语语序错误：“拉出来”中“出”“来”是趋向补语，顺序应为“出来”，不能说“来出”，应说“拉出来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbe18f3c-0bfb-4f8d-8f30-faa5ce06c6e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86798, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "推", "is_correct": true, "explanation": "推：用力使物体离开自己或朝远处移动，与“拉”构成反义关系。"}, {"text": "送", "is_correct": false, "explanation": "送：把东西交给别人，动作方向并不相反，与“拉”不是反义关系。"}, {"text": "抬", "is_correct": false, "explanation": "抬：用手或肩把东西托起，并非与拉相反的方向动作，不构成反义。"}, {"text": "搬", "is_correct": false, "explanation": "搬：挪动物品的位置，强调搬运而非方向相反，与“拉”不构成反义。"}], "correct_answer": "推", "explanations": {"推": "推：用力使物体离开自己或朝远处移动，与“拉”构成反义关系。", "送": "送：把东西交给别人，动作方向并不相反，与“拉”不是反义关系。", "抬": "抬：用手或肩把东西托起，并非与拉相反的方向动作，不构成反义。", "搬": "搬：挪动物品的位置，强调搬运而非方向相反，与“拉”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbe18f3c-0bfb-4f8d-8f30-faa5ce06c6e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86798, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "推", "is_correct": true, "explanation": "推：用力使物体离开自己或朝远处移动，与“拉”构成反义关系。"}, {"text": "扔", "is_correct": false, "explanation": "扔：抛掷出去，强调抛出的动作，与“拉”不构成反义关系。"}, {"text": "挑", "is_correct": false, "explanation": "挑：用扁担担东西，或从中选择，与“拉”不构成反义关系。"}, {"text": "扛", "is_correct": false, "explanation": "扛：把物体放在肩上承载，与拉的方向不相反，不构成反义。"}], "correct_answer": "推", "explanations": {"推": "推：用力使物体离开自己或朝远处移动，与“拉”构成反义关系。", "扔": "扔：抛掷出去，强调抛出的动作，与“拉”不构成反义关系。", "挑": "挑：用扁担担东西，或从中选择，与“拉”不构成反义关系。", "扛": "扛：把物体放在肩上承载，与拉的方向不相反，不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbe18f3c-0bfb-4f8d-8f30-faa5ce06c6e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86798, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用力使物体朝自己的方向或沿着一定方向移动。", "primary_collocate": null, "pronunciation": "lā", "ipa": "la˥", "syllable_count": 1, "sentences": [{"text": "他用力把门拉开了。", "target_word": "拉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两匹马拉着一辆大车。", "target_word": "拉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把窗帘拉上。", "target_word": "拉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几个人一起拉绳子。", "target_word": "拉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把大箱子拉到门口。", "target_word": "拉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拉着行李箱走进车站。", "target_word": "拉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们拉着风筝线跑。", "target_word": "拉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你拉抽屉，别推。", "target_word": "拉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几个人把车拉出了泥坑。", "target_word": "拉", "complexity_tier": "T3", "furigana": "jǐ gè rén bǎ chē lā chū le ní kēng", "sentence_source": "generated"}, {"text": "箱子太重，我拉不动。", "target_word": "拉", "complexity_tier": "T3", "furigana": "xiāngzi tài zhòng, wǒ lā bu dòng", "sentence_source": "generated"}], "morphological_forms": [{"form": "拉了", "label": "体标"}, {"form": "拉着", "label": "体标"}, {"form": "拉过", "label": "体标"}, {"form": "拉拉", "label": "重叠"}], "register": "中性", "sense_fingerprint": "用力使物体朝自己或沿某方向移动，也指车马牵引、运载", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff939fe6-9da8-4641-8328-502a2b4a468a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86798, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "拉", "is_correct": true, "explanation": "拉（lā，第一声）：用力使物体朝自己或某个方向移动，是本条目的目标词。"}, {"text": "腊", "is_correct": false, "explanation": "腊（là，第四声）与拉（lā，第一声）声调不同，意思是腊肉、腊月，不是拉。"}, {"text": "辣", "is_correct": false, "explanation": "辣（là，第四声）与拉（lā，第一声）声调不同，意思是味道刺激，不是拉。"}, {"text": "蜡", "is_correct": false, "explanation": "蜡（là，第四声）与拉（lā，第一声）声调不同，意思是蜡烛的材料，不是拉。"}], "explanations": {"拉": "拉（lā，第一声）：用力使物体朝自己或某个方向移动，是本条目的目标词。", "腊": "腊（là，第四声）与拉（lā，第一声）声调不同，意思是腊肉、腊月，不是拉。", "辣": "辣（là，第四声）与拉（lā，第一声）声调不同，意思是味道刺激，不是拉。", "蜡": "蜡（là，第四声）与拉（lā，第一声）声调不同，意思是蜡烛的材料，不是拉。"}, "sentence_index": null, "correct_answer": "拉"}, "level_3": {"options": [{"text": "拉", "is_correct": true, "explanation": "拉开：用力使门移动而打开，符合句中“用力把门”的语境。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能施加于门，“唱开门”不成立。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮开”指加热至沸腾，与用力打开门无关，句意荒谬。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”是书写动作，不能使门移动，句意不通。"}], "explanations": {"拉": "拉开：用力使门移动而打开，符合句中“用力把门”的语境。", "唱": "搭配：“唱”不能施加于门，“唱开门”不成立。", "煮": "语义：“煮开”指加热至沸腾，与用力打开门无关，句意荒谬。", "写": "语义：“写”是书写动作，不能使门移动，句意不通。"}, "sentence_index": 0, "correct_answer": "拉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他站在车后面，拉着孩子的车往前走。", "explanation": "这里应该用〈推〉。他站在车后面，车在他前方，要让车往前走应用手往前推；“拉”表示朝自己这边拖，与“往前走”方向相反。"}, {"text": "他把外套拉在门后面。", "explanation": "这里应该用〈挂〉。“拉”表示用力使东西朝某方向移动，把衣服挂起来要用〈挂〉。"}, {"text": "他拉着一杯热水走进教室。", "explanation": "这里应该用〈拿〉。拿杯子是手握着走，不是朝自己这边用力拖，“拉”用在这里不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbe18f3c-0bfb-4f8d-8f30-faa5ce06c6e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86798, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拉", "is_correct": true, "explanation": "拉着：用手握住线并朝自己方向拽，符合“风筝线”的语境。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”不能与“风筝线”搭配，“洗着风筝线跑”不成立。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，不能用来表示握着风筝线，句意荒谬。"}, {"text": "倒", "is_correct": false, "explanation": "搭配：“倒”的对象通常是液体或容器，“倒着风筝线跑”不通。"}], "explanations": {"拉": "拉着：用手握住线并朝自己方向拽，符合“风筝线”的语境。", "洗": "搭配：“洗”不能与“风筝线”搭配，“洗着风筝线跑”不成立。", "吃": "语义：“吃”指进食，不能用来表示握着风筝线，句意荒谬。", "倒": "搭配：“倒”的对象通常是液体或容器，“倒着风筝线跑”不通。"}, "sentence_index": 6, "correct_answer": "拉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她拉着一碗汤走进屋。", "explanation": "这里应该用〈端〉。端汤是双手托着走，不是朝自己这边用力拖动，“拉”用在这里不自然。"}, {"text": "他把信拉成了两半。", "explanation": "这里应该用〈撕〉。“拉”表示朝自己方向拖动，不表示把纸撕开，把信撕成两半要用〈撕〉。"}, {"text": "他拉着一篮水果进了门。", "explanation": "这里应该用〈提〉。提篮子是手拎着走，不是朝自己方向拖拽，“拉”用在这里不自然，应说“提着”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbe18f3c-0bfb-4f8d-8f30-faa5ce06c6e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86798, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把车拉了到院子里。", "corrected_sentence": "他把车拉到了院子里。", "error_description": "“了”位置错误：“拉到”是动词加结果补语，完成体“了”应放在补语之后，说“拉到了”，不能插在“拉”和“到”之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbe18f3c-0bfb-4f8d-8f30-faa5ce06c6e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86798, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请把抽屉开拉。", "corrected_sentence": "请把抽屉拉开。", "error_description": "补语语序错误：“拉开”是动词加结果补语，“开”必须放在“拉”后面，不能说“开拉”，应说“请把抽屉拉开”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbe18f3c-0bfb-4f8d-8f30-faa5ce06c6e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
