INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86799, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "究竟是想弄明白到底怎么回事。", "primary_collocate": null, "pronunciation": "jiū jìng", "ipa": "tɕjoʊ˥ tɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "你究竟想去哪儿？", "target_word": "究竟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这究竟是怎么回事？", "target_word": "究竟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他究竟有没有来过？", "target_word": "究竟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想知道，他究竟是谁。", "target_word": "究竟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你究竟喜欢哪一个？", "target_word": "究竟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事究竟对不对？", "target_word": "究竟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "究竟是谁打破了杯子？", "target_word": "究竟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么晚了，你究竟去了哪儿？", "target_word": "究竟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们究竟在吵什么？", "target_word": "究竟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你说的究竟是真的还是假的？", "target_word": "究竟", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "疑问句中加强语气：想弄明白事情到底是怎么回事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7673fbc5-6e78-4bef-848b-ae27656be33f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86799, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "究竟", "is_correct": true, "explanation": "正确。“究竟”用于疑问句，加强追问“到底想去哪儿”的语气。"}, {"text": "已经", "is_correct": false, "explanation": "语义：“已经”表示动作已经完成，与“想去哪儿”这种尚未定下的意愿相悖。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”表示即刻发生，不能用于“想”这种心理状态的追问。"}, {"text": "一起", "is_correct": false, "explanation": "搭配：“一起”表示共同进行，单独的“你”不能与“想去哪儿”这种个人意愿搭配。"}], "explanations": {"究竟": "正确。“究竟”用于疑问句，加强追问“到底想去哪儿”的语气。", "已经": "语义：“已经”表示动作已经完成，与“想去哪儿”这种尚未定下的意愿相悖。", "马上": "语义：“马上”表示即刻发生，不能用于“想”这种心理状态的追问。", "一起": "搭配：“一起”表示共同进行，单独的“你”不能与“想去哪儿”这种个人意愿搭配。"}, "sentence_index": 0, "correct_answer": "究竟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的成绩究竟很好。", "explanation": "这里应该用〈其实〉。表示“到底”的“究竟”用于疑问句追问，不能用来陈述事实；陈述时应说“其实”。"}, {"text": "我们究竟到了机场。", "explanation": "这里应该用〈终于〉。“究竟”表示追问到底，不能用于陈述已经达到的结果。"}, {"text": "我们究竟去过北京。", "explanation": "这里应该用〈曾经〉。表示“到底”的“究竟”用于疑问句追问，不能陈述过去的经历；应说“我们曾经去过北京”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cf7ce71-ddfc-406e-88fa-d631d3cd9ba7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86799, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "究竟", "is_correct": true, "explanation": "正确。“究竟”用于疑问句，追问到底是谁打破了杯子。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：“曾经”指过去有过的经历，与追问刚发生的事件的当事人不合。"}, {"text": "忽然", "is_correct": false, "explanation": "搭配：“忽然”修饰动作的突然发生，不能直接修饰“是谁”这样的判断句。"}, {"text": "恰好", "is_correct": false, "explanation": "语义：“恰好”表示碰巧，与句中追问责任人的语气不符。"}], "explanations": {"究竟": "正确。“究竟”用于疑问句，追问到底是谁打破了杯子。", "曾经": "语义：“曾经”指过去有过的经历，与追问刚发生的事件的当事人不合。", "忽然": "搭配：“忽然”修饰动作的突然发生，不能直接修饰“是谁”这样的判断句。", "恰好": "语义：“恰好”表示碰巧，与句中追问责任人的语气不符。"}, "sentence_index": 6, "correct_answer": "究竟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈究竟不同意。", "explanation": "这里应该用〈本来〉。“究竟”用于疑问句追问到底，不能用于陈述“本来不同意”这样的事实。"}, {"text": "他究竟没有来。", "explanation": "这里应该用〈果然〉。表示“到底”的“究竟”用于追问，陈述“果然没有来”时要用“果然”。"}, {"text": "这个方法究竟有效。", "explanation": "这里应该用〈始终〉。“究竟”用于疑问句追问到底，陈述方法一直有效时要用“始终”，不用“究竟”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cf7ce71-ddfc-406e-88fa-d631d3cd9ba7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
