INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86800, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，到底；追问原因。", "primary_collocate": null, "pronunciation": "jiū jìng", "ipa": "tɕjoʊ˥ tɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他究竟为什么不高兴？", "target_word": "究竟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "究竟是什么原因，让你迟到？", "target_word": "究竟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你究竟为什么哭了？", "target_word": "究竟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电脑究竟为什么打不开？", "target_word": "究竟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他究竟为什么要走呢？", "target_word": "究竟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你究竟怎么回事，为什么不说话？", "target_word": "究竟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你究竟为什么不吃饭？", "target_word": "究竟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不明白，他究竟为什么生气。", "target_word": "究竟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "究竟为什么价格涨了这么多？", "target_word": "究竟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你究竟为什么不愿意去？", "target_word": "究竟", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词：到底，用来追问原因", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7673fbc5-6e78-4bef-848b-ae27656be33f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86800, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "究竟", "is_correct": true, "explanation": "正确。“究竟”用于追问原因，加强“到底为什么不高兴”的语气。"}, {"text": "已经", "is_correct": false, "explanation": "语义：“已经”表示状态已经发生，与追问尚未明了的原因不合。"}, {"text": "只", "is_correct": false, "explanation": "语义：“只”表示限定，“只为什么”不能成立，与原因追问不搭。"}, {"text": "一起", "is_correct": false, "explanation": "搭配：“一起”表示共同行为，不能修饰单人的情绪状态“不高兴”。"}], "explanations": {"究竟": "正确。“究竟”用于追问原因，加强“到底为什么不高兴”的语气。", "已经": "语义：“已经”表示状态已经发生，与追问尚未明了的原因不合。", "只": "语义：“只”表示限定，“只为什么”不能成立，与原因追问不搭。", "一起": "搭配：“一起”表示共同行为，不能修饰单人的情绪状态“不高兴”。"}, "sentence_index": 0, "correct_answer": "究竟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我究竟考上了大学。", "explanation": "这里应该用〈终于〉。“究竟”只用于追问原因，陈述已经达到的结果时要用“终于”，不能用“究竟”。"}, {"text": "这个办法究竟好用。", "explanation": "这里应该用〈确实〉。“究竟”用于追问，陈述办法确实好用时不能用“究竟”。"}, {"text": "我究竟不想去。", "explanation": "这里应该用〈本来〉。表示“到底”的“究竟”用于疑问句追问，陈述“本来不想去”时要用“本来”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cf7ce71-ddfc-406e-88fa-d631d3cd9ba7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86800, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "究竟", "is_correct": true, "explanation": "正确。“究竟”用于疑问句，加强追问“到底为什么不吃饭”的语气。"}, {"text": "忽然", "is_correct": false, "explanation": "搭配：“忽然”修饰动作的突然发生，不能放在“为什么”前加强追问。"}, {"text": "恰好", "is_correct": false, "explanation": "语义：“恰好”表示碰巧，与追问原因的语气不符。"}, {"text": "幸亏", "is_correct": false, "explanation": "语义：“幸亏”表示庆幸，不能用于追问原因的疑问句。"}], "explanations": {"究竟": "正确。“究竟”用于疑问句，加强追问“到底为什么不吃饭”的语气。", "忽然": "搭配：“忽然”修饰动作的突然发生，不能放在“为什么”前加强追问。", "恰好": "语义：“恰好”表示碰巧，与追问原因的语气不符。", "幸亏": "语义：“幸亏”表示庆幸，不能用于追问原因的疑问句。"}, "sentence_index": 6, "correct_answer": "究竟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他究竟会来。", "explanation": "这里应该用〈一定〉。“究竟”用于追问原因，不表示“一定会”的肯定判断，陈述时要用“一定”。"}, {"text": "这道菜究竟很好吃。", "explanation": "这里应该用〈果然〉。表示“到底”的“究竟”用于疑问句追问，陈述菜果然好吃时要用“果然”。"}, {"text": "我究竟早就知道了。", "explanation": "这里应该用〈其实〉。“究竟”用于追问，陈述“其实早就知道”时不能用“究竟”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cf7ce71-ddfc-406e-88fa-d631d3cd9ba7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
