INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86801, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "红色是像苹果和太阳那样的颜色。", "primary_collocate": null, "pronunciation": "hóng sè", "ipa": "xʊŋ˧˥ sɤ˥˩", "syllable_count": 2, "sentences": [{"text": "太阳落山时，天空是红色的。", "target_word": "红色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早上的太阳是红色的。", "target_word": "红色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个红色很像苹果的颜色。", "target_word": "红色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把墙刷成了红色。", "target_word": "红色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的新书包是红色的。", "target_word": "红色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不喜欢红色，喜欢白色。", "target_word": "红色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红色和黄色放在一起很好看。", "target_word": "红色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小弟画了一个红色的太阳。", "target_word": "红色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到红色的太阳，我很高兴。", "target_word": "红色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她给我看了红色的苹果和黄色的香蕉。", "target_word": "红色", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "紅色", "label": "繁体"}], "register": "中性", "sense_fingerprint": "像苹果和太阳的颜色", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25be5f49-5a16-4b1c-a339-0cf287f7ff26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86801, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "红色", "is_correct": true, "explanation": "红色是名词，指像苹果和太阳那样的颜色，此处作“是……的”的表语。"}, {"text": "数字", "is_correct": false, "explanation": "语义：“数字”不是颜色，天空不能“是数字的”。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“是……的”后要接具体颜色词，“颜色”是上位词，不能直接充当表语。"}, {"text": "声音", "is_correct": false, "explanation": "语义：天空不能是声音，“声音”不是可见的颜色，与句中“天空”不搭配。"}], "explanations": {"红色": "红色是名词，指像苹果和太阳那样的颜色，此处作“是……的”的表语。", "数字": "语义：“数字”不是颜色，天空不能“是数字的”。", "颜色": "搭配：“是……的”后要接具体颜色词，“颜色”是上位词，不能直接充当表语。", "声音": "语义：天空不能是声音，“声音”不是可见的颜色，与句中“天空”不搭配。"}, "sentence_index": 0, "correct_answer": "红色"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这面墙的红色很甜。", "explanation": "这里用的是颜色义，颜色没有味道，不能用味觉义的“甜”来形容墙面的颜色。"}, {"text": "这面墙的红色很认真地工作了。", "explanation": "这里把颜色当作能主动做事的人来写，颜色不能“工作”，属于颜色义的误用。"}, {"text": "我们假期去参观了很多红色旅游景点。", "explanation": "这里用的是“革命历史”义（红色旅游），不是颜色义，与本词的颜色义不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f59eef98-5920-4c5f-afac-18238bea63cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86801, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "红色", "is_correct": true, "explanation": "红色是名词，指像苹果和太阳那样的颜色，此处与“黄色”并列作主语。"}, {"text": "数字", "is_correct": false, "explanation": "语义：“数字”不是颜色，不能与“黄色”并列构成配色，句子不通。"}, {"text": "音乐", "is_correct": false, "explanation": "语义：“音乐”不是可见的颜色，不能与“黄色”放在一起看。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”不可见，与“黄色”并列没有意义。"}], "explanations": {"红色": "红色是名词，指像苹果和太阳那样的颜色，此处与“黄色”并列作主语。", "数字": "语义：“数字”不是颜色，不能与“黄色”并列构成配色，句子不通。", "音乐": "语义：“音乐”不是可见的颜色，不能与“黄色”放在一起看。", "味道": "语义：“味道”不可见，与“黄色”并列没有意义。"}, "sentence_index": 6, "correct_answer": "红色"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌的红色很好听。", "explanation": "“红色”是看得见的颜色，不能用“好听”来形容，颜色和声音无关。"}, {"text": "红色很会唱歌。", "explanation": "“红色”是颜色，不是人，不能“唱歌”。"}, {"text": "这杯水的红色很香。", "explanation": "“红色”是看得见的颜色，没有气味，不能用“香”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f59eef98-5920-4c5f-afac-18238bea63cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86801, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把门漆了红色。", "corrected_sentence": "他把门漆成了红色。", "error_description": "错误：“漆了红色”，缺少结果补语“成”；正确：“漆成了红色”。“漆”后面要用“成”引出颜色结果。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f59eef98-5920-4c5f-afac-18238bea63cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86801, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那只红色很漂亮。", "corrected_sentence": "那种红色很漂亮。", "error_description": "错误：“那只红色”，“只”用于动物等个体；正确：“那种红色”，颜色名词要用“种”计量。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f59eef98-5920-4c5f-afac-18238bea63cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
