INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86803, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "肉是动物身上软软的、可以吃的部分。", "primary_collocate": null, "pronunciation": "ròu", "ipa": "ɻou˥˩", "syllable_count": 1, "sentences": [{"text": "我今天想吃肉。", "target_word": "肉", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "弟弟不喜欢吃蔬菜，只喜欢吃肉。", "target_word": "肉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈去市场买了一斤肉。", "target_word": "肉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块肉煮了两个小时，很软。", "target_word": "肉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不吃肉，只吃菜和米饭。", "target_word": "肉", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "冰箱里还有一块肉，晚上可以做饭。", "target_word": "肉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店的肉很新鲜。", "target_word": "肉", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你把肉切成小片，再放进锅里。", "target_word": "肉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫最爱吃肉。", "target_word": "肉", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们明天用这块肉做饺子。", "target_word": "肉", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一块肉", "label": "量词"}, {"form": "一斤肉", "label": "量词"}, {"form": "猪肉", "label": "复合"}, {"form": "牛肉", "label": "复合"}, {"form": "肉类", "label": "复合"}], "register": "中性", "sense_fingerprint": "肉：作为食物的动物的肉，如“吃肉”“买肉”“一块肉”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '851174ca-2114-4551-bf43-9f2fc3ac5b77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86803, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "肉", "is_correct": true, "explanation": "“肉”是动物身上可以吃的部分，是本词的本义。"}, {"text": "柔", "is_correct": false, "explanation": "ròu（第四声）与 róu（第二声）声调不同，róu 意思是柔软。"}, {"text": "揉", "is_correct": false, "explanation": "ròu（第四声）与 róu（第二声）声调不同，róu 意思是揉搓。"}, {"text": "漏", "is_correct": false, "explanation": "ròu 与 lòu 声母不同（r 与 l），lòu 意思是漏掉。"}, {"text": "豆", "is_correct": false, "explanation": "ròu 与 dòu 声母不同（r 与 d），dòu 意思是豆子。"}, {"text": "入", "is_correct": false, "explanation": "ròu 与 rù 韵母不同（ou 与 u），rù 意思是进入。"}, {"text": "奏", "is_correct": false, "explanation": "ròu 与 zòu 声母不同（r 与 z），zòu 意思是演奏。"}], "explanations": {"肉": "“肉”是动物身上可以吃的部分，是本词的本义。", "柔": "ròu（第四声）与 róu（第二声）声调不同，róu 意思是柔软。", "揉": "ròu（第四声）与 róu（第二声）声调不同，róu 意思是揉搓。", "漏": "ròu 与 lòu 声母不同（r 与 l），lòu 意思是漏掉。", "豆": "ròu 与 dòu 声母不同（r 与 d），dòu 意思是豆子。", "入": "ròu 与 rù 韵母不同（ou 与 u），rù 意思是进入。", "奏": "ròu 与 zòu 声母不同（r 与 z），zòu 意思是演奏。"}, "sentence_index": null, "correct_answer": "肉"}, "level_3": {"options": [{"text": "肉", "is_correct": true, "explanation": "“肉”是可以吃的动物的肉，句中“想吃肉”正确。"}, {"text": "饮料", "is_correct": false, "explanation": "搭配：饮料要说“喝”，不说“吃”。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子不是食物，不能说“想吃椅子”。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具不能吃，不能说“想吃玩具”。"}], "explanations": {"肉": "“肉”是可以吃的动物的肉，句中“想吃肉”正确。", "饮料": "搭配：饮料要说“喝”，不说“吃”。", "椅子": "语义：椅子不是食物，不能说“想吃椅子”。", "玩具": "语义：玩具不能吃，不能说“想吃玩具”。"}, "sentence_index": 0, "correct_answer": "肉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天都喝肉。", "explanation": "这里应该用〈牛奶〉。肉是固体食物，不能用〈喝〉，应说〈喝牛奶〉。"}, {"text": "屋里的肉很亮，照得人眼睛疼。", "explanation": "这里应该用〈光〉。肉指可以吃的动物组织，不能用来形容明亮，应说〈光〉。"}, {"text": "今天的肉很清新，适合去郊外走走。", "explanation": "这里应该用〈空气〉。肉不能用来形容清新，形容清新要用〈空气〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '711ec6d4-218e-455b-9b09-3ea66234cce2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86803, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "肉", "is_correct": true, "explanation": "“肉”是动物身上可以吃的部分，是本词的本义。"}, {"text": "逗", "is_correct": false, "explanation": "ròu（第四声）与 dòu（第四声）声母不同（r 与 d），dòu 意思是逗弄。"}, {"text": "购", "is_correct": false, "explanation": "ròu 与 gòu 声母不同（r 与 g），gòu 意思是购买。"}, {"text": "凑", "is_correct": false, "explanation": "ròu 与 còu 声母不同（r 与 c），còu 意思是凑集。"}, {"text": "扣", "is_correct": false, "explanation": "ròu 与 kòu 声母不同（r 与 k），kòu 意思是扣子。"}], "explanations": {"肉": "“肉”是动物身上可以吃的部分，是本词的本义。", "逗": "ròu（第四声）与 dòu（第四声）声母不同（r 与 d），dòu 意思是逗弄。", "购": "ròu 与 gòu 声母不同（r 与 g），gòu 意思是购买。", "凑": "ròu 与 còu 声母不同（r 与 c），còu 意思是凑集。", "扣": "ròu 与 kòu 声母不同（r 与 k），kòu 意思是扣子。"}, "sentence_index": null, "correct_answer": "肉"}, "level_3": {"options": [{"text": "肉", "is_correct": true, "explanation": "“肉”指可以吃的动物的肉，“很新鲜”形容食物，句子正确。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是矿物，不能用“新鲜”形容。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是建筑部件，不能用“新鲜”形容。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑是电器，不能说“很新鲜”。"}], "explanations": {"肉": "“肉”指可以吃的动物的肉，“很新鲜”形容食物，句子正确。", "石头": "语义：石头是矿物，不能用“新鲜”形容。", "窗户": "语义：窗户是建筑部件，不能用“新鲜”形容。", "电脑": "语义：电脑是电器，不能说“很新鲜”。"}, "sentence_index": 6, "correct_answer": "肉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "肉在教室里上课。", "explanation": "这里应该用〈学生〉。肉不能去上课，主语应是〈学生〉。"}, {"text": "肉从东边升起来了。", "explanation": "这里应该用〈太阳〉。肉不会升起，从东边升起的应是〈太阳〉。"}, {"text": "外面的肉很晴朗，适合出门。", "explanation": "这里应该用〈天空〉。晴朗形容天空或天气，肉不能用来形容天气，应说〈天空〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '711ec6d4-218e-455b-9b09-3ea66234cce2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86803, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "奶奶昨天买了一朵肉。", "corrected_sentence": "奶奶昨天买了一块肉。", "error_description": "量词错误：肉要用“块”，“朵”用于花、云等，不用于肉。正确：“一块肉”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '711ec6d4-218e-455b-9b09-3ea66234cce2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86803, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈把这块肉切了成小片。", "corrected_sentence": "妈妈把这块肉切成了小片。", "error_description": "“了”的位置错误：“切成”是动词加结果补语，“了”应放在补语之后，不能插在“切”和“成”之间。正确：“妈妈把这块肉切成了小片。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '711ec6d4-218e-455b-9b09-3ea66234cce2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
