INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86804, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人或动物体内附着在骨头上的柔软组织。", "primary_collocate": null, "pronunciation": "ròu", "ipa": "ɻou˥˩", "syllable_count": 1, "sentences": [{"text": "他很瘦，身上几乎没有肉。", "target_word": "肉", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他最近胖了，脸上都是肉。", "target_word": "肉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他摔了一跤，膝盖破了，露出了里面的肉。", "target_word": "肉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "伤口很深，能看到里面的肉。", "target_word": "肉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "刀不小心切到了手上的肉。", "target_word": "肉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他生病以后，身上的肉少了很多。", "target_word": "肉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "运动以后，他腿上的肉变硬了。", "target_word": "肉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的手被热水烫伤了，手上的肉很疼。", "target_word": "肉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "宝宝的手软软的，全是肉。", "target_word": "肉", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "医生说这里的肉已经长好了。", "target_word": "肉", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一块肉", "label": "量词"}, {"form": "一片肉", "label": "量词"}, {"form": "肉体", "label": "复合"}, {"form": "骨肉", "label": "复合"}], "register": "中性", "sense_fingerprint": "肉：人或动物身体上附着在骨头上的柔软组织，如“身上没有肉”“手上的肉很疼”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '851174ca-2114-4551-bf43-9f2fc3ac5b77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86804, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "肉", "is_correct": true, "explanation": "“肉”指人或动物身上附着在骨头上的柔软组织，是本词的本义。"}, {"text": "揉", "is_correct": false, "explanation": "ròu（第四声）与 róu（第二声）声调不同，róu 意思是揉搓。"}, {"text": "漏", "is_correct": false, "explanation": "ròu 与 lòu 声母不同（r 与 l），lòu 意思是漏掉。"}, {"text": "豆", "is_correct": false, "explanation": "ròu 与 dòu 声母不同（r 与 d），dòu 意思是豆子。"}, {"text": "奏", "is_correct": false, "explanation": "ròu 与 zòu 声母不同（r 与 z），zòu 意思是演奏。"}], "explanations": {"肉": "“肉”指人或动物身上附着在骨头上的柔软组织，是本词的本义。", "揉": "ròu（第四声）与 róu（第二声）声调不同，róu 意思是揉搓。", "漏": "ròu 与 lòu 声母不同（r 与 l），lòu 意思是漏掉。", "豆": "ròu 与 dòu 声母不同（r 与 d），dòu 意思是豆子。", "奏": "ròu 与 zòu 声母不同（r 与 z），zòu 意思是演奏。"}, "sentence_index": null, "correct_answer": "肉"}, "level_3": {"options": [{"text": "肉", "is_correct": true, "explanation": "“肉”指身上附着在骨头上的柔软组织，句中“身上几乎没有肉”正确。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不长在身上，不能说“身上几乎没有桌子”。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不是身体的组成部分，不能说“身上几乎没有汽车”。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高指身材的高矮，不是身上的一种东西，不能说“身上几乎没有身高”。"}], "explanations": {"肉": "“肉”指身上附着在骨头上的柔软组织，句中“身上几乎没有肉”正确。", "桌子": "语义：桌子是家具，不长在身上，不能说“身上几乎没有桌子”。", "汽车": "语义：汽车不是身体的组成部分，不能说“身上几乎没有汽车”。", "身高": "体貌：身高指身材的高矮，不是身上的一种东西，不能说“身上几乎没有身高”。"}, "sentence_index": 0, "correct_answer": "肉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的肉很亮，看起来很精神。", "explanation": "这里应该用〈眼睛〉。肉是身体组织，不能用来形容明亮，应说〈眼睛〉。"}, {"text": "他写完了肉，就去睡觉了。", "explanation": "这里应该用〈作业〉。肉不能被写，写完的应是〈作业〉。"}, {"text": "肉在院子里跑来跑去。", "explanation": "这里应该用〈小狗〉。肉不会自己跑，跑来跑去的应是〈小狗〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '711ec6d4-218e-455b-9b09-3ea66234cce2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86804, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "肉", "is_correct": true, "explanation": "“肉”指身上附着在骨头上的柔软组织，是本词的本义。"}, {"text": "逗", "is_correct": false, "explanation": "ròu（第四声）与 dòu（第四声）声母不同（r 与 d），dòu 意思是逗弄。"}, {"text": "扣", "is_correct": false, "explanation": "ròu 与 kòu 声母不同（r 与 k），kòu 意思是扣子。"}, {"text": "凑", "is_correct": false, "explanation": "ròu 与 còu 声母不同（r 与 c），còu 意思是凑集。"}, {"text": "入", "is_correct": false, "explanation": "ròu 与 rù 韵母不同（ou 与 u），rù 意思是进入。"}], "explanations": {"肉": "“肉”指身上附着在骨头上的柔软组织，是本词的本义。", "逗": "ròu（第四声）与 dòu（第四声）声母不同（r 与 d），dòu 意思是逗弄。", "扣": "ròu 与 kòu 声母不同（r 与 k），kòu 意思是扣子。", "凑": "ròu 与 còu 声母不同（r 与 c），còu 意思是凑集。", "入": "ròu 与 rù 韵母不同（ou 与 u），rù 意思是进入。"}, "sentence_index": null, "correct_answer": "肉"}, "level_3": {"options": [{"text": "肉", "is_correct": true, "explanation": "“肉”指身上附着在骨头上的柔软组织，运动后变硬，句子正确。"}, {"text": "钢笔", "is_correct": false, "explanation": "语义：钢笔是文具，不是身体的一部分，不能说腿上的钢笔变硬。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“腿上的……”后不接年龄，年龄不能说变硬。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是建筑部件，不长在腿上，不能说变硬。"}], "explanations": {"肉": "“肉”指身上附着在骨头上的柔软组织，运动后变硬，句子正确。", "钢笔": "语义：钢笔是文具，不是身体的一部分，不能说腿上的钢笔变硬。", "年龄": "搭配：“腿上的……”后不接年龄，年龄不能说变硬。", "窗户": "语义：窗户是建筑部件，不长在腿上，不能说变硬。"}, "sentence_index": 6, "correct_answer": "肉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很会弹肉。", "explanation": "这里应该用〈钢琴〉。肉不能被弹，应说〈弹钢琴〉。"}, {"text": "他修好了肉。", "explanation": "这里应该用〈自行车〉。肉不能被修，修好的应是〈自行车〉。"}, {"text": "他学习肉很认真。", "explanation": "这里应该用〈汉语〉。肉不是可以学习的内容，学习的应是〈汉语〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '711ec6d4-218e-455b-9b09-3ea66234cce2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.p