INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86805, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "曾经是说以前有过这件事。", "primary_collocate": null, "pronunciation": "céng jīng", "ipa": "tsʰɤŋ˧˥ tɕiŋ˥", "syllable_count": 2, "sentences": [{"text": "他曾经爱过这个女孩。", "target_word": "曾经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我曾经看过这部电影。", "target_word": "曾经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店曾经很有名。", "target_word": "曾经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候我曾经掉进过河里。", "target_word": "曾经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她曾经想当歌手。", "target_word": "曾经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老李曾经去过很多国家。", "target_word": "曾经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路曾经很热闹。", "target_word": "曾经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们曾经是好朋友。", "target_word": "曾经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他曾经说过这件事。", "target_word": "曾经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶曾经住在乡下。", "target_word": "曾经", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "说以前有过这件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25be5f49-5a16-4b1c-a339-0cf287f7ff26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86805, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "曾经", "is_correct": true, "explanation": "曾经是副词，表示以前有过这件事，这里修饰“爱过”。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示动作正在进行，与“爱过”所表示的已完成经历相冲突。"}, {"text": "将要", "is_correct": false, "explanation": "语义：“将要”指将来，与“爱过”所说的过去经历矛盾。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”指即将发生，不能表示已经有过的经历。"}], "explanations": {"曾经": "曾经是副词，表示以前有过这件事，这里修饰“爱过”。", "正在": "体貌：“正在”表示动作正在进行，与“爱过”所表示的已完成经历相冲突。", "将要": "语义：“将要”指将来，与“爱过”所说的过去经历矛盾。", "马上": "语义：“马上”指即将发生，不能表示已经有过的经历。"}, "sentence_index": 0, "correct_answer": "曾经"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我现在曾经很饿。", "explanation": "这里“曾经”只表示过去有过某种情况，不能与表示当下状态的“现在”搭配。"}, {"text": "他曾经明天来。", "explanation": "这里“曾经”只说过去，不能用于“明天”这样的将来时间。"}, {"text": "这件事曾经在下周解决。", "explanation": "这里应该用〈将要〉。“曾经”只说过去，不能与“下周”这样的将来时间词搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f59eef98-5920-4c5f-afac-18238bea63cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86805, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "曾经", "is_correct": true, "explanation": "曾经是副词，表示过去曾有过这种状态，放在“很热闹”之前。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示进行，不能直接修饰“很热闹”这种状态。"}, {"text": "刚", "is_correct": false, "explanation": "搭配：“刚”表示刚刚发生，不能修饰“很热闹”这样的状态。"}, {"text": "不断", "is_correct": false, "explanation": "语义：“不断”修饰反复进行的动作，不能修饰“很热闹”这种状态。"}], "explanations": {"曾经": "曾经是副词，表示过去曾有过这种状态，放在“很热闹”之前。", "正在": "体貌：“正在”表示进行，不能直接修饰“很热闹”这种状态。", "刚": "搭配：“刚”表示刚刚发生，不能修饰“很热闹”这样的状态。", "不断": "语义：“不断”修饰反复进行的动作，不能修饰“很热闹”这种状态。"}, "sentence_index": 6, "correct_answer": "曾经"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个计划曾经在明年实施。", "explanation": "这里应该用〈将要〉。“曾经”只说过去，不能用于“明年”这样的将来时间。"}, {"text": "他现在曾经在厨房做饭。", "explanation": "这里应该用〈正在〉。“曾经”只表示过去，不能与“现在”一起说正在进行的动作。"}, {"text": "下周这场比赛曾经很精彩。", "explanation": "这里应该用〈将会〉。“曾经”只说过去，不能与“下周”这样的将来时间词搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f59eef98-5920-4c5f-afac-18238bea63cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86805, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座桥曾经了很壮观。", "corrected_sentence": "这座桥曾经很壮观。", "error_description": "错误：“曾经”后面不能直接加“了”，“曾经”应直接修饰后面的“很壮观”；正确：“曾经很壮观”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f59eef98-5920-4c5f-afac-18238bea63cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86805, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他曾经吃完很多苦。", "corrected_sentence": "他曾经吃过很多苦。", "error_description": "错误：“吃完很多苦”，“完”表示动作结束，与“曾经”所表示的过去经历不符，也不能说“吃完苦”；正确：“吃过很多苦”，用“过”表示经历。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f59eef98-5920-4c5f-afac-18238bea63cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
