INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86807, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "背后是在一个人或东西的后面。", "primary_collocate": null, "pronunciation": "bèi hòu", "ipa": "peɪ˥˩ xoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "他站在我背后。", "target_word": "背后", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "门背后有一只猫。", "target_word": "背后", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小狗藏在椅子背后。", "target_word": "背后", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "房子背后有一座小山。", "target_word": "背后", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子躲在妈妈的背后，不敢说话。", "target_word": "背后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我听到背后有人叫我的名字。", "target_word": "背后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请不要站在我背后，我看不到电视了。", "target_word": "背后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把手放在背后，笑着看我。", "target_word": "背后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校背后有一条小河，河边的树很高。", "target_word": "背后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "照相的时候，奶奶坐在中间，我站在她背后。", "target_word": "背后", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "背後", "label": "繁体"}], "register": "中性", "sense_fingerprint": "背后：人或物的后面，表示空间位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dfa9012-682f-47cd-812e-5fb770f93c09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86807, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "背后", "is_correct": true, "explanation": "正确：“背后”表示空间位置，指人的后面，与“站在我……”搭配。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“站在……”后接处所，“石头”作处所要说“石头上”，“站在我石头”说不通。"}, {"text": "名字", "is_correct": false, "explanation": "语义：“名字”不是处所，人不能站在“名字”里。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：表示“桌子”的位置要说“桌子上”，“站在我桌子”不成立。"}], "explanations": {"背后": "正确：“背后”表示空间位置，指人的后面，与“站在我……”搭配。", "石头": "搭配：“站在……”后接处所，“石头”作处所要说“石头上”，“站在我石头”说不通。", "名字": "语义：“名字”不是处所，人不能站在“名字”里。", "桌子": "搭配：表示“桌子”的位置要说“桌子上”，“站在我桌子”不成立。"}, "sentence_index": 0, "correct_answer": "背后"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他站在背后我，看不见电视。", "explanation": "语序错误：“背后”是方位词，应说“站在我背后”，不能放在“我”之前。"}, {"text": "我们先吃饭，背后再去散步。", "explanation": "这里应该用〈然后〉。“背后”只表示位置，不表示动作的先后，动作的先后要用“然后”。"}, {"text": "我背后才知道这件事。", "explanation": "这里应该用〈后来〉。“背后”只表示位置，不表示时间；表示过了一段时间以后要用“后来”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab2ec06d-117f-4282-82e1-1de125000776') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86807, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "背后", "is_correct": true, "explanation": "正确：“背后”表示人的后面，与“站在我……”搭配，指空间位置。"}, {"text": "天空", "is_correct": false, "explanation": "语义：人不能站在“天空”里面，句子说不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“站在颜色”不成立，“颜色”不是可以站立的处所。"}, {"text": "饼干", "is_correct": false, "explanation": "搭配：“站在”后要接处所，“饼干”不能作站立的处所。"}], "explanations": {"背后": "正确：“背后”表示人的后面，与“站在我……”搭配，指空间位置。", "天空": "语义：人不能站在“天空”里面，句子说不通。", "颜色": "语义：“站在颜色”不成立，“颜色”不是可以站立的处所。", "饼干": "搭配：“站在”后要接处所，“饼干”不能作站立的处所。"}, "sentence_index": 6, "correct_answer": "背后"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "教室背后后面坐着一个同学。", "explanation": "这里“背后”与“后面”意思重复，只用一个即可，应说“教室后面坐着一个同学”。"}, {"text": "吃完饭背后，我们去散步。", "explanation": "这里应该用〈之后〉。“背后”只表示位置，不表示动作的先后；动作的先后要用“之后”。"}, {"text": "我把书放在背后的上面，你找一下。", "explanation": "这里“背后”与“上面”都是方位词，不能叠用，应说“背后”或“上面”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab2ec06d-117f-4282-82e1-1de125000776') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86807, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "椅子在背后有一个箱子。", "corrected_sentence": "椅子背后有一个箱子。", "error_description": "错误：“椅子在背后”。“在”后直接接方位词“背后”，缺少所指的名词。正确：“椅子背后”或“在椅子背后”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab2ec06d-117f-4282-82e1-1de125000776') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86807, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一棵大树站在房子在背后。", "corrected_sentence": "一棵大树站在房子背后。", "error_description": "错误：“站在房子在背后”。正确：“站在房子背后”。“在”已经引出了处所，“背后”前面不能再加“在”，重复了。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab2ec06d-117f-4282-82e1-1de125000776') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86808, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "当面", "is_correct": true, "explanation": "正确：“当面”指当着面、公开地，与“背后”的“暗地里、不当面”意思相对。"}, {"text": "手机", "is_correct": false, "explanation": "无关：“手机”是物品，与“暗地里”没有反义关系。"}, {"text": "河流", "is_correct": false, "explanation": "无关：“河流”是自然事物，与“暗地里”没有反义关系。"}, {"text": "天空", "is_correct": false, "explanation": "无关：“天空”是自然景物，与“暗地里”没有反义关系。"}], "correct_answer": "当面", "explanations": {"当面": "正确：“当面”指当着面、公开地，与“背后”的“暗地里、不当面”意思相对。", "手机": "无关：“手机”是物品，与“暗地里”没有反义关系。", "河流": "无关：“河流”是自然事物，与“暗地里”没有反义关系。", "天空": "无关：“天空”是自然景物，与“暗地里”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab2ec06d-117f-4282-82e1-1de125000776') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86808, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "当面", "is_correct": true, "explanation": "正确：“当面”指当着面、公开地，与“背后”的“暗地里、不当面”意思相对。"}, {"text": "牛奶", "is_correct": false, "explanation": "无关：“牛奶”是饮品，与“暗地里”没有反义关系。"}, {"text": "书桌", "is_correct": false, "explanation": "无关：“书桌”是家具，与“暗地里”没有反义关系。"}, {"text": "云朵", "is_correct": false, "explanation": "无关：“云朵”是自然景物，与“暗地里”没有反义关系。"}], "correct_answer": "当面", "explanations": {"当面": "正确：“当面”指当着面、公开地，与“背后”的“暗地里、不当面”意思相对。", "牛奶": "无关：“牛奶”是饮品，与“暗地里”没有反义关系。", "书桌": "无关：“书桌”是家具，与“暗地里”没有反义关系。", "云朵": "无关：“云朵”是自然景物，与“暗地里”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab2ec06d-117f-4282-82e1-1de125000776') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86808, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "暗地里，不当面；事情表面之后不为人见的部分。", "primary_collocate": null, "pronunciation": "bèi hòu", "ipa": "peɪ˥˩ xoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "他从不在背后说我。", "target_word": "背后", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "成功的背后是很多努力。", "target_word": "背后", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大家都在背后叫他“老大”。", "target_word": "背后", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "别在背后说别人的坏话。", "target_word": "背后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有话就当面说，不要在背后说。", "target_word": "背后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事的背后有一个故事。", "target_word": "背后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她在背后帮了我很多忙。", "target_word": "背后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不要在别人背后议论他们的生活。", "target_word": "背后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司的背后有一个很有钱的老板。", "target_word": "背后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我发现这件事的背后，其实有人在帮他。", "target_word": "背后", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "背後", "label": "繁体"}], "register": "中性", "sense_fingerprint": "背后：暗地里、不当面，或事情表面之后的隐藏部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dfa9012-682f-47cd-812e-5fb770f93c09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86808, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "背后", "is_correct": true, "explanation": "正确：“背后”表示暗地里、不当面，与“说我”搭配。"}, {"text": "天空", "is_correct": false, "explanation": "语义：“天空”不是说话的场所，“在天空说我”说不通。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：表示处所要说“桌子上”，“在桌子说我”不成立。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”不是说话的场所，句子不通。"}], "explanations": {"背后": "正确：“背后”表示暗地里、不当面，与“说我”搭配。", "天空": "语义：“天空”不是说话的场所，“在天空说我”说不通。", "桌子": "搭配：表示处所要说“桌子上”，“在桌子说我”不成立。", "石头": "语义：“石头”不是说话的场所，句子不通。"}, "sentence_index": 0, "correct_answer": "背后"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在背后当着大家的面批评了我。", "explanation": "这里应该用〈当面〉。“背后”指暗地里、不当面，而“当着大家的面”是公开的，两者矛盾。"}, {"text": "你有意见就在背后直接告诉我吧。", "explanation": "这里应该用〈当面〉。“直接告诉我”是当着我的面说，“背后”指不当面，两者不能搭配。"}, {"text": "他在背后公开地宣布了比赛结果。", "explanation": "这里应该用〈当众〉。“背后”指暗地里，“公开地宣布”是当众的行为，两者矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab2ec06d-117f-4282-82e1-1de125000776') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86808, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "背后", "is_correct": true, "explanation": "正确：“背后”表示暗地里，修饰“帮了我很多忙”，符合语境。"}, {"text": "名字", "is_correct": false, "explanation": "语义：“名字”不是帮忙的场所，“在名字帮了我”说不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不能作帮忙的场所，句子不成立。"}, {"text": "饼干", "is_correct": false, "explanation": "搭配：“在……帮忙”需要人或处所，“饼干”不能这样用。"}], "explanations": {"背后": "正确：“背后”表示暗地里，修饰“帮了我很多忙”，符合语境。", "名字": "语义：“名字”不是帮忙的场所，“在名字帮了我”说不通。", "颜色": "语义：“颜色”不能作帮忙的场所，句子不成立。", "饼干": "搭配：“在……帮忙”需要人或处所，“饼干”不能这样用。"}, "sentence_index": 6, "correct_answer": "背后"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在背后公开地给大家发了奖。", "explanation": "这里应该用〈当众〉。“背后”指暗地里，“公开地给大家发奖”是当众的行为，两者矛盾。"}, {"text": "他背后对大家说，我们都很高兴。", "explanation": "这里应该用〈当面〉。“背后”指暗地里，“对大家说”是公开的行为，两者不能搭配。"}, {"text": "这件事的背后，我们吃了一顿饭。", "explanation": "这里应该用〈之后〉。“背后”不表示时间先后，“这件事之后”才表示事情发生以后的时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab2ec06d-117f-4282-82e1-1de125000776') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86808, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他从不在背后的批评朋友。", "corrected_sentence": "他从不在背后批评朋友。", "error_description": "错误：“在背后的批评”。正确：“在背后批评”。“背后”作状语修饰动词时，其后不加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab2ec06d-117f-4282-82e1-1de125000776') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86808, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他对背后默默地支持我。", "corrected_sentence": "他在背后默默地支持我。", "error_description": "错误：“他对背后默默地支持我”。正确：“他在背后默默地支持我”。表示“暗地里”时要用介词“在”引出“背后”，“对”不能引出这一处所。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab2ec06d-117f-4282-82e1-1de125000776') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
