INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86809, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，用在形容词或名词性短语前，强调说话人的感叹、夸奖或不满。", "primary_collocate": null, "pronunciation": "zhēn shì", "ipa": "ʈʂən˥ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "你做的饭真是太好吃了！", "target_word": "真是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天的天气真是好极了。", "target_word": "真是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个孩子真是聪明。", "target_word": "真是", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你真是个好人。", "target_word": "真是", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这场雨真是下得太大了。", "target_word": "真是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他真是一个让人生气的人。", "target_word": "真是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你们能来，我真是太高兴了。", "target_word": "真是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她唱歌真是好听，大家都鼓掌。", "target_word": "真是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "又迟到了，你真是太让我失望了。", "target_word": "真是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家饭馆的菜真是又好又便宜。", "target_word": "真是", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "用在形容词或名词前，强调说话人的感叹、夸奖或不满", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7ebaaf2-ff86-4acd-81d5-d33d40a45ed1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86809, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "从来", "is_correct": false, "explanation": "语义：“从来”表示一直以来，与品尝饭菜后当下的感叹语境不合。"}, {"text": "真是", "is_correct": true, "explanation": "“真是”是副词，修饰后面的“太好吃了”，表示说话人的感叹，符合语境。"}, {"text": "特此", "is_correct": false, "explanation": "语域：“特此”是公文用语，不能用于品尝饭菜后的口语感叹。"}, {"text": "共同", "is_correct": false, "explanation": "搭配：“共同”要求多个主体一起做某事，“你做的饭”只是一个主语，不能搭配。"}], "explanations": {"从来": "语义：“从来”表示一直以来，与品尝饭菜后当下的感叹语境不合。", "真是": "“真是”是副词，修饰后面的“太好吃了”，表示说话人的感叹，符合语境。", "特此": "语域：“特此”是公文用语，不能用于品尝饭菜后的口语感叹。", "共同": "搭配：“共同”要求多个主体一起做某事，“你做的饭”只是一个主语，不能搭配。"}, "sentence_index": 0, "correct_answer": "真是"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很真是聪明，每次考试都第一。", "explanation": "这里应该删去〈很〉。真是已表示程度强，不能再与很同时修饰形容词；直接说“他真是聪明”即可。"}, {"text": "这个真是孩子聪明。", "explanation": "语序错误：真是应放在主语之后，写作“这个孩子真是聪明”。"}, {"text": "这个菜不真是好吃。", "explanation": "这里应该删去〈不〉。感叹用的“真是”前面不能加“不”来否定；要表示否定，可以说“这个菜真是不好吃”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b98cb1a-b764-4cf7-8b0f-bea141ae3341') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86809, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "最", "is_correct": false, "explanation": "搭配：“最”与“太”不同时修饰同一个形容词，“我最太高兴了”不通顺。"}, {"text": "真是", "is_correct": true, "explanation": "“真是”是副词，强调“太高兴了”的心情，与前面“你们能来”的语境相合。"}, {"text": "亲自", "is_correct": false, "explanation": "语义：“亲自”要求有具体的动作，与表示心情的“高兴”不合。"}, {"text": "一起", "is_correct": false, "explanation": "语义：“一起”表示共同做事，与表达个人心情的语境不合。"}], "explanations": {"最": "搭配：“最”与“太”不同时修饰同一个形容词，“我最太高兴了”不通顺。", "真是": "“真是”是副词，强调“太高兴了”的心情，与前面“你们能来”的语境相合。", "亲自": "语义：“亲自”要求有具体的动作，与表示心情的“高兴”不合。", "一起": "语义：“一起”表示共同做事，与表达个人心情的语境不合。"}, "sentence_index": 6, "correct_answer": "真是"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我很真是饿了。", "explanation": "这里应该删去〈很〉。真是已表示程度强，不能与很同时修饰形容词；说“我真是饿了”即可。"}, {"text": "这家饭馆的菜真是的好。", "explanation": "这里应该删去〈的〉。真是后直接接形容词，不能加结构助词“的”。"}, {"text": "这本书不真是有意思。", "explanation": "这里应该删去〈不〉。感叹用的“真是”前面不能加“不”来否定；可以说“这本书真是没意思”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b98cb1a-b764-4cf7-8b0f-bea141ae3341') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86809, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这盘菜真是是好吃。", "corrected_sentence": "这盘菜真是好吃。", "error_description": "“真是”后面直接接形容词，不能重复“是”；正确说法是“这盘菜真是好吃”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b98cb1a-b764-4cf7-8b0f-bea141ae3341') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86809, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这顿晚饭真是个丰盛。", "corrected_sentence": "这顿晚饭真是丰盛。", "error_description": "“真是”后面直接接形容词，不能加量词“个”；正确说法是“这顿晚饭真是丰盛”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b98cb1a-b764-4cf7-8b0f-bea141ae3341') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
