INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86810, 1, 'prompt1_core', '{"pos": "叹词", "semantic_class": "function", "definition": "口语中表示不满、责怪，或感叹的说法。", "primary_collocate": null, "pronunciation": "zhēn shì", "ipa": "ʈʂən˥ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "你真是，怎么又忘了带钥匙？", "target_word": "真是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他真是，也不打个电话就走了。", "target_word": "真是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "真是，下雨天还要我出去买东西！", "target_word": "真是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你们真是，这么晚才告诉我。", "target_word": "真是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟真是，又把水洒在地上了。", "target_word": "真是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板真是，周末还让大家来加班。", "target_word": "真是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "真是，我说了多少遍，你还不听！", "target_word": "真是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你真是，开会的时候怎么玩手机？", "target_word": "真是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小王真是，约好了又不来。", "target_word": "真是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈说：“你真是，衣服又乱放！”", "target_word": "真是", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "口语中用来抱怨、责怪别人的插入语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7ebaaf2-ff86-4acd-81d5-d33d40a45ed1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86810, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "真是", "is_correct": true, "explanation": "“真是”读作 zhēn shì，是口语中表示责怪或感叹的说法，是目标词。"}, {"text": "真实", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，“真实”指符合事实的，意思不同。"}, {"text": "阵势", "is_correct": false, "explanation": "zhēn（第一声）与 zhèn（第四声）声调不同，阵势指队列或局势，意思不同。"}, {"text": "正是", "is_correct": false, "explanation": "zhēn 与 zhèng 韵母不同（en 与 eng），“正是”表示恰好、确定，不表示责怪。"}], "explanations": {"真是": "“真是”读作 zhēn shì，是口语中表示责怪或感叹的说法，是目标词。", "真实": "shì（第四声）与 shí（第二声）声调不同，“真实”指符合事实的，意思不同。", "阵势": "zhēn（第一声）与 zhèn（第四声）声调不同，阵势指队列或局势，意思不同。", "正是": "zhēn 与 zhèng 韵母不同（en 与 eng），“正是”表示恰好、确定，不表示责怪。"}, "sentence_index": null, "correct_answer": "真是"}, "level_3": {"options": [{"text": "哈哈", "is_correct": false, "explanation": "语义：“哈哈”是笑声，与句子中责怪的语气相矛盾。"}, {"text": "真是", "is_correct": true, "explanation": "“真是”是口语叹词，用来表示责怪，与后面“怎么又忘了带钥匙”的语气一致。"}, {"text": "谢谢", "is_correct": false, "explanation": "搭配：“谢谢”是表示感谢的固定用语，不能用来开头责备别人。"}, {"text": "哇", "is_correct": false, "explanation": "语义：“哇”表示惊叹或赞赏，不表示责怪，与句子语气不合。"}], "explanations": {"哈哈": "语义：“哈哈”是笑声，与句子中责怪的语气相矛盾。", "真是": "“真是”是口语叹词，用来表示责怪，与后面“怎么又忘了带钥匙”的语气一致。", "谢谢": "搭配：“谢谢”是表示感谢的固定用语，不能用来开头责备别人。", "哇": "语义：“哇”表示惊叹或赞赏，不表示责怪，与句子语气不合。"}, "sentence_index": 0, "correct_answer": "真是"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个孩子很真是，又乱放东西。", "explanation": "这里应该删去〈很〉。叹词“真是”表示责怪，不能受程度副词“很”修饰；说“这个孩子真是，又乱放东西”即可。"}, {"text": "这个真是孩子又乱放东西。", "explanation": "语序错误：真是应放在主语之后，写作“这个孩子真是又乱放东西”。"}, {"text": "真是，我们班一共三十个人。", "explanation": "这里应该删去〈真是〉。叹词真是带有责怪或感叹，客观陈述人数时多余。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b98cb1a-b764-4cf7-8b0f-bea141ae3341') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86810, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "真是", "is_correct": true, "explanation": "“真是”读作 zhēn shì，是口语中表示责怪的说法，是目标词。"}, {"text": "展示", "is_correct": false, "explanation": "zhēn 与 zhǎn 韵母（en/an）和声调都不同，“展示”指把东西呈现出来，意思不同。"}, {"text": "战士", "is_correct": false, "explanation": "zhēn 与 zhàn 韵母（en/an）和声调都不同，“战士”指军人，意思不同。"}, {"text": "诊室", "is_correct": false, "explanation": "zhēn（第一声）与 zhěn（第三声）声调不同，“诊室”指医生看病的房间，意思不同。"}], "explanations": {"真是": "“真是”读作 zhēn shì，是口语中表示责怪的说法，是目标词。", "展示": "zhēn 与 zhǎn 韵母（en/an）和声调都不同，“展示”指把东西呈现出来，意思不同。", "战士": "zhēn 与 zhàn 韵母（en/an）和声调都不同，“战士”指军人，意思不同。", "诊室": "zhēn（第一声）与 zhěn（第三声）声调不同，“诊室”指医生看病的房间，意思不同。"}, "sentence_index": null, "correct_answer": "真是"}, "level_3": {"options": [{"text": "谢谢", "is_correct": false, "explanation": "语义：“谢谢”表示感谢，与责备对方的语气相反。"}, {"text": "真是", "is_correct": true, "explanation": "“真是”放在句首表示责备，与后面“我说了多少遍，你还不听”的抱怨语气一致。"}, {"text": "早上好", "is_correct": false, "explanation": "语义：“早上好”是问候语，不能表示责备或抱怨。"}, {"text": "嘻嘻", "is_correct": false, "explanation": "语义：“嘻嘻”是笑声，与句子中责备的语气相矛盾。"}], "explanations": {"谢谢": "语义：“谢谢”表示感谢，与责备对方的语气相反。", "真是": "“真是”放在句首表示责备，与后面“我说了多少遍，你还不听”的抱怨语气一致。", "早上好": "语义：“早上好”是问候语，不能表示责备或抱怨。", "嘻嘻": "语义：“嘻嘻”是笑声，与句子中责备的语气相矛盾。"}, "sentence_index": 6, "correct_answer": "真是"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的真是书包很重。", "explanation": "语序错误：真是不能插在定语“我的”与中心语“书包”之间；应写作“我的书包真是很重”。"}, {"text": "这些书真是，一共三本。", "explanation": "这里应该删去〈真是〉。叹词真是带有责怪或感叹，客观陈述数量时多余。"}, {"text": "真是，他昨天在图书馆借了三本书。", "explanation": "这里应该删去〈真是〉。叹词真是带有不满或感叹，叙述中性的已发生事实时多余。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b98cb1a-b764-4cf7-8b0f-bea141ae3341') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86810, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你真是了，又把窗户打开了。", "corrected_sentence": "你真是，又把窗户打开了。", "error_description": "“真是”作叹词，后面不能加助词“了”；正确说法是“你真是，又把窗户打开了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b98cb1a-b764-4cf7-8b0f-bea141ae3341') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86810, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "真是个，这孩子又把玩具弄坏了。", "corrected_sentence": "真是，这孩子又把玩具弄坏了。", "error_description": "“真是”作叹词，后面不能加量词“个”；正确说法是“真是，这孩子又把玩具弄坏了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b98cb1a-b764-4cf7-8b0f-bea141ae3341') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86811, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "明亮", "is_correct": false, "explanation": "“明亮”说的是光线或颜色，与说明是否完备无关，不是“详细”的反义词。"}, {"text": "简略", "is_correct": true, "explanation": "“简略”与“详细”构成反义：“详细”是讲得清楚、什么都讲到，“简略”是只说大概、不展开，正好相反。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”与“吵闹”相对，和“详细”没有反义关系。"}, {"text": "快速", "is_correct": false, "explanation": "“快速”说的是速度，与“详细”的反义关系不成立。"}], "correct_answer": "简略", "explanations": {"明亮": "“明亮”说的是光线或颜色，与说明是否完备无关，不是“详细”的反义词。", "简略": "“简略”与“详细”构成反义：“详细”是讲得清楚、什么都讲到，“简略”是只说大概、不展开，正好相反。", "安静": "“安静”与“吵闹”相对，和“详细”没有反义关系。", "快速": "“快速”说的是速度，与“详细”的反义关系不成立。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f59eef98-5920-4c5f-afac-18238bea63cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86811, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "干净", "is_correct": false, "explanation": "“干净”说的是整洁，与“详细”没有反义关系。"}, {"text": "柔软", "is_correct": false, "explanation": "“柔软”说的是质地，与“详细”没有反义关系。"}, {"text": "简略", "is_correct": true, "explanation": "“简略”与“详细”构成反义：“详细”是讲得完备，“简略”是只说大概，正好相反。"}, {"text": "温暖", "is_correct": false, "explanation": "“温暖”说的是温度或感情，与“详细”没有反义关系。"}], "correct_answer": "简略", "explanations": {"干净": "“干净”说的是整洁，与“详细”没有反义关系。", "柔软": "“柔软”说的是质地，与“详细”没有反义关系。", "简略": "“简略”与“详细”构成反义：“详细”是讲得完备，“简略”是只说大概，正好相反。", "温暖": "“温暖”说的是温度或感情，与“详细”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f59eef98-5920-4c5f-afac-18238bea63cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86811, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "详细是说得很清楚，什么都讲到了。", "primary_collocate": null, "pronunciation": "xiáng xì", "ipa": "ɕiɑŋ˧˥ ɕi˥˩", "syllable_count": 2, "sentences": [{"text": "老师讲得很详细。", "target_word": "详细", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你详细说一说。", "target_word": "详细", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把事情说得很详细。", "target_word": "详细", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书写得很详细。", "target_word": "详细", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图画得不太详细。", "target_word": "详细", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她详细地告诉了我路线。", "target_word": "详细", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把你的想法详细写下来。", "target_word": "详细", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的介绍很详细，我听懂了。", "target_word": "详细", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生详细问了我的病情。", "target_word": "详细", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你说得不够详细。", "target_word": "详细", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "詳細", "label": "繁体"}], "register": "中性", "sense_fingerprint": "说得清楚，什么都讲到了", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25be5f49-5a16-4b1c-a339-0cf287f7ff26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86811, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "相惜", "is_correct": false, "explanation": "xiāng xī（相惜）两个音节的声调都与 xiáng xì 不同，意思是互相爱惜。"}, {"text": "详细", "is_correct": true, "explanation": "正确答案：详细 xiáng xì，意思是说得很清楚、什么都讲到了。"}, {"text": "纤细", "is_correct": false, "explanation": "xiān xì（纤细）第一音节韵尾 n 与 ng 不同，声调也不同，第二音节相同，意思是细长柔弱。"}, {"text": "相似", "is_correct": false, "explanation": "xiāng sì（相似）第一音节声调不同，第二音节声母 s 与 x 不同，意思是相像。"}], "explanations": {"相惜": "xiāng xī（相惜）两个音节的声调都与 xiáng xì 不同，意思是互相爱惜。", "详细": "正确答案：详细 xiáng xì，意思是说得很清楚、什么都讲到了。", "纤细": "xiān xì（纤细）第一音节韵尾 n 与 ng 不同，声调也不同，第二音节相同，意思是细长柔弱。", "相似": "xiāng sì（相似）第一音节声调不同，第二音节声母 s 与 x 不同，意思是相像。"}, "sentence_index": null, "correct_answer": "详细"}, "level_3": {"options": [{"text": "冷", "is_correct": false, "explanation": "语义：“冷”说的是温度，不能用来形容讲课的清楚程度。"}, {"text": "高", "is_correct": false, "explanation": "语义：“高”说的是高度，不能用来形容讲话是否清楚完备。"}, {"text": "详细", "is_correct": true, "explanation": "正确：“详细”表示讲得清楚、什么都讲到了，与“讲得很”搭配自然。"}, {"text": "红", "is_correct": false, "explanation": "搭配：“红”不能与“讲得很”搭配，表示讲课的状态。"}], "explanations": {"冷": "语义：“冷”说的是温度，不能用来形容讲课的清楚程度。", "高": "语义：“高”说的是高度，不能用来形容讲话是否清楚完备。", "详细": "正确：“详细”表示讲得清楚、什么都讲到了，与“讲得很”搭配自然。", "红": "搭配：“红”不能与“讲得很”搭配，表示讲课的状态。"}, "sentence_index": 0, "correct_answer": "详细"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的性格很详细，大家都喜欢和他做朋友。", "explanation": "这里应该用〈细致〉。“详细”指说明、计划讲得完备，形容人的性格细心周到要用“细致”，“详细”不能用来形容性格。"}, {"text": "我今天的心情很详细。", "explanation": "这里应该用〈细腻〉。“细腻”形容心思敏感体贴，形容心情要用“细腻”；“详细”指说明讲得完备，不能用来形容心情。"}, {"text": "他笑得很详细，大家都被逗乐了。", "explanation": "“详细”指把事情说得清楚、什么都讲到，只用于讲、写、说明等，不能用来形容笑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f59eef98-5920-4c5f-afac-18238bea63cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86811, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "向西", "is_correct": false, "explanation": "xiàng xī（向西）两个音节的声调都与 xiáng xì 不同，意思是朝西。"}, {"text": "相信", "is_correct": false, "explanation": "xiāng xìn（相信）第一音节声调不同，第二音节多了韵尾 n，意思是认为可靠。"}, {"text": "详细", "is_correct": true, "explanation": "正确答案：详细 xiáng xì，意思是说得很清楚、什么都讲到了。"}, {"text": "向心", "is_correct": false, "explanation": "xiàng xīn（向心）第一音节声调不同，第二音节多了韵尾 n 且声调不同，意思是朝向中心。"}], "explanations": {"向西": "xiàng xī（向西）两个音节的声调都与 xiáng xì 不同，意思是朝西。", "相信": "xiāng xìn（相信）第一音节声调不同，第二音节多了韵尾 n，意思是认为可靠。", "详细": "正确答案：详细 xiáng xì，意思是说得很清楚、什么都讲到了。", "向心": "xiàng xīn（向心）第一音节声调不同，第二音节多了韵尾 n 且声调不同，意思是朝向中心。"}, "sentence_index": null, "correct_answer": "详细"}, "level_3": {"options": [{"text": "激烈", "is_correct": false, "explanation": "语义：“激烈”形容冲突或动作的强烈，不能用来修饰把想法写下来的动作。"}, {"text": "详细", "is_correct": true, "explanation": "正确：“详细”表示说得清楚、什么都讲到了，可以修饰“写下来”。"}, {"text": "响亮", "is_correct": false, "explanation": "搭配：“响亮”形容声音，与“写下来”不搭配。"}, {"text": "大声", "is_correct": false, "explanation": "语义：“大声”说的是声音，把想法写下来的动作不能用“大声”来形容。"}], "explanations": {"激烈": "语义：“激烈”形容冲突或动作的强烈，不能用来修饰把想法写下来的动作。", "详细": "正确：“详细”表示说得清楚、什么都讲到了，可以修饰“写下来”。", "响亮": "搭配：“响亮”形容声音，与“写下来”不搭配。", "大声": "语义：“大声”说的是声音，把想法写下来的动作不能用“大声”来形容。"}, "sentence_index": 6, "correct_answer": "详细"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的声音很详细，坐在后面的人也听得很清楚。", "explanation": "这里误把“详细”当成〈清晰〉的意思，即清楚分明。“清晰”形容声音、发音清楚，“详细”指说明讲得完备，不能形容声音。"}, {"text": "这间房间很详细，阳光照进来特别暖。", "explanation": "这里误把“详细”当成〈明亮〉的意思，即亮堂透彻。“明亮”形容光线充足，“详细”不能用来形容房间的光线。"}, {"text": "周末我们过得很详细，大家都很开心。", "explanation": "这里误把“详细”当成〈充实〉的意思，即丰富饱满。“充实”形容日子过得丰富有意义，“详细”不能形容生活状态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f59eef98-5920-4c5f-afac-18238bea63cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86811, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把路线讲很详细，我一下子就明白了。", "corrected_sentence": "她把路线讲得很详细，我一下子就明白了。", "error_description": "错误：“讲很详细”，漏掉了补语前的“得”。正确：“讲得很详细”。“详细”作补语说明“讲”的程度，要用“得”连接，漏掉“得”就不成话。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f59eef98-5920-4c5f-afac-18238bea63cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86811, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她详细的解释了每一个步骤。", "corrected_sentence": "她详细地解释了每一个步骤。", "error_description": "错误：“详细的解释了”。正确：“详细地解释了”。“详细”在动词前作状语时要用“地”，用“的”会把它当成定语，后面接动词就不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f59eef98-5920-4c5f-afac-18238bea63cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86812, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "温暖", "is_correct": false, "explanation": "“温暖”说的是温度或感情，与“详细”没有反义关系。"}, {"text": "简略", "is_correct": true, "explanation": "“简略”与“详细”构成反义：“详细”是周密完备、细节很多，“简略”是只说大概，正好相反。"}, {"text": "柔软", "is_correct": false, "explanation": "“柔软”说的是质地，与“详细”没有反义关系。"}, {"text": "干净", "is_correct": false, "explanation": "“干净”说的是整洁，与“详细”没有反义关系。"}], "correct_answer": "简略", "explanations": {"温暖": "“温暖”说的是温度或感情，与“详细”没有反义关系。", "简略": "“简略”与“详细”构成反义：“详细”是周密完备、细节很多，“简略”是只说大概，正好相反。", "柔软": "“柔软”说的是质地，与“详细”没有反义关系。", "干净": "“干净”说的是整洁，与“详细”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f59eef98-5920-4c5f-afac-18238bea63cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86812, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "安静", "is_correct": false, "explanation": "“安静”与“吵闹”相对，和“详细”没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”说的是光线或颜色，与说明是否完备无关，不是“详细”的反义词。"}, {"text": "快速", "is_correct": false, "explanation": "“快速”说的是速度，与“详细”的反义关系不成立。"}, {"text": "简略", "is_correct": true, "explanation": "“简略”与“详细”构成反义：“详细”是周密完备，“简略”是只说大概，正好相反。"}], "correct_answer": "简略", "explanations": {"安静": "“安静”与“吵闹”相对，和“详细”没有反义关系。", "明亮": "“明亮”说的是光线或颜色，与说明是否完备无关，不是“详细”的反义词。", "快速": "“快速”说的是速度，与“详细”的反义关系不成立。", "简略": "“简略”与“详细”构成反义：“详细”是周密完备，“简略”是只说大概，正好相反。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f59eef98-5920-4c5f-afac-18238bea63cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86812, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "周密完备；细节很多。", "primary_collocate": null, "pronunciation": "xiáng xì", "ipa": "ɕiɑŋ˧˥ ɕi˥˩", "syllable_count": 2, "sentences": [{"text": "这是一份很详细的计划。", "target_word": "详细", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做了详细的记录。", "target_word": "详细", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行计划写得非常详细。", "target_word": "详细", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报告里有详细的数据。", "target_word": "详细", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张表很详细，每一项都写了。", "target_word": "详细", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈的菜谱很详细，每一步都有图。", "target_word": "详细", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请看详细的说明书。", "target_word": "详细", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的调查很详细。", "target_word": "详细", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察做了详细的检查。", "target_word": "详细", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地址不够详细。", "target_word": "详细", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "詳細", "label": "繁体"}], "register": "中性", "sense_fingerprint": "周密完备，细节很多", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25be5f49-5a16-4b1c-a339-0cf287f7ff26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86812, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "相惜", "is_correct": false, "explanation": "xiāng xī（相惜）两个音节的声调都与 xiáng xì 不同，意思是互相爱惜。"}, {"text": "详细", "is_correct": true, "explanation": "正确答案：详细 xiáng xì，意思是周密完备、细节很多。"}, {"text": "纤细", "is_correct": false, "explanation": "xiān xì（纤细）第一音节韵尾 n 与 ng 不同，声调也不同，第二音节相同，意思是细长柔弱。"}, {"text": "相似", "is_correct": false, "explanation": "xiāng sì（相似）第一音节声调不同，第二音节声母 s 与 x 不同，意思是相像。"}], "explanations": {"相惜": "xiāng xī（相惜）两个音节的声调都与 xiáng xì 不同，意思是互相爱惜。", "详细": "正确答案：详细 xiáng xì，意思是周密完备、细节很多。", "纤细": "xiān xì（纤细）第一音节韵尾 n 与 ng 不同，声调也不同，第二音节相同，意思是细长柔弱。", "相似": "xiāng sì（相似）第一音节声调不同，第二音节声母 s 与 x 不同，意思是相像。"}, "sentence_index": null, "correct_answer": "详细"}, "level_3": {"options": [{"text": "甜", "is_correct": false, "explanation": "语义：“甜”说的是味道，计划没有味道，不能这样形容。"}, {"text": "详细", "is_correct": true, "explanation": "正确：“详细”表示周密完备、细节很多，正好修饰“计划”。"}, {"text": "冷", "is_correct": false, "explanation": "语义：“冷”说的是温度，不能用来形容计划。"}, {"text": "响亮", "is_correct": false, "explanation": "搭配：“响亮”形容声音，与“计划”不搭配。"}], "explanations": {"甜": "语义：“甜”说的是味道，计划没有味道，不能这样形容。", "详细": "正确：“详细”表示周密完备、细节很多，正好修饰“计划”。", "冷": "语义：“冷”说的是温度，不能用来形容计划。", "响亮": "搭配：“响亮”形容声音，与“计划”不搭配。"}, "sentence_index": 0, "correct_answer": "详细"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的心里很详细，一直放不下那件事。", "explanation": "“详细”形容计划、资料等内容周密完备，不能用来形容人心里放不下事的感受。"}, {"text": "街上很详细，人来人往的。", "explanation": "这里误把“详细”当成〈繁多〉的意思，即细节很多。“详细”的这一义只用于计划、资料等，不能用来形容街上人多。"}, {"text": "这间房子很详细，一家人住正好。", "explanation": "这里误把“详细”当成〈完善〉的意思，即周密完备。“完善”形容设施、条件齐全，“详细”只用于说明、计划等，不能用来形容房子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f59eef98-5920-4c5f-afac-18238bea63cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86812, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "向西", "is_correct": false, "explanation": "xiàng xī（向西）两个音节的声调都与 xiáng xì 不同，意思是朝西。"}, {"text": "相信", "is_correct": false, "explanation": "xiāng xìn（相信）第一音节声调不同，第二音节多了韵尾 n，意思是认为可靠。"}, {"text": "详细", "is_correct": true, "explanation": "正确答案：详细 xiáng xì，意思是周密完备、细节很多。"}, {"text": "向心", "is_correct": false, "explanation": "xiàng xīn（向心）第一音节声调不同，第二音节多了韵尾 n 且声调不同，意思是朝向中心。"}], "explanations": {"向西": "xiàng xī（向西）两个音节的声调都与 xiáng xì 不同，意思是朝西。", "相信": "xiāng xìn（相信）第一音节声调不同，第二音节多了韵尾 n，意思是认为可靠。", "详细": "正确答案：详细 xiáng xì，意思是周密完备、细节很多。", "向心": "xiàng xīn（向心）第一音节声调不同，第二音节多了韵尾 n 且声调不同，意思是朝向中心。"}, "sentence_index": null, "correct_answer": "详细"}, "level_3": {"options": [{"text": "苦", "is_correct": false, "explanation": "语义：“苦”形容味道，不能用来修饰说明书。"}, {"text": "大声", "is_correct": false, "explanation": "语义：“大声”形容声音，不能用来修饰说明书。"}, {"text": "详细", "is_correct": true, "explanation": "正确：“详细”修饰“说明书”，表示内容完备、讲得清楚。"}, {"text": "辣", "is_correct": false, "explanation": "搭配：“辣”形容味道，与“说明书”不搭配。"}], "explanations": {"苦": "语义：“苦”形容味道，不能用来修饰说明书。", "大声": "语义：“大声”形容声音，不能用来修饰说明书。", "详细": "正确：“详细”修饰“说明书”，表示内容完备、讲得清楚。", "辣": "搭配：“辣”形容味道，与“说明书”不搭配。"}, "sentence_index": 6, "correct_answer": "详细"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "教室里很详细，大家学习很专心。", "explanation": "这里误把“详细”当成〈明亮〉的意思，即亮堂清楚。“明亮”形容光线充足，“详细”不能用来形容教室的光线。"}, {"text": "灯光很详细，照得人很舒服。", "explanation": "这里误把“详细”当成〈充足〉的意思，即数量足够。“充足”形容光线、数量够多，“详细”不能用来形容灯光。"}, {"text": "大家很详细，一起唱着歌。", "explanation": "这里误把“详细”当成〈热情〉的意思。“热情”形容待人态度亲切，“详细”只用于说明或资料，不能用来形容人的态度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f59eef98-5920-4c5f-afac-18238bea63cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86812, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份说明书写很详细，连每个按钮都有说明。", "corrected_sentence": "这份说明书写得很详细，连每个按钮都有说明。", "error_description": "错误：“写很详细”，漏掉了补语前的“得”。正确：“写得很详细”。“详细”作补语说明“写”的程度，要用“得”连接，漏掉“得”就不成话。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f59eef98-5920-4c5f-afac-18238bea63cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86812, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他详细的记录了每一笔开支。", "corrected_sentence": "他详细地记录了每一笔开支。", "error_description": "错误：“详细的记录了”。正确：“详细地记录了”。“详细”在动词前作状语时要用“地”，用“的”会把它当成定语，后面接动词就不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f59eef98-5920-4c5f-afac-18238bea63cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
