INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86813, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "而是用在“不是”后面，说出真正的样子。", "primary_collocate": null, "pronunciation": "ér shì", "ipa": "ɚ˧˥ ʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "他不是不想去，而是没有时间。", "target_word": "而是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不是老师，而是学生。", "target_word": "而是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这不是我的书，而是她的。", "target_word": "而是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不是在哭，而是在笑。", "target_word": "而是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不是没钱，而是不想买。", "target_word": "而是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我今天不是坐车来的，而是走路来的。", "target_word": "而是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "问题不是太难，而是我没认真看。", "target_word": "而是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不是生气了，而是有点累。", "target_word": "而是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里不是学校，而是医院。", "target_word": "而是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢的不是苹果，而是香蕉。", "target_word": "而是", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "不是A而是B，否定A，说出真实情况B", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25be5f49-5a16-4b1c-a339-0cf287f7ff26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86813, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "所以", "is_correct": false, "explanation": "语义：“所以”表示因果结果，与前面的否定不相接，句意不通。"}, {"text": "而是", "is_correct": true, "explanation": "正确：“而是”与前面的“不是”配对，否定“不想去”的说法后引出真正的原因。"}, {"text": "或者", "is_correct": false, "explanation": "语义：“或者”表示选择，不能用来纠正前面的否定。"}, {"text": "如果", "is_correct": false, "explanation": "搭配：“如果”要和“就”配合，句中没有“就”，结构不完整。"}], "explanations": {"所以": "语义：“所以”表示因果结果，与前面的否定不相接，句意不通。", "而是": "正确：“而是”与前面的“不是”配对，否定“不想去”的说法后引出真正的原因。", "或者": "语义：“或者”表示选择，不能用来纠正前面的否定。", "如果": "搭配：“如果”要和“就”配合，句中没有“就”，结构不完整。"}, "sentence_index": 0, "correct_answer": "而是"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他不是不想去，而是不想去。", "explanation": "这里误把“而是”用来重复前面被否定的内容。“而是”要引出与“不是”所否定的内容不同的真正情况，这句说的是同一件事，应直接说“他想去”或“他不想去”。"}, {"text": "这不是我的伞，而是我的伞。", "explanation": "这里误把“而是”用来重复前面被否定的内容。“不是”否定了“这是我的伞”，“而是”却又说回“我的伞”，前后矛盾，“而是”不能这样用。"}, {"text": "我不是没吃饭，而是没吃饭。", "explanation": "这里误把“而是”用来重复前面被否定的内容。“不是没吃饭”后又说“没吃饭”，前后是同一件事，“而是”应引出不同的真正情况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f59eef98-5920-4c5f-afac-18238bea63cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86813, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "否则", "is_correct": false, "explanation": "语义：“否则”表示不这样就会怎样，与前面的否定不相接，句意不通。"}, {"text": "然后", "is_correct": false, "explanation": "语义：“然后”表示先后顺序，不能引出“没认真看”这一纠正。"}, {"text": "而是", "is_correct": true, "explanation": "正确：“而是”与前面的“不是”配对，否定“问题太难”后引出真正的原因。"}, {"text": "虽然", "is_correct": false, "explanation": "搭配：“虽然”要和“但是”或“却”配合，这里没有对应的转折词。"}], "explanations": {"否则": "语义：“否则”表示不这样就会怎样，与前面的否定不相接，句意不通。", "然后": "语义：“然后”表示先后顺序，不能引出“没认真看”这一纠正。", "而是": "正确：“而是”与前面的“不是”配对，否定“问题太难”后引出真正的原因。", "虽然": "搭配：“虽然”要和“但是”或“却”配合，这里没有对应的转折词。"}, "sentence_index": 6, "correct_answer": "而是"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他不是迟到，而是迟到了。", "explanation": "这里误把“而是”用来重复前面被否定的内容。“不是迟到”后又说“迟到了”，前后是同一件事，“而是”应引出不同的真正情况。"}, {"text": "我喜欢的不是苹果，而是苹果。", "explanation": "这里误把“而是”用来重复前面被否定的内容。前面否定了“苹果”，后面又说“苹果”，前后矛盾。"}, {"text": "这里不是学校，而是学校。", "explanation": "这里误把“而是”用来重复前面被否定的内容。“不是学校”后又说“学校”，前后矛盾，“而是”应引出不同的真正情况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f59eef98-5920-4c5f-afac-18238bea63cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86813, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次出差为了开会，而是为了见客户。", "corrected_sentence": "这次出差不是为了开会，而是为了见客户。", "error_description": "错误：“为了开会，而是为了见客户”，漏掉了“不是”。正确：“不是为了开会，而是为了见客户”。“而是”必须与前面的“不是”配对，否定前一个说法后再引出正确的说法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f59eef98-5920-4c5f-afac-18238bea63cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86813, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次失败是我的错，而是系统出了问题。", "corrected_sentence": "这次失败不是我的错，而是系统出了问题。", "error_description": "错误：“是我的错，而是系统出了问题”，“而是”前面缺少与之配对的“不是”。正确：“不是我的错，而是系统出了问题”。“不是”否定前一说法，“而是”再引出真正的情况。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f59eef98-5920-4c5f-afac-18238bea63cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
