INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86814, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f59eef98-5920-4c5f-afac-18238bea63cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86814, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，用在“不是……”之后，引出正确的说法。", "primary_collocate": null, "pronunciation": "ér shì", "ipa": "ɚ˧˥ ʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "他笑不是因为高兴，而是因为紧张。", "target_word": "而是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我来这里不是玩，而是工作。", "target_word": "而是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她要的不是钱，而是时间。", "target_word": "而是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不是天气不好，而是我不想出门。", "target_word": "而是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不是忘了，而是不愿意说。", "target_word": "而是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师不是在骂你，而是在帮你。", "target_word": "而是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要的不是礼物，而是你的心意。", "target_word": "而是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不是不会做，而是做得太慢。", "target_word": "而是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟不是睡着了，而是在听音乐。", "target_word": "而是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不是走了，而是去买东西了。", "target_word": "而是", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "不是……，而是……，引出正确的原因、目的或说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25be5f49-5a16-4b1c-a339-0cf287f7ff26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86814, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "然后", "is_correct": false, "explanation": "语义：“然后”表示先后顺序，不能用来引出“紧张”这一真正原因。"}, {"text": "而是", "is_correct": true, "explanation": "正确：“而是”与“不是”配对，否定“因为高兴”的原因后引出真正的原因“紧张”。"}, {"text": "如果", "is_correct": false, "explanation": "搭配：“如果”要和“就”配合，句中没有“就”，结构不完整。"}, {"text": "所以", "is_correct": false, "explanation": "语义：“所以”表示结果，不能用来引出笑的真正原因。"}], "explanations": {"然后": "语义：“然后”表示先后顺序，不能用来引出“紧张”这一真正原因。", "而是": "正确：“而是”与“不是”配对，否定“因为高兴”的原因后引出真正的原因“紧张”。", "如果": "搭配：“如果”要和“就”配合，句中没有“就”，结构不完整。", "所以": "语义：“所以”表示结果，不能用来引出笑的真正原因。"}, "sentence_index": 0, "correct_answer": "而是"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他不是迟到，而是迟到了。", "explanation": "这里误把“而是”用来重复前面被否定的内容。“不是迟到”后又说“迟到了”，前后是同一件事，“而是”应引出不同的真正情况。"}, {"text": "她要的不是钱，而是钱。", "explanation": "这里误把“而是”用来重复前面被否定的内容。“不是钱”后又说“钱”，前后矛盾，“而是”不能这样用。"}, {"text": "我们不是坐车去，而是坐车去。", "explanation": "这里误把“而是”用来重复前面被否定的内容。“不是坐车去”后又说“坐车去”，前后是同一件事，“而是”应引出不同的真正情况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f59eef98-5920-4c5f-afac-18238bea63cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86814, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "或者", "is_correct": false, "explanation": "语义：“或者”表示选择，不能用来纠正“礼物”这一说法。"}, {"text": "而是", "is_correct": true, "explanation": "正确：“而是”与“不是”配对，否定“礼物”后引出真正想要的“你的心意”。"}, {"text": "虽然", "is_correct": false, "explanation": "搭配：“虽然”要和“但是”或“却”配合，这里没有对应的转折词。"}, {"text": "否则", "is_correct": false, "explanation": "语义：“否则”表示不这样就会怎样，与前面的否定不相接，句意不通。"}], "explanations": {"或者": "语义：“或者”表示选择，不能用来纠正“礼物”这一说法。", "而是": "正确：“而是”与“不是”配对，否定“礼物”后引出真正想要的“你的心意”。", "虽然": "搭配：“虽然”要和“但是”或“却”配合，这里没有对应的转折词。", "否则": "语义：“否则”表示不这样就会怎样，与前面的否定不相接，句意不通。"}, "sentence_index": 6, "correct_answer": "而是"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我来这里不是工作，而是工作。", "explanation": "这里误把“而是”用来重复前面被否定的内容。“不是工作”后又说“工作”，前后是同一件事，“而是”应引出不同的真正情况。"}, {"text": "这件事不是我做的，而是我做的。", "explanation": "这里误把“而是”用来重复前面被否定的内容。“不是我做的”后又说“是我做的”，前后直接矛盾，“而是”不能这样用。"}, {"text": "我们不是去看电影，而是去看电影。", "explanation": "这里误把“而是”用来重复前面被否定的内容。“不是去看电影”后又说“去看电影”，前后是同一件事，“而是”应引出不同的真正原因或说法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f59eef98-5920-4c5f-afac-18238bea63cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86814, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他这次没来，因为忘了，而是因为生病了。", "corrected_sentence": "他这次没来，不是因为忘了，而是因为生病了。", "error_description": "错误：“因为忘了，而是因为生病了”，漏掉了“不是”。正确：“不是因为忘了，而是因为生病了”。“而是”要与前面的“不是”配对，先否定一个原因，再引出正确的原因。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f59eef98-5920-4c5f-afac-18238bea63cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86814, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次成功是因为运气好，而是大家一起努力。", "corrected_sentence": "这次成功不是因为运气好，而是大家一起努力。", "error_description": "错误：“是因为运气好，而是大家一起努力”，“而是”前面缺少与之配对的“不是”。正确：“不是因为运气好，而是大家一起努力”。“不是”否定前一原因，“而是”再引出真正的情况。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f59eef98-5920-4c5f-afac-18238bea63cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
