INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86816, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "说话；发言。", "primary_collocate": null, "pronunciation": "jiǎng huà", "ipa": "tɕjɑŋ˨˩ xwa˥˩", "syllable_count": 2, "sentences": [{"text": "校长在大会上讲话。", "target_word": "讲话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天经理要在会上讲话。", "target_word": "讲话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请王老师给大家讲话。", "target_word": "讲话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他讲话时，大家都认真听。", "target_word": "讲话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会时，他第一个讲话。", "target_word": "讲话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市长在开幕式上讲话了。", "target_word": "讲话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天谁来讲话？", "target_word": "讲话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们安静，经理要讲话了。", "target_word": "讲话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在毕业典礼上讲话，大家鼓掌。", "target_word": "讲话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长在台上讲话的时候，同学们都安静地听。", "target_word": "讲话", "complexity_tier": "T3", "furigana": "xiàozhǎng zài táishang jiǎnghuà de shíhou, tóngxuémen dōu ānjìng de tīng", "sentence_source": "generated"}], "morphological_forms": [{"form": "讲了话", "label": "体标"}, {"form": "讲过话", "label": "体标"}], "register": "中性", "sense_fingerprint": "在会议、典礼等场合向众人发言", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff939fe6-9da8-4641-8328-502a2b4a468a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86816, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "讲话", "is_correct": true, "explanation": "讲话：此处指在大会上正式发言，符合句中的场合。"}, {"text": "跑步", "is_correct": false, "explanation": "语义：“跑步”是运动，“校长在大会上跑步”句意荒谬。"}, {"text": "做", "is_correct": false, "explanation": "配价：“做”必须带宾语，“校长在大会上做”语义和结构都不完整。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：“洗澡”是私人活动，与在大会上发言无关，句意不通。"}], "explanations": {"讲话": "讲话：此处指在大会上正式发言，符合句中的场合。", "跑步": "语义：“跑步”是运动，“校长在大会上跑步”句意荒谬。", "做": "配价：“做”必须带宾语，“校长在大会上做”语义和结构都不完整。", "洗澡": "语义：“洗澡”是私人活动，与在大会上发言无关，句意不通。"}, "sentence_index": 0, "correct_answer": "讲话"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她在纸上讲话，画了一幅画。", "explanation": "这里应该用〈画〉。“讲话”不能表示在纸上作画，画画要用〈画〉。"}, {"text": "他在石头上讲话，雕出了一只鸟。", "explanation": "这里应该用〈雕〉。“讲话”不能表示雕刻，雕东西要用〈雕〉。"}, {"text": "他在墙上讲话，刷了一遍油漆。", "explanation": "这里应该用〈刷〉。“讲话”不能表示刷漆，刷油漆要用〈刷〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbe18f3c-0bfb-4f8d-8f30-faa5ce06c6e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86816, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "讲话", "is_correct": true, "explanation": "讲话：此处指发言，询问谁来在场合中发言，符合句意。"}, {"text": "打嗝", "is_correct": false, "explanation": "语义：“打嗝”是生理现象，不是发言，“今天谁来打嗝”句意荒谬。"}, {"text": "吞", "is_correct": false, "explanation": "配价：“吞”必须带宾语，“今天谁来吞”结构不完整，不成立。"}, {"text": "咬", "is_correct": false, "explanation": "配价：“咬”必须带宾语，单独用在“谁来”之后语义和结构都不成立。"}], "explanations": {"讲话": "讲话：此处指发言，询问谁来在场合中发言，符合句意。", "打嗝": "语义：“打嗝”是生理现象，不是发言，“今天谁来打嗝”句意荒谬。", "吞": "配价：“吞”必须带宾语，“今天谁来吞”结构不完整，不成立。", "咬": "配价：“咬”必须带宾语，单独用在“谁来”之后语义和结构都不成立。"}, "sentence_index": 6, "correct_answer": "讲话"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她在树叶上讲话，摘下了一朵花。", "explanation": "这里应该用〈摘〉。“讲话”不能表示摘花，摘花要用〈摘〉。"}, {"text": "妈妈在锅里讲话，炒好了一盘菜。", "explanation": "这里应该用〈炒〉。“讲话”不能表示炒菜，炒菜要用〈炒〉。"}, {"text": "他在地板上讲话，拖干净了客厅。", "explanation": "这里应该用〈拖〉。“讲话”不能表示拖地，拖地要用〈拖〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbe18f3c-0bfb-4f8d-8f30-faa5ce06c6e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86816, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "王主任讲话讲的很清楚。", "corrected_sentence": "王主任讲话讲得很清楚。", "error_description": "补语误用：“讲话讲得很清楚”中补语要用“得”引出，不能用“的”，应说“讲得很清楚”，不能说“讲的很清楚”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbe18f3c-0bfb-4f8d-8f30-faa5ce06c6e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86816, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "校长讲话过。", "corrected_sentence": "校长讲过话。", "error_description": "体标位置错误：“讲过话”是离合词加“过”，“过”应放在“讲”后面，不能说“讲话过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbe18f3c-0bfb-4f8d-8f30-faa5ce06c6e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
