INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86823, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "不久是过了一小会儿，不太长。", "primary_collocate": null, "pronunciation": "bù jiǔ", "ipa": "pu˥˩ tɕjoʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他说完话，不久就走了。", "target_word": "不久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们吃完饭，不久下起了雨。", "target_word": "不久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑了，不久月亮就出来了。", "target_word": "不久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他搬到北京，不久就找到了工作。", "target_word": "不久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师进来，不久大家都安静了。", "target_word": "不久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天到了，不久花都开了。", "target_word": "不久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他打了电话，不久朋友就到了。", "target_word": "不久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳下山，不久天就黑了。", "target_word": "不久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她下了课，不久就回家了。", "target_word": "不久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他吃了药，不久就睡着了。", "target_word": "不久", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不久前", "label": "复合"}, {"form": "不久以后", "label": "复合"}], "register": "中性", "sense_fingerprint": "副词；某事之后过了不长时间，接着发生另一件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa28d71a-cd8b-403b-8f08-c583f9f3d70d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86823, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不久", "is_correct": true, "explanation": "不久：表示说完话后过了一小会儿才走，符合句意。"}, {"text": "一直", "is_correct": false, "explanation": "语义：「一直」表示动作或状态持续不断，与「说完话就走了」这种瞬间完成的动作不符。"}, {"text": "曾经", "is_correct": false, "explanation": "体貌：「曾经」表示过去有过某种经历，与「就」所表示的紧接发生不相容。"}, {"text": "仍然", "is_correct": false, "explanation": "语义：「仍然」表示状态持续不变，与「说完话就走了」的变化矛盾。"}], "explanations": {"不久": "不久：表示说完话后过了一小会儿才走，符合句意。", "一直": "语义：「一直」表示动作或状态持续不断，与「说完话就走了」这种瞬间完成的动作不符。", "曾经": "体貌：「曾经」表示过去有过某种经历，与「就」所表示的紧接发生不相容。", "仍然": "语义：「仍然」表示状态持续不变，与「说完话就走了」的变化矛盾。"}, "sentence_index": 0, "correct_answer": "不久"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座老城有三百年的历史，不久就变了样。", "explanation": "这里应该用〈逐渐〉。「不久」表示过了一小会儿，不能与「三百年的历史」这样的漫长过程搭配。"}, {"text": "这个问题研究了十年，不久就解决了。", "explanation": "这里应该用〈最终〉。「不久」表示过了短时间，不能用于经过十年这样漫长过程之后的结果。"}, {"text": "他在国外住了二十年，不久就回国了。", "explanation": "这里应该用〈很久以后〉。「不久」表示过了一小会儿，不能与「住了二十年」这样的长时间搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebe4df0-deea-49ac-80a5-64074ed8d248') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86823, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不久", "is_correct": true, "explanation": "不久：表示打完电话后过了一小会儿朋友才到，符合句意。"}, {"text": "从来", "is_correct": false, "explanation": "语义：「从来」指从过去到现在始终如此，多与否定词连用，不能表示某事之后很快发生。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：「偶尔」指不常发生，与「打了电话，朋友就到了」的紧接关系相矛盾。"}, {"text": "始终", "is_correct": false, "explanation": "体貌：「始终」表示状态持续不变，与打完电话后朋友瞬间到达的完成性动作不符。"}], "explanations": {"不久": "不久：表示打完电话后过了一小会儿朋友才到，符合句意。", "从来": "语义：「从来」指从过去到现在始终如此，多与否定词连用，不能表示某事之后很快发生。", "偶尔": "语义：「偶尔」指不常发生，与「打了电话，朋友就到了」的紧接关系相矛盾。", "始终": "体貌：「始终」表示状态持续不变，与打完电话后朋友瞬间到达的完成性动作不符。"}, "sentence_index": 6, "correct_answer": "不久"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请你不久坐下，我们开始吧。", "explanation": "这里应该用〈立即〉。「不久」表示过了一小会儿才发生，不能用于要求对方马上行动的句子。"}, {"text": "他在这家公司干了五年，不久就升职了。", "explanation": "这里应该用〈后来〉。「不久」表示过了一小会儿，与「干了五年」这样的长时间相矛盾。"}, {"text": "他读了十年书，不久就毕业了。", "explanation": "这里应该用〈终于〉。「不久」表示过了一小会儿，与「读了十年书」这样的长时间相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebe4df0-deea-49ac-80a5-64074ed8d248') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86823, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他吃完饭，不久的就出门了。", "corrected_sentence": "他吃完饭，不久就出门了。", "error_description": "错误：「不久的就出门了」；正确：「不久就出门了」。「不久」是副词，后面不能加结构助词「的」，应直接接「就」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebe4df0-deea-49ac-80a5-64074ed8d248') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86823, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他刚打完电话，很不久朋友就到了。", "corrected_sentence": "他刚打完电话，不久朋友就到了。", "error_description": "错误：「很不久朋友就到了」；正确：「不久朋友就到了」。「不久」是时间副词，前面不能加程度副词「很」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebe4df0-deea-49ac-80a5-64074ed8d248') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
