INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86824, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "时间不长。", "primary_collocate": null, "pronunciation": "bù jiǔ", "ipa": "pu˥˩ tɕjoʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他才走不久，你别打电话。", "target_word": "不久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店开了不久，人还不多。", "target_word": "不久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台电脑买了不久，我还不太会用。", "target_word": "不久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我来北京不久，还不太习惯。", "target_word": "不久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我学汉语不久，说得不太好。", "target_word": "不久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事发生不久，大家还记得。", "target_word": "不久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他刚工作不久，钱不多。", "target_word": "不久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他刚搬来不久，还不认识邻居。", "target_word": "不久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她离开家不久，还不太习惯独自生活。", "target_word": "不久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们认识不久，还不太了解。", "target_word": "不久", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不久前", "label": "复合"}, {"form": "不久以后", "label": "复合"}], "register": "中性", "sense_fingerprint": "副词；动作或状态开始后到现在时间还不长", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa28d71a-cd8b-403b-8f08-c583f9f3d70d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86824, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不久", "is_correct": true, "explanation": "不久：表示走了之后时间不长，与「才」和「你别打电话」的语境相符。"}, {"text": "很久", "is_correct": false, "explanation": "语义：「很久」指时间长，与「才走」所表示的刚离开语境相矛盾。"}, {"text": "好久", "is_correct": false, "explanation": "语义：「好久」指时间长，与「才」表示的刚刚发生相矛盾。"}, {"text": "许久", "is_correct": false, "explanation": "语义：「许久」指时间长，与「才走」所表示的刚离开语境相矛盾。"}], "explanations": {"不久": "不久：表示走了之后时间不长，与「才」和「你别打电话」的语境相符。", "很久": "语义：「很久」指时间长，与「才走」所表示的刚离开语境相矛盾。", "好久": "语义：「好久」指时间长，与「才」表示的刚刚发生相矛盾。", "许久": "语义：「许久」指时间长，与「才走」所表示的刚离开语境相矛盾。"}, "sentence_index": 0, "correct_answer": "不久"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他已经在北京住了十年，还是不太习惯，因为来北京不久。", "explanation": "这里应该用〈很久〉。「不久」表示时间不长，与「住了十年」的长时间相矛盾。"}, {"text": "这座桥修建不久，却已经有几百年的历史。", "explanation": "这里应该用〈很久〉。「不久」表示时间不长，与「几百年的历史」相矛盾。"}, {"text": "这份工作他干了三十年，但入行不久。", "explanation": "这里应该用〈很久〉。「不久」表示时间不长，与「干了三十年」相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebe4df0-deea-49ac-80a5-64074ed8d248') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86824, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不久", "is_correct": true, "explanation": "不久：工作的时间短，与「刚」和「钱不多」相符。"}, {"text": "刚刚", "is_correct": false, "explanation": "语法：「刚刚」是副词，须放在动词前，不能直接接在「工作」之后作谓语。"}, {"text": "良久", "is_correct": false, "explanation": "搭配：「良久」多作状语，用在句首或动词前，不能放在「工作」之后。"}, {"text": "才", "is_correct": false, "explanation": "语法：「才」是副词，须修饰动词，不能直接接在「工作」之后，句子不通。"}], "explanations": {"不久": "不久：工作的时间短，与「刚」和「钱不多」相符。", "刚刚": "语法：「刚刚」是副词，须放在动词前，不能直接接在「工作」之后作谓语。", "良久": "搭配：「良久」多作状语，用在句首或动词前，不能放在「工作」之后。", "才": "语法：「才」是副词，须修饰动词，不能直接接在「工作」之后，句子不通。"}, "sentence_index": 6, "correct_answer": "不久"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他早就认识我，认识我不久了。", "explanation": "这里应该用〈很久〉。「不久」表示时间不长，与「早就认识」所表示的很长时间相矛盾。"}, {"text": "这个传统流传了千年，形成不久。", "explanation": "这里应该用〈很久〉。「不久」表示时间不长，与「流传了千年」相矛盾。"}, {"text": "他童年时就学会了画画，学画不久。", "explanation": "这里应该用〈很久〉。「不久」表示时间不长，与「童年时」就开始学画的长期经历相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebe4df0-deea-49ac-80a5-64074ed8d248') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86824, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我到公司工作太不久，还在适应。", "corrected_sentence": "我到公司工作不久，还在适应。", "error_description": "错误：「太不久」；正确：「不久」。「不久」本身已表示时间不长，不能再加程度副词「太」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebe4df0-deea-49ac-80a5-64074ed8d248') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86824, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们做朋友很不久，还不太熟。", "corrected_sentence": "我们做朋友不久，还不太熟。", "error_description": "错误：「很不久」；正确：「不久」。「不久」是表示时间的副词，不能用程度副词「很」修饰。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebe4df0-deea-49ac-80a5-64074ed8d248') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
