INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86826, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，表示进一层；而且。", "primary_collocate": null, "pronunciation": "qiě", "ipa": "tɕʰjɛ˨˩˦", "syllable_count": 1, "sentences": [{"text": "这个办法简单且有效。", "target_word": "且", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家店的菜便宜且好吃。", "target_word": "且", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他聪明且努力，老师很喜欢他。", "target_word": "且", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房间干净且安静，很适合学习。", "target_word": "且", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书内容丰富且容易懂。", "target_word": "且", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里的空气新鲜且湿润。", "target_word": "且", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她说话清楚且有礼貌。", "target_word": "且", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这种水果甜且便宜，很多人买。", "target_word": "且", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的字大且清楚，我一看就懂。", "target_word": "且", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条路宽且直，开车很方便。", "target_word": "且", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "且：连词，表示进一层，相当于而且", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef6fb817-c5a5-47d1-a0ed-24e25267f898') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86826, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "且", "is_correct": true, "explanation": "正确：且（qiě）是连词，表示进一层，相当于“而且”。"}, {"text": "切", "is_correct": false, "explanation": "切（qiē，第一声）与 qiě（第三声）声调不同，意思是“切开”。"}, {"text": "姐", "is_correct": false, "explanation": "姐（jiě）与 qiě 声母不同（j 与 q），声调相同，意思是“姐姐”。"}, {"text": "解", "is_correct": false, "explanation": "解（jiě）与 qiě 声母不同（j 与 q），声调相同，意思是“了解”“解开”。"}, {"text": "茄", "is_correct": false, "explanation": "茄（qié，第二声）与 qiě（第三声）声调不同，意思是“茄子”。"}], "explanations": {"且": "正确：且（qiě）是连词，表示进一层，相当于“而且”。", "切": "切（qiē，第一声）与 qiě（第三声）声调不同，意思是“切开”。", "姐": "姐（jiě）与 qiě 声母不同（j 与 q），声调相同，意思是“姐姐”。", "解": "解（jiě）与 qiě 声母不同（j 与 q），声调相同，意思是“了解”“解开”。", "茄": "茄（qié，第二声）与 qiě（第三声）声调不同，意思是“茄子”。"}, "sentence_index": null, "correct_answer": "且"}, "level_3": {"options": [{"text": "且", "is_correct": true, "explanation": "正确：“且”是连词，表示进一层，连接并列的形容词“简单”和“有效”，符合语境。"}, {"text": "或", "is_correct": false, "explanation": "语义：“或”表示选择，二者只能选一，与“简单”“有效”并存的意思不符。"}, {"text": "所以", "is_correct": false, "explanation": "语义：“所以”表示因果，办法简单不能推出有效。"}, {"text": "况且", "is_correct": false, "explanation": "搭配：“况且”用于补充理由，连接分句，不直接连接并列的形容词。"}], "explanations": {"且": "正确：“且”是连词，表示进一层，连接并列的形容词“简单”和“有效”，符合语境。", "或": "语义：“或”表示选择，二者只能选一，与“简单”“有效”并存的意思不符。", "所以": "语义：“所以”表示因果，办法简单不能推出有效。", "况且": "搭配：“况且”用于补充理由，连接分句，不直接连接并列的形容词。"}, "sentence_index": 0, "correct_answer": "且"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这不是我的错，且是你的错。", "explanation": "这里应该用〈而是〉。且表示递进，不能表示否定前者、转而肯定后者的对比关系。"}, {"text": "下雨了，且比赛取消了。", "explanation": "这里应该用〈所以〉。且只表示并列或递进，不能表示因果；“下雨”与“比赛取消”之间是因果关系。"}, {"text": "他的字很漂亮，且速度很慢。", "explanation": "这里应该用〈但是〉。且表示递进，前后语义要一致；“字漂亮”与“速度慢”是转折关系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a681fc-fe7f-4c14-8977-15c7203e90a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86826, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "且", "is_correct": true, "explanation": "正确：且（qiě）是连词，表示进一层，相当于“而且”。"}, {"text": "写", "is_correct": false, "explanation": "写（xiě）与 qiě 声母不同（x 与 q），声调相同，意思是“写字”。"}, {"text": "企", "is_correct": false, "explanation": "企（qǐ，第三声）与 qiě 仅韵母不同（i 与 ie），声调相同，意思是“踮起脚”。"}, {"text": "窃", "is_correct": false, "explanation": "窃（qiè，第四声）与 qiě（第三声）声调不同，意思是“偷窃”。"}, {"text": "怯", "is_correct": false, "explanation": "怯（qiè，第四声）与 qiě（第三声）声调不同，意思是“胆怯”。"}], "explanations": {"且": "正确：且（qiě）是连词，表示进一层，相当于“而且”。", "写": "写（xiě）与 qiě 声母不同（x 与 q），声调相同，意思是“写字”。", "企": "企（qǐ，第三声）与 qiě 仅韵母不同（i 与 ie），声调相同，意思是“踮起脚”。", "窃": "窃（qiè，第四声）与 qiě（第三声）声调不同，意思是“偷窃”。", "怯": "怯（qiè，第四声）与 qiě（第三声）声调不同，意思是“胆怯”。"}, "sentence_index": null, "correct_answer": "且"}, "level_3": {"options": [{"text": "且", "is_correct": true, "explanation": "正确：“且”是连词，表示进一层，连接并列的形容词“清楚”和“有礼貌”，递进关系成立。"}, {"text": "而是", "is_correct": false, "explanation": "语义：“而是”表示对比、否定前者，“说话清楚”与“有礼貌”并不对立。"}, {"text": "还是", "is_correct": false, "explanation": "搭配：“还是”多用于选择式疑问句，不能连接陈述句中并列的形容词。"}, {"text": "因而", "is_correct": false, "explanation": "语义：“因而”表示因果，说话清楚不能推出有礼貌。"}], "explanations": {"且": "正确：“且”是连词，表示进一层，连接并列的形容词“清楚”和“有礼貌”，递进关系成立。", "而是": "语义：“而是”表示对比、否定前者，“说话清楚”与“有礼貌”并不对立。", "还是": "搭配：“还是”多用于选择式疑问句，不能连接陈述句中并列的形容词。", "因而": "语义：“因而”表示因果，说话清楚不能推出有礼貌。"}, "sentence_index": 6, "correct_answer": "且"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "如果下雪，学校且放假。", "explanation": "这里应该用〈就〉。且是连词，不能用在“如果……”之后引出结果。"}, {"text": "她买了牛奶，面包且鸡蛋。", "explanation": "这里应该用〈和〉。且一般连接形容词或动词短语，不用来连接并列的名词。"}, {"text": "他生病了，且没有来上课。", "explanation": "这里应该用〈因此〉。且不能表示因果；“生病”是“没来上课”的原因。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a681fc-fe7f-4c14-8977-15c7203e90a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86826, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台电脑轻巧且的耐用。", "corrected_sentence": "这台电脑轻巧且耐用。", "error_description": "错误形式：“且的”。正确形式：“且”直接连接并列的形容词“轻巧”和“耐用”，“且”后不能加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a681fc-fe7f-4c14-8977-15c7203e90a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86826, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这里的水果新鲜且也便宜。", "corrected_sentence": "这里的水果新鲜且便宜。", "error_description": "错误形式：“且也”。正确形式：“且”后直接接并列的形容词“便宜”，不能再加副词“也”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a681fc-fe7f-4c14-8977-15c7203e90a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
