INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86827, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bc40e6-4fff-497e-83e1-617b30d2c32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86827, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "信仰是你心里非常相信、并按它去做的东西。", "primary_collocate": null, "pronunciation": "xìn yǎng", "ipa": "ɕin˥˩ jɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他心里有一个信仰，所以再难也不放弃。", "target_word": "信仰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人的信仰不一样，我们要互相尊重。", "target_word": "信仰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的信仰是帮助别人，她每天都这样做。", "target_word": "信仰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有信仰的人，有时会不知道活着是为了什么。", "target_word": "信仰", "complexity_tier": "T3", "furigana": "méiyǒu xìnyǎng de rén, yǒushí huì bù zhīdào huózhe shì wèile shénme.", "sentence_source": "generated"}, {"text": "爷爷一辈子都按自己的信仰生活。", "target_word": "信仰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对他来说，诚实就是最重要的信仰。", "target_word": "信仰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个年轻人为了信仰，放弃了很多钱。", "target_word": "信仰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "失去信仰以后，他每天都很难过。", "target_word": "信仰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，有信仰的人心里更有力量。", "target_word": "信仰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的信仰很简单：做一个好人。", "target_word": "信仰", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "宗教信仰", "label": "复合"}], "register": "中性", "sense_fingerprint": "个人心中深信并照着去做的信念", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e1c9056-d391-4ceb-b6b4-66d28e0beac3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86827, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "信仰", "is_correct": true, "explanation": "正确：信仰指心里深信并照着去做的信念，与“再难也不放弃”相合。"}, {"text": "皮包", "is_correct": false, "explanation": "语义：皮包是装东西的物品，放不进心里，句子不通。"}, {"text": "苹果", "is_correct": false, "explanation": "语义：苹果是水果，不能说“心里有一个苹果”来表示坚持。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“心里有石头”指心中忧虑、放不下，与句中“再难也不放弃”的坚持相反，句子不通。"}], "explanations": {"信仰": "正确：信仰指心里深信并照着去做的信念，与“再难也不放弃”相合。", "皮包": "语义：皮包是装东西的物品，放不进心里，句子不通。", "苹果": "语义：苹果是水果，不能说“心里有一个苹果”来表示坚持。", "石头": "语义：“心里有石头”指心中忧虑、放不下，与句中“再难也不放弃”的坚持相反，句子不通。"}, "sentence_index": 0, "correct_answer": "信仰"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台机器的信仰很好，用了很多年都没坏。", "explanation": "这里应该用〈质量〉。质量指物品的好坏，信仰指心中信奉的东西，不用于说机器的品质。"}, {"text": "他做生意很讲信仰，从不欺骗客户。", "explanation": "这里应该用〈诚信〉。诚信指待人真诚、守信用，信仰指心中信奉的东西，不用于说做生意的态度。"}, {"text": "这家老店的信仰很好，大家都愿意来。", "explanation": "这里应该用〈信用〉。信用指守约、可靠的声誉，信仰指信奉的主张，不用于店铺的名声。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bc40e6-4fff-497e-83e1-617b30d2c32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86827, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "信仰", "is_correct": true, "explanation": "正确：信仰指心中深信并遵循的东西，为它放弃钱财与句意相合。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是人会为之放弃钱财的目标，句子不通。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能成为人为之放弃钱财的目标，句子不通。"}, {"text": "咖啡", "is_correct": false, "explanation": "搭配：“为了咖啡放弃很多钱”不合常理，“为了”后接的目标与“放弃很多钱”不相称。"}], "explanations": {"信仰": "正确：信仰指心中深信并遵循的东西，为它放弃钱财与句意相合。", "天气": "语义：天气不是人会为之放弃钱财的目标，句子不通。", "石头": "语义：石头不能成为人为之放弃钱财的目标，句子不通。", "咖啡": "搭配：“为了咖啡放弃很多钱”不合常理，“为了”后接的目标与“放弃很多钱”不相称。"}, "sentence_index": 6, "correct_answer": "信仰"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我对你的信仰很深，从不怀疑你。", "explanation": "这里应该用〈信任〉。信任指彼此相信、可以依靠，信仰指心中信奉的主张或宗教，不用于对某个人的信赖。"}, {"text": "这种米的信仰很好，大家都爱买。", "explanation": "这里应该用〈口碑〉。口碑指群众对人或物品的评价，信仰指个人心中信奉的东西，不用于说商品的评价。"}, {"text": "这家公司的信仰很好，大家都愿意合作。", "explanation": "这里应该用〈信誉〉。信誉指可靠、守信的评价，信仰不用于公司的声誉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bc40e6-4fff-497e-83e1-617b30d2c32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86827, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她心里有一张信仰，从不撒谎。", "corrected_sentence": "她心里有一种信仰，从不撒谎。", "error_description": "量词“张”用于纸、桌子等有平面的东西，不用于心中的信念。信仰应该用“种”，错误在于“一张信仰”，正确形式是“一种信仰”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bc40e6-4fff-497e-83e1-617b30d2c32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86827, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一直保持着一只信仰。", "corrected_sentence": "他一直保持着一种信仰。", "error_description": "量词“只”多用于动物，信仰应该用“种”。错误在于“一只信仰”，正确形式是“一种信仰”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bc40e6-4fff-497e-83e1-617b30d2c32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86828, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bc40e6-4fff-497e-83e1-617b30d2c32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
