INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86828, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "对某种主张、宗教或思想的相信和尊敬。", "primary_collocate": null, "pronunciation": "xìn yǎng", "ipa": "ɕin˥˩ jɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他的宗教信仰是佛教。", "target_word": "信仰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们有选择自己信仰的自由。", "target_word": "信仰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人因为信仰不同，吃的东西也不一样。", "target_word": "信仰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们家几代人都有同样的宗教信仰。", "target_word": "信仰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人把一生都给了自己的宗教信仰。", "target_word": "信仰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校里的学生来自不同国家，信仰也不同。", "target_word": "信仰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对这种思想的信仰越来越深。", "target_word": "信仰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个地方，人们的宗教信仰受到尊重。", "target_word": "信仰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小的信仰是基督教，后来没有改变。", "target_word": "信仰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要笑话别人的宗教信仰。", "target_word": "信仰", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "宗教信仰", "label": "复合"}], "register": "中性", "sense_fingerprint": "对宗教、主张或思想的信奉与尊崇", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e1c9056-d391-4ceb-b6b4-66d28e0beac3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86828, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "信仰", "is_correct": true, "explanation": "正确：信仰指对宗教或主张的相信和尊敬，与“佛教”相合。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高是人的体貌数据，与宗教无关，不能说“是佛教”。"}, {"text": "国籍", "is_correct": false, "explanation": "语义：国籍指所属国家，与宗教无关，不能说“是佛教”。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“宗教”后接的是信仰、团体等，不接颜色，“颜色是佛教”也不成立。"}], "explanations": {"信仰": "正确：信仰指对宗教或主张的相信和尊敬，与“佛教”相合。", "身高": "语义：身高是人的体貌数据，与宗教无关，不能说“是佛教”。", "国籍": "语义：国籍指所属国家，与宗教无关，不能说“是佛教”。", "颜色": "搭配：“宗教”后接的是信仰、团体等，不接颜色，“颜色是佛教”也不成立。"}, "sentence_index": 0, "correct_answer": "信仰"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对这次比赛很有信仰。", "explanation": "这里应该用〈信心〉。信心指对能否取胜的把握，信仰指信奉的主张或宗教，不用于对比赛的把握。"}, {"text": "这家工厂的信仰很高，产品卖得很好。", "explanation": "这里应该用〈声誉〉。声誉指社会上对人或单位的评价，信仰指信奉的主张或宗教，不用于工厂的评价。"}, {"text": "这家银行的信仰很高，大家都放心。", "explanation": "这里应该用〈信用〉。信用指守约、可靠的声誉，信仰不用于银行的声誉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bc40e6-4fff-497e-83e1-617b30d2c32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86828, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "信仰", "is_correct": true, "explanation": "正确：信仰指对某种思想的相信和尊敬，与“越来越深”相合。"}, {"text": "高度", "is_correct": false, "explanation": "搭配：“深”不修饰“高度”，高度要说“高”，“越来越深”不成立。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重不是思想，不能说“对这种思想的体重”。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格不是思想，不能说“对这种思想的价格”。"}], "explanations": {"信仰": "正确：信仰指对某种思想的相信和尊敬，与“越来越深”相合。", "高度": "搭配：“深”不修饰“高度”，高度要说“高”，“越来越深”不成立。", "体重": "语义：体重不是思想，不能说“对这种思想的体重”。", "价格": "语义：价格不是思想，不能说“对这种思想的价格”。"}, "sentence_index": 6, "correct_answer": "信仰"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对老板的信仰很深，从不怀疑他。", "explanation": "这里应该用〈信任〉。信任指彼此相信、可以依靠，信仰指信奉的主张或宗教，不用于对某个人的信赖。"}, {"text": "这家餐厅的信仰很好，大家都爱来。", "explanation": "这里应该用〈信誉〉。信誉指可靠、守信的评价，信仰不用于餐厅的声誉。"}, {"text": "他做事很讲信仰，从不欺骗别人。", "explanation": "这里应该用〈诚信〉。诚信指待人真诚、守信用，信仰指信奉的主张或宗教，不用于说做事的态度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bc40e6-4fff-497e-83e1-617b30d2c32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86828, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他有一只宗教信仰，每周都去教堂。", "corrected_sentence": "他有一种宗教信仰，每周都去教堂。", "error_description": "量词“只”用于动物，信仰应该用“种”。错误在于把“一只”用于“宗教信仰”，正确形式是“一种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bc40e6-4fff-497e-83e1-617b30d2c32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86828, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她有一张宗教信仰，每天都祈祷。", "corrected_sentence": "她有一种宗教信仰，每天都祈祷。", "error_description": "量词“张”用于纸、桌子等有平面的东西，不用于信仰。错误在于“一张宗教信仰”，正确形式是“一种宗教信仰”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bc40e6-4fff-497e-83e1-617b30d2c32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
