INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86829, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "先后是一个接一个，有早有晚。", "primary_collocate": null, "pronunciation": "xiān hòu", "ipa": "ɕi̯ɛn˥ xou̯˥˩", "syllable_count": 2, "sentences": [{"text": "他先后去过北京、上海和广州。", "target_word": "先后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年夏天，我们先后收到了三封信。", "target_word": "先后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司先后开了五家新店。", "target_word": "先后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人们先后走进了教室。", "target_word": "先后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她先后养过两只猫和一条狗。", "target_word": "先后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震后，医生先后赶到了现场。", "target_word": "先后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明和小红先后跑到了终点。", "target_word": "先后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他先后换了三份工作，最后才定下来。", "target_word": "先后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那几年，爷爷奶奶先后离开了老家。", "target_word": "先后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师先后教过我们三年级和四年级。", "target_word": "先后", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "先后：副词，表示几个人或几件事一个接一个地发生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dfa9012-682f-47cd-812e-5fb770f93c09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86829, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "先后", "is_correct": true, "explanation": "正确：「先后」表示几件事或几个人一个接一个地发生，符合「去过三个地方」的意思。"}, {"text": "纷纷", "is_correct": false, "explanation": "搭配：「纷纷」要求主语是很多人或很多事物，句中只有「他」一个人，「他纷纷去过」说不通。"}, {"text": "一起", "is_correct": false, "explanation": "搭配：「一起」需要同伴，句中没有同伴，「他一起去过」说不通。"}, {"text": "同时", "is_correct": false, "explanation": "语义：「同时」表示同一时间，与逐个去过的次序相反。"}], "explanations": {"先后": "正确：「先后」表示几件事或几个人一个接一个地发生，符合「去过三个地方」的意思。", "纷纷": "搭配：「纷纷」要求主语是很多人或很多事物，句中只有「他」一个人，「他纷纷去过」说不通。", "一起": "搭配：「一起」需要同伴，句中没有同伴，「他一起去过」说不通。", "同时": "语义：「同时」表示同一时间，与逐个去过的次序相反。"}, "sentence_index": 0, "correct_answer": "先后"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他先后吃了一顿饭。", "explanation": "这里应该用〈先〉。「先后」要求两件以上的事或人按次序出现，一顿饭只有一件事，应该用「先」。"}, {"text": "他先后买了一台电脑。", "explanation": "这里应该去掉〈先后〉，直接说「买了一台电脑」。「先后」要求两件以上的事或人按次序出现，只买一台电脑只发生一次，不能用「先后」。"}, {"text": "我们先后同时出发。", "explanation": "这里「先后」用错。「先后」指有先有后、一件接一件，与“同一时刻”的意思正相反，两者自相矛盾，应去掉「先后」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab2ec06d-117f-4282-82e1-1de125000776') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86829, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "先后", "is_correct": true, "explanation": "正确：「先后」表示两人一个接一个地跑到终点，符合句子的意思。"}, {"text": "非常", "is_correct": false, "explanation": "语法：「非常」修饰形容词或心理动词，不能修饰「跑到了终点」这样的动作，「非常跑到了终点」不成立。"}, {"text": "总是", "is_correct": false, "explanation": "语义：「总是」表示习惯性，与这一次比赛的具体结果不符。"}, {"text": "顺便", "is_correct": false, "explanation": "语义：「顺便」表示附带，与跑到终点这件主要的事不相符。"}], "explanations": {"先后": "正确：「先后」表示两人一个接一个地跑到终点，符合句子的意思。", "非常": "语法：「非常」修饰形容词或心理动词，不能修饰「跑到了终点」这样的动作，「非常跑到了终点」不成立。", "总是": "语义：「总是」表示习惯性，与这一次比赛的具体结果不符。", "顺便": "语义：「顺便」表示附带，与跑到终点这件主要的事不相符。"}, "sentence_index": 6, "correct_answer": "先后"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位老师先后一直教过我们三年级和四年级。", "explanation": "「先后」指一件接一件、有先有后，与“持续不断”的意思不合，应去掉「先后」。"}, {"text": "这位老师先后教过我们一节课。", "explanation": "「先后」要求两件以上的事按次序出现，只教过一节课，应去掉「先后」。"}, {"text": "这位老师先后同时教过我们三年级和四年级。", "explanation": "「先后」指一件接一件、有先有后，与“同一时刻”的意思正相反，应去掉「先后」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab2ec06d-117f-4282-82e1-1de125000776') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86829, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她先后在三家医院工作着。", "corrected_sentence": "她先后在三家医院工作过。", "error_description": "体标用错。错误形式是「工作着」，「着」表示动作持续进行，与「先后」所指已经发生的几次经历不合；正确形式是「工作过」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab2ec06d-117f-4282-82e1-1de125000776') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86829, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两个同学先后走了进了会议室。", "corrected_sentence": "两个同学先后走进了会议室。", "error_description": "「了」位置错误。错误形式是「走了进了」，复合动词「走进」中间不能加「了」，「了」只放在动词末尾，正确形式是「走进了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab2ec06d-117f-4282-82e1-1de125000776') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
