INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86831, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人士是有某一种身份的人。", "primary_collocate": null, "pronunciation": "rén shì", "ipa": "ʐən˧˥ ʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "他是一位专业人士，对这个问题很清楚。", "target_word": "人士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司需要懂技术的专业人士。", "target_word": "人士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外籍人士可以在这里办手续。", "target_word": "人士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路是为残疾人士修的。", "target_word": "人士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家医院请来了几位医学专业人士。", "target_word": "人士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是宗教人士，常去山上的小庙。", "target_word": "人士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "业内人士说，今年的房价会很稳。", "target_word": "人士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住在这里的多是商界人士。", "target_word": "人士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多外籍人士在这所学校学中文。", "target_word": "人士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们都是从事法律工作的人士。", "target_word": "人士", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "专业人士", "label": "复合"}], "register": "书面语", "sense_fingerprint": "指具有某种职业或身份的人，常放在身份词后，如专业人士、外籍人士", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04fa6d51-9971-4407-9e63-187a99b3aa35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86831, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "人士", "is_correct": true, "explanation": "正确答案。人士 rénshì 指有某种身份或职业的人。"}, {"text": "人生", "is_correct": false, "explanation": "rénshēng（第一声）与 rénshì 的韵母和声调都不同，意思是人的一生。"}, {"text": "人手", "is_correct": false, "explanation": "rénshǒu（第三声）与 rénshì 的韵母不同，意思是人手、劳动力。"}, {"text": "人数", "is_correct": false, "explanation": "rénshù 与 rénshì 的韵母不同，意思是人的数目。"}, {"text": "认识", "is_correct": false, "explanation": "rènshi 的第一音节 rèn 与 rén 只有声调不同，第二音节为轻声，意思是认识、了解。"}], "explanations": {"人士": "正确答案。人士 rénshì 指有某种身份或职业的人。", "人生": "rénshēng（第一声）与 rénshì 的韵母和声调都不同，意思是人的一生。", "人手": "rénshǒu（第三声）与 rénshì 的韵母不同，意思是人手、劳动力。", "人数": "rénshù 与 rénshì 的韵母不同，意思是人的数目。", "认识": "rènshi 的第一音节 rèn 与 rén 只有声调不同，第二音节为轻声，意思是认识、了解。"}, "sentence_index": null, "correct_answer": "人士"}, "level_3": {"options": [{"text": "人士", "is_correct": true, "explanation": "正确。“人士”指有某种身份或职业的人，“专业人士”搭配自然。"}, {"text": "外行", "is_correct": false, "explanation": "语义：“外行”指不懂行的人，与“专业”相反，也与“对这个问题很清楚”矛盾。"}, {"text": "游客", "is_correct": false, "explanation": "搭配：“专业”不能修饰“游客”，“一位专业游客”不成立。"}, {"text": "小孩", "is_correct": false, "explanation": "语义：小孩没有专业身份，与“对这个问题很清楚”也不相符。"}], "explanations": {"人士": "正确。“人士”指有某种身份或职业的人，“专业人士”搭配自然。", "外行": "语义：“外行”指不懂行的人，与“专业”相反，也与“对这个问题很清楚”矛盾。", "游客": "搭配：“专业”不能修饰“游客”，“一位专业游客”不成立。", "小孩": "语义：小孩没有专业身份，与“对这个问题很清楚”也不相符。"}, "sentence_index": 0, "correct_answer": "人士"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "书里出现了许多虚构的人士，读起来很有趣。", "explanation": "这里应该用〈人物〉。“人士”指现实中有某种身份或属于某界别的人，小说里的虚构角色应说“人物”。"}, {"text": "公司新招的人士下周开始上班。", "explanation": "这里应该用〈员工〉。“员工”指在单位工作的人，“人士”指有某种身份或属于某界别的人，不用于指新入职的普通职工。"}, {"text": "演唱会的人士都很激动。", "explanation": "这里应该用〈观众〉。“人士”指有某种身份或属于某界别的人，不用于泛指看演出的人群，这里应说“观众”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c80a291-cf97-4dfa-beee-2c8c814bc789') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86831, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "人士", "is_correct": true, "explanation": "正确答案。人士 rénshì 指有某种身份或职业的人。"}, {"text": "人声", "is_correct": false, "explanation": "rénshēng（第一声）与 rénshì 的韵母和声调都不同，意思是人的声音。"}, {"text": "人身", "is_correct": false, "explanation": "rénshēn（第一声）与 rénshì 的韵母和声调都不同，意思是人的身体。"}, {"text": "人寿", "is_correct": false, "explanation": "rénshòu（第四声）与 rénshì 的韵母不同，意思是人的寿命。"}], "explanations": {"人士": "正确答案。人士 rénshì 指有某种身份或职业的人。", "人声": "rénshēng（第一声）与 rénshì 的韵母和声调都不同，意思是人的声音。", "人身": "rénshēn（第一声）与 rénshì 的韵母和声调都不同，意思是人的身体。", "人寿": "rénshòu（第四声）与 rénshì 的韵母不同，意思是人的寿命。"}, "sentence_index": null, "correct_answer": "人士"}, "level_3": {"options": [{"text": "人士", "is_correct": true, "explanation": "正确。“业内人士”指某一行业内的人，搭配自然。"}, {"text": "路人", "is_correct": false, "explanation": "语义：“路人”指路上偶然经过的人，与“业内”相矛盾。"}, {"text": "局外人", "is_correct": false, "explanation": "语义：“局外人”指不在某个圈子里的人，与“业内”相矛盾。"}, {"text": "农民", "is_correct": false, "explanation": "搭配：“业内”修饰某个行业内部的人，不能用来修饰“农民”。"}], "explanations": {"人士": "正确。“业内人士”指某一行业内的人，搭配自然。", "路人": "语义：“路人”指路上偶然经过的人，与“业内”相矛盾。", "局外人": "语义：“局外人”指不在某个圈子里的人，与“业内”相矛盾。", "农民": "搭配：“业内”修饰某个行业内部的人，不能用来修饰“农民”。"}, "sentence_index": 6, "correct_answer": "人士"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座城市一共有五百万人士。", "explanation": "这里应该用〈人口〉。“人士”指有某种身份的人，不用于统计总人数，统计总人数要用“人口”。"}, {"text": "这个工厂的人士不够，需要招人。", "explanation": "这里应该用〈人手〉。“人手”指干活的人，“人士”不能表示所需的劳动力。"}, {"text": "我家的人士都在农村生活。", "explanation": "这里应该用〈亲戚〉。“人士”指有一定身份或属于某界别的人，不用于指家中的亲属。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c80a291-cf97-4dfa-beee-2c8c814bc789') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86831, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位律师是一只专业人士，经验很丰富。", "corrected_sentence": "这位律师是一位专业人士，经验很丰富。", "error_description": "量词错误：“人士”指人，要用量词“位”，不能用“只”（“只”多用于动物）。正确的是“一位专业人士”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c80a291-cf97-4dfa-beee-2c8c814bc789') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86831, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位工程师是人士，做事很认真。", "corrected_sentence": "这位工程师是专业人士，做事很认真。", "error_description": "修饰语缺失：“人士”前面需要“专业”说明身份，“是人士”说法不完整。正确的是“是专业人士”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c80a291-cf97-4dfa-beee-2c8c814bc789') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
