INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86832, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指有一定影响或属于某一方面的人。", "primary_collocate": null, "pronunciation": "rén shì", "ipa": "ʐən˧˥ ʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "会上来了很多知名人士。", "target_word": "人士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社会各界人士都来参加了这次活动。", "target_word": "人士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一位爱国人士给学校捐了很多书。", "target_word": "人士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政界人士对这件事没有发表意见。", "target_word": "人士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有关人士已经到了现场。", "target_word": "人士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "知情人士说，公司明年会搬家。", "target_word": "人士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位著名人士在大会上讲了话。", "target_word": "人士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "许多文化界人士写信支持他。", "target_word": "人士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是当地很有影响的人士。", "target_word": "人士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各方人士都希望这件事能解决好。", "target_word": "人士", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "知名人士", "label": "复合"}], "register": "书面语", "sense_fingerprint": "指有一定社会影响或属于某一界别、某一方面的人，如知名人士、各界人士", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04fa6d51-9971-4407-9e63-187a99b3aa35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86832, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "人士", "is_correct": true, "explanation": "正确答案。人士 rénshì 指有一定社会影响或属于某一界别的人。"}, {"text": "人身", "is_correct": false, "explanation": "rénshēn（第一声）与 rénshì 的韵母和声调都不同，意思是人的身体。"}, {"text": "人寿", "is_correct": false, "explanation": "rénshòu（第四声）与 rénshì 的韵母不同，意思是人的寿命。"}, {"text": "人数", "is_correct": false, "explanation": "rénshù 与 rénshì 的韵母不同，意思是人的数目。"}, {"text": "认识", "is_correct": false, "explanation": "rènshi 的第一音节 rèn 与 rén 只有声调不同，第二音节为轻声，意思是认识、了解。"}], "explanations": {"人士": "正确答案。人士 rénshì 指有一定社会影响或属于某一界别的人。", "人身": "rénshēn（第一声）与 rénshì 的韵母和声调都不同，意思是人的身体。", "人寿": "rénshòu（第四声）与 rénshì 的韵母不同，意思是人的寿命。", "人数": "rénshù 与 rénshì 的韵母不同，意思是人的数目。", "认识": "rènshi 的第一音节 rèn 与 rén 只有声调不同，第二音节为轻声，意思是认识、了解。"}, "sentence_index": null, "correct_answer": "人士"}, "level_3": {"options": [{"text": "人士", "is_correct": true, "explanation": "正确。“知名人士”指有一定社会影响的人，搭配自然。"}, {"text": "路人", "is_correct": false, "explanation": "语义：“路人”指路上偶然经过的普通人，与“知名”相矛盾。"}, {"text": "乞丐", "is_correct": false, "explanation": "语义：乞丐与“知名”的含义相矛盾，句子不成立。"}, {"text": "游客", "is_correct": false, "explanation": "搭配：“知名”通常修饰人物或机构，“知名游客”搭配不当。"}], "explanations": {"人士": "正确。“知名人士”指有一定社会影响的人，搭配自然。", "路人": "语义：“路人”指路上偶然经过的普通人，与“知名”相矛盾。", "乞丐": "语义：乞丐与“知名”的含义相矛盾，句子不成立。", "游客": "搭配：“知名”通常修饰人物或机构，“知名游客”搭配不当。"}, "sentence_index": 0, "correct_answer": "人士"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这部小说的主要人士是一位老师。", "explanation": "这里应该用〈人物〉。小说里的角色叫“人物”，“人士”指现实中有一定身份或属于某界别的人。"}, {"text": "医院的人士都很配合治疗。", "explanation": "这里应该用〈病人〉。“人士”指有一定身份或属于某界别的人，不用于指在医院看病的患者，这里应说“病人”。"}, {"text": "这个小区住着很多人士。", "explanation": "这里应该用〈居民〉。“人士”指有一定身份或属于某界别的人，泛指住在小区里的人应用“居民”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c80a291-cf97-4dfa-beee-2c8c814bc789') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86832, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "人士", "is_correct": true, "explanation": "正确答案。人士 rénshì 指有一定社会影响或属于某一界别的人。"}, {"text": "人生", "is_correct": false, "explanation": "rénshēng（第一声）与 rénshì 的第二音节韵母和声调都不同，意思是人的一生。"}, {"text": "人手", "is_correct": false, "explanation": "rénshǒu（第三声）与 rénshì 的韵母不同，意思是人手、劳动力。"}, {"text": "人声", "is_correct": false, "explanation": "rénshēng（第一声）与 rénshì 的韵母和声调都不同，意思是人的声音。"}], "explanations": {"人士": "正确答案。人士 rénshì 指有一定社会影响或属于某一界别的人。", "人生": "rénshēng（第一声）与 rénshì 的第二音节韵母和声调都不同，意思是人的一生。", "人手": "rénshǒu（第三声）与 rénshì 的韵母不同，意思是人手、劳动力。", "人声": "rénshēng（第一声）与 rénshì 的韵母和声调都不同，意思是人的声音。"}, "sentence_index": null, "correct_answer": "人士"}, "level_3": {"options": [{"text": "人士", "is_correct": true, "explanation": "正确。“著名人士”指有名望的人，在大会上讲话很自然。"}, {"text": "嫌疑犯", "is_correct": false, "explanation": "语义：“嫌疑犯”与“著名”的正面含义相矛盾，也不符合在大会上讲话的情境。"}, {"text": "幼儿", "is_correct": false, "explanation": "语义：幼儿不具备“著名”的身份，不能在大会上以此身份讲话。"}, {"text": "行人", "is_correct": false, "explanation": "语义：“行人”指路上步行的人，与“著名”相矛盾。"}], "explanations": {"人士": "正确。“著名人士”指有名望的人，在大会上讲话很自然。", "嫌疑犯": "语义：“嫌疑犯”与“著名”的正面含义相矛盾，也不符合在大会上讲话的情境。", "幼儿": "语义：幼儿不具备“著名”的身份，不能在大会上以此身份讲话。", "行人": "语义：“行人”指路上步行的人，与“著名”相矛盾。"}, "sentence_index": 6, "correct_answer": "人士"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座城市一共有五百万人士。", "explanation": "这里应该用〈人口〉。“人士”指有某种身份的人，不用于统计总人数，统计总人数要用“人口”。"}, {"text": "公园里有很多人士在散步。", "explanation": "这里应该用〈老人〉。“人士”指有某种身份或属于某界别的人，不用于泛指在公园散步的老年人，这里应说“老人”。"}, {"text": "我家的人士都在农村生活。", "explanation": "这里应该用〈亲戚〉。“人士”指有一定身份或属于某界别的人，不用于指家中的亲属。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c80a291-cf97-4dfa-beee-2c8c814bc789') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86832, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位作家是一只知名人士，经常接受采访。", "corrected_sentence": "这位作家是一位知名人士，经常接受采访。", "error_description": "量词错误：“人士”指人，要用量词“位”，不能用“只”（“只”多用于动物）。正确的是“一位知名人士”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c80a291-cf97-4dfa-beee-2c8c814bc789') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86832, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是很有影响的知名人士的。", "corrected_sentence": "他是很有影响的知名人士。", "error_description": "句末多加“的”：“他是很有影响的知名人士”已是完整的句子，“人士”后不能再加“的”。正确的是“他是很有影响的知名人士。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c80a291-cf97-4dfa-beee-2c8c814bc789') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
