INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86834, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "property", "definition": "正赶上时候；马上。", "primary_collocate": null, "pronunciation": "jí shí", "ipa": "tɕi˧˥ ʂɨ˧˥", "syllable_count": 2, "sentences": [{"text": "发现问题要及时告诉我。", "target_word": "及时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人要及时吃药。", "target_word": "及时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有了新消息，请及时通知大家。", "target_word": "及时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他及时把钱还给了朋友。", "target_word": "及时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作业做完后，要及时交给老师。", "target_word": "及时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他感冒了，应该及时去医院。", "target_word": "及时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他发现错误后及时改了。", "target_word": "及时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请及时回复我的信。", "target_word": "及时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，大家及时收了衣服。", "target_word": "及时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈及时给我打了电话。", "target_word": "及时", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "作状语，放在动词前，表示不拖延、马上去做，如及时通知、及时处理", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04fa6d51-9971-4407-9e63-187a99b3aa35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86834, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "及时", "is_correct": true, "explanation": "及时 jí shí：正赶上时候，不拖延，马上去做。"}, {"text": "集市", "is_correct": false, "explanation": "集市 jí shì：shì（第四声）与 shí（第二声）声调不同，意思是定期开放的市场。"}, {"text": "急事", "is_correct": false, "explanation": "急事 jí shì：shì（第四声）与 shí（第二声）声调不同，意思是紧急的事情。"}, {"text": "基石", "is_correct": false, "explanation": "基石 jī shí：jī（第一声）与 jí（第二声）声调不同，意思是建筑的基础石头，比喻根本。"}, {"text": "几时", "is_correct": false, "explanation": "几时 jǐ shí：jǐ（第三声）与 jí（第二声）声调不同，意思是什么时候。"}], "explanations": {"及时": "及时 jí shí：正赶上时候，不拖延，马上去做。", "集市": "集市 jí shì：shì（第四声）与 shí（第二声）声调不同，意思是定期开放的市场。", "急事": "急事 jí shì：shì（第四声）与 shí（第二声）声调不同，意思是紧急的事情。", "基石": "基石 jī shí：jī（第一声）与 jí（第二声）声调不同，意思是建筑的基础石头，比喻根本。", "几时": "几时 jǐ shí：jǐ（第三声）与 jí（第二声）声调不同，意思是什么时候。"}, "sentence_index": null, "correct_answer": "及时"}, "level_3": {"options": [{"text": "拖拖拉拉", "is_correct": false, "explanation": "语义：“拖拖拉拉”表示拖延，与“发现问题要……告诉我”的及时要求相反。"}, {"text": "及时", "is_correct": true, "explanation": "及时：不拖延，发现问题后马上告诉我，符合句中的要求。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”多与否定或已发生的事实连用，不能与表示要求的“要”搭配。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示频率低，与“发现问题要……告诉我”强调马上告知的要求相反。"}], "explanations": {"拖拖拉拉": "语义：“拖拖拉拉”表示拖延，与“发现问题要……告诉我”的及时要求相反。", "及时": "及时：不拖延，发现问题后马上告诉我，符合句中的要求。", "从来": "搭配：“从来”多与否定或已发生的事实连用，不能与表示要求的“要”搭配。", "偶尔": "语义：“偶尔”表示频率低，与“发现问题要……告诉我”强调马上告知的要求相反。"}, "sentence_index": 0, "correct_answer": "及时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "欢迎你及时来我家做客。", "explanation": "这里应该用〈随时〉。随时表示任何时候都可以，及时强调在需要时马上去做，不用于表示“任何时候都欢迎来”。"}, {"text": "他拖了三个月才及时交报告。", "explanation": "这里不能用〈及时〉。及时表示不拖延、正赶上需要的时候；拖了三个月才交，与“及时”矛盾，应说“延误”或去掉“及时”。"}, {"text": "他及时长高了。", "explanation": "这里应该用〈自然〉。及时表示有人主动去赶上需要的时机；身高是自然生长的变化，应说“自然长高”，不能用“及时”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c80a291-cf97-4dfa-beee-2c8c814bc789') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86834, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "互相", "is_correct": false, "explanation": "语法：“互相”要求两方或多方，主语只有“他”一人，不能说“他互相改了”。"}, {"text": "及时", "is_correct": true, "explanation": "及时：不拖延，发现错误后马上改正，符合句意。"}, {"text": "更加", "is_correct": false, "explanation": "搭配：“更加”修饰形容词或心理活动，不能修饰“改”这样的动作。"}, {"text": "从没", "is_correct": false, "explanation": "语义：“从没”表示从未发生，与句中已发生的“改了”相矛盾。"}], "explanations": {"互相": "语法：“互相”要求两方或多方，主语只有“他”一人，不能说“他互相改了”。", "及时": "及时：不拖延，发现错误后马上改正，符合句意。", "更加": "搭配：“更加”修饰形容词或心理活动，不能修饰“改”这样的动作。", "从没": "语义：“从没”表示从未发生，与句中已发生的“改了”相矛盾。"}, "sentence_index": 6, "correct_answer": "及时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们每天及时运动半个小时。", "explanation": "这里应该用〈坚持〉。及时强调在需要时不拖延地去做，每天有规律地做要用〈坚持〉。"}, {"text": "他跑步的速度很及时。", "explanation": "这里应该用〈快〉。及时指正赶上需要的时候，形容速度应说“快”，不能用“及时”。"}, {"text": "我及时喜欢上了这本书。", "explanation": "这里应该用〈逐渐〉。及时表示为应对需要而不拖延地去做；“喜欢上”是心理上慢慢产生的变化，应说“逐渐喜欢上”，不能用“及时”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c80a291-cf97-4dfa-beee-2c8c814bc789') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86834, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师及时了把作业发给了我们。", "corrected_sentence": "老师及时把作业发给了我们。", "error_description": "“了”位置错误：“及时”是状语，后面不能直接加“了”。正确的说法是“老师及时把作业发给了我们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c80a291-cf97-4dfa-beee-2c8c814bc789') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86834, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请你及时一下回复我的信。", "corrected_sentence": "请你及时回复我的信。", "error_description": "“及时”是副词，作状语直接放在动词前，后面不能加“一下”。正确的说法是“请你及时回复我的信”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c80a291-cf97-4dfa-beee-2c8c814bc789') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86835, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab2ec06d-117f-4282-82e1-1de125000776') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86835, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab2ec06d-117f-4282-82e1-1de125000776') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86835, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "可怕是让人心里害怕。", "primary_collocate": null, "pronunciation": "kě pà", "ipa": "kʰɤ˨˩˦ pʰa˥˩", "syllable_count": 2, "sentences": [{"text": "这部电影太可怕了，我看了一半就关了。", "target_word": "可怕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的夜晚黑得可怕。", "target_word": "可怕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他讲了一个可怕的鬼故事。", "target_word": "可怕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别怕，那只狗其实不可怕。", "target_word": "可怕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震是一件非常可怕的事。", "target_word": "可怕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过去的战争让人觉得可怕。", "target_word": "可怕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最可怕的不是黑夜，而是一个人。", "target_word": "可怕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到可怕的画面，她马上闭上了眼睛。", "target_word": "可怕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路上车很多，开起来真可怕。", "target_word": "可怕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个老人的眼神很可怕，我不敢看他。", "target_word": "可怕", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "可怕：形容词，让人心里害怕", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dfa9012-682f-47cd-812e-5fb770f93c09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86835, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "好看", "is_correct": false, "explanation": "语义：“好看”说影片精彩，与后一句“看了一半就关了”的意思相矛盾。"}, {"text": "可怕", "is_correct": true, "explanation": "“可怕”说电影让人害怕，正好解释了为什么看了一半就关了，是原句的词。"}, {"text": "体贴", "is_correct": false, "explanation": "搭配：“体贴”形容人待人细心周到，不能用来形容电影。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人或物的身材体形，电影没有身材，不能这样说。"}], "explanations": {"好看": "语义：“好看”说影片精彩，与后一句“看了一半就关了”的意思相矛盾。", "可怕": "“可怕”说电影让人害怕，正好解释了为什么看了一半就关了，是原句的词。", "体贴": "搭配：“体贴”形容人待人细心周到，不能用来形容电影。", "高大": "体貌：“高大”形容人或物的身材体形，电影没有身材，不能这样说。"}, "sentence_index": 0, "correct_answer": "可怕"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "听到雷声，我很可怕。", "explanation": "这里应该用〈害怕〉。“可怕”说事物让人害怕，不能用来说“我”心里害怕。"}, {"text": "这碗面很可怕，我吃了两碗。", "explanation": "这里应该用〈可口〉。面条不会令人害怕，形容味道好要用“可口”。"}, {"text": "这个笑话很可怕，大家都笑了。", "explanation": "这里应该用〈可笑〉。笑话不会令人害怕，引人发笑的要说“可笑”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab2ec06d-117f-4282-82e1-1de125000776') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86835, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "便宜", "is_correct": false, "explanation": "搭配：「便宜」说价格低，黑夜和人都没有价格，不能这样说。"}, {"text": "可怕", "is_correct": true, "explanation": "“可怕”指令人害怕，与“黑夜”和“一个人”的语境相符，是原句的词。"}, {"text": "整齐", "is_correct": false, "explanation": "搭配：“整齐”说排列或衣着有条理，不能用来形容黑夜。"}, {"text": "精致", "is_correct": false, "explanation": "搭配：“精致”说器物或工艺做得细巧，不能用来形容黑夜。"}], "explanations": {"便宜": "搭配：「便宜」说价格低，黑夜和人都没有价格，不能这样说。", "可怕": "“可怕”指令人害怕，与“黑夜”和“一个人”的语境相符，是原句的词。", "整齐": "搭配：“整齐”说排列或衣着有条理，不能用来形容黑夜。", "精致": "搭配：“精致”说器物或工艺做得细巧，不能用来形容黑夜。"}, "sentence_index": 6, "correct_answer": "可怕"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份友谊很可怕，我一直很珍惜。", "explanation": "这里应该用〈可贵〉。友谊不会令人害怕，值得珍惜要说“可贵”。"}, {"text": "这个做法很可怕，值得大家学习。", "explanation": "这里应该用〈可取〉。做法不会令人害怕，值得采用、效仿要说“可取”。"}, {"text": "那个生病的孩子真可怕，我很同情他。", "explanation": "这里应该用〈可怜〉。“可怕”指令人害怕，生病的孩子只让人同情，应说“可怜”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab2ec06d-117f-4282-82e1-1de125000776') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86835, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那次地震太可怕的，大家都跑出了房子。", "corrected_sentence": "那次地震太可怕了，大家都跑出了房子。", "error_description": "“太……了”的“了”不能换成“的”。错误写法是“太可怕的”，后面没有被修饰的名词，正确写法是“太可怕了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab2ec06d-117f-4282-82e1-1de125000776') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
